INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186000,'40063','A por ellos','fiesta','fiestas_wiki','A por ellos es una jota festiva, propia de la localidad de Cuéllar, provincia de Segovia, España, convertida en himno de las fiestas de Nuestra Señora del Rosario, que comienzan el último sábado de agosto y en las que tienen lugar los encierros de Cuéllar.',NULL,NULL,'https://es.wikipedia.org/wiki/A_por_ellos','IT Internacional');
