INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186002,'37011','Acto del Descendimiento (Salamanca)','fiesta','fiestas_wiki','El Acto del Descendimiento es una celebración religiosa popular de la Semana Santa de Salamanca que se viene realizando el día de Viernes Santo desde el siglo XVII. Organizado por la Cofradía de la Vera Cruz constituye uno de los actos distintivos de esta Semana Santa. Consiste en un Sermón seguido de un desenclavo…',NULL,NULL,'https://es.wikipedia.org/wiki/Acto_del_Descendimiento_(Salamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186003,'29067','Agrupación de Cofradías de Semana Santa de Málaga','fiesta','fiestas_wiki','La Agrupación de Cofradías de Semana Santa de Málaga, más comúnmente conocida como Agrupación de Cofradías de Málaga o La Agrupación de Cofradías a secas, es un organismo fundado en 1921 por las cofradías y hermandades existentes en la ciudad en tal año, con el fin de: «Organizar y coordinar las actividades de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Agrupación_de_Cofradías_de_Semana_Santa_de_Málaga','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186004,'23050','Agrupación de Cofradías y Hermandades de la Ciudad de Jaén','fiesta','fiestas_wiki','La Agrupación de Cofradías y Hermandades de la Ciudad de Jaén, más comúnmente Agrupación de Cofradías de Jaén o simplemente Agrupación de Cofradías, es un organismo fundado en 1946 por las cofradías y hermandades de pasión existentes en la ciudad en tal año. Su principal fin es «Organizar y coordinar las…',NULL,NULL,'https://es.wikipedia.org/wiki/Agrupación_de_Cofradías_y_Hermandades_de_la_Ciudad_de_Jaén','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186005,'20036','Alarde de Fuenterrabía','fiesta','fiestas_wiki','El Alarde de Fuenterrabía es un desfile que tiene lugar durante las fiestas de Fuenterrabía, Guipúzcoa (España), el día 8 de septiembre con motivo de la renovación del voto hecho a la Virgen de Guadalupe durante el Sitio de la ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Alarde_de_Fuenterrabía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186006,'50178','Alardo','fiesta','fiestas_wiki','El alardo es, en las fiestas de Moros y Cristianos, el simulacro de combate entre moros y cristianos,​ en forma de disparada de arcabuces entre los miembros de ambos bandos.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Alardo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186007,'03038','Alberto Escámez','fiesta','fiestas_wiki','Alberto Escámez López (Linares, 1896-Torrevieja, 1970) fue un militar y músico español, siendo el primer autor en componer marchas procesionales para el género de cornetas y tambores.',NULL,NULL,'https://es.wikipedia.org/wiki/Alberto_Escámez','IT Internacional');
