INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186009,'30030','Alfajor (España)','fiesta','fiestas_wiki','En España, el alfajor es un dulce de la repostería española, una variedad de dulce típicamente navideño, propio de la cocina andaluza y también de Murcia. Suele estar realizado a partir de una pasta de almendras, nueces y miel, al igual que muchos otros dulces tradicionales como el turrón o el mazapán. Puede ser en…',NULL,NULL,'https://es.wikipedia.org/wiki/Alfajor_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186010,'02011','Alfombras de Serrín de Elche de la Sierra','fiesta','fiestas_wiki','Las Alfombras de Serrín es una fiesta que se celebra en Elche de la Sierra (Albacete) la noche precedente al Corpus Christi. Consiste en la realización, por parte de los vecinos, de alfombras de serrín y viruta a lo largo de calles y plazas de la localidad, creando mosaicos y escenas religiosas.',NULL,NULL,'https://es.wikipedia.org/wiki/Alfombras_de_Serrín_de_Elche_de_la_Sierra','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186011,'44206','Alfombras del Santísimo Misterio','fiesta','fiestas_wiki','Las Alfombras del Santísimo Misterio de Aguaviva, Teruel son declaradas fiesta de interés turístico de Aragón por el Departamento de Vertebración del Territorio, Movilidad y Vivienda del Gobierno de Aragón.​ Se llevan a cabo el día 28 de agosto, en honor al Santísimo Misterio de Aguaviva y coincidiendo con la Feria…',NULL,NULL,'https://es.wikipedia.org/wiki/Alfombras_del_Santísimo_Misterio','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186012,'50067','Alfonsadas','fiesta','fiestas_wiki','Las Alfonsadas es una fiesta medieval, declarada de interés turístico de Aragón,​ que se desarrolla durante el fin de semana más cercano al 24 de junio en Calatayud (Zaragoza). Se trata de una conmemoración histórica original, arraigada en la tradición popular de la localidad en la que se escenifica la reconquista…',NULL,NULL,'https://es.wikipedia.org/wiki/Alfonsadas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186013,'32071','Almadía','fiesta','fiestas_wiki','Una almadía (Navarra), armadía​ o nabata (Aragón) o rai (Cataluña) es una balsa hecha de troncos de madera, cuya función es la conducción de los propios troncos por los ríos, desde los bosques de explotación maderera hasta los puntos de carga para su transporte o hasta donde se encuentran las serrerías. Las…',NULL,NULL,'https://es.wikipedia.org/wiki/Almadía','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186014,'06006','Almossassa Batalyaws','fiesta','fiestas_wiki','AlMossasa Batalyaws es una fiesta-conmemoración que se celebra en la ciudad de Badajoz, en España, con motivo de la fundación de la ciudad (sobre un asentamiento visigodo anterior [cita requerida]) por el caudillo rebelde Ibn Marwan en el 875. Durante un fin de semana, la alcazaba de la ciudad revive con la…',NULL,NULL,'https://es.wikipedia.org/wiki/Almossassa_Batalyaws','Interés Turístico Regional');
