INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186017,'46250','Amparito Roca','fiesta','fiestas_wiki','Amparito Roca es el nombre de un pasodoble compuesto en 1925 por el músico y compositor catalán Jaume Texidor Dalmau (1884-1957).[cita requerida] En septiembre de 1925, mientras residía en la localidad valenciana de Horno de Alcedo, el músico barcelonés Jaime Texidor Dalmau, que en aquel año era director de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Amparito_Roca');
