INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186043,'90235','Antruejo de Llamas de la Ribera','fiesta','fiestas_wiki','El antruejo de Llamas de la Ribera es una fiesta popular que se celebra el domingo de carnaval en la localidad española de Llamas de la Ribera (León).',NULL,NULL,'https://es.wikipedia.org/wiki/Antruejo_de_Llamas_de_la_Ribera','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186044,'47113','Antruido','fiesta','fiestas_wiki','El Antruido​ es una tradición popular de origen pagano asociada a la celebración del Carnaval, propia de la Montaña de Riaño en la provincia de León, España.​ En Pedrosa del Rey y Siero de la Reina se celebró este Antruido hasta las segunda década del siglo XX. En Crémenes y en La Puerta, hasta la década de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Antruido','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186045,'08007','Aplec de Calella','fiesta','fiestas_wiki','El Aplec de Calella o Aplec Pairal de Cataluña, cuyo origen se remonta al 1926, es el decano de los encuentros de sardana, y se celebra en el Paseo Marítimo Manuel Puigvert y el Parque Dalmau de Calella como escenarios naturales.​ El encuentro nació para conmemorar el segundo aniversario de la fundación de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Aplec_de_Calella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186046,'25120','Aplec del Caragol','fiesta','fiestas_wiki','L''Aplec del Caragol es un encuentro que se hace anualmente, durante un fin de semana de mayo, en la ribera del río Segre y los Camps Elisis de Lérida desde 1980. Es una manifestación gastronómica donde el caracol es el protagonista, en su mayoría de la variedad Helix aspersa, o bover en catalán, e incorpora música,…',NULL,NULL,'https://es.wikipedia.org/wiki/Aplec_del_Caragol','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186047,'46204','Aplec del Puig','fiesta','fiestas_wiki','Desde los años 1960, el último domingo de octubre, el Aplec del Puig reúne los nacionalistas valencianos de todas partes para celebrar una jornada festiva en uno de los lugares con más simbolismo e historia de la Comunidad Valenciana, el municipio del Puig, en la Horta Norte.​​ Los actos se inician con una marcha…',39.58795833,-0.30364722,'https://es.wikipedia.org/wiki/Aplec_del_Puig');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186048,'25072','Aquelarre de Cervera','fiesta','fiestas_wiki','El Aquelarre de Cervera es una fiesta tradicional celebrada en Cervera (la Segarra) el último fin de semana de agosto desde 1978.​ Cervera se llena de correfocs, espectáculos, magia, esoterismo y brujas. Sus protagonistas son el Mascle Cabró y sus damas, las brujas. Además, durante los días del Aquelarre se…',41.6657,1.271001,'https://es.wikipedia.org/wiki/Aquelarre_de_Cervera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186049,'29067','Archicofradía Sacramental de la Expiración (Málaga)','fiesta','fiestas_wiki','La Archicofradía Sacramental de la Expiración, cuya denominación oficial es Pontificia, Real, Ilustre y Venerable Archicofradía Sacramental de Culto y Procesión del Santísimo Cristo de la Expiración y María Santísima de los Dolores Coronada, es una Hermandad perchelera perteneciente a la Agrupación de Cofradías que…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_Sacramental_de_la_Expiración_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186050,'29067','Archicofradía Sacramental de la Pasión (Málaga)','fiesta','fiestas_wiki','La Archicofradía de la Pasión, cuya denominación oficial y completa es Real, Muy Ilustre y Venerable Archicofradía de Nazarenos del Santísimo Sacramento, Nuestro Padre Jesús de la Pasión y María Santísima del Amor Doloroso, es una cofradía malagueña, miembro de la Agrupación de Cofradías, que participa en la Semana…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_Sacramental_de_la_Pasión_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186051,'03064','Archicofradía Sacramental de los Dolores (Málaga)','fiesta','fiestas_wiki','Muy Antigua, Venerable y Pontificia Archicofradía Sacramental de Nazarenos del Santísimo Cristo de la Redención y Nuestra Señora de los Dolores es una hermandad de culto y procesión malagueña, más conocida como Dolores de San Juan, por tener su sede canónica en la parroquia de San Juan del centro de Málaga.',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_Sacramental_de_los_Dolores_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186052,'04063','Archicofradía de la Corte de María','fiesta','fiestas_wiki','La Archicofradía de la Corte de María es una cofradía de culto católico establecida en la localidad de Liria, Valencia que venera la imagen de la Inmaculada Concepción, de la que toma su nombre popular. La particular devoción a su imagen titular, la Inmaculada Concepción de María, que recibe entre sus fieles y…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_de_la_Corte_de_María');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186053,'29067','Archicofradía de la Sangre (Málaga)','fiesta','fiestas_wiki','La Archicofradía de la Sangre, cuya denominación oficial es Pontificia, Real, Muy Ilustre y Venerable Archicofradía del Santísimo Cristo de la Sangre, María Santísima de Consolación y Lágrimas; y del Santo Sudario, es una Cofradía de Málaga, miembro cofundador de la Agrupación de Cofradías, que participa en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_de_la_Sangre_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186054,'22124','Archicofradía del Huerto (Málaga)','fiesta','fiestas_wiki','La Archicofradía del Huerto, cuya denominación oficial y completa es Pontificia, Real, Muy Ilustre y Venerable Archicofradía Sacramental y Seráfica de Nuestro Padre Jesús Orando en el Huerto, Nuestra Señora de la Concepción, San Juan Evangelista y Nuestra Señora de la Oliva, es una Hermandad católica de culto y…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_del_Huerto_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186055,'11020','Archicofradía del Inmaculado Corazón de María (Jerez de la Frontera)','fiesta','fiestas_wiki','La Archicofradía del Inmaculado Corazón de María, también conocida como Archicofradía del Rosario, es una cofradía lefítica católica que realiza una procesión anual en el mes de octubre en Jerez de la Frontera por la festividad de Nuestra Señora del Rosario, que se celebra el 7 de octubre.',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_del_Inmaculado_Corazón_de_María_(Jerez_de_la_Frontera)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186056,'29067','Archicofradía del Paso y la Esperanza (Málaga)','fiesta','fiestas_wiki','La Archicofradía del Paso y la Esperanza, cuya denominación oficial es Pontificia y Real Archicofradía del Dulce Nombre de Jesús Nazareno del Paso y María Santísima de la Esperanza Coronada, conocida como la Reina de Málaga, es una Hermandad perteneciente a la Agrupación de Cofradías que hace estación de penitencia…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_del_Paso_y_la_Esperanza_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186057,'30030','Archicofradía del Resucitado (Murcia)','fiesta','fiestas_wiki','La Real y Muy Ilustre Archicofradía de Nuestro Señor Jesucristo Resucitado es una cofradía de culto católico perteneciente a la Semana Santa de Murcia (Región de Murcia, España). La llamada procesión de "los blancos" (o "del demonio" por el popular personaje que desfila en ella) constituye el colofón de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_del_Resucitado_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186058,'11020','Archicofradía del Rosario de Montañeses (Jerez de la Frontera)','fiesta','fiestas_wiki','La Archicofradía del Rosario de Montañeses es una cofradía católica que realiza una procesión anual durante la tarde del 12 de octubre. Su nombre completo es Muy Antigua, Venerable e Ilustre Archicofradía de Nuestra Señora del Rosario.',NULL,NULL,'https://es.wikipedia.org/wiki/Archicofradía_del_Rosario_de_Montañeses_(Jerez_de_la_Frontera)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186059,'40063','Archivo Parroquial de Cuéllar','fiesta','fiestas_wiki','El Archivo Parroquial de Cuéllar es un archivo de documentos de titularidad eclesiástica, con sede en la Casa Parroquial de la villa segoviana de Cuéllar (Castilla y León).',NULL,NULL,'https://es.wikipedia.org/wiki/Archivo_Parroquial_de_Cuéllar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186060,'27028','Arde Lucus','fiesta','fiestas_wiki','El Arde Lucus (también escrito como Arde Lvcvs) es una fiesta celebrada en Lugo a mediados del mes de junio que revive el pasado romano y castreño de la ciudad amurallada, y que surgió para conmemorar la fundación de la ciudad. La primera edición se celebró en el año 2000.',43.0116667,-7.5572222,'https://es.wikipedia.org/wiki/Arde_Lucus','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186061,'13004','Armaos','fiesta','fiestas_wiki','Las de armaos son cofradías religiosas cuya disciplina militar es heredada de las tropas imperiales de la España de los siglos del xᴠɪ al xᴠɪɪ, que representan a las tropas del Imperio romano durante la Semana Santa en Castilla-La Mancha, especialmente, en la provincia de Ciudad Real, originándose la primera…',NULL,NULL,'https://es.wikipedia.org/wiki/Armaos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186062,'08302','Arroces del Mundo','fiesta','fiestas_wiki','Arroces del Mundo es una fiesta intercultural, popular y participativa que se celebra a principios de junio en el barrio de San Francisco en Bilbao desde el año 2003.',NULL,NULL,'https://es.wikipedia.org/wiki/Arroces_del_Mundo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186063,'10072','As Borrallás','fiesta','fiestas_wiki','As Borrallás es una fiesta transfronteriza que se celebra en las localidades de Eljas (Cáceres) y Fóios (Portugal) en fechas cercanas al 1 de noviembre, Día de Todos los Santos.',40.2174602,-6.84810799,'https://es.wikipedia.org/wiki/As_Borrallás','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186064,'29085','As-Sharq','fiesta','fiestas_wiki','As-Sharq es una feria celebrada en Salares, en la provincia de Málaga, España. Se trata de una feria temática dedicada a la cultura andalusí, en la que se pretende transmitir la riqueza cultural del legado hispanoárabe. La fiesta tiene lugar durante un fin de semana del mes de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/As-Sharq');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186065,'46250','Associació d''Estudis Fallers','fiesta','fiestas_wiki','La "Associació d''Estudis Fallers" (ADEF) es una entidad constituida el 22 de febrero de 1990 en Valencia​​ cuyos objetivos fundacionales son: desarrollar y prestigiar científicamente los estudios falleros y de la cultura popular y ponerlos a disposición de la sociedad, siendo la AdEf el entre el.mundo académico y…',NULL,NULL,'https://es.wikipedia.org/wiki/Associació_d''Estudis_Fallers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186066,'46105','Aurora de Cullera','fiesta','fiestas_wiki','La Aurora de Cullera o la Noche de la Aurora o la Aurora de San Antonio es, quizás, el acto más popular y más emotivo de las Fiestas Patronales de Cullera (Valencia). Las fiestas empiezan el sábado siguiente al domingo de Pascua, ese día se celebra la «Baixà» (Bajada de la madre de Dios del Castillo de Cullera) y…',NULL,NULL,'https://es.wikipedia.org/wiki/Aurora_de_Cullera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186067,'31216','Auto de los Reyes Magos (Sangüesa)','fiesta','fiestas_wiki','El Auto de los Reyes Magos de Sangüesa, de forma oficial Auto de los Reyes Magos/El Misterio de Reyes,​ es una fiesta de interés turístico desde 2012 celebrada en la localidad navarra de Sangüesa.​',NULL,NULL,'https://es.wikipedia.org/wiki/Auto_de_los_Reyes_Magos_(Sangüesa)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186068,'03052','Auto sacramental de los Reyes Magos de Cañada','fiesta','fiestas_wiki','El Auto sacramental de los Reyes Magos de Cañada es una fiesta que se realiza en Cañada, Alicante (España). Es una tradición que se basa en la representación teatral, tanto móvil como en escenarios fijos, de la anunciación, de la adoración de los Reyes Magos al niño Jesús y de la matanza de los inocentes de…',NULL,NULL,'https://es.wikipedia.org/wiki/Auto_sacramental_de_los_Reyes_Magos_de_Cañada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186069,'06023','Bacanal de la Grasa (Carnaval de Zafra)','fiesta','fiestas_wiki','La Bacanal de la Grasa es una fiesta gastronómica y popular celebrada anualmente en Zafra (Badajoz, España) durante el Domingo de Carnaval. Es considerada el día más destacado del Carnaval de Zafra y reúne a miles de vecinos y visitantes en las plazas históricas de la ciudad para degustar los productos del cerdo…',NULL,NULL,'https://es.wikipedia.org/wiki/Bacanal_de_la_Grasa_(Carnaval_de_Zafra)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186070,'43148','Baile de diablos','fiesta','fiestas_wiki','El baile de diablos (en catalán, ball de diables) es una de las tradiciones más arraigadas inicialmente en Cataluña, sobre todo por Tarragona y cercanías, y posteriormente en la Comunidad Valenciana, donde se llama correfocs (correfuegos), e Islas Baleares. Actualmente, su participación en pasacalles, procesiones y…',NULL,NULL,'https://es.wikipedia.org/wiki/Baile_de_diablos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186071,'04063','Bajada (fiesta)','fiesta','fiestas_wiki','Con el término Bajada se conoce en las Islas Canarias a una tradición popular y religiosa muy arraigada en varias islas de este archipiélago. La misma consiste en el traslado de la imagen de la Virgen María patrona de la isla desde su santuario habitual a la capital insular con periodicidad variada dependiendo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Bajada_(fiesta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186072,'38027','Bajada de la Virgen del Pino de El Paso','fiesta','fiestas_wiki','La bajada de la Virgen del Pino de El Paso es una fiesta trienal que se celebra en el municipio de El Paso (Isla de La Palma, Canarias) en la que se traslada la imagen de la Virgen del Pino desde su ermita en el monte de Cumbre Nueva hasta el casco urbano de El Paso, acompañada de un desfile de romeros ataviados…',NULL,NULL,'https://es.wikipedia.org/wiki/Bajada_de_la_Virgen_del_Pino_de_El_Paso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186073,'43148','Bajada del Águila','fiesta','fiestas_wiki','Acto cada año más popular que se celebra dentro de las Fiestas de Santa Tecla de Tarragona la noche del 21 al 22 de septiembre. Consiste en el recorrido nocturno por varias calles de la Part Alta de la ciudad de Tarragona de L''Aliga, de La Mulassa, el Lleó ( Besties del Seguici o Cortejo Popular ) y de Els Gegants…',NULL,NULL,'https://es.wikipedia.org/wiki/Bajada_del_Águila');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186074,'31232','Bajada del Ángel (Tudela)','fiesta','fiestas_wiki','La bajada del ángel se trata de una ceremonia celebrada en Tudela, Navarra, durante el Domingo de Resurrección en la que se representa la aparición del Ángel San Gabriel a María para anunciarle la resurrección de Jesús.​ Actualmente está declarada como Fiesta de Interés Turístico de Navarra y Fiesta de Interés…',NULL,NULL,'https://es.wikipedia.org/wiki/Bajada_del_Ángel_(Tudela)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186075,'22053','Ball dels Salvatges','fiesta','fiestas_wiki','El Baile de los Salvajes (en catalán ribagorzano y oficialmente Ball dels Salvatges) es una representación tradicional del siglo XIV que se realiza en Benabarre, en la Ribagorza, en agosto, desde 2010 con carácter bienal.​ Se trata de una representación que une teatro, música y danza en la que participan alrededor…',42.11667,0.48333,'https://es.wikipedia.org/wiki/Ball_dels_Salvatges','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186076,'41091','Banda de Cornetas y Tambores Nuestra Señora del Sol','fiesta','fiestas_wiki','La Banda de Cornetas y Tambores Nuestra Señora de Sol es una banda de música instrumental de Sevilla, Andalucía, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Banda_de_Cornetas_y_Tambores_Nuestra_Señora_del_Sol','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186077,'46212','Banda de Cornetas y Tambores del Real Cuerpo de Bomberos','fiesta','fiestas_wiki','La Banda de Cornetas y Tambores del Real Cuerpo de Bomberos es una banda musical de la ciudad andaluza de Málaga, creada en 1911, siendo la pionera de este tipo de bandas en toda Andalucía y España.​ Actualmente está dirigida por José Luis Gil.',NULL,NULL,'https://es.wikipedia.org/wiki/Banda_de_Cornetas_y_Tambores_del_Real_Cuerpo_de_Bomberos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186078,'41091','Banda de Música de la Cruz Roja','fiesta','fiestas_wiki','La Banda de Música de la Cruz Roja es una agrupación musical ubicada en Sevilla (España), fue fundada en el año 1937.',NULL,NULL,'https://es.wikipedia.org/wiki/Banda_de_Música_de_la_Cruz_Roja','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186079,'41091','Banda de Música del Maestro Tejera','fiesta','fiestas_wiki','La Banda de Música del Maestro Tejera es una agrupación musical fundada en 1910 que tiene su sede en la ciudad de Sevilla (España).​',NULL,NULL,'https://es.wikipedia.org/wiki/Banda_de_Música_del_Maestro_Tejera','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186080,'21041','Banda de música de Nuestra Señora Madre de la Consolación de Huelva','fiesta','fiestas_wiki','La Banda de Música Nuestra Madre de la Consolación se crea en el año 1994 dentro del seno de la Hdad. de la Buena Muerte de la ciudad de Huelva. Realiza su presentación en la Iglesia del Convento de las RR MM Agustinas en enero del mismo año, cosechando gran éxito.',NULL,NULL,'https://es.wikipedia.org/wiki/Banda_de_música_de_Nuestra_Señora_Madre_de_la_Consolación_de_Huelva','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186081,'23055','Bandas de cabecera','fiesta','fiestas_wiki','Las Bandas de Cabecera son bandas de Semana Santa que se sitúan al principio de la procesión. Tienen una gran tradición en Linares (Jaén) donde, a día de hoy, hay 6: Santa Cena Sacramental, Siete palabras, Rescate, Nazareno, Expiración y Santo Entierro por orden de salida.',NULL,NULL,'https://es.wikipedia.org/wiki/Bandas_de_cabecera','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186082,'37164','Bando de la Huerta','fiesta','fiestas_wiki','El Bando de la Huerta es el nombre que recibe el día grande de las Fiestas de Primavera de Murcia. Título que comparte con el Entierro de la Sardina y que tiene lugar el martes de Pascua. La jornada es toda una exaltación de las tradiciones huertanas, tan íntimamente ligadas a la historia de la capital murciana.',NULL,NULL,'https://es.wikipedia.org/wiki/Bando_de_la_Huerta','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186083,'49275','Barandales','fiesta','fiestas_wiki','Barandales es un personaje que desempeña la misión de avisar al público de la marcha de las procesiones de Semana Santa en Zamora, España.​ Suele vestir con amplios ropajes y agitan con las manos dos pesados esquilones (rondan los cinco kilos). Se origina este personaje en el siglo XVI como campanillero avisador de…',NULL,NULL,'https://es.wikipedia.org/wiki/Barandales','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186084,'29067','Basílica del Dulce Nombre de Jesús (Málaga)','fiesta','fiestas_wiki','La basílica del Dulce Nombre de Jesús Nazareno del Paso y María Santísima de la Esperanza, conocida simplemente como Basílica de la Esperanza, de la ciudad andaluza de Málaga (España) se encuentra ubicada en el barrio de El Perchel. Construida en 1988, ostenta desde el 28 de mayo de 1998, junto a la Catedral de…',36.71797741,-4.42681321,'https://es.wikipedia.org/wiki/Basílica_del_Dulce_Nombre_de_Jesús_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186085,'09177','Batalla de Atapuerca','fiesta','fiestas_wiki','La batalla de Atapuerca ocurrió el 1 de septiembre de 1054 en la llanura frente a la sierra de Atapuerca (Burgos) entre Fernando I, rey de León y conde de Castilla, y su hermano García Sánchez III «el de Nájera», rey de Pamplona, hijos ambos de Sancho III el Mayor.',42.35,-3.51666667,'https://es.wikipedia.org/wiki/Batalla_de_Atapuerca','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186086,'39035','Batalla de Flores (Laredo)','fiesta','fiestas_wiki','La Batalla de Flores es la fiesta popular más importante de la localidad cántabra de Laredo, en España. Se celebra el último viernes de agosto desde el año 1908 y está declarada Fiesta de Interés Turístico desde 1965 y Fiesta de Interés Turístico Nacional desde 2011.​ Consiste en un desfile de carrozas cuyos…',NULL,NULL,'https://es.wikipedia.org/wiki/Batalla_de_Flores_(Laredo)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186087,'02001','Batalla de flores (Albacete)','fiesta','fiestas_wiki','La Batalla de Flores es una de las tradiciones más populares y multitudinarias de la ciudad española de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Batalla_de_flores_(Albacete)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186088,'02071','Batalla del vino','fiesta','fiestas_wiki','La batalla del vino es una Fiesta de Interés Turístico Nacional,​ que se desarrolla anualmente durante la mañana del 29 de junio, festividad de San Pedro, en la ciudad de Haro (La Rioja) España. Consiste en remojar con vino tinto a otros participantes hasta quedar completamente morados y tiene lugar a unos seis km…',NULL,NULL,'https://es.wikipedia.org/wiki/Batalla_del_vino','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186089,'28514','Batalla naval de Vallecas','fiesta','fiestas_wiki','La batalla naval de Vallecas es una fiesta que se celebra en el distrito de Puente de Vallecas en Madrid, en la que los participantes se arrojan agua los unos a los otros. Se celebra el domingo del segundo o tercer fin de semana de julio, englobada en las fiestas populares de la Virgen del Carmen.',NULL,NULL,'https://es.wikipedia.org/wiki/Batalla_naval_de_Vallecas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186090,'07049','Bellea del foc','fiesta','fiestas_wiki','La bellea del foc​ (en español belleza del fuego) es la reina de las fiestas de la ciudad española de Alicante, las Hogueras de San Juan. La bellea va ataviada con el traje de novia alicantina y es la representante honorífica de los festejos sanjuaneros. Cuenta con seis damas de honor que reciben el nombre de dama…',NULL,NULL,'https://es.wikipedia.org/wiki/Bellea_del_foc','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186091,'16009','Beni de Cádiz','fiesta','fiestas_wiki','Benito Rodríguez Rey, conocido artísticamente como Beni de Cádiz (Cádiz, 26 de enero de 1930-Sevilla, 22 de diciembre de 1992), fue un cantaor flamenco español, hermano del también cantaor Amós Rodríguez Rey​y nieto del cantaor El Niño de la Isla.',NULL,NULL,'https://es.wikipedia.org/wiki/Beni_de_Cádiz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186092,'14020','Beñesmer','fiesta','fiestas_wiki','Beñesmer o Beñesmen es el nombre que daban los aborígenes guanches de la isla de Tenerife −Islas Canarias− al mes de agosto antes de la conquista castellana en el siglo xv, aplicándose por extensión también a las celebraciones de la cosecha desarrolladas en esa época.',NULL,NULL,'https://es.wikipedia.org/wiki/Beñesmer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186093,'02001','Bienal de Artes Plásticas Ciudad de Albacete','fiesta','fiestas_wiki','La Bienal de Artes Plásticas Ciudad de Albacete, conocida también como Bienal de Albacete, es una exposición internacional de artes plásticas que se celebra cada dos años en la ciudad española de Albacete.​​​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Bienal_de_Artes_Plásticas_Ciudad_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186094,'10203','Boda Regia','fiesta','fiestas_wiki','Boda Regia es un festival medieval que se celebra desde 2004 el primer fin de semana de agosto de cada año en el municipio cacereño de Valencia de Alcántara en España. En 2016 fue declarada Fiesta de Interés Turístico de Extremadura.',NULL,NULL,'https://es.wikipedia.org/wiki/Boda_Regia','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186095,'32086','Boteiro','fiesta','fiestas_wiki','El boteiro es la figura más emblemática del Entrudio o Carnaval de la comarca de Viana del Bollo. Según su área de procedencia, los trajes y dinámicas de los boteiros cambian.',NULL,NULL,'https://es.wikipedia.org/wiki/Boteiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186096,'49219','Bou (Toro) Capllaçat','fiesta','fiestas_wiki','El toro capllaçat ​ es una fiesta popular taurina típica en las comarcas del sur de Cataluña (Baix Ebre y Montsià) y en las comarcas del norte del País Valenciano . ​ El protagonista es un toro, el cual va atado de los cuernos por una cuerda delantera y una detrás sujetada por los corredores, los cuales pasean el…',NULL,NULL,'https://es.wikipedia.org/wiki/Bou_(Toro)_Capllaçat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186097,'03014','Bous a la Mar','fiesta','fiestas_wiki','Los Bous a la Mar (en español: Toros al Mar) son una modalidad de festejo popular taurino que tiene lugar en una plaza abierta al mar situada en el puerto o en las playas de las localidades donde se celebra.',38.84027778,0.10861111,'https://es.wikipedia.org/wiki/Bous_a_la_Mar','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186098,'12115','Bous al carrer','fiesta','fiestas_wiki','Los bous al carrer (en castellano toros en la calle), también llamado correbous o bous, es una fiesta taurina popular típica, donde se sueltan, conducen, torean o recortan las reses bravas sin que exista lidia de las mismas. En este sentido, se incluyen dentro de esta categoría la suelta de vaquillas, el toro…',NULL,NULL,'https://es.wikipedia.org/wiki/Bous_al_carrer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186099,'40158','Buengrado','fiesta','fiestas_wiki','Buengrado fue una localidad de la provincia de Segovia, actual comunidad autónoma de Castilla y León. Perteneció a la Comunidad de Villa y Tierra de Cuéllar, y estaba encuadrado dentro del Sexmo de Hontalbilla, en el actual término municipal de Perosillo. Anteriormente, en 1247, se denominaba Malgrado[1].',41.38,-4.14611111,'https://es.wikipedia.org/wiki/Buengrado','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186100,'90090','Butifuera','fiesta','fiestas_wiki','La Butifuera (también llamada botifuera o botijuela) es una fiesta de tradición agrícola muy popular en los pueblos de tradición olivarera de Andalucía, principalmente en la provincia de Jaén (España). Se celebra con ella el final de la recolección de aceituna, que comienza generalmente a finales de noviembre y…',NULL,NULL,'https://es.wikipedia.org/wiki/Butifuera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186101,'39076','Cabalgata de Reyes Magos Santillana del Mar','fiesta','fiestas_wiki','La Cabalgata de Reyes Magos de Santillana Del Mar es una Cabalgata de Reyes Magos con Auto sacramental que tiene lugar la tarde noche del 5 de enero en la Villa de Santillana Del Mar (Cantabria, España) lleva celebrándose desde 1959 y es la única Cabalgata de Reyes Magos junto a la de Alcoy (Alicante, España) en…',NULL,NULL,'https://es.wikipedia.org/wiki/Cabalgata_de_Reyes_Magos_Santillana_del_Mar','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186102,'03002','Cabalgata de Reyes Magos de Alcoy','fiesta','fiestas_wiki','La Cabalgata de Reyes Magos que se celebra el 5 de enero en Alcoy (Alicante, España) se considera como la más antigua de España, seguida de la de Igualada en 1895​ y la de San Vicente dels Horts en 1896.​ Está declarada fiesta de interés turístico nacional.​',38.6983,-0.4736,'https://es.wikipedia.org/wiki/Cabalgata_de_Reyes_Magos_de_Alcoy','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186103,'02001','Cabalgata de la Feria de Albacete','fiesta','fiestas_wiki','La Cabalgata de la Feria de Albacete es una de las tradiciones más populares y multitudinarias de la ciudad española de Albacete. Se realiza anualmente el 7 de septiembre como marco de inicio de la Feria de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Cabalgata_de_la_Feria_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186104,'46159','Cabalgata y Fiesta de la Cerámica (Manises)','fiesta','fiestas_wiki','La Cabalgata y Fiesta de la Cerámica es una fiesta que se celebra a mitad del mes de julio en Manises, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Cabalgata_y_Fiesta_de_la_Cerámica_(Manises)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186105,'19044','Caballada de Atienza','fiesta','fiestas_wiki','La Caballada de Atienza es el nombre coloquial de una Hermandad, originalmente de arrieros medievales, cuyo nombre oficial es Cofradía de la Santísima Trinidad, aunque por Caballada también se conoce la fiesta más popular que protagoniza esta entidad. La fiesta, que fue declarada de interés turístico nacional,​ se…',NULL,NULL,'https://es.wikipedia.org/wiki/Caballada_de_Atienza','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186106,'03027','Caballero Cubierto de Orihuela','fiesta','fiestas_wiki','El Caballero Cubierto de Orihuela (Alicante), también llamado Caballero Portaestandarte o Caballero Portaguión, es la persona designada anualmente por la corporación municipal de la ciudad, por su amor y lealtad a la ciudad, para portar el pendón-estandarte que abre la procesión del Santo Entierro de Cristo en…',NULL,NULL,'https://es.wikipedia.org/wiki/Caballero_Cubierto_de_Orihuela','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186107,'30015','Caballos del Vino','fiesta','fiestas_wiki','Los Caballos del Vino son un festejo que tiene lugar en Caravaca de la Cruz (Murcia), España, del 1 al 3 de mayo. Está organizado por el Bando de los Caballos del Vino, una federación compuesta por sesenta asociaciones denominadas «peñas caballistas». Las sesenta peñas, con sus respectivos caballos, participan en…',38.1075,-1.86,'https://es.wikipedia.org/wiki/Caballos_del_Vino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186108,'04065','Caganer','fiesta','fiestas_wiki','Un caganer es una figurita de nacimiento que se suele colocar en los belenes, como tradición en Cataluña, la Comunidad Valenciana y las Islas Baleares, normalmente escondida en un rincón, detrás de un arbusto, agachada y en postura de estar defecando.​ También es frecuente esta figura en los belenes de otros puntos…',NULL,NULL,'https://es.wikipedia.org/wiki/Caganer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186109,'37300','Calbote (fiesta)','fiesta','fiestas_wiki','Calbote, además del nombre tradicional de la castaña asada, da nombre también a la fiesta que se celebra el día de Todos los Santos (1 de noviembre) en algunas zonas de las provincias españolas de Zamora, Ávila, Salamanca, Cáceres,​ Badajoz y Toledo.',NULL,NULL,'https://es.wikipedia.org/wiki/Calbote_(fiesta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186110,'20069','Caldereros de San Sebastián','fiesta','fiestas_wiki','La fiesta de caldereros en San Sebastián (España) se desarrolla el primer sábado de febrero y es una de las más antiguas de la ciudad. Innumerables comparsas recorren las calles de la ciudad, elevando un clamor de sartenes y martillos mientras cientos de voces entonan las melodías de Raimundo Sarriegui y letra de…',NULL,NULL,'https://es.wikipedia.org/wiki/Caldereros_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186111,'30016','Californios (cofradía)','fiesta','fiestas_wiki','Californios es el sobrenombre por el que se conoce a los miembros de la Pontificia, Real e Ilustre Cofradía de Nuestro Padre Jesús en el Doloroso Paso del Prendimiento y Esperanza de la Salvación de las Almas de la ciudad española de Cartagena, fundada en 1747. Es una de las cuatro cofradías que procesionan cada…',NULL,NULL,'https://es.wikipedia.org/wiki/Californios_(cofradía)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186112,'02001','Calle Feria (Albacete)','fiesta','fiestas_wiki','La calle Feria o calle de la Feria es una de las calles más antiguas y emblemáticas de la ciudad española de Albacete.',38.995962,-1.860671,'https://es.wikipedia.org/wiki/Calle_Feria_(Albacete)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186113,'28079','Camilo Pérez Monllor','fiesta','fiestas_wiki','Camilo Pérez Monllor (Alcoy, Alicante, 25 de julio de 1877-Madrid, 4 de enero de 1947) fue un compositor y director de orquesta español. Su padre Camilo Pérez Laporta y su hermano Evaristo Pérez Monllor también fueron compositores y directores de orquesta.',NULL,NULL,'https://es.wikipedia.org/wiki/Camilo_Pérez_Monllor','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186114,'38035','Camino del Hermano Pedro','fiesta','fiestas_wiki','El camino del Hermano Pedro (también conocido como ruta del Hermano Pedro o ruta del camino del Hermano Pedro) es un antiguo camino de peregrinación, vinculado a la figura de San Pedro de Betancur (más conocido como Santo Hermano Pedro), quién es el primer santo de las Islas Canarias. Recorre aproximadamente 19…',NULL,NULL,'https://es.wikipedia.org/wiki/Camino_del_Hermano_Pedro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186115,'38032','Camino viejo de Candelaria (Tenerife)','fiesta','fiestas_wiki','El camino Viejo de Candelaria (también camino de Candelaria, camino real de Candelaria y camino de Nuestra Señora de Candelaria) es un antiguo camino de peregrinación, declarado en parte de su recorrido Bien de Interés Cultural, con categoría de Sitio Histórico, desde 2008.​​ Discurre por los términos municipales…',28.419752,-16.346935,'https://es.wikipedia.org/wiki/Camino_viejo_de_Candelaria_(Tenerife)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186116,'90288','Campanilleros','fiesta','fiestas_wiki','Los campanilleros son grupos de músicos tradicionales que en la región española de Andalucía y en partes de la de Extremadura y el sur de Castilla-La Mancha entonan canciones de carácter religioso con acompañamiento de guitarras, campanillas y otros instrumentos.​ Los coros de campanilleros cantan al alba los…',NULL,NULL,'https://es.wikipedia.org/wiki/Campanilleros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186117,'90465','Campaña navideña de Campofrío','fiesta','fiestas_wiki','La campaña navideña de Campofrío es una campaña publicitaria realizada desde 2011 por la empresa de alimentación Campofrío Food Group con temática navideña emitida en diciembre en España.',NULL,NULL,'https://es.wikipedia.org/wiki/Campaña_navideña_de_Campofrío');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186118,'44135','Cantabria Gaitera: Fiesta de la Cultura Popular','fiesta','fiestas_wiki','Cantabria Gaitera: Fiesta de la Cultura Popular fue una celebración organizada por la Asociación para la Defensa de los Intereses de Cantabria (ADIC). Tenía como principal objetivo la promoción de la gaita de fuelle, instrumento tradicional en el occidente de Cantabria, además de promocionar y difundir las…',NULL,NULL,'https://es.wikipedia.org/wiki/Cantabria_Gaitera:_Fiesta_de_la_Cultura_Popular');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186119,'03027','Canto de La Pasión de Orihuela','fiesta','fiestas_wiki','El Canto de La Pasión es una obra literaria y musical anónima del siglo XVIII. Forma parte de las acciones cuaresmales de Orihuela (Alicante).',NULL,NULL,'https://es.wikipedia.org/wiki/Canto_de_La_Pasión_de_Orihuela','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186120,'46021','Canto de la Alcachofa (Alacuás)','fiesta','fiestas_wiki','El Cant de la Carxofa es una representación religiosa que se realiza en varias localidades de la comarca de l''Horta Sud, así como en Vila-real y Caudete (Castilla-La Mancha) y que consiste en la realización de un canto tras una misa y procesión. En Alacuás se celebra los días 8 y 9 de septiembre de cada año en…',39.45833306,-0.46277806,'https://es.wikipedia.org/wiki/Canto_de_la_Alcachofa_(Alacuás)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186121,'06124','Capeas de Segura de León','fiesta','fiestas_wiki','Las Capeas de Segura de León es un festejo popular taurino que se celebra en la localidad de Segura de León (Badajoz) en septiembre con motivo del Cristo de la Reja.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Capeas_de_Segura_de_León','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186122,'02001','Capilla de la Feria','fiesta','fiestas_wiki','La capilla de la Feria, también conocida como capilla de la Virgen de los Llanos, es una capilla situada en el Recinto Ferial de Albacete, en la ciudad española de Albacete.',38.997199,-1.870439,'https://es.wikipedia.org/wiki/Capilla_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186123,'49219','Capuchino (toro)','fiesta','fiestas_wiki','Capuchino es el nombre del toro de la ganadería gaditana de Jandilla que corneó mortalmente al joven Daniel Jimeno Romero, de 27 años y natural de Alcalá de Henares (Madrid), en los Sanfermines de 2009. El astado, hijo de la vaca Capuchina, número 106, colorado, ojo de perdiz y de 515 kg, fue el gran protagonista…',NULL,NULL,'https://es.wikipedia.org/wiki/Capuchino_(toro)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186124,'44025','Caramellas','fiesta','fiestas_wiki','Las caramellas (en catalán, caramelles) son canciones populares típicas de la Cataluña Vieja, Andorra y del norte de la Nueva, que se cantan por Pascua para celebrar la resurrección de Jesús, aunque también pueden tener carácter profano. Los intérpretes son grupos de niños o adultos que salen a cantar por casas y…',NULL,NULL,'https://es.wikipedia.org/wiki/Caramellas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186125,'37344','Carasses','fiesta','fiestas_wiki','Las Carasses son una fiesta popular que consiste en que un grupo de personas disfrazadas y con la cara cubierta con una tela o una gasa pintada –o bien una máscara o careta– desfila por las calles al son de la música de la dulzaina y el tabal al ritmo de unas danzas particulares. Durante el recorrido, los…',NULL,NULL,'https://es.wikipedia.org/wiki/Carasses');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186126,'08008','Carles Flotats i Galtés','fiesta','fiestas_wiki','Carles Flotats i Galtés (Barcelona, 3 de noviembre de 1880-Canet de Mar, 10 de noviembre de 1949) fue un escultor e imaginero español.',NULL,NULL,'https://es.wikipedia.org/wiki/Carles_Flotats_i_Galtés','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186127,'18087','Carlos Cano','fiesta','fiestas_wiki','José Carlos Cano Fernández (Granada, 28 de enero de 1946​ - ibídem, 19 de diciembre de 2000​),​ artísticamente conocido como Carlos Cano, fue un cantautor español. Cultivó sobre todo la copla,​ aunque también el fandango, la habanera, el fado, el tango, el pasodoble, la nana, la murga y el bolero.',NULL,NULL,'https://es.wikipedia.org/wiki/Carlos_Cano','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186128,'16009','Carlos Edmundo de Ory','fiesta','fiestas_wiki','Carlos Edmundo de Ory (Cádiz, España, 27 de abril de 1923 - Thézy-Glimont, Picardía, Francia, 11 de noviembre de 2010​) fue un poeta, ensayista, epigramista y traductor español, principal representante del postismo. Fue hijo del poeta modernista Eduardo de Ory.',NULL,NULL,'https://es.wikipedia.org/wiki/Carlos_Edmundo_de_Ory','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186129,'41050','Carlos Herrera (periodista)','fiesta','fiestas_wiki','Carlos Herrera Crusset (Cuevas del Almanzora, Almería, 8 de julio de 1957) es un locutor de radio y presentador de televisión español. Desde el 1 de septiembre de 2015 dirige el matinal Herrera en COPE de la Cadena COPE. Desde 2004 hasta marzo de 2015 dirigió el matinal Herrera en la onda en la cadena de radio Onda…',NULL,NULL,'https://es.wikipedia.org/wiki/Carlos_Herrera_(periodista)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186130,'12040','Carlos Latre','fiesta','fiestas_wiki','Carlos Latre Ruiz (Castellón de la Plana, 30 de enero de 1979) es un humorista, actor, actor de doblaje, presentador, showman e imitador español. Es especialmente conocido por sus imitaciones de famosos y por formar parte del jurado del programa Tu cara me suena (2011-2024).',NULL,NULL,'https://es.wikipedia.org/wiki/Carlos_Latre','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186131,'02001','Carnaval de Albacete','fiesta','fiestas_wiki','Carnaval de Albacete, también conocido como Carnavales de Albacete, es una de las fiestas más populares de la ciudad española de Albacete. Tiene lugar inmediatamente antes de la Cuaresma cristiana, con fecha variable (entre febrero y marzo según el año).',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186132,'13001','Carnaval de Alcázar de San Juan','fiesta','fiestas_wiki','El Carnaval de Alcázar de San Juan, declarado fiesta de interés turístico Nacional,​ se caracteriza porque, a diferencia del resto de carnavales de España, se celebra en navidades. El día del entierro de la sardina coincide con el 28 de diciembre, día de los Santos Inocentes. El carnaval se celebra en Navidad,…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Alcázar_de_San_Juan','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186133,'16002','Carnaval de Algeciras','fiesta','fiestas_wiki','El Carnaval de Algeciras, llamado también Carnaval Especial utilizando el conocido epíteto de la ciudad, es una fiesta celebrada unos días antes del comienzo de la Cuaresma al modo de otros Carnavales andaluces.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Algeciras','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186134,'90628','Carnaval de Arrecife','fiesta','fiestas_wiki','La fecha de la que data el Carnaval de Arrecife (Lanzarote, Canarias, España) se desconoce, aunque se estima que su celebración comenzó con los primeros conquistadores allá por el siglo XV. Siendo Lanzarote la primera isla conquistada, existe la creencia, aunque sin constatar de manera documental, que se trata de…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Arrecife');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186135,'26002','Carnaval de Astorga','fiesta','fiestas_wiki','El carnaval de Astorga es una celebración anual que se celebra el Sábado de Piñata, primer sábado después del Miércoles de Ceniza, en la ciudad de Astorga, León, España. El comienzo de la fiesta se realiza con un pregón en la Plaza Mayor de Astorga. Seguidamente, se realiza un desfile de grupos y charangas para dar…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Astorga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186136,'06006','Carnaval de Badajoz','fiesta','fiestas_wiki','El Carnaval de Badajoz se celebra en la ciudad de Badajoz siendo su fiesta más identitaria y popular. Es la fiesta más multitudinaria de Extremadura y una de las más importantes de España. El gran desfile está considerado el mejor de Europa y cuenta con más de 11.000 participantes integrados en comparsas, grupos…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186137,'06006','Carnaval de Badajoz 2015','fiesta','fiestas_wiki','La XXXV edición del carnaval de Badajoz comenzó oficialmente el 13 de febrero de 2015 y finalizó el 17 de febrero de 2015.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2015','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186138,'06006','Carnaval de Badajoz 2016','fiesta','fiestas_wiki','La XXXVI edición del carnaval de Badajoz comenzó oficialmente el 5 de febrero de 2016 y finalizó el 9 de febrero de 2016.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2016','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186139,'06006','Carnaval de Badajoz 2017','fiesta','fiestas_wiki','La XXXVII edición del carnaval de Badajoz comenzó oficialmente el 24 de febrero de 2017 y finalizó el 28 de febrero de 2017',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2017','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186140,'06006','Carnaval de Badajoz 2018','fiesta','fiestas_wiki','La XXXVIII edición del carnaval de Badajoz comenzó oficialmente el 9 de febrero de 2018, y finalizó el 13 de febrero de 2018',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2018','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186141,'06006','Carnaval de Badajoz 2019','fiesta','fiestas_wiki','La XXXIX edición del carnaval de Badajoz comenzó oficialmente el 1 de marzo de 2019 y finalizó el 5 de marzo de 2019. Esta edición aspiraba a convertirse en Fiesta de interés turístico internacional, pero según informó el concejal de fiestas Miguel Ángel Rodríguez de la Calle, la fiesta tendrá que esperar un año…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2019','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186142,'06006','Carnaval de Badajoz 2020','fiesta','fiestas_wiki','La XL edición del carnaval de Badajoz comenzó oficialmente el 21 de febrero de 2020 y finalizó el 25 de febrero de 2020.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Badajoz_2020','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186143,'30016','Carnaval de Cartagena','fiesta','fiestas_wiki','Los Carnavales de Cartagena. En la Región de Murcia, España. Se caracteriza por ser un conjunto de actos que van desde el pregón, desfiles, elección de la reina del carnaval y chirigotas en el que sus participantes van disfrazados para la ocasión.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Cartagena','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186144,'16009','Carnaval de Cádiz','fiesta','fiestas_wiki','El Carnaval de Cádiz es uno de los carnavales más famosos e importantes de España, por lo que ha sido reconocido en 1980 conjuntamente con el Carnaval de Santa Cruz de Tenerife, con la declaración de Fiesta de Interés Turístico Internacional.​​ Ambos son los primeros carnavales de España con tal distinción.​…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Cádiz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186145,'14021','Carnaval de Córdoba','fiesta','fiestas_wiki','El carnaval de Córdoba es una fiesta popular de carácter lúdico y cultural que se celebra anualmente en la ciudad de Córdoba (Andalucía) durante las semanas previas al inicio de la Cuaresma. La festividad se divide principalmente en dos grandes bloques: el Concurso Oficial de Agrupaciones Carnavalescas (COAC),…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Córdoba','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186146,'16085','Carnaval de El Hierro','fiesta','fiestas_wiki','En el carnaval de la isla canaria de El Hierro (España), se conserva la costumbre, que se conoce hoy en día como Los Carneros de Tigaday, la cual se celebra en la localidad de Tigaday en el municipio de La Frontera. Se festeja el domingo y martes de Carnaval, esta consiste en un grupo de hombres disfrazados con…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_El_Hierro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186147,'13047','Carnaval de Herencia','fiesta','fiestas_wiki','El Carnaval de Herencia (Ciudad Real) España es una celebración declarada como Fiesta de Interés Turístico Nacional. Se celebra en el mes de febrero aunque no hay una fecha fija puesto que depende del calendario lunar que rige la celebración de la Semana Santa y, consecuentemente, la Cuaresma, que empieza justo el…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Herencia','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186148,'21042','Carnaval de Isla Cristina','fiesta','fiestas_wiki','El carnaval de Isla Cristina, en la provincia de Huelva, es uno de los más antiguos y famosos de España​ y está declarado como Fiesta de Interés Turístico de Andalucía,​ además de ser el carnaval andaluz que más interés suscita tras el de Cádiz.​​ Celebrado 40 días antes de la Semana Santa, coincidiendo el…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Isla_Cristina','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186149,'11020','Carnaval de Jerez','fiesta','fiestas_wiki','El Carnaval de Jerez es un carnaval de antigua tradición que se celebra en Jerez de la Frontera (Andalucía, España). Su carácter festivo, andaluz y sus referencias vitivinícolas lo dotan de una identidad propia.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Jerez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186150,'35020','Carnaval de La Aldea de San Nicolás','fiesta','fiestas_wiki','En la época de Carnaval que se celebra en la localidad de La Aldea de San Nicolás de la Isla de Gran Canaria (Islas Canarias, España), se ha recuperado elementos tradicionales como las máscaras; el uso de velos o paños para ocultar la cara; la vestimenta vieja; una vara de caña o un cestillo. A los niños también se…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_La_Aldea_de_San_Nicolás');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186151,'26009','Carnaval de La Bañeza','fiesta','fiestas_wiki','El Carnaval de La Bañeza (también llamado fiestas de invierno, carnavales, correr el carnaval, antruejo), en la provincia de León, es una fiesta declarada de Interés Turístico Nacional​​ que comienza a tomar importancia y fama a principios del siglo XX, en la represión franquista, debido a la prohibición expresa de…',42.30333333,-5.90305556,'https://es.wikipedia.org/wiki/Carnaval_de_La_Bañeza','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186152,'31140','Carnaval de Lanz','fiesta','fiestas_wiki','El Carnaval de Lanz es una de las fiestas más importantes que se celebran en Lanz y el más multitudinario de Navarra. Se trata de una fiesta de carácter tradicional que tiene lugar en los días que preceden al miércoles de Ceniza. Cuando cae la noche las calles de la villa se inundan con los vecinos representando a…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Lanz','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186153,'35016','Carnaval de Las Palmas de Gran Canaria','fiesta','fiestas_wiki','El Carnaval de Las Palmas de Gran Canaria es una de las fiestas más antiguas, con más historia y carácter propio de España, que se celebra en la ciudad del mismo nombre (Las Palmas de Gran Canaria). Más de cinco siglos de vida han hecho de esta fiesta popular la de mayor arraigo y una de las más multitudinarias del…',28.1272,-15.4314,'https://es.wikipedia.org/wiki/Carnaval_de_Las_Palmas_de_Gran_Canaria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186154,'38024','Carnaval de Los Llanos de Aridane','fiesta','fiestas_wiki','El Carnaval de Los Llanos de Aridane es una fiesta de carnaval celebrada en la localidad palmera de Los Llanos de Aridane (Islas Canarias, España). Se caracteriza por una manifestación que ha sido incorporada de manera oficial en el año 1993 la añeja tradición de las viejas: Las Viejas a Caballotas. Las Viejas a…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Los_Llanos_de_Aridane');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186155,'09208','Carnaval de Mecerreyes','fiesta','fiestas_wiki','El Carnaval de Mecerreyes es una fiesta tradicional que se celebra el domingo gordo o domingo de Carnaval en la localidad burgalesa de Mecerreyes de España.',42.0963283,-3.57234865,'https://es.wikipedia.org/wiki/Carnaval_de_Mecerreyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186156,'36011','Carnaval de Pontevedra','fiesta','fiestas_wiki','El Carnaval de Pontevedra (Entroido de Pontevedra en gallego) es una de las fiestas más emblemáticas de la ciudad española de Pontevedra, que combina tradición popular, humor, sátira y participación ciudadana. Se celebra antes de la Cuaresma y sus actos principales se desarrollan en el casco histórico y en las…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186157,'38011','Carnaval de Puerto de la Cruz','fiesta','fiestas_wiki','El Carnaval Internacional Puerto de la Cruz se celebra en el municipio canario de Puerto de la Cruz (Tenerife, España). En este carnaval destacan los siguientes eventos: Gran Gala de Elección de la Reina del Carnaval. Entierro de la sardina.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Puerto_de_la_Cruz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186158,'01902','Carnaval de Salcedo (Álava)','fiesta','fiestas_wiki','El Carnaval de Salcedo es una fiesta que se celebra en la época de los carnavales en el concejo de Salcedo perteneciente al municipio de Lantarón (Álava).',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Salcedo_(Álava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186159,'38012','Carnaval de Santa Cruz de Tenerife','fiesta','fiestas_wiki','El Carnaval de Santa Cruz de Tenerife es una de las fiestas más antiguas, con más historia y carácter propio de España y del mundo. Es considerado el segundo carnaval más popular y conocido internacionalmente, después de los que se celebran en Río de Janeiro (Brasil).​​​ De hecho, la ciudad de Santa Cruz de…',28.47,-16.25,'https://es.wikipedia.org/wiki/Carnaval_de_Santa_Cruz_de_Tenerife','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186160,'39079','Carnaval de Santoña','fiesta','fiestas_wiki','El Carnaval de Santoña, celebrado en los mese de febrero y marzo, es una de las celebraciones más emblemáticas de la villa de Santoña, en la comunidad autónoma de Cantabria.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Santoña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186161,'25207','Carnaval de Solsona','fiesta','fiestas_wiki','El Carnaval de Solsona es una fiesta popular que se celebra en la localidad de Solsona (Lérida) España. Empieza unos días antes del Jueves Lardero y acaba, como todo Carnaval tradicional, el Miércoles de Ceniza.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Solsona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186162,'42173','Carnaval de Soria','fiesta','fiestas_wiki','El Carnaval de Soria, Castilla y León (España), comienza siempre el jueves anterior al Miércoles de Ceniza. Los carnavales de Soria comienzan con una arraigada tradición, el Jueves Lardero, día en el que es típico merendar pan, chorizo y huevo. El resto de los días transcurren con los habituales desfiles de…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Soria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186163,'02073','Carnaval de Tarazona de la Mancha','fiesta','fiestas_wiki','El Carnaval es la fiesta más importante y conocida que se celebra en la localidad de Tarazona de la Mancha (Albacete). Está declarada como Fiesta de Interés Turístico Regional en Castilla-La Mancha desde el año 2013.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Tarazona_de_la_Mancha','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186164,'35024','Carnaval de Teguise','fiesta','fiestas_wiki','El Carnaval de Teguise se celebra en el municipio canario de Teguise (Lanzarote, España). El ritual festivo de Los diabletes, característico de este carnaval, tiene unas raíces que se remontan originariamente a América, y que fue importada por algún emigrante. Otras teorías mucho más creíbles apuntan a un origen…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Teguise');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186165,'45168','Carnaval de Toledo','fiesta','fiestas_wiki','El Carnaval de Toledo es una de las fiestas más llamativas de la ciudad de Toledo, España. Como cada año, se realizan una serie de concursos de disfraces y charangas (banda de música popular) así como el desfile que llama la atención por el gran número de carrozas y personas participantes. Hasta la edición de 2010,…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Toledo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186166,'20071','Carnaval de Tolosa','fiesta','fiestas_wiki','El Carnaval de Tolosa es el carnaval más emblemático de la provincia de Guipúzcoa , en el País Vasco (España).​',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Tolosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186167,'10212','Carnaval de Villanueva de la Vera','fiesta','fiestas_wiki','El Carnaval de Villanueva de la Vera es una fiesta considerada de las más representativas del carnaval tradicional que se celebra en el pueblo del mismo nombre, en la provincia de Cáceres, Extremadura, España, durante los días anteriores al Miércoles de Ceniza. La fiesta se concentra junto a un muñeco hecho de…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Villanueva_de_la_Vera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186168,'08307','Carnaval de Villanueva y Geltrú','fiesta','fiestas_wiki','El Carnaval de Villanueva y Geltrú es uno de los más tradicionales de toda España.[cita requerida] Su historia se remonta a más de 250 años​ de antigüedad y su acto más espectacular son "Las Comparsas" ("Les Comparses"), donde 3.000 personas salen a la calle con sus sociedades y acompañados por más de 30 charangas…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Villanueva_y_Geltrú','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186169,'02027','Carnaval de Villarrobledo','fiesta','fiestas_wiki','El Carnaval de Villarrobledo es la fiesta más importante y conocida que se celebra en el municipio español de Villarrobledo, en la provincia de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Villarrobledo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186170,'12138','Carnaval de Vinaroz','fiesta','fiestas_wiki','El carnaval de Vinaròs (en valenciano, carnestoltes de Vinaròs) es uno de los carnavales más famosos de la costa mediterránea española, por lo que ha sido reconocido como Fiesta de Interés Turístico Autonómico el 22 de febrero del 2007.​ Aun siendo una fiesta de larga tradición fue prohibida por decreto franquista,…',40.47044,0.47539,'https://es.wikipedia.org/wiki/Carnaval_de_Vinaroz','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186171,'01061','Carnaval de Zalduondo','fiesta','fiestas_wiki','El Carnaval de Zalduondo es una tradición que se celebra el domingo de Carnaval en la localidad alavesa de Zalduendo de Álava. Es considerado el carnaval más antiguo de Álava.',42.8859043,-2.34692107,'https://es.wikipedia.org/wiki/Carnaval_de_Zalduondo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186172,'30003','Carnaval de Águilas','fiesta','fiestas_wiki','El Carnaval de Águilas llevado a cabo en el municipio de Águilas, es el carnaval más emblemático de la Región de Murcia y uno de los más famosos de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_de_Águilas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186173,'49219','Carnaval del Toro','fiesta','fiestas_wiki','El Carnaval del Toro está considerado uno de los festejos más antiguos de España, junto con los carnavales de Ciudad Rodrigo, son una de las fiestas más populares de esta localidad salmantina.​ Se conocen como Carnaval del toro por unir en una misma celebración dos tradiciones, la taurina y la carnavalesca. En este…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_del_Toro','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186174,'41059','Carnaval en Andalucía','fiesta','fiestas_wiki','Entre las muchas localidades de Andalucía en que se celebra el carnaval, se encuentran: Alcalá de Guadaíra, ciudad de la provincia de Sevilla. Mairena del Aljarafe, municipio de la provincia de Sevilla. Algeciras, municipio de la provincia de Cádiz.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_en_Andalucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186175,'25001','Carnaval en España','fiesta','fiestas_wiki','El Carnaval en España es una antigua celebración festiva documentada desde la Edad Media y con una rica personalidad propia a partir del Renacimiento que ha quedado recogida en la literatura española y otras artes localizadas en los diferentes pueblos que componen el Estado español.​ Como en el resto de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_en_España');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186176,'30030','Carnaval en la región de Murcia','fiesta','fiestas_wiki','En la región de Murcia el carnaval se celebra en diferentes poblaciones repartidas por toda la provincia, habiendo grandes diferencias entre algunos de ellos, especialmente entre los más antiguos. El carnaval más importante de la Región de Murcia es el de Águilas, declarado de interés turístico internacional y…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_en_la_región_de_Murcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186177,'46253','Carnaval en los Pirineos','fiesta','fiestas_wiki','Debido al aislamiento de los valles pirenaicos, en estos se han conservado carnavales tradicionales en los que se han mezclado elementos paganos, con elementos judeocristianos.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_en_los_Pirineos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186178,'50007','Carnaval rural ILEGAN','fiesta','fiestas_wiki','El Carnaval Rural ILEGAN es una fiesta que se celebra todos los años en los concejos alaveses de Ilarduia, Egino y Andoin, del municipio de Aspárrena. Se celebrar el sábado anterior al jueves de Lardero.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_rural_ILEGAN');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186179,'01901','Carnaval rural de Villodas','fiesta','fiestas_wiki','El carnaval rural de Villodas es una tradición que se celebra en el concejo de Villodas, en el municipio de Iruña de Oca en Álava.',NULL,NULL,'https://es.wikipedia.org/wiki/Carnaval_rural_de_Villodas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186180,'31129','Carnavales de Ituren y Zubieta','fiesta','fiestas_wiki','Los Carnavales de Ituren y Zubieta son una fiesta de interés turístico en la comarca del Alto Bidasoa, en el valle de Malerreka (Navarra). Se desarrollan tomando como referencia el último domingo de enero. Ambas localidades navarras se anticipan a las fechas oficiales del carnaval para celebrar uno muy singular el…',43.12894,-1.70722,'https://es.wikipedia.org/wiki/Carnavales_de_Ituren_y_Zubieta','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186181,'90641','Carnavales en la cultura popular vasca','fiesta','fiestas_wiki','A los carnavales de distintos pueblos del País Vasco, Navarra y País Vasco francés se les llama en euskera dependiendo de los dialectos iñauteriak, ihoteak o inoteak. En algunas zonas como Guipúzcoa, a todo el proceso del Carnaval le dan el nombre que se da a uno de los días, por ejemplo Astearteak, los martes (en…',NULL,NULL,'https://es.wikipedia.org/wiki/Carnavales_en_la_cultura_popular_vasca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186182,'49176','Carochos','fiesta','fiestas_wiki','Los Carochos son los personajes de una mascarada invernal celebrada principalmente en Riofrío de Aliste (provincia de Zamora).​ Poseen ciertas similitudes con las mascaradas asturianas (las denominadas zamarronadas),​​ y en menor medida a las celebraciones invernales de origen gallego y leonesas («zafarronadas»).…',NULL,NULL,'https://es.wikipedia.org/wiki/Carochos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186183,'05051','Carrera de cintas a caballo','fiesta','fiestas_wiki','La carrera de cintas a caballo es un juego que se celebra en la mayoría de localidades españolas, probablemente de origen Vetton, evolucionó hasta la Edad Media inspirado en los torneos y justas de época medieval, la costumbre se extendió durante tiempos coloniales en América Latina.',NULL,NULL,'https://es.wikipedia.org/wiki/Carrera_de_cintas_a_caballo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186184,'05051','Carrera del encierro','fiesta','fiestas_wiki','La Carrera del Encierro de Pamplona, denominada anteriormente como Cross del Encierro, es una competición atlética celebrada anualmente en la capital de la Comunidad Foral de Navarra desde el año 1984 los días previos a los San Fermines.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Carrera_del_encierro','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186185,'05051','Carrera oficial','fiesta','fiestas_wiki','La carrera oficial es el recorrido obligado que, en muchas localidades españolas, han de efectuar todas las cofradías que llevan a cabo la procesión de penitencia durante la Semana Santa.',NULL,NULL,'https://es.wikipedia.org/wiki/Carrera_oficial');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186186,'05051','Carrera urbana internacional Noche de San Antón','fiesta','fiestas_wiki','La Carrera Urbana Internacional Noche de San Antón es una carrera que tiene lugar en Jaén (Andalucía, España), el fin de semana más próximo a las Fiestas de San Antón.',NULL,NULL,'https://es.wikipedia.org/wiki/Carrera_urbana_internacional_Noche_de_San_Antón','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186187,'11032','Carreras de caballos de Sanlúcar','fiesta','fiestas_wiki','Las carreras de caballos de Sanlúcar son una competición hípica que se celebran anualmente en la playa del municipio español de Sanlúcar de Barrameda, en Andalucía.​',NULL,NULL,'https://es.wikipedia.org/wiki/Carreras_de_caballos_de_Sanlúcar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186188,'04031','Carretillas de Cantoría','fiesta','fiestas_wiki','Las Carretillas de Cantoria es un festejo que se celebra en la localidad de Cantoria (provincia de Almería) en la noche del 16 de enero y como antesala a la fiesta de San Antonio Abad, patrón de dicha localidad.',NULL,NULL,'https://es.wikipedia.org/wiki/Carretillas_de_Cantoría');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186189,'50227','Carthagineses y Romanos','fiesta','fiestas_wiki','Carthagineses son unas fiestas de carácter histórico que desde 1990 se celebran en la ciudad española de Cartagena, durante la segunda quincena del mes de septiembre para conmemorar los hechos históricos acaecidos en la ciudad durante la segunda guerra púnica. Se rememoran acontecimientos como la fundación de Qart…',NULL,NULL,'https://es.wikipedia.org/wiki/Carthagineses_y_Romanos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186190,'49189','Carvallar de San Justo','fiesta','fiestas_wiki','La Carballeira de San Xusto es un robledal que se encuentra en la parroquia de San Xurxo de Sacos (Cerdedo-Cotobade), en una loma sobre lo río Lérez.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Carvallar_de_San_Justo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186191,'30033','Casa Museo de las Cofradías (Puerto Lumbreras)','fiesta','fiestas_wiki','La casa Museo de las Cofradías se sitúa en la calle Francisco Tirado de la localidad de Puerto Lumbreras (Región de Murcia, España), junto a la Casa de los Duendes y próxima a la Iglesia Parroquial de Nuestra Señora del Rosario. Inaugurada en el año 2012,​ se emplaza en un edificio con una superficie de casi 1200…',37.55930556,-1.81147222,'https://es.wikipedia.org/wiki/Casa_Museo_de_las_Cofradías_(Puerto_Lumbreras)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186192,'38023','Casa del Carnaval (Santa Cruz de Tenerife)','fiesta','fiestas_wiki','La Casa del Carnaval es un museo ubicado en la ciudad de Santa Cruz de Tenerife (Islas Canarias, España) y dedicado a esta fiesta carnavalera, la cual tiene la categoría de Fiesta de Interés Turístico Internacional.',28.46470389,-16.25600306,'https://es.wikipedia.org/wiki/Casa_del_Carnaval_(Santa_Cruz_de_Tenerife)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186193,'18087','Cascamorras','fiesta','fiestas_wiki','El Cascamorras es una fiesta española de "Interés Turístico Internacional" que se celebra cada año en las ciudades de Baza y de Guadix, en el centro-norte de la provincia de Granada. Desde 2006 estaba declarada como "Fiesta de Interés Turístico Nacional". En el año 2013, la fiesta de Cascamorras fue declarada como…',NULL,NULL,'https://es.wikipedia.org/wiki/Cascamorras','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186194,'06049','Caseta de feria andaluza','fiesta','fiestas_wiki','Las casetas son recintos acotados por paredes de tela y techados. Referente a ferias, particularmente a la feria en Andalucía (España), por ejemplo, para animar el ambiente se ponen sevillanas, que son canciones populares. Normalmente tienen un tablao para bailar.',NULL,NULL,'https://es.wikipedia.org/wiki/Caseta_de_feria_andaluza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186195,'02001','Caseta de los Jardinillos','fiesta','fiestas_wiki','La Caseta de los Jardinillos es un recinto multiusos al aire libre diseñado para albergar todo tipo de eventos, espectáculos y conciertos situado en el paseo de la Feria de la ciudad española de Albacete. Su mayor protagonismo se produce durante la famosa Feria de Albacete, declarada de Interés Turístico…',38.99713056,-1.866925,'https://es.wikipedia.org/wiki/Caseta_de_los_Jardinillos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186196,'90641','Caso de La Manada','fiesta','fiestas_wiki','El caso de La Manada es el nombre por el que se conocen los sucesos relacionados con un caso de violación múltiple acaecido en Pamplona (Navarra, España), en la madrugada del 7 de julio de 2016, durante las fiestas de San Fermín. Un grupo de cinco hombres violó a una joven de dieciocho años en un portal en el…',NULL,NULL,'https://es.wikipedia.org/wiki/Caso_de_La_Manada','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186197,'41091','Cayetano González','fiesta','fiestas_wiki','Cayetano González Gómez (Málaga, 9 de diciembre de 1896-Sevilla, 2 de septiembre de 1975), fue un orfebre español conocido principalmente por las obras que realizó para diferentes hermandades y cofradías de la Semana Santa de Sevilla.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Cayetano_González','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186198,'41095','Cayetano Utrera Ravassa','fiesta','fiestas_wiki','Cayetano Utrera Ravassa (Málaga, 17 de diciembre de 1938 - Málaga, 17 de agosto de 2012) fue un político español, alcalde de Málaga durante la dictadura franquista.',NULL,NULL,'https://es.wikipedia.org/wiki/Cayetano_Utrera_Ravassa','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186199,'40063','Cecilio de Benito','fiesta','fiestas_wiki','Cecilio de Benito Sánchez (Cuéllar, 1869 – ib., 1940) fue un músico, compositor y director español.',NULL,NULL,'https://es.wikipedia.org/wiki/Cecilio_de_Benito','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186200,'36015','Celebración de la Reconquista','fiesta','fiestas_wiki','La Celebración de la Reconquista de Vigo es una fiesta carácter histórico que se celebra en la zona vieja de la ciudad de Vigo (Galicia), entre finales de marzo y principios de abril. La fecha oficial es el 28 de marzo (festivo local en Vigo),​ pero se hace coincidir en fin de semana según el calendario anual. En…',NULL,NULL,'https://es.wikipedia.org/wiki/Celebración_de_la_Reconquista','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186201,'30011','Celedón','fiesta','fiestas_wiki','Celedón es el personaje cuya llegada, bajando del cielo con un paraguas, abre las fiestas patronales de Vitoria,​ capital de la provincia vasca de Álava. Las fiestas de Vitoria se celebran en honor a la Virgen Blanca (Andre Mari Zuria), cuya festividad se conmemora el 5 de agosto. Los festejos comienzan un día…',NULL,NULL,'https://es.wikipedia.org/wiki/Celedón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186202,'06110','Celia Cruz','fiesta','fiestas_wiki','Celia Caridad Cruz y Alfonso​ (La Habana, 21 de octubre de 1925-Fort Lee, Nueva Jersey, 16 de julio de 2003), más conocida como Celia Cruz, fue una cantante cubana de música tropical. Apodada la Reina de la Salsa​ y la Guarachera de Cuba,​es ampliamente considerada como una de las artistas latinas más populares e…',NULL,NULL,'https://es.wikipedia.org/wiki/Celia_Cruz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186203,'49248','Celia Villalobos','fiesta','fiestas_wiki','Celia Villalobos Talero (Arroyo de la Miel, Benalmádena, Málaga, 18 de abril de 1949) es una funcionaria y expolítica española, que fue diputada en el Congreso por Málaga desde el año 1986, durante diez legislaturas. Ha sido ministra de Sanidad y Consumo, alcaldesa de Málaga y ha ocupado diversos cargos de…',NULL,NULL,'https://es.wikipedia.org/wiki/Celia_Villalobos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186204,'18087','Centro de Estudios Cofrades','fiesta','fiestas_wiki','El Centro de Estudios Cofrades (CEC) es un órgano dependiente de la Federación de Hermandades y Cofradías de Granada que fue creado en 2014.',37.17305556,-3.60111111,'https://es.wikipedia.org/wiki/Centro_de_Estudios_Cofrades','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186205,'45034','Centro de Interpretación Pecados y Danzantes','fiesta','fiestas_wiki','El Centro de Interpretación Pecados y Danzantes es un museo etnográfico que gira en torno a la fiesta de los Pecados y Danzantes, ubicado en el municipio de Camuñas de la provincia de Toledo.​',39.42571667,-3.45991667,'https://es.wikipedia.org/wiki/Centro_de_Interpretación_Pecados_y_Danzantes','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186206,'36023','Centuria Romana Macarena','fiesta','fiestas_wiki','La Centuria Romana Macarena es un grupo que procesiona vestido como la Guardia Pretoriana de Poncio Pilato. Acompañan el paso del Jesús de la Sentencia de la Hermandad de la Esperanza Macarena, durante su estación de penitencia de la madrugada del Viernes Santo de la Semana Santa de Sevilla.',NULL,NULL,'https://es.wikipedia.org/wiki/Centuria_Romana_Macarena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186207,'07046','Cerdo del Concejo','fiesta','fiestas_wiki','El cerdo del Concejo (denominado también rey de los cochinos) fue una tradición popular del mundo rural, mediante la cual se cuidaba colectivamente un cerdo que se ponía a disposición del concejo.​ La celebración pronto se asoció a San Antonio Abad (protector de las bestias útiles al hombre). La celebración…',NULL,NULL,'https://es.wikipedia.org/wiki/Cerdo_del_Concejo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186208,'03038','Certamen Internacional de Habaneras y Polifonía de Torrevieja','fiesta','fiestas_wiki','El Certamen Internacional de Habaneras y Polifonía de Torrevieja es un concurso internacional de música coral especializado en habaneras y polifonía que se celebra desde 1955 en la localidad española de Torrevieja, en la provincia de Alicante. Está declarado Fiesta de Interés Turístico Internacional desde 1994.',37.97777778,-0.68333333,'https://es.wikipedia.org/wiki/Certamen_Internacional_de_Habaneras_y_Polifonía_de_Torrevieja','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186209,'22074','Chaquetía','fiesta','fiestas_wiki','En determinadas partes de Extremadura, se denomina chaquetía a la merienda del día 1 o 2 de noviembre que se hace en el campo y en la que se consumen frutos del tiempo como higos pasos, nueces, bellotas, granadas, castañas y preparados como el dulce de membrillo y también ciertas tortas típicas, bollas, o panes…',NULL,NULL,'https://es.wikipedia.org/wiki/Chaquetía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186210,'46079','Chirigota','fiesta','fiestas_wiki','La chirigota es una agrupación musical coral del Carnaval en España que canta principalmente por las calles ofreciendo coplas humorísticas a la ciudad. Las chirigotas canta coplas y poseen unas formas musicales muy simples procedentes del pasodoble, la rumba, el tanguillo, la seguidilla, la jota, la isa canaria,…',NULL,NULL,'https://es.wikipedia.org/wiki/Chirigota');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186211,'10195','Chíviri','fiesta','fiestas_wiki','El chíviri es una fiesta de interés turístico en la que miles de personas se visten con trajes tradicionales y cantan y bailan formando corros al ritmo de canciones populares. Se celebra en la Plaza Mayor del pueblo español de Trujillo el Domingo de Pascua, como culminación de la Semana Santa Trujillana. El lunes…',39.46527778,-5.87888889,'https://es.wikipedia.org/wiki/Chíviri','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186212,'32054','Cigarrón','fiesta','fiestas_wiki','Se llama cigarrón al traje característico del entroido de Verín, provincia de Orense, Galicia, España. La máscara está compuesta por una careta de madera pintada de colores llamativos, que se prolonga en una especie de mitra de metal con un motivo de animales o astros león, lobo, vaca, buey. A diferencia del…',NULL,NULL,'https://es.wikipedia.org/wiki/Cigarrón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186213,'50297','Cincomarzada','fiesta','fiestas_wiki','La Cincomarzada fue un enfrentamiento entre zaragozanos isabelinos y carlistas que tuvo lugar el 5 de marzo de 1838.​ Se celebra anualmente como fiesta popular en Zaragoza, en el parque del Tío Jorge con comida y bebida traída por los propios ciudadanos y amenizada con música y juegos.',NULL,NULL,'https://es.wikipedia.org/wiki/Cincomarzada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186214,'50251','Cipotegato','fiesta','fiestas_wiki','El Cipotegato es la tradición más universal de Tarazona y tiene lugar cada año el día 27 de agosto.​ La fiesta fue declarada de interés regional aragonés en 1998 y de interés nacional en 2009.​',NULL,NULL,'https://es.wikipedia.org/wiki/Cipotegato','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186215,'40057','Coca amb tonyina','fiesta','fiestas_wiki','La coca amb tonyina o coca en toñina​​ (en español: coca con atún) es una coca típica de la cocina alicantina, muy relacionada con las Hogueras de San Juan en la provincia española de Alicante.​ Tiene forma de empanada rectangular, en porciones, y suele comerse los días de la fiesta en la calle, bien sea en una…',NULL,NULL,'https://es.wikipedia.org/wiki/Coca_amb_tonyina','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186216,'50297','Codorníu','fiesta','fiestas_wiki','Codorníu (Grupo Raventós - Codorníu) es un grupo empresarial de origen español y propiedad estadounidense (la mayoría de sus acciones pertenecen al fondo de inversión Carlyle), dedicado a la producción de cava y vino. Fundada en España en 1551, es una de las empresas más antiguas del país; siendo la Casa de…',NULL,NULL,'https://es.wikipedia.org/wiki/Codorníu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186217,'05219','Cofradía Penitencial de La Oración del Huerto y San Pascual Bailón','fiesta','fiestas_wiki','La Cofradía Penitencial de La Oración del Huerto y San Pascual Bailón es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_de_La_Oración_del_Huerto_y_San_Pascual_Bailón','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186218,'47186','Cofradía Penitencial de Nuestro Padre Jesús Nazareno (Valladolid)','fiesta','fiestas_wiki','La Insigne Cofradía Penitencial de Nuestro Padre Jesús Nazareno, fundada en 1596, es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid. Cofradía de gran arraigo y tradición, es una de las cinco penitenciales históricas. Su imagen titular, Nuestro Padre Jesús Nazareno (Escuela…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_de_Nuestro_Padre_Jesús_Nazareno_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186219,'37273','Cofradía Penitencial de la Sagrada Pasión de Cristo','fiesta','fiestas_wiki','La Cofradía Penitencial de la Sagrada Pasión de Cristo es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid. Es una de las cinco penitenciales históricas.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_de_la_Sagrada_Pasión_de_Cristo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186220,'47186','Cofradía Penitencial de la Santa Vera Cruz (Valladolid)','fiesta','fiestas_wiki','La Cofradía Penitencial de la Santa Vera Cruz es la más antigua (su fundación data de principios del siglo XV) de las 20 cofradías penitenciales que existen, en la actualidad, en la Semana Santa de Valladolid. Es una de las cinco cofradías históricas con continuidad desde sus comienzos. Tiene su sede en la Iglesia…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_de_la_Santa_Vera_Cruz_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186221,'47186','Cofradía Penitencial del Santísimo Cristo Despojado, Cristo Camino del Calvario y Nuestra Señora de la Amargura','fiesta','fiestas_wiki','La Real Cofradía Penitencial del Santísimo Cristo Despojado, Cristo Camino del Calvario y Nuestra Señora de la Amargura es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_del_Santísimo_Cristo_Despojado,_Cristo_Camino_del_Calvario_y_Nuestra_Señora_de_la_Amargura','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186222,'37273','Cofradía Penitencial y Sacramental de la Sagrada Cena','fiesta','fiestas_wiki','La Cofradía Penitencial y Sacramental de la Sagrada Cena es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_Penitencial_y_Sacramental_de_la_Sagrada_Cena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186223,'50297','Cofradía de Cristo Abrazado a la Cruz y de la Verónica (Zaragoza)','fiesta','fiestas_wiki','La cofradía de Cristo Abrazado a la Cruz y de la Verónica, fundada en 1992 como cofradía penitencial, es una de las 25 hermandades que forman la Semana Santa de la Inmortal Ciudad de Zaragoza. Fiesta declarada de Interés Turístico Nacional. [1].',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Cristo_Abrazado_a_la_Cruz_y_de_la_Verónica_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186224,'03027','Cofradía de El Lavatorio (Orihuela)','fiesta','fiestas_wiki','La Real Archicofradía y Mayordomía de Nuestra Señora del Pilar y Real Cofradía de "El Lavatorio" o Real Cofradía de El Lavatorio abreviado es una agrupación pasional fundada en el año 1758. Desfila el Miércoles Santo y el Viernes Santo en la Semana Santa de Orihuela.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_El_Lavatorio_(Orihuela)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186225,'29067','Cofradía de Jesús "El Rico" (Málaga)','fiesta','fiestas_wiki','La Hermandad del Rico, cuya denominación oficial es Real, Excelentísima, Muy Ilustre y Venerable Cofradía de Culto y Procesión de Nuestro Padre Jesús Nazareno Titulado “El Rico” y María Santísima del Amor , es una hermandad de Málaga, miembro de la Agrupación de Cofradías, que participa en la Semana Santa malagueña.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Jesús_"El_Rico"_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186226,'50297','Cofradía de Jesús Camino del Calvario','fiesta','fiestas_wiki','La Cofradía de Jesús Camino del Calvario es una cofradía de la Semana Santa de Zaragoza. Fue fundada en el año 1938 por un grupo de hombres piadosos que se agrupaban y portaban el paso de la Verónica (o de Jesús Camino del Calvario) en la procesión del Santo Entierro, en el Viernes Santo de 1935. La cofradía…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Jesús_Camino_del_Calvario','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186227,'23060','Cofradía de Jesús Cautivo y María Santísima de la Trinidad (Martos)','fiesta','fiestas_wiki','La Cofradía de Nuestro Padre Jesús Cautivo de la Túnica Blanca y María Santísima de la Trinidad en su Mayor Dolor y Desamparo es una de las agrupaciones de pasión religiosas de la ciudad de Martos (Jaén), España cuyo Hermano Mayor es Juan Moreno Miranda (28 de junio de 2005). Tiene su sede en el Monasterio de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Jesús_Cautivo_y_María_Santísima_de_la_Trinidad_(Martos)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186228,'04063','Cofradía de Jesús de la Humillación, María Santísima de la Amargura, San Felipe y Santiago el Menor','fiesta','fiestas_wiki','La Cofradía de Jesús de la Humillación, María Santísima de la Amargura, San Felipe y Santiago el Menor fundada en 1991, es una de las cofradías que participan en los actos de Semana Santa en Zaragoza (España)',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Jesús_de_la_Humillación,_María_Santísima_de_la_Amargura,_San_Felipe_y_Santiago_el_Menor','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186229,'02071','Cofradía de Jesús de la Soledad ante las Negaciones de San Pedro y de San Lamberto','fiesta','fiestas_wiki','La Cofradía de Jesús de la Soledad ante las Negaciones de San Pedro y de San Lamberto es la más reciente de las 25 cofradías de la Semana Santa en Zaragoza, constituida como cofradía penitencial el 21 de marzo de 2017.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Jesús_de_la_Soledad_ante_las_Negaciones_de_San_Pedro_y_de_San_Lamberto','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186230,'50297','Cofradía de Nuestra Señora de la Asunción y Llegada de Jesús al Calvario','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora de la Asunción y Llegada de Jesús al Calvario es una cofradía penitencial fundada en 1953 en Zaragoza y es una de las 25 participantes en la procesión general del Santo Entierro.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_la_Asunción_y_Llegada_de_Jesús_al_Calvario','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186231,'02001','Cofradía de Nuestra Señora de la Esperanza Macarena (Albacete)','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora Reina de la Esperanza Macarena, Santísimo Cristo de la Esperanza y Traición de Judas es una cofradía de la Semana Santa de Albacete (España).​​ Tiene su sede canónica en la Iglesia de San Francisco de Asís. Fue fundada en 1945 en el seno del Colegio Oficial de Agentes Comerciales de…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_la_Esperanza_Macarena_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186232,'47186','Cofradía de Nuestra Señora de la Piedad (Valladolid)','fiesta','fiestas_wiki','La Muy Ilustre Cofradía Penitencial de Nuestra Señora de la Piedad es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa en Semana Santa de Valladolid. Su fecha de fundación data en torno a 1504, pero su primera regla no fue aprobada hasta 1578. Es una de las cinco penitenciales históricas.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_la_Piedad_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186233,'50297','Cofradía de Nuestra Señora de la Piedad y del Santo Sepulcro','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora de la Piedad y del Santo Sepulcro, fundada en 1937 como cofradía penitencial, es una de las 25 participantes en la Semana Santa en Zaragoza y la más antigua de la ciudad. La cofradía está formada únicamente por hombres: las mujeres tan sólo pueden salir como manolas acompañando a la…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_la_Piedad_y_del_Santo_Sepulcro','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186234,'02001','Cofradía de Nuestra Señora de la Soledad (Albacete)','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora de la Soledad y Ecce Homo es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Iglesia de Nuestra Señora del Pilar. Fue fundada en 1896 formando parte del Santísimo Cristo de la Agonía si bien la cofradía ya existía como hermandad en el siglo XV.…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_la_Soledad_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186235,'02001','Cofradía de Nuestra Señora de los Dolores (Albacete)','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora de los Dolores, Jesús de la Pasión en su caída y Cristo Resucitado, más conocida como La Dolorosa, es una cofradía de la Semana Santa de Albacete (España). Es la cofradía más antigua de Castilla-La Mancha.​​ Tiene su sede canónica en la Catedral de San Juan Bautista de Albacete. Fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_de_los_Dolores_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186236,'02001','Cofradía de Nuestra Señora del Mayor Dolor','fiesta','fiestas_wiki','La Cofradía de Nuestra Señora del Mayor Dolor es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Iglesia de Fátima. Fue fundada en 1954 en las Escuelas Pías de Albacete. Cuenta con seis imágenes: Entrada Triunfal en Jerusalén (1955), Jesús Cautivo en su Prendimiento (1990), La…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestra_Señora_del_Mayor_Dolor','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186237,'02001','Cofradía de Nuestro Padre Jesús Nazareno (Albacete)','fiesta','fiestas_wiki','La Cofradía de Nuestro Padre Jesús Nazareno es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Catedral de San Juan Bautista de Albacete. Fue fundada en 1884 como asociación religiosa en torno a la imagen del Nazareno venerada en la Catedral. Cuenta con seis imágenes: Nuestro…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestro_Padre_Jesús_Nazareno_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186238,'10037','Cofradía de Nuestro Padre Jesús Nazareno (Cáceres)','fiesta','fiestas_wiki','La Pontificia y Real Cofradía de Nuestro Padre Jesús Nazareno y Nuestra Señora de la Misericordia es una cofradía católica de la ciudad española de Cáceres. Participa en la Semana Santa de dicha ciudad. Su origen data de 1464, según un libro de ordenanzas que se conserva en los archivos históricos de la cofradía.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestro_Padre_Jesús_Nazareno_(Cáceres)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186239,'30030','Cofradía de Nuestro Padre Jesús Nazareno (Murcia)','fiesta','fiestas_wiki','La Real y Muy Ilustre Cofradía de Nuestro Padre Jesús Nazareno es una cofradía de culto católico de la Semana Santa de Murcia (Región de Murcia, España) que desfila en la mañana del Viernes Santo por las calles de la ciudad. Los Moraos o Los Salzillos; como se le denomina popularmente, es una de las instituciones…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestro_Padre_Jesús_Nazareno_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186240,'47186','Cofradía de Nuestro Padre Jesús Resucitado y María Santísima de la Alegría (Valladolid)','fiesta','fiestas_wiki','La Cofradía de Nuestro Padre Jesús Resucitado, María Santísima de la Alegría y las Lágrimas de San Pedro es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestro_Padre_Jesús_Resucitado_y_María_Santísima_de_la_Alegría_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186241,'02001','Cofradía de Nuestro Padre Jesús de la Oración en el Huerto (Albacete)','fiesta','fiestas_wiki','La Cofradía de Nuestro Padre Jesús de la Oración en el Huerto es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Iglesia de Fátima. Fue fundada en 1984 por miembros de la asociación religiosa de la Adoración Nocturna. Cuenta con tres imágenes: Nuestro Padre Jesús de la Oración…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Nuestro_Padre_Jesús_de_la_Oración_en_el_Huerto_(Albacete)','IT Nacional');
