INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186244,'04063','Cofradía de Santa María Magdalena','fiesta','fiestas_wiki','La Cofradía de Santa María Magdalena es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Iglesia de Fátima. Fue fundada en 1987 por un grupo de mujeres de la Cofradía de Nuestra Señora del Mayor Dolor, siendo la primera cofradía formada y dirigida solo por mujeres (aunque en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_Santa_María_Magdalena','IT Nacional');
