INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186246,'30030','Cofradía de la Caridad (Murcia)','fiesta','fiestas_wiki','La Muy Ilustre y Venerable Cofradía del Santísimo Cristo de la Caridad es una cofradía de culto católico que tiene su sede canónica en la Iglesia de Santa Catalina de la ciudad de Murcia (España). Participa en la Semana Santa de Murcia desfilando en la jornada de Sábado de Pasión. Desde el año 2013 también organiza…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_la_Caridad_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186247,'50297','Cofradía de la Columna (Zaragoza)','fiesta','fiestas_wiki','La Real, Pontificia, Antiquísima, Ilustre, Franciscana y Penitencial Hermandad y Cofradía del Señor Atado a la Columna y de Nuestra Señora de la Fraternidad en el Mayor Dolor fundada en 1804, es una cofradía de Zaragoza (España) que participa en las procesiones y actos de la Semana Santa de esta ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_la_Columna_(Zaragoza)','IT Internacional');
