INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186250,'90289','Cofradía de la Entrada de Jesús en Jerusalén (Albalate del Arzobispo)','fiesta','fiestas_wiki','La Cofradía de la Entrada de Jesús en Jerusalén de Albalate del Arzobispo es una cofradía de Teruel, que saca la peana de la Burrica durante la Semana Santa. En los primeros años esta peana solía ser sacada por los quintos del pueblo. Con el tiempo acompañaron el paso niñas vestidas de hebreas.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_la_Entrada_de_Jesús_en_Jerusalén_(Albalate_del_Arzobispo)');
