INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186263,'10037','Cofradía de la Soledad (Cáceres)','fiesta','fiestas_wiki','La Ilustre y Real Cofradía de Nuestra Señora de la Soledad y del Santo Entierro es una cofradía de la Semana Santa de Cáceres, en Extremadura; fundada originalmente en 1470. Su sede canónica se encuentra en la Ermita de la Soledad de Cáceres . Procesiona el Viernes Santo y el Domingo de Resurrección.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_la_Soledad_(Cáceres)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186264,'04029','Cofradía de la Vera Cruz','fiesta','fiestas_wiki','El término Cofradía (o Hermandad) de la Vera Cruz hace referencia a las cofradías de carácter penitencial, que se caracterizaban porque los hermanos pertenecientes a las mismas se disciplinaban públicamente durante las procesiones, por eso se las conocía también con el nombre de "cofradías de los disciplinantes".​…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_de_la_Vera_Cruz');
