INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186271,'10037','Cofradía del Cristo Negro (Cáceres)','fiesta','fiestas_wiki','La muy Solemne, Venerable y Pontificia Cofradía Hermandad Penitencial del Santo Crucifijo de Santa María de Jesús (Cristo Negro) es una cofradía fundada en 1490 y refundada en 1986 cuya sede está en la concatedral de Santa María, en Cáceres. Esta cofradía saca en procesión, durante la noche del Miércoles al Jueves…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Cristo_Negro_(Cáceres)','IT Internacional');
