INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186276,'30030','Cofradía del Perdón (Murcia)','fiesta','fiestas_wiki','La Real, Ilustre y Muy Noble Cofradía del Santísimo Cristo del Perdón es una cofradía de culto católico de la Semana Santa de Murcia (Región de Murcia, España) que desfila cada Lunes Santo desde el castizo barrio de San Antolín, siendo una de las cofradías más antiguas de la ciudad ya que sus orígenes se remontan a…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Perdón_(Murcia)','IT Internacional');
