INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186278,'30030','Cofradía del Refugio (Murcia)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo del Refugio es una cofradía de culto católico de la Semana Santa de Murcia (Región de Murcia, España) que desfila todos los Jueves Santo, siendo la decana dentro del estilo de Silencio de la ciudad, pues fue fundada en 1942. Popularmente se la conoce como la Procesión del Silencio.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Refugio_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186279,'30030','Cofradía del Rescate (Murcia)','fiesta','fiestas_wiki','La Hermandad de Esclavos de Nuestro Padre Jesús del Rescate y María Santísima de la Esperanza es una cofradía de culto católico de la Semana Santa de Murcia (Región de Murcia, España) que desfila en la jornada de Martes Santo. Su cotitular, Nuestro Padre Jesús del Rescate, es una de las imágenes más veneradas no…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Rescate_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186280,'30016','Cofradía del Resucitado (Cartagena)','fiesta','fiestas_wiki','La Cofradía del Resucitado es el nombre de la Real e Ilustre Cofradía de Nuestro Padre Jesús Resucitado de la ciudad española de Cartagena, fundada en 1943. Es la más joven de las cuatro cofradías que procesionan cada Semana Santa en Cartagena.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Resucitado_(Cartagena)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186281,'47186','Cofradía del Santo Entierro (Valladolid)','fiesta','fiestas_wiki','La Cofradía del Santo Entierro es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santo_Entierro_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186282,'30030','Cofradía del Santo Sepulcro (Murcia)','fiesta','fiestas_wiki','La Real y Muy Ilustre Cofradía del Santo Sepulcro de Nuestro Señor Jesucristo es una cofradía de culto católico de la Semana Santa de Murcia que desfila cada noche de Viernes Santo. Es una de las cofradías más antiguas de la ciudad y de hecho es considerada como la procesión "oficial" de Murcia. Es de estilo…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santo_Sepulcro_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186283,'47186','Cofradía del Santo Sepulcro y Santísimo Cristo del Consuelo (Valladolid)','fiesta','fiestas_wiki','La Cofradía del Santo Sepulcro y Santísimo Cristo del Consuelo es una de las 20 cofradías que existen actualmente en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santo_Sepulcro_y_Santísimo_Cristo_del_Consuelo_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186284,'02001','Cofradía del Santísimo Cristo de la Agonía (Albacete)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo de la Agonía y Nuestra Señora de la Amargura es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Catedral de San Juan Bautista de Albacete. Fue fundada en 1896 por el comerciante catalán Juan Nicolau Planagumá en la Iglesia de las Justinianas.…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Cristo_de_la_Agonía_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186285,'30019','Cofradía del Santísimo Cristo de la Agonía (Cieza)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo de la Agonía es una cofradía de la Semana Santa de Cieza, en la Región de Murcia (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Cristo_de_la_Agonía_(Cieza)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186286,'02001','Cofradía del Santísimo Cristo de la Coronación de Espinas (Albacete)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo de la Coronación de Espinas es una cofradía de la Semana Santa de Albacete (España).​​ Tiene su sede canónica en la Iglesia de El Buen Pastor. Fue fundada en 2013. Cuenta con dos imágenes: La Coronación de Espinas (2018) y La Sagrada Lanzada (2018) Procesiona en Sábado de Pasión,…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Cristo_de_la_Coronación_de_Espinas_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186287,'27066','Cofradía del Santísimo Cristo de la Piedad (Vivero)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo de la Piedad es una de las ocho cofradías que existen, en la Semana Santa de Vivero.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Cristo_de_la_Piedad_(Vivero)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186288,'50297','Cofradía del Santísimo Ecce Homo y Nuestra Señora de las Angustias (Zaragoza)','fiesta','fiestas_wiki','La Cofradía del Santísimo Ecce Homo y Nuestra Señora de las Angustias refundada en 1948 como cofradía penitencial, es una de las 25 participantes en la Semana Santa zaragozana.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Ecce_Homo_y_Nuestra_Señora_de_las_Angustias_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186289,'27066','Cofradía del Santísimo Rosario (Vivero)','fiesta','fiestas_wiki','La Ilustre y Venerable Cofradía del Santísimo Rosario es una de las ocho cofradías que existen en la Semana Santa de Vivero.',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Santísimo_Rosario_(Vivero)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186290,'02001','Cofradía del Silencio y Santo Vía Crucis (Albacete)','fiesta','fiestas_wiki','La Cofradía del Silencio y Santo Vía Crucis es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Iglesia de la Purísima Concepción. Fundada en 1951, cuenta con una imagen: Santísimo Cristo del Consuelo (1951), obra del escultor murciano Antonio Garrigós Giner. Procesiona en…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Silencio_y_Santo_Vía_Crucis_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186291,'30016','Cofradía del Socorro (Cartagena)','fiesta','fiestas_wiki','La Cofradía del Socorro es el nombre acortado de la Ilustre Cofradía del Santísimo y Real Cristo del Socorro, fundada originalmente con el nombre de Muy Devota, Venerable e Ilustrísima Cofradía de la Hermandad de Caballeros del Santísimo y Real Cristo del Socorro de la ciudad española de Cartagena, fundada en 1691.…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Socorro_(Cartagena)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186292,'30030','Cofradía del Yacente (Murcia)','fiesta','fiestas_wiki','La Cofradía del Santísimo Cristo Yacente y Nuestra Señora de la Luz en Su Soledad es una cofradía de nazarenos de culto católico de la Semana Santa de Murcia (Región de Murcia, España), que desfila en la tarde del Sábado Santo siendo por tanto la última cofradía pasional que hace estación de penitencia en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_Yacente_(Murcia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186293,'14065','Cofradía del cristo de la Victoria (Cáceres)','fiesta','fiestas_wiki','La Cofradía Dominicana del Santísimo Cristo de la Victoria, Nuestra Señora del Rosario en sus Misterios Dolorosos y San Juan Macías,​ más conocida como Cofradía Dominicana o de la Victoria, es una hermandad de la Semana Santa de Cáceres, en España. La hermandad erigida canónicamente en el año 2009, tiene su origen…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradía_del_cristo_de_la_Victoria_(Cáceres)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186294,'47186','Cofradías penitenciales históricas de Valladolid','fiesta','fiestas_wiki','Se considera como cofradías penitenciales históricas de la ciudad de Valladolid a cinco Hermandades que se constituyeron o bien en los últimos años del siglo XV o en el XVI, con unas características y un sello inconfundibles en cada una. Desde los comienzos y durante muchos años tuvieron su misión social y…',NULL,NULL,'https://es.wikipedia.org/wiki/Cofradías_penitenciales_históricas_de_Valladolid','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186295,'26084','Comadres (fiesta)','fiesta','fiestas_wiki','Las Comadres es una fiesta que se celebra en Asturias (España). Esta fiesta coincide con el jueves anterior al martes de carnaval (es decir, el jueves lardero). Consiste en la reunión de grupos de mujeres para merendar, bailar, hablar y pasarlo bien.',NULL,NULL,'https://es.wikipedia.org/wiki/Comadres_(fiesta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186296,'37344','Comisión fallera','fiesta','fiestas_wiki','Una comisión fallera es una agrupación de personas que apoyan o patrocinan la creación de una falla. Tradicionalmente se componen generalmente de vecinos de las calles aledañas al lugar donde se planta la falla aunque pueden encontrarse componentes de la comisión de otras ubicaciones, de otras poblaciones…',NULL,NULL,'https://es.wikipedia.org/wiki/Comisión_fallera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186297,'50178','Comparsa (Moros y Cristianos)','fiesta','fiestas_wiki','El concepto de comparsa en la fiesta de Moros y Cristianos es un tanto diferente al concepto de comparsa de la fiesta de carnaval. Si atendemos al origen de la comparsa, en la fiesta de Moros y Cristianos podemos comprobar que está relacionado con el concepto de compañía, ya que parte de los actos de las fiestas de…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_(Moros_y_Cristianos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186298,'50178','Comparsa Huestes del Cadí','fiesta','fiestas_wiki','Las Huestes del Cadí es una de las cuatro comparsas que forman el Bando Moro de las fiestas de Moros y Cristianos de Elda; en el momento actual es la más joven de las nueve comparsas de las fiestas. Se fundó en 1976 y desfiló por primera vez en las fiestas de Moros y Cristianos de junio de 1977 y es una de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_Huestes_del_Cadí','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186299,'03040','Comparsa de Almogávares','fiesta','fiestas_wiki','Los Almogávares son una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Almogávares','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186300,'03040','Comparsa de Andaluces','fiesta','fiestas_wiki','Los Andaluces, conocidos comúnmente como Contrabandistas, son una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Andaluces','Interés Turístico Regional');
