INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186302,'03040','Comparsa de Cristianos (Villena)','fiesta','fiestas_wiki','La Comparsa de Cristianos, es una de las catorce comparsas participantes de las Fiestas de Moros y Cristianos de la ciudad de Villena (España). Documentada ya en 1843 es además, la comparsa pionera del bando cristiano.',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Cristianos_(Villena)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186303,'03040','Comparsa de Estudiantes (Villena)','fiesta','fiestas_wiki','La comparsa de Estudiantes es una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena, España. Se caracteriza por sus bloques formales de negro y blanco, en una organización muy homogénea. Es la única comparsa de Villena que no tiene ninguna escuadra especial…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Estudiantes_(Villena)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186304,'03040','Comparsa de Labradores (Villena)','fiesta','fiestas_wiki','Los Labradores, conocidos popularmente como “Maseros”, son una de las catorce comparsas que participan en la Fiestas de Moros y Cristianos de la ciudad de Villena (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Labradores_(Villena)','Interés Turístico Regional');
