INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186310,'50178','Comparsa de Moros Viejos','fiesta','fiestas_wiki','Los Moros Viejos son una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena (España). Son además, la comparsa más antigua de cuantas componen el bando moro.',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Moros_Viejos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186311,'03040','Comparsa de Piratas','fiesta','fiestas_wiki','La comparsa de Piratas es una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena, España. Desfiló por primera vez en 1939 y es original de Villena, donde consiguió ser una de las comparsas más populares, siendo posteriormente emulada en muchas otras poblaciones…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Piratas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186312,'50178','Comparsa de Zíngaros','fiesta','fiestas_wiki','Los Zíngaros son una de las nueve comparsas que participan en las Fiestas de Moros y Cristianos de Elda (España). Fundada en 1948, es junto a la Comparsa de Huestes del Cadí, original de la ciudad de Elda.',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_Zíngaros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186313,'50297','Comparsa de gigantes y cabezudos (Zaragoza)','fiesta','fiestas_wiki','La Comparsa de Gigantes y Cabezudos de Zaragoza está formada actualmente por 14 gigantes y 11 cabezudos. La mayoría son personajes populares que vivieron y formaron parte de la historia de Zaragoza. La comparsa de gigantes y cabezudos sale a las calles de la ciudad en San Valero, en la Procesión del Corpus Christi,…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_de_gigantes_y_cabezudos_(Zaragoza)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186314,'03040','Comparsa del Bando Marroquí','fiesta','fiestas_wiki','El Bando Marroquí (más popularmente conocidos como Marruecos) es una de las catorce comparsas que participan en las Fiestas de Moros y Cristianos de la ciudad de Villena, España. Su denominación original es la de Bando de Marroquíes del Rif o simplemente Marroquíes, pero pronto se les dio el nombre popular de…',NULL,NULL,'https://es.wikipedia.org/wiki/Comparsa_del_Bando_Marroquí','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186315,'43148','Concurso Internacional de Castillos de Fuegos Artificiales de Tarragona','fiesta','fiestas_wiki','El Concurso Internacional de Castillos de Fuegos Artificiales Ciudad de Tarragona fue creado el año 1990, en una ciudad con una larga tradición pirotécnica. Tarragona ya contaba con fabricación de "voladores de fuego griego" por parte de los drogueros y los especieros en el año 1383, y se usaban para las fiestas…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_Internacional_de_Castillos_de_Fuegos_Artificiales_de_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186316,'50178','Concurso Internacional de Minicuadros de la comparsa Huestes del Cadí','fiesta','fiestas_wiki','La Comparsa Huestes del Cadí es una de las cuatro que forman parte del bando moro en las Fiestas de Moros y Cristianos de Elda. Fue gestada ideológicamente en la Navidad de 1975, entrando en fase de trabajo a principios de 1976,​​ para hacerse real con la aceptación por la Junta Central de Comparsas.',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_Internacional_de_Minicuadros_de_la_comparsa_Huestes_del_Cadí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186317,'46235','Concurso Internacional de Paella Valenciana de Sueca','fiesta','fiestas_wiki','El Concurso Internacional de Paella Valenciana de Sueca (en valenciano y oficialmente Concurs Internacional de Paella Valenciana) es una competición culinaria para elaborar una paella valenciana, según unos parámetros establecidos y con unos ingredientes determinados, que se celebra anualmente en la localidad…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_Internacional_de_Paella_Valenciana_de_Sueca','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186318,'49219','Concurso de recortes','fiesta','fiestas_wiki','El concurso de recortes es un espectáculo taurino donde los participantes se enfrentan a varios toros o vaquillas, por turnos, y realizan toda clase de recortes, saltos y quiebros sobre el animal, con la finalidad de engañar al toro en el último momento y arriesgar al máximo para llevarse el trofeo. Esta rama de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_de_recortes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186319,'16009','Concurso oficial de agrupaciones del carnaval de Cádiz','fiesta','fiestas_wiki','El Concurso oficial de agrupaciones carnavalescas de Cádiz (COAC) se celebra en el Gran Teatro Falla durante un mes, teniendo su final el viernes previo al miércoles de Ceniza, después de diferentes fases clasificatorias. En este concurso toma parte agrupaciones de toda Andalucía e incluso en los últimos años de…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_oficial_de_agrupaciones_del_carnaval_de_Cádiz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186320,'16009','Concurso oficial de agrupaciones del carnaval de Cádiz 2007','fiesta','fiestas_wiki','El concurso oficial de agrupaciones del carnaval de Cádiz de 2007 se celebró entre el 22 de enero y el 16 de febrero en el Gran Teatro Falla de Cádiz.',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_oficial_de_agrupaciones_del_carnaval_de_Cádiz_2007','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186321,'03064','Congregación de Esclavas de María Santísima de los Dolores','fiesta','fiestas_wiki','La Congregación de Esclavas de María Santísima de los Dolores fundada en 1866 es una de las 25 cofradías penitenciales de la Semana Santa en Zaragoza. Única exclusivamente femenina, siendo la única que no es mixta.',NULL,NULL,'https://es.wikipedia.org/wiki/Congregación_de_Esclavas_de_María_Santísima_de_los_Dolores','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186322,'29067','Congregación de Mena','fiesta','fiestas_wiki','La Congregación de Mena, cuyo nombre oficial y completo es Pontificia y Real Congregación del Santísimo Cristo de la Buena Muerte y Ánimas y Nuestra Señora de la Soledad Coronada (Mena), es una hermandad religiosa o cofradía con sede canónica en la Iglesia de Santo Domingo, en el barrio de El Perchel, en la ciudad…',NULL,NULL,'https://es.wikipedia.org/wiki/Congregación_de_Mena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186323,'02001','Congregación-Cofradía de Nuestra Señora de las Angustias (Albacete)','fiesta','fiestas_wiki','La Congregación-Cofradía de Nuestra Señora de las Angustias es una cofradía de la Semana Santa de Albacete (España).​​ Tiene su sede canónica en la Iglesia de Nuestra Señora de las Angustias. Fue fundada el 7 de junio de 1958 por un grupo de fieles devotos de Nuestra Señora de las Angustias, muchos de ellos…',NULL,NULL,'https://es.wikipedia.org/wiki/Congregación-Cofradía_de_Nuestra_Señora_de_las_Angustias_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186324,'31260','Conmemoración de la Batalla de Lácar','fiesta','fiestas_wiki','La Conmemoración de la batalla de Lácar (O simplemente conocida como La batalla de Lácar) es una fiesta de interés turístico celebrada en la localidad navarra de Lácar, situada en el Valle de Yerri.​',NULL,NULL,'https://es.wikipedia.org/wiki/Conmemoración_de_la_Batalla_de_Lácar','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186325,'41091','Consejo General de Hermandades y Cofradías de la Ciudad de Sevilla','fiesta','fiestas_wiki','El Consejo General de Hermandades y Cofradías de la Ciudad de Sevilla es el órgano encargado de la regulación del conjunto de procesiones de la Semana Santa de Sevilla. Agiliza trámites y acuerdos con las instituciones oficiales y controla los horarios de paso por la carrera oficial. Sus miembros son elegidos cada…',NULL,NULL,'https://es.wikipedia.org/wiki/Consejo_General_de_Hermandades_y_Cofradías_de_la_Ciudad_de_Sevilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186326,'06001','Contempopránea','fiesta','fiestas_wiki','Contempopránea es un festival de música pop independiente que se celebra todos los veranos en Alburquerque (Badajoz). En él se reúnen año tras año numerosos artistas de la escena indie española, y millares de seguidores. A partir de 2014, la edición se ha dividido entre esta localidad pacense y Badajoz.​ El…',NULL,NULL,'https://es.wikipedia.org/wiki/Contempopránea');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186327,'46190','Cordà de Paterna','fiesta','fiestas_wiki','La cordà de Paterna es la culminación de las fiestas mayores de la localidad valenciana, que se celebra la noche del último domingo de agosto (fecha variable), festividad de San Vicente.​',39.502778,-0.440556,'https://es.wikipedia.org/wiki/Cordà_de_Paterna','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186328,'16009','Coro de carnaval','fiesta','fiestas_wiki','Un coro de carnaval es un tipo de agrupación carnavalesca genuina de Cádiz que sale a la calle en bateas o carrozas a cantar y ofrecer coplas al pueblo. Puede contener de 12 a 45 componentes (35 voces y 10 orquesta), los cuales cantan en diferentes voces: tenor, segunda y bajo. La orquesta es de pulso y púa y los…',NULL,NULL,'https://es.wikipedia.org/wiki/Coro_de_carnaval','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186329,'03064','Coronación Canónica de la Virgen de los Dolores','fiesta','fiestas_wiki','María Santísima de los Dolores, fue coronada canónicamente el 4 de octubre de 1986 en una ceremonia multitudinaria que tuvo lugar en la Catedral de Málaga.',NULL,NULL,'https://es.wikipedia.org/wiki/Coronación_Canónica_de_la_Virgen_de_los_Dolores');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186330,'29067','Coronación canónica de la Virgen del Rocío (Málaga)','fiesta','fiestas_wiki','María Santísima del Rocío, conocida como la Novia de Málaga fue coronada canónicamente el 12 de septiembre de 2015 en una ceremonia multitudinaria que tuvo lugar en la Catedral de Málaga y que fue televisada a toda España a través de 13TV.​ Los medios de comunicación locales y regionales calificaron como hito sin…',NULL,NULL,'https://es.wikipedia.org/wiki/Coronación_canónica_de_la_Virgen_del_Rocío_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186331,'29067','Corporaciones no agrupadas de la Semana Santa de Málaga','fiesta','fiestas_wiki','El Viernes de Dolores y el Sábado de Pasión han sido siempre para las corporaciones unos días de gran actividad en los templos y sedes, si bien desde hace unos años dichas jornadas han venido a convertirse en fecha idónea para las corporaciones no pertenecientes a la Agrupación de Cofradías, ya sea por lejanía…',NULL,NULL,'https://es.wikipedia.org/wiki/Corporaciones_no_agrupadas_de_la_Semana_Santa_de_Málaga','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186332,'18087','Corpus Christi de Granada','fiesta','fiestas_wiki','La Feria del Corpus Christi de Granada, es la Fiesta Mayor de la ciudad de Granada, en el que se celebra el Corpus Christi. Esta celebración es una festividad religiosa celebrada por la Iglesia Católica en honor al Santísimo Sacramento del Altar, es decir, la Eucaristía. Una de las principales tradiciones del…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186333,'08003','Corpus Christi en Barcelona','fiesta','fiestas_wiki','La solemnidad del Corpus Christi en Barcelona ha sido históricamente una de las fiestas más importantes de la ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186334,'37046','Corpus Christi en Béjar','fiesta','fiestas_wiki','El Corpus Christi de Béjar es una fiesta que se celebra el domingo siguiente a Pentecostés –sesenta días después del Domingo de Resurrección– en Béjar (Salamanca, España). Fue declarada Fiesta de Interés Turístico Nacional en 2010 y de Interés Turístico Internacional en 2019.​​ Es la fiesta más destacada de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Béjar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186335,'23050','Corpus Christi en Jaén','fiesta','fiestas_wiki','La solemnidad del Corpus Christi (en latín, "Cuerpo de Cristo") es una celebración religiosa católica que cuenta con amplia repercusión popular en la ciudad de Jaén.​ Se celebra el domingo posterior a la solemnidad de la Santísima Trinidad, que a su vez tiene lugar el domingo siguiente a Pentecostés.…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Jaén');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186336,'45082','Corpus Christi en Lagartera','fiesta','fiestas_wiki','La solemnidad del Corpus Christi en Lagartera (España) es una fiesta católica, eucarística que se celebra cada año en esta villa. El Corpus de Lagartera destaca por el engalanamiento de las fachadas, colgando de ellas diferentes piezas textiles, y por la realización de altares a las puertas de las casas, que…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Lagartera','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186337,'90233','Corpus Christi en Laguna de Negrillos','fiesta','fiestas_wiki','La solemnidad del Corpus Christi en Laguna de Negrillos, de gran raigambre entre sus gentes, destaca ante todo por su peculiar procesión. Es esta una celebración que parece haber permanecido ajena al transcurrir de los años y en la que se mezclan la luz y el color, lo sagrado y lo profano, la tradición y el mito,…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Laguna_de_Negrillos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186338,'35016','Corpus Christi en Las Palmas de Gran Canaria','fiesta','fiestas_wiki','El Corpus Christi es una solemnidad religiosa católica que cuenta con amplia repercusión popular en la ciudad de Las Palmas de Gran Canaria.​ La celebración tiene su centro en la catedral de Canarias donde sale la procesión del Santísimo Sacramento.',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Las_Palmas_de_Gran_Canaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186339,'41091','Corpus Christi en Sevilla','fiesta','fiestas_wiki','El Corpus Christi es una solemnidad religiosa católica que cuenta con amplia repercusión popular en Sevilla. Se mantiene en Sevilla, junto con Granada y Toledo, la procesión del Corpus Christi en su día originario, el jueves, aun cuando la solemnidad litúrgica fue trasladada al domingo sucesivo en España. También…',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Sevilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186340,'43148','Corpus Christi en Tarragona','fiesta','fiestas_wiki','La solemnidad del Corpus Christi en Tarragona pertenece al ciclo anual de celebraciones de esta localidad. Tiene lugar entre los meses de mayo y junio. Es una de las fiestas más antiguas que aún se organizan y viven en esta ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186341,'45168','Corpus Christi en Toledo','fiesta','fiestas_wiki','La procesión del Corpus Christi en Toledo (España) es una solemnidad católica, eucarística de tradición muy antigua que se celebra cada año en esta ciudad. Es la fiesta principal de los toledanos y de gran notoriedad entre los católicos españoles, habiendo sido declarada en 1980 de Interés Turístico Internacional.…',39.86666667,-4.03333333,'https://es.wikipedia.org/wiki/Corpus_Christi_en_Toledo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186342,'38017','Correr el cacharro','fiesta','fiestas_wiki','Correr el cacharro es un acto festivo que se celebra las fiestas en honor a San Andrés en el Valle de La Orotava y otras localidades del norte de la isla de Tenerife, principalmente en Icod de los Vinos y el Puerto de la Cruz, y también en Granadilla de abona,consistente en recorrer las calles de los pueblos al…',NULL,NULL,'https://es.wikipedia.org/wiki/Correr_el_cacharro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186343,'02001','Corrida de Asprona','fiesta','fiestas_wiki','Las corrida de Asprona es una tradicional corrida de toros del calendario taurino español que se celebra anualmente en la ciudad española de Albacete.​​​​​​ Tiene lugar en el mes de junio en la plaza de toros de Albacete a beneficio de Asprona, la Asociación para la atención a Personas con Discapacidad Intelectual…',NULL,NULL,'https://es.wikipedia.org/wiki/Corrida_de_Asprona','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186344,'28079','Cortylandia','fiesta','fiestas_wiki','Cortylandia es el nombre que recibe el espectáculo infantil animatrónico organizado anualmente en fechas navideñas por El Corte Inglés en la fachada de sus centros comerciales más importantes. El espectáculo, que consiste en un retablo lleno de figuras y decoración que se mueven y cantan diversos temas, se organizó…',NULL,NULL,'https://es.wikipedia.org/wiki/Cortylandia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186345,'39020','Coso Blanco','fiesta','fiestas_wiki','El Coso Blanco es una fiesta catalogada como Fiesta de Interés Turístico Regional. celebrada el primer viernes del mes de julio en la ciudad de Castro-Urdiales (Cantabria, España) desde al año 1948. Consiste en el desfile de carrozas adornadas fundamentalmente con papel de seda de color blanco, pudiéndose añadir…',NULL,NULL,'https://es.wikipedia.org/wiki/Coso_Blanco','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186346,'23055','Costaleros del Mayor Dolor','fiesta','fiestas_wiki','Cuadrilla de costaleros de la cofradía del Nazareno de Linares, que realiza su estación de penitencia cada Viernes Santo de la Semana Santa de Linares, portando a Nuestra Señora del Mayor Dolor (popularmente, "la Niña").',NULL,NULL,'https://es.wikipedia.org/wiki/Costaleros_del_Mayor_Dolor','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186347,'07049','Cremá','fiesta','fiestas_wiki','La Cremá​ (del valenciano popular cremà, de cremada, "quemada") es el acto de prender fuego a los monumentos de cartón o madera (llamadas fallas u hogueras) durante las fiestas de varias localidades de la Comunidad Valenciana (España), especialmente las Fallas celebradas en Valencia y las Hogueras de San Juan…',NULL,NULL,'https://es.wikipedia.org/wiki/Cremá','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186348,'50297','Cristo Resucitado (Zaragoza)','fiesta','fiestas_wiki','Cristo Resucitado es una imagen tallada por el escultor aragonés Jorge Albareda Agüeras en el año 1977, titular de la Real Hermandad de Cristo Resucitado y Santa María de la Esperanza y del Consuelo y venerado en el Colegio San Agustín de Zaragoza.​',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_Resucitado_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186349,'38026','Cristo a la Columna (La Orotava)','fiesta','fiestas_wiki','El Santísimo Cristo a la Columna es una imagen que representa a Jesús de Nazaret, se venera en el altar colateral de la nave del evangelio de la parroquia de san Juan Bautista de la Villa de la Orotava, Tenerife, Canarias. Es el titular de la Venerable Esclavitud del Santísimo Cristo a la columna.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_a_la_Columna_(La_Orotava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186350,'38048','Cristo a la Columna (Valverde)','fiesta','fiestas_wiki','La talla del Santísimo Cristo a la Columna es una imagen de Cristo en la columna, de gran calidad artística y de procedencia genovesa.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_a_la_Columna_(Valverde)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186351,'08302','Cristo crucificado (iglesia de San Francisco de Palencia)','fiesta','fiestas_wiki','El Cristo crucificado, situado en la Iglesia de San Francisco de Palencia, es una escultura en madera policromada del escultor de origen nórdico Alejo de Vahía, sugiriendo, por el cuidado en el modelado, una cronología ca. 1500.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_crucificado_(iglesia_de_San_Francisco_de_Palencia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186352,'44046','Cristo de la Buena Muerte','fiesta','fiestas_wiki','El Cristo de la Buena Muerte o Cristo de Mena son las advocaciones de Cristo que surgen de una talla de Cristo crucificado original de Pedro de Mena datada aproximadamente en 1660, y que se conservó en la iglesia de Santo Domingo (Málaga) hasta su destrucción, en mayo de 1931, durante la ola de anticlericalismo…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Buena_Muerte','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186353,'35017','Cristo de la Buena Muerte (Puerto del Rosario)','fiesta','fiestas_wiki','El Santísimo Cristo de la Buena Muerte es una escultura que representa a Jesús de Nazaret crucificado que se encuentra en la Capilla Militar o Acuartelamiento de Puerto del Rosario (Fuerteventura, España). Se trata de la advocación de Cristo que suscita más devoción en la isla de Fuerteventura.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Buena_Muerte_(Puerto_del_Rosario)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186354,'35016','Cristo de la Humildad y Paciencia (Las Palmas de Gran Canaria)','fiesta','fiestas_wiki','El Santísimo Cristo de la Humildad y Paciencia es una imagen de Jesús de Nazaret que evoca el momento de la pasión de Jesús cuando éste sale del interrogatorio de Anás y se encuentra con san Pedro. Se venera en la parroquia de San Francisco de Asís del barrio de Triana de Las Palmas de Gran Canaria, Gran Canaria…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Humildad_y_Paciencia_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186355,'38005','Cristo de la Misericordia (Garachico)','fiesta','fiestas_wiki','El Santísimo Cristo de la Misericordia es una escultura que representa a Jesús de Nazaret crucificado que se venera en la Villa de Garachico al norte de la isla de Tenerife (España). El Cristo fue moldeado mediante la técnica en pasta de maíz por los indios Tarascos de México, lo que se llama Tatzingüe. La imagen…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Misericordia_(Garachico)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186356,'90778','Cristo de la Reconciliación (Candelaria)','fiesta','fiestas_wiki','El Santísimo Cristo de la Reconciliación es una imagen de Jesucristo crucificado de gran calidad artística, hecha en madera policromada por el escultor sevillano Ricardo Rivera Martínez en 1996. Preside la capilla que lleva su nombre en la Basílica de Nuestra Señora de la Candelaria, situada en el municipio…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Reconciliación_(Candelaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186357,'35016','Cristo de la Sala Capitular (Las Palmas de Gran Canaria)','fiesta','fiestas_wiki','El Santísimo Cristo de la Sala Capitular es una imagen de Jesucristo crucificado, hecha en madera policromada por el escultor José Luján Pérez en 1793.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Sala_Capitular_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186358,'38023','Cristo de la Sala Capitular (San Cristóbal de La Laguna)','fiesta','fiestas_wiki','El Santísimo Cristo de la Sala Capitular, también conocido como Cristo del Amor Misericordioso, nombre que recibe por la inscripción que figuraba en el retablo de la Catedral de Nuestra Señora de los Remedios de San Cristóbal de La Laguna (Tenerife, Islas Canarias), donde estuvo colocado posteriormente, es una…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Sala_Capitular_(San_Cristóbal_de_La_Laguna)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186359,'38024','Cristo de la Salud (Los Llanos de Aridane)','fiesta','fiestas_wiki','El Santísimo Cristo de la Salud es una escultura que representa a Jesús de Nazaret crucificado que se venera en el municipio de Los Llanos de Aridane en la isla de La Palma (España). Concretamente el Cristo se venera en la iglesia parroquial del municipio, la Parroquia de Nuestra Señora de los Remedios. Destaca…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Salud_(Los_Llanos_de_Aridane)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186360,'35016','Cristo de la Vera Cruz (Las Palmas de Gran Canaria)','fiesta','fiestas_wiki','El Santísimo Cristo de la Vera Cruz es una imagen de Jesús crucificado que se venera en la Parroquia matriz de San Agustín de Hipona en Las Palmas de Gran Canaria, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Vera_Cruz_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186361,'35024','Cristo de la Vera Cruz (Teguise)','fiesta','fiestas_wiki','El Santísimo Cristo de la Vera Cruz es una escultura que representa a Jesús de Nazaret crucificado que se venera en el municipio de Teguise en la isla de Lanzarote (España). Concretamente el Cristo se venera en la Ermita del Santísimo Cristo de la Vera Cruz. Se trata de la advocación de Cristo más venerada de…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_la_Vera_Cruz_(Teguise)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186362,'41091','Cristo de las Tres Caídas (Sevilla)','fiesta','fiestas_wiki','El Cristo de las Tres Caídas es una imagen de Jesús de Nazaret con la cruz a cuestas que evoca el momento de su tercera caída. Se encuentra en la capilla de los Marineros, en el barrio de Triana en Sevilla, Andalucía, España. Es una imagen titular de la Pontificia, Real e Ilustre Hermandad y Archicofradía de…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_las_Tres_Caídas_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186363,'23021','Cristo de los Carboneros','fiesta','fiestas_wiki','El Cristo de los Carboneros es una obra realizada por Francisco del Rincón en 1606. Portada el Viernes Santo en la Procesión de Regla de la Ilustre Cofradía Penitencial de Nuestra Señora de las Angustias, la imagen está ubicada en la Iglesia de Nuestra Señora de las Angustias de Valladolid (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_los_Carboneros','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186364,'18087','Cristo de los Favores','fiesta','fiestas_wiki','El Santísimo Cristo de los Favores, cuya distinción honorífica fue concedida por la ciudad de Granada en el año 2003 con la medalla de oro de la ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_de_los_Favores','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186365,'35016','Cristo del Buen Fin (Las Palmas de Gran Canaria)','fiesta','fiestas_wiki','El Santísimo Cristo del Buen Fin es una imagen de Cristo crucificado, que se encuentra en la ermita del Espíritu Santo en el barrio de Vegueta (Las Palmas de Gran Canaria, España).​ La talla es de tamaño natural, hecha de pasta de composición no conocida, datada en el último tercio del siglo XVII y de autor…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_del_Buen_Fin_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186366,'38012','Cristo del Buen Viaje (Santa Cruz de Tenerife)','fiesta','fiestas_wiki','El Santísimo Cristo del Buen Viaje es una imagen de Cristo crucificado, que se encuentra en la Iglesia Matriz de Nuestra Señora de la Concepción (Santa Cruz de Tenerife, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_del_Buen_Viaje_(Santa_Cruz_de_Tenerife)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186367,'38006','Cristo del Calvario (Icod de los Vinos)','fiesta','fiestas_wiki','El Santísimo Cristo del Calvario, también llamado Cristo de Icod o Cristo Rescatado, es una imagen que representa a Jesucristo crucificado en el momento de su muerte, de gran devoción popular en el municipio y ciudad de Icod de los Vinos (isla de Tenerife, Canarias, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_del_Calvario_(Icod_de_los_Vinos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186368,'38026','Cristo del Calvario (La Orotava)','fiesta','fiestas_wiki','El Santísimo Cristo del Calvario es un grupo escultórico de madera policromada que representa a La Piedad, María sosteniendo el cuerpo sin vida de Jesús. Fue realizada en 1814 por el ilustre escultor orotavense Fernando Estévez. Una magnífica obra donde quedan reflejados los rasgos de su estilo personal.',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_del_Calvario_(La_Orotava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186369,'35016','Cristo del Granizo','fiesta','fiestas_wiki','El Santísimo Cristo del Granizo es una imagen de Jesús de Nazaret que evoca el momento de su flagelación. Se venera en la parroquia de Santo Domingo de Guzmán en el barrio de Vegueta de Las Palmas de Gran Canaria , Gran Canaria (Islas Canarias),(España). Actualmente sale el Viernes Santo en la procesión magna…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristo_del_Granizo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186370,'37112','Cristóbal Toral','fiesta','fiestas_wiki','Cristóbal Toral Ruiz (Torre Alháquime,Cádiz, 15 de abril de 1940) es un pintor español conocido por sus cuadros realistas en los que destacan la presencia de maletas y el concepto del «viaje». La mayoría de sus obras pueden observarse en el Museo de la Ciudad de Antequera, en la de la provincia de Málaga. La…',NULL,NULL,'https://es.wikipedia.org/wiki/Cristóbal_Toral','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186371,'12032','Cruces de Mayo de Burriana','fiesta','fiestas_wiki','Las Cruces de Mayo de Burriana son una fiesta que se tiene lugar anualmente en dicha ciudad castellonense el primer fin de semana de mayo.',39.88961,-0.08389,'https://es.wikipedia.org/wiki/Cruces_de_Mayo_de_Burriana','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186372,'12012','Cruz de guía','fiesta','fiestas_wiki','La cruz de guía es la insignia que, portada por un hermano de la cofradía, encabeza las procesiones públicas. Las que salen en las cofradías de la Semana Santa suele tener unos dos metros y medio de altura y carece de la figura de Cristo crucificado.',NULL,NULL,'https://es.wikipedia.org/wiki/Cruz_de_guía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186373,'16009','Cuarteto de carnaval','fiesta','fiestas_wiki','El cuarteto de carnaval es un tipo de agrupación carnavalesca genuina de Cádiz. Aunque su nombre hace pensar que está compuesto por 4 componentes, los cuartetos en Cádiz además pueden ser de 3 y de 5. Se acompañan con claves o palos, pitos o güiros y ocasionalmente de una guitarra.',NULL,NULL,'https://es.wikipedia.org/wiki/Cuarteto_de_carnaval','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186374,'22168','Cucaña','fiesta','fiestas_wiki','La cucaña, también conocida como palo encebado, es un juego que consiste en escalar, trepar y marinear, solamente con ayuda de brazos y piernas, por un poste vertical u horizontal de aproximadamente 5 metros de longitud, que suele estar alisado o embadurnado con alguna sustancia resbaladiza. Los mayos (postes…',NULL,NULL,'https://es.wikipedia.org/wiki/Cucaña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186375,'19191','Curpillos','fiesta','fiestas_wiki','El Curpillos es una fiesta cívica, religiosa y militar que se celebra el viernes siguiente del Corpus Christi,​​ en el Monasterio de las Huelgas de Burgos.',NULL,NULL,'https://es.wikipedia.org/wiki/Curpillos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186376,'50252','Dance de Tauste','fiesta','fiestas_wiki','El dance de Tauste es una celebración típica de la localidad de Tauste, que se realiza el día 21 de abril a las 13:00 en la Plaza del Ayuntamiento durante las fiestas patronales, tras la finalización de la Misa Mayor, en honor de San Miguel y la Virgen de Sancho Abarca.​​ La celebración está compuesta por…',NULL,NULL,'https://es.wikipedia.org/wiki/Dance_de_Tauste','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186377,'20069','Danza de San Sebastián de Aldán','fiesta','fiestas_wiki','La Danza de San Sebastián tiene lugar cada 20 de enero en Aldán parroquia del municipio gallego de Cangas del Morrazo (Pontevedra) España, coincidiendo con la festividad de este santo.',NULL,NULL,'https://es.wikipedia.org/wiki/Danza_de_San_Sebastián_de_Aldán','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186378,'17211','Danza de la muerte de Verges','fiesta','fiestas_wiki','La danza de la muerte de Verges es una representación en los actos de la procesión tradicional de Jueves Santo en Verges, España. Es un género de baile basado en la danza de la Muerte que en la época medieval era común en toda la Europa occidental.',42.061179,3.046056,'https://es.wikipedia.org/wiki/Danza_de_la_muerte_de_Verges','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186379,'90270','Danza de los zancos de Anguiano','fiesta','fiestas_wiki','La Danza de los zancos es una fiesta folklórica tradicional declarada bien de interés cultural de carácter inmaterial,​ que se celebra cada año en Anguiano en La Rioja (España). En ella ocho jóvenes del pueblo, provistos de zancos de 50 centímetros de altura y amplios faldones, se lanzan por una cuesta empedrada…',NULL,NULL,'https://es.wikipedia.org/wiki/Danza_de_los_zancos_de_Anguiano','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186380,'16130','Danzantes de Montalbo','fiesta','fiestas_wiki','Los Danzantes de Montalbo son una manifestación festiva, religiosa y ritual celebrada en la localidad de Montalbo, en la provincia de Cuenca (España). La tradición forma parte de las fiestas patronales del municipio en honor a Jesús de la Columna y se desarrolla principalmente en torno a la festividad de San Miguel…',NULL,NULL,'https://es.wikipedia.org/wiki/Danzantes_de_Montalbo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186381,'46139','Danzas de Guadasuar','fiesta','fiestas_wiki','Las danzas de Guadasuar o las danzadas es de la modalidad procesional o de ida, representación típica de la antigua danza de calle valenciana.​ Danzas con características similares a la de Guadasuar se conservan en otros lugares valencianos, desde la Huerta de Valencia en el Valle de Albaida. Esta danza conserva lo…',NULL,NULL,'https://es.wikipedia.org/wiki/Danzas_de_Guadasuar','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186382,'02001','Dehesa de Los Llanos','fiesta','fiestas_wiki','La Dehesa de Los Llanos es una finca manchega y paraje natural que se encuentra a menos de 5 kilómetros al sur de la ciudad española de Albacete. Su extensión de 10 000 hectáreas permite obtener los ingredientes necesarios para la alimentación de su propio ganado ovino formado por más de 5500 ovejas manchegas, del…',38.92837306,-1.86331611,'https://es.wikipedia.org/wiki/Dehesa_de_Los_Llanos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186383,'33032','Descenso Folklórico del Nalón','fiesta','fiestas_wiki','El Descenso Folklórico del Nalón es un desfile acuático y de tono humorístico que se celebra en el río Nalón a su paso por el concejo de Laviana en Asturias. Ocasionalmente es también citado como "Descenso Folclórico del Nalón" o "Descenso del Nalón". En el año 2025 cumplió la n.º 56 edición que ha sido la más…',NULL,NULL,'https://es.wikipedia.org/wiki/Descenso_Folklórico_del_Nalón','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186384,'03036','Descenso Internacional del Sella','fiesta','fiestas_wiki','El Descenso Internacional del Sella, conocido popularmente como Las Piraguas (Les Piragües en asturiano), se celebra el primer sábado de agosto posterior al día 2 de dicho mes entre las localidades asturianas de Arriondas y Ribadesella, con un recorrido de 20 km a lo largo del río Sella. La prueba está organizada…',NULL,NULL,'https://es.wikipedia.org/wiki/Descenso_Internacional_del_Sella','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186385,'05002','Descenso Internacional y Fluvial de la Calle de Galiana','fiesta','fiestas_wiki','El Descenso Internacional y Fluvial de la Calle de Galiana es un popular fiesta que se celebra durante el Antroxu de Avilés, Principado de Asturias en la jornada del sábado, en el mes de febrero desde 1988. El acto, de carácter multitudinario, se ha convertido en referencia del carnaval avilesino, muy…',NULL,NULL,'https://es.wikipedia.org/wiki/Descenso_Internacional_y_Fluvial_de_la_Calle_de_Galiana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186386,'33041','Descenso a nado de la ría del Navia','fiesta','fiestas_wiki','El Descenso a nado de la ría de Navia se celebra desde 1958 el fin de semana de agosto que la marea lo permite en la ría que forma el río Navia a su paso por la localidad asturiana del mismo nombre. La prueba está organizada por la Asociación de Amigos de la Ría de Navia.',NULL,NULL,'https://es.wikipedia.org/wiki/Descenso_a_nado_de_la_ría_del_Navia','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186387,'03064','Dolores Aguirre (ganadería)','fiesta','fiestas_wiki','La ganadería de Dolores Aguirre Ybarra es una ganadería de toros de lidia de la provincia de Sevilla, cuyas reses pastan en la finca "Dehesa de Frías", en el término municipal de Constantina, y que está inscrita dentro de la Unión de Criadores de Toros de Lidia.​ Desde 1977 y hasta su muerte en 2013 fue propiedad…',NULL,NULL,'https://es.wikipedia.org/wiki/Dolores_Aguirre_(ganadería)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186388,'10218','Domingo de los Tiros','fiesta','fiestas_wiki','El Domingo de los Tiros es una celebración religiosa y tradicional que tiene lugar cada Domingo de Resurrección en la localidad española de Zarza la Mayor, en la provincia de Cáceres, Extremadura. La fiesta conmemora la resurrección de Jesús mediante el encuentro procesional entre las imágenes del Cristo Resucitado…',NULL,NULL,'https://es.wikipedia.org/wiki/Domingo_de_los_Tiros','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186389,'29001','Don Juan en Alcalá','fiesta','fiestas_wiki','Don Juan en Alcalá es la representación teatral del Don Juan Tenorio, según la obra de José Zorrilla, celebrada en Alcalá de Henares. Se interpreta anualmente, desde 1984, en el fin de semana más cercano al día uno de noviembre de cada año.',NULL,NULL,'https://es.wikipedia.org/wiki/Don_Juan_en_Alcalá','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186390,'28079','Doña Manolita','fiesta','fiestas_wiki','Doña Manolita es la Administración de Loterías y Apuestas del Estado número 67, ubicada en Madrid.',NULL,NULL,'https://es.wikipedia.org/wiki/Doña_Manolita');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186391,'35016','Drag Chuchi','fiesta','fiestas_wiki','Drag Chuchi, nombre artístico de Pedro Bethencourt Guerra (Las Palmas, 15 de junio de 1990), es una drag queen y artista multidisciplinar española, conocida por ser la ganadora de la Gala Drag Queen de Las Palmas de Gran Canaria en 2019, así como por competir en la tercera temporada de Drag Race España.​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Drag_Chuchi','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186392,'35016','Drag Sethlas','fiesta','fiestas_wiki','Drag Sethlas, nombre artístico de Borja Casillas Toledo (Las Palmas de Gran Canaria, 26 de enero de 1991),​ es una artista drag española, conocida por haber ganado la Gala Drag Queen de Las Palmas de Gran Canaria en 2017 y 2020, participar en la segunda temporada de Drag Race España y obtener la victoria en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Drag_Sethlas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186393,'35016','Drag Shírah','fiesta','fiestas_wiki','Drag Shírah, nombre artístico de Carla Domínguez Curbelo (Las Palmas de Gran Canaria, 17 de febrero de 2001),​ es una performer y artista drag española.',NULL,NULL,'https://es.wikipedia.org/wiki/Drag_Shírah','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186394,'35016','Drag Vulcano','fiesta','fiestas_wiki','Drag Vulcano, nombre artístico de Isidro Javier Pérez Mateo (Gáldar, 1990), es una drag queen española, conocida por competir en la primera temporada de Drag Race España​​ y ser la ganadora de la Gala Drag Queen de Las Palmas de Gran Canaria en 2022.​​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Drag_Vulcano','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186395,'15078','Día Nacional de Galicia','fiesta','fiestas_wiki','El Día Nacional de Galicia,​ también conocido como Día da Patria Galega,​ es la fiesta nacional oficial de Galicia, según decreto de la Junta de Galicia de 1 de enero de 1979 publicado en el Diario Oficial de Galicia.​ Se celebra el día 25 de julio, día de la festividad del apóstol Santiago el Mayor.',42.88,-8.53,'https://es.wikipedia.org/wiki/Día_Nacional_de_Galicia','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186396,'02001','Día de Albacete','fiesta','fiestas_wiki','El Día de Albacete o Día de la Ciudad de Albacete es la jornada festiva oficial de la ciudad española de Albacete.​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186397,'12100','Día de América en Asturias','fiesta','fiestas_wiki','El Día de América de Asturias es una fiesta de interés turístico nacional​ que se celebra en la ciudad asturiana de Oviedo, España, durante la festividad local de San Mateo el día 19 de septiembre de cada año.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_América_en_Asturias','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186398,'44084','Día de Aragón','fiesta','fiestas_wiki','Oficialmente conocido como El Día de Aragón, se celebra el 23 de abril para homenajear a San Jorge como santo patrón del Reino de Aragón. La festividad fue declarada por las Cortes de Aragón en 1461 con el fin de ser un fiesta «perpetua, guardada, observada y celebrada solemnemente». Su popularidad ha ido…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Aragón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186399,'33024','Día de Asturias en Gijón','fiesta','fiestas_wiki','El Día de Asturias en Gijón se celebra en la localidad asturiana de Gijón el primer domingo de agosto. La fiesta comienza con la jira al Cerro de Santa Catalina, en dónde se encuentra la estatua de Chillida, el Elogio del Horizonte. Después de la jira, a las seis desde los Jardines del Náutico parte el desfile de…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Asturias_en_Gijón','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186400,'39059','Día de Campoo','fiesta','fiestas_wiki','La festividad del Día de Campoo se celebra cada año en el último domingo del mes de septiembre. Tiene lugar en la localidad de Reinosa (Cantabria) y en ella se ensalzan las costumbres, tradiciones y folclore de la comarca cántabra de Campoo que por su idiosincrasia y aislamiento con el resto de Cantabria mantiene…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Campoo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186401,'38012','Día de Canarias','fiesta','fiestas_wiki','El 30 de mayo es reconocido como el Día de Canarias. Este es un día festivo en todas las islas de Canarias. Se conmemora con este día, el aniversario de la primera sesión del Parlamento de Canarias con sede en la ciudad de Santa Cruz de Tenerife, llevada a cabo el 30 de mayo de 1983.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186402,'47098','Día de Castilla y León','fiesta','fiestas_wiki','El Día de Castilla y León es la fiesta oficial de esa comunidad autónoma española, celebrada cada 23 de abril. El centro de la celebración es la localidad vallisoletana de Villalar de los Comuneros, lugar en el que se conmemora el aniversario de la batalla, decisiva para las Comunidades de Castilla, que se saldó…',41.7544,-4.7819,'https://es.wikipedia.org/wiki/Día_de_Castilla_y_León');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186403,'31078','Día de Castilla-La Mancha','fiesta','fiestas_wiki','El Día de Castilla-La Mancha es la jornada festiva de la comunidad autónoma española de Castilla-La Mancha. Se celebra el día 31 de mayo, conmemorando el aniversario de la constitución de las Cortes Regionales por primera vez en su historia. La primera vez que se celebró fue en 1984.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Castilla-La_Mancha');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186404,'25167','Día de Cataluña','fiesta','fiestas_wiki','El Día Once de Septiembre​ (en catalán, Diada de l''Onze de Setembre) o Día Nacional de Cataluña​ (en catalán, Diada Nacional de Catalunya),​ también conocido como Día de Cataluña o Fiesta Nacional de Cataluña (en catalán, Festa Nacional de Catalunya),​ o simplemente, la Diada,​ es la fiesta oficial de Cataluña,…',41.8375,1.5378,'https://es.wikipedia.org/wiki/Día_de_Cataluña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186405,'39012','Día de La Montaña','fiesta','fiestas_wiki','El Día de Cantabria, conocido por el nombre tradicional de Día de La Montaña, se celebra el segundo domingo de agosto en Cabezón de la Sal (Cantabria, España) y es una jornada de exaltación de las costumbres, tradiciones y valores etnográficos de la comunidad.​​ A pesar de su nombre, esta celebración no es el día…',43.3075,-4.2325,'https://es.wikipedia.org/wiki/Día_de_La_Montaña','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186406,'04078','Día de La Rioja','fiesta','fiestas_wiki','El Día de La Rioja es la jornada festiva de la comunidad autónoma española de La Rioja (España). Se celebra el día 9 de junio, en conmemoración de la firma por parte del Rey Juan Carlos I del Estatuto de Autonomía de La Rioja en esa fecha del año 1982 y mediante la cual se constituía como comunidad autónoma…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_La_Rioja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186407,'52001','Día de Melilla','fiesta','fiestas_wiki','El Día de Melilla celebrado en Melilla el 17 de septiembre, es una fiesta que marca la fecha en que Pedro de Estopiñán y Virués se convirtió en el primer gobernador de Melilla por los Reyes Católicos en el 17 de septiembre de 1497, después de la toma de Melilla. La plaza de Melilla fue la primera de las plazas…',35.29361111,-2.93388889,'https://es.wikipedia.org/wiki/Día_de_Melilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186408,'08302','Día de Navarra','fiesta','fiestas_wiki','La Ley Foral 18/1985, de 27 de septiembre, aprobada por el Parlamento de Navarra declaró como Día de Navarra el día 3 de diciembre, festividad de San Francisco Javier, disponiendo que el Gobierno de Navarra adopte las medidas necesarias para la celebración anual de dicha festividad y organice los actos pertinentes.…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Navarra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186409,'09180','Día de San Esteban','fiesta','fiestas_wiki','El Día de San Esteban o la Fiesta de San Esteban es un día de santo cristiano que se celebra el día posterior a Navidad (26 de diciembre) en la Iglesia latina y en la Iglesia Hispano-Mozárabe y el 27 en la Iglesias eslavo-bizantinas. En este día se recuerda a San Esteban, el primer mártir del cristianismo. La…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_San_Esteban');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186410,'12099','Día de San Jorge','fiesta','fiestas_wiki','El Día de San Jorge conmemora la muerte del soldado mártir Jorge, el 23 de abril de 303.​ Además, es el santo patrón de países como Bulgaria, Etiopía, Georgia, Inglaterra y, antiguamente, Portugal. En España lo es de la comunidad autónoma de Aragón y Cataluña, así como de las poblaciones de Cáceres (provincia de…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_San_Jorge');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186411,'28050','Día de Santa Juana','fiesta','fiestas_wiki','El día de Santa Juana, conocido como el día de la tortilla, se celebra el 9 de marzo, desde el siglo XVI, para venerar a Juana Vázquez, abadesa del Monasterio de Santa Juana de la Cruz, ubicado en Cubas de la Sagra. Se trata de una fiesta popular que se conmemora en varios municipios españoles donde la gente del…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Santa_Juana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186412,'20069','Día de Santo Tomás','fiesta','fiestas_wiki','El día de Santo Tomás (21 de diciembre) es una de las fiestas importantes del calendario de varias ciudades del País Vasco, como San Sebastián (Guipúzcoa),​ Bilbao (Vizcaya), Lequeitio (Vizcaya), Mondragón (Guipúzcoa), Azpeitia (Guipúzcoa) o Irún (Guipúzcoa). El origen de la fiesta se ubica probablemente en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Santo_Tomás');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186413,'25001','Día de Txitxiburduntzi','fiesta','fiestas_wiki','Día de Txitxiburduntzi, en euskera Txitxiburduntzi eguna, es una antigua tradición del País Vasco.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_Txitxiburduntzi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186414,'31059','Día de la Almadía','fiesta','fiestas_wiki','El Día de la Almadía es una fiesta declarada Fiesta de Interés Turístico Regional en Navarra y Fiesta de Interés Turístico Nacional celebrada en la localidad navarra de Burgui (Valle de Roncal).​​',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Almadía','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186415,'14020','Día de la Comunidad Valenciana','fiesta','fiestas_wiki','El 9 de octubre es el Día de la Comunidad Valenciana y en él se conmemora la entrada a la ciudad de Valencia del rey de Aragón Jaime I El Conquistador en 1238. La conquista y formación del Reino de Valencia no se culminó hasta 1304-1305 con la Sentencia Arbitral de Torrellas y el Tratado de Elche, y el territorio…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Comunidad_Valenciana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186416,'28079','Día de la Comunidad de Madrid','fiesta','fiestas_wiki','El 2 de mayo de cada año se celebra el Día de la Comunidad de Madrid, la fiesta regional de esta comunidad autónoma de España. Con ella, se conmemora el Levantamiento del 2 de Mayo de 1808, en el que el pueblo madrileño se levantó en armas para rebelarse contra la ocupación francesa de España y para expulsar a este…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Comunidad_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186417,'22125','Día de la Faldeta','fiesta','fiestas_wiki','El Día de la Faldeta es una celebración del municipio español de Fraga en la provincia de Huesca, comunidad autónoma de Aragón que se celebró por primera vez en el año 1977 y consiste en una festividad homenaje a sus antepasados y a la mujer fragatina, a su forma de vida y a su manera de vestir.​​ Hasta hace unos…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Faldeta','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186418,'22125','Día de la Longaniza','fiesta','fiestas_wiki','El Día de la Longaniza es una fiesta celebrada en el municipio de Graus, en la provincia de Huesca, norte de España, en torno a la longaniza de Graus, un reconocido producto local. Se celebra el último sábado de cada julio y en 2013 fue declarada Fiesta de Interés Turístico por el Gobierno de Aragón. En julio de…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Longaniza','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186419,'29027','Día de la Música','fiesta','fiestas_wiki','El día de la música es un festival celebrado en Benamocarra, en la provincia de Málaga, España.​',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Música');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186420,'30030','Día de la Región de Murcia','fiesta','fiestas_wiki','El Día de la Región de Murcia, Día de Murcia o Día del pueblo murciano es la jornada festiva de la comunidad autónoma española de la Región de Murcia.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Región_de_Murcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186421,'26084','Día de la Tortilla','fiesta','fiestas_wiki','El día de la tortilla es un día de fiesta popular celebrada en varios municipios españoles. En algunos de ellos coincide con el día de comienzo del carnaval, es decir, con el jueves Lardero. Es costumbre la peregrinación de los habitantes del municipio a una zona tradicional de la propia localidad o cercana a ella…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_Tortilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186422,'31036','Día de la Tostada','fiesta','fiestas_wiki','El Día de la Tostada, denominado oficialmente como Día de la Tostada y la Fiesta del Aceite de Navarra, es una Fiesta de Interés Turístico de Navarra que se celebra el último domingo de febrero​​ y organizada por el ayuntamiento y el Consorcio Turístico de Tierra Estella.',42.5881424,-2.100715,'https://es.wikipedia.org/wiki/Día_de_la_Tostada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186423,'29901','Día de la berza','fiesta','fiestas_wiki','El día de la berza es una jornada gastronómica con fines benéficos celebrada en Torremolinos (Málaga) España. Su principal protagonista es la berza, plato presentado en cocido con garbanzos; y la pringá.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_berza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186424,'06061','Día de la haba','fiesta','fiestas_wiki','El día de la haba es un festival gastronómico celebrado en abril en Villanueva de la Concepción (Málaga) España.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_haba');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186425,'29033','Día de la morcilla','fiesta','fiestas_wiki','El día de la morcilla es una jornada gastronómica celebrada en Canillas de Aceituno (Málaga) España. Como su nombre indica, está dedicado a la morcilla, embutido típico de la zona. Esta fiesta está declarada "Fiesta de Singularidad Turística de la provincia de Málaga".',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_morcilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186426,'29067','Día de la sopa mondeña','fiesta','fiestas_wiki','El día de la sopa mondeña es un festival gastronómico celebrado en Monda (Málaga) España.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_la_sopa_mondeña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186427,'26051','Día de las Letras Canarias','fiesta','fiestas_wiki','El 21 de febrero es reconocido como el Día de las Letras Canarias, día instituido por el Gobierno de Canarias en 2006 con la intención de institucionalizarlo y celebrarse todos los años, y como homenaje a José de Viera y Clavijo, uno de los principales autores de la literatura canaria​ y máximo exponente de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_las_Letras_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186428,'33073','Día de los Pueblos de Asturias','fiesta','fiestas_wiki','El Día de los Pueblos de Asturias se celebra el último domingo del mes de agosto en Navelgas, Tineo, Asturias. La fiesta tiene como principal objetivo el hermanamiento de los diferentes pueblos de Asturias. El pueblo de Navelgas se llena de grupos folclóricos, bandas de gaitas, etc.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_los_Pueblos_de_Asturias','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186429,'49088','Día de los gamones','fiesta','fiestas_wiki','En plena Sierra de Cádiz, en el conjunto de perlas que conforman la Ruta de los Pueblos Blancos, hay una que resplandece con un brillo especial en el mes de mayo de cada año. Rodeada de las Sierras que llevan su mismo nombre, Ubrique engalana sus calles cada 3 del quinto mes en el Día de las Cruces de Mayo para…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_de_los_gamones');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186430,'29079','Día del Aceite Verdial','fiesta','fiestas_wiki','El día del Aceite Verdial es una jornada gastronómica celebrada en Periana (Málaga) España, celebrada el domingo posterior a la Semana Santa. Su principal protagonista es el aceite de oliva que se degusta en distintos platos así como otros productos como las habas, el bacalao y la paella. Está declarada Fiesta de…',NULL,NULL,'https://es.wikipedia.org/wiki/Día_del_Aceite_Verdial');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186431,'04078','Día del Camero Viejo','fiesta','fiestas_wiki','El Día del Camero Viejo es una fiesta de carácter anual y sede rotativa que se celebra en los pueblos del Camero Viejo, en La Rioja (España). En ella se suelen realizar distintas exposiciones, juegos, verbenas y una comida de hermandad.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_del_Camero_Viejo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186432,'29083','Día del caracol','fiesta','fiestas_wiki','El día del caracol es una fiesta gastronómica celebrada en Riogordo (Málaga) España, el último domingo de mayo. Además está declarado "Fiesta de interés singular de la provincia". La fiesta consiste en la degustación del caldo de caracol elaborado al estilo tradicional.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_del_caracol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186433,'29901','Día del pescaíto','fiesta','fiestas_wiki','El día del pescaíto es una jornada gastronómica celebrada en Torremolinos (Málaga) España. Su principal protagonista es el pescaíto frito, típico plato de la Costa del Sol y de otras localidades costeras de Andalucía y el resto de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Día_del_pescaíto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186434,'50174','Efraín Gómez Montón','fiesta','fiestas_wiki','Efraín Gómez Montón. Imaginero valenciano, nacido en Benaguacil (Valencia) el 8 de noviembre de 1924. Fallecido en la playa del Mareny de Barraquetes el 2 de agosto de 2008.',NULL,NULL,'https://es.wikipedia.org/wiki/Efraín_Gómez_Montón','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186435,'02001','Ejidos de la Feria','fiesta','fiestas_wiki','Los Ejidos de la Feria, también conocidos como La Cuerda o las Eras de Santa Catalina, es una gran explanada peatonal que rodea al Recinto Ferial de Albacete en el castizo y céntrico barrio Feria de la ciudad española de Albacete. Centro neurálgico de la capital, junto con el contiguo paseo de la Feria, es uno de…',38.99638,-1.869661,'https://es.wikipedia.org/wiki/Ejidos_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186436,'90255','El Alarde de Antzuola','fiesta','fiestas_wiki','El Alarde de Anzuola es un desfile que tiene lugar durante las fiestas de Anzuola (Guipúzcoa), el sábado por la tarde del tercer fin de semana de julio. En un tiempo, sin embargo, también fue conocida como el Alarde del Moro. El Alarde es fruto del trabajo y entendimiento colectivo de los distintos agentes…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Alarde_de_Antzuola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186437,'34120','El Bautizo del Niño','fiesta','fiestas_wiki','El Bautizo del Niño Jesús en la ciudad de Palencia es una celebración típicamente palentina que goza del reconocimiento de Fiesta de Interés Turístico Regional desde el año 1999,​ y desde marzo de 2015 tiene la consideración de Fiesta de Interés Turístico Nacional.​ Se celebra el día 1 de enero alrededor de las…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Bautizo_del_Niño','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186438,'11033','El Brujo (Nanclares)','fiesta','fiestas_wiki','El Brujo es el personaje que abre las fiestas patronales de Nanclares de la Oca, en la provincia vasca de Álava (España). Las fiestas de Nanclares, que se celebran en honor a la Asunción de Nuestra Señora y San Roque, arrancan la tarde del 12 o 13 de agosto de cada año y finalizan la noche del 16 de agosto. Desde…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Brujo_(Nanclares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186439,'33066','El Carmín','fiesta','fiestas_wiki','La Fiesta de Nuestra Señora del Carmen y Carmín, conocida popularmente como el Carmín de La Pola son las fiestas principales de la parroquia asturiana de La Pola Siero, en el concejo de Siero (España).',NULL,NULL,'https://es.wikipedia.org/wiki/El_Carmín','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186440,'43074','El Castillo de la Olla','fiesta','fiestas_wiki','El Castillo de La Olla (en valenciano Castell de L´Olla), es el evento más destacado de las fiestas de San Lorenzo (en valenciano festes de Sant Llorens). Estas fiestas se celebran en la población de Altea en la provincia de Alicante (España). Las fiestas de San Lorenzo tienen una duración aproximada de 4 días, del…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Castillo_de_la_Olla','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186441,'29067','El Cautivo (Málaga)','fiesta','fiestas_wiki','Nuestro Padre Jesús Cautivo, conocido popularmente como El Cautivo, es una escultura católica venerada en la ciudad andaluza de Málaga (España). Fue realizada en 1939 por el granadino José Gabriel Martín Simón para la Cofradía del Cautivo, de la que es titular, y con la que realiza su estación de penitencia el…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Cautivo_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186442,'09079','El Colacho','fiesta','fiestas_wiki','El Colacho es una fiesta que se celebra anualmente en la localidad de Castrillo de Murcia (Burgos, España). Lleva celebrándose ininterrumpidamente desde 1621.',42.358781,-4.061778,'https://es.wikipedia.org/wiki/El_Colacho','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186443,'90024','El Demonio de Badalona','fiesta','fiestas_wiki','El Demonio de Badalona (en catalán, El dimoni de Badalona) es la fiesta tradicional más importante de Badalona (Barcelona). Es el acto central de la Fiesta Mayor de la ciudad que se celebra las primeras semanas del mes de mayo y que es conocida como las Fiestas de Mayo (Festes de Maig). El 10 de mayo a partir de…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Demonio_de_Badalona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186444,'37273','El Descendimiento (Gregorio Fernández)','fiesta','fiestas_wiki','El Descendimiento es una obra realizada entre 1623 y 1624 por Gregorio Fernández, siendo modificada en 1757 por Pedro León Sedano. Portado el Viernes Santo en la Procesión General de la Sagrada Pasión del Redentor por la Cofradía del Descendimiento y Santísimo Cristo de la Buena Muerte, el grupo escultórico,…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Descendimiento_(Gregorio_Fernández)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186445,'47086','El Descendimiento (Medina de Rioseco)','fiesta','fiestas_wiki','El Descendimiento, también conocido como El Descendimiento de la Cruz y La Escalera, es una obra realizada por Francisco Díez de Tudanca en 1663 y modificada por Mariano Nieto Pérez en 1985. Portado el Viernes Santo por la Hermandad del Descendimiento de la Cruz, el grupo escultórico está ubicado en la Capilla de…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Descendimiento_(Medina_de_Rioseco)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186446,'10037','El Desván del Duende','fiesta','fiestas_wiki','El Desván del Duende fue un grupo español, originario de Extremadura. Su música se caracterizó por una marcada fusión de estilos y temáticas, dando cabida en sus letras a una reconocible carga de poesía, surrealismo y crítica social. Su fama empezó en el año 2006, gracias al tema Macetas de colores, elegido canción…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Desván_del_Duende','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186447,'38010','El Nazareno (Los Realejos)','fiesta','fiestas_wiki','El Nazareno es una pieza de imaginería tallada en madera de barbuzano, según descubriera el imaginero y restaurador Ezequiel de León Domínguez durante su intervención en 1993, que está considerada una de las mejores obras salidas de la gubia del escultor manchego de nacimiento, y sevillano de formación Martín de…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Nazareno_(Los_Realejos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186448,'38037','El Nazareno de Fernando Estévez','fiesta','fiestas_wiki','El Nazareno de Santa Cruz de La Palma es una escultura de madera policromada que representa a Jesucristo cargando con la cruz camino al Monte Calvario, tallada en 1840 por el ilustre escultor orotavense Fernando Estévez de Salas. Se la considera su obra más perfecta y acabada. A la imagen se le conoce también como…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Nazareno_de_Fernando_Estévez','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186449,'29083','El Paso de Riogordo','fiesta','fiestas_wiki','La Semana Santa en Riogordo es altamente conocida por El Paso, una representación religiosa que tiene lugar en la localidad de Riogordo, (Málaga) España. En la que se escenifican diferentes actos referentes a la pasión y muerte de Jesús. Está considerada como Fiesta de Interés Turístico Nacional y se celebra…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Paso_de_Riogordo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186450,'22002','El Rocío','fiesta','fiestas_wiki','El Rocío es una aldea​​ perteneciente al municipio de Almonte, en la provincia de Huelva, Andalucía (España). En ella se celebra anualmente la peregrinación mariana más importante de España (la Romería del Rocío),​​durante la cual el municipio se convierte en el 3.er más poblado del país.​​El Rocío se encuentra en…',37.13187778,-6.48251389,'https://es.wikipedia.org/wiki/El_Rocío','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186451,'43065','El Selu','fiesta','fiestas_wiki','José Luis García Cossío (Cádiz, 3 de junio de 1962) es un chirigotero español del Carnaval de Cádiz, conocido en el mundo del carnaval como El Selu.',NULL,NULL,'https://es.wikipedia.org/wiki/El_Selu','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186452,'47186','El Señor Atado a la Columna (Gregorio Fernández)','fiesta','fiestas_wiki','El Señor atado a la columna es una de las obras maestras del escultor barroco español Gregorio Fernández, que la talló en 1619 para la Cofradía Penitencial de la Santa Vera Cruz de Valladolid. Constituye el mayor exponente de representación escultórica de Cristo atado a la columna por su perfección anatómica y…',41.6538,-4.72639,'https://es.wikipedia.org/wiki/El_Señor_Atado_a_la_Columna_(Gregorio_Fernández)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186453,'16124','El Tío de la Tiza','fiesta','fiestas_wiki','Antonio Rodríguez Martínez (Cádiz, 24 de diciembre de 1861-Sevilla, 19 de agosto de 1912), más conocido como El Tío de la Tiza, fue un autor de agrupaciones español del Carnaval de Cádiz. Ha pasado a la historia del carnaval de Cádiz por su celebérrimo tango Los duros antiguos. Su apodo le viene por la costumbre…',NULL,NULL,'https://es.wikipedia.org/wiki/El_Tío_de_la_Tiza','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186454,'16009','El Yuyu','fiesta','fiestas_wiki','José Guerrero Roldán (Cádiz, 18 de septiembre de 1967), más conocido como El Yuyu, es un locutor de radio y autor de agrupaciones español del carnaval de Cádiz.​',NULL,NULL,'https://es.wikipedia.org/wiki/El_Yuyu','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186455,'33044','El desarme','fiesta','fiestas_wiki','El desarme es una fiesta de interés turístico nacional ​ que se celebra en la ciudad española de Oviedo, capital del Principado de Asturias. Cada 19 de octubre sus restaurantes presentan el cartel anunciador: ¡Hay desarme!',NULL,NULL,'https://es.wikipedia.org/wiki/El_desarme');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186456,'20070','El día de la bestia','fiesta','fiestas_wiki','El día de la bestia es una película hispano-italiana de comedia de terror y fantasía de 1995, dirigida por Álex de la Iglesia, quien coescribió el guion con Jorge Guerricaechevarría. Está protagonizada por Álex Angulo, Santiago Segura y Armando de Razza. La película ganó un total de seis premios Goya, incluyendo el…',NULL,NULL,'https://es.wikipedia.org/wiki/El_día_de_la_bestia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186457,'37285','El noveno','fiesta','fiestas_wiki','Las fiestas del Noveno, celebradas en la localidad salamantina de San Felices de los Gallegos, conmemoran la exención del pago a los habitantes del municipio de una novena parte de sus cosechas al Duque de Alba, hazaña lograda en 1852.',NULL,NULL,'https://es.wikipedia.org/wiki/El_noveno','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186458,'39035','El último desembarco de Carlos V','fiesta','fiestas_wiki','El último desembarco de Carlos V es una conmemoración y recreación histórica que tiene lugar cada tercer fin de semana de septiembre en Laredo (Cantabria, España). Es una fiesta local con mucho aire cultural y medieval celebrada de viernes a domingo.',NULL,NULL,'https://es.wikipedia.org/wiki/El_último_desembarco_de_Carlos_V');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186459,'38012','Eloísa González','fiesta','fiestas_wiki','Eloísa González Medina (La Guancha, Santa Cruz de Tenerife; 20 de noviembre de 1980) es una presentadora, actriz, cantante y modelo española.',NULL,NULL,'https://es.wikipedia.org/wiki/Eloísa_González','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186460,'25001','Els Elois','fiesta','fiestas_wiki','Els Elois es la fiesta más antigua de la ciudad de Berga (Cataluña).',NULL,NULL,'https://es.wikipedia.org/wiki/Els_Elois');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186461,'50178','Embajada (Moros y Cristianos)','fiesta','fiestas_wiki','La embajada es uno de los actos que forman parte de la fiesta en las fiestas de Moros y Cristianos en la Comunidad Valenciana, es una doble representación en la que intervienen pocos personajes, generalmente el capitán, el embajador y un centinela de cada bando.​ Se lleva a cabo en el marco de un castillo, real o…',NULL,NULL,'https://es.wikipedia.org/wiki/Embajada_(Moros_y_Cristianos)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186462,'45106','Embrujo de la luna mora','fiesta','fiestas_wiki','El embrujo de la luna mora es un festival celebrado en Carratraca, en la provincia de Málaga, España. La celebración tiene como objetivo dar a conocer el legado cultural andalusí, transportando a los visitantes al pasado para rememorar la convivencia existente entre las culturas que convivieron en aquella época.…',NULL,NULL,'https://es.wikipedia.org/wiki/Embrujo_de_la_luna_mora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186463,'45168','Emilio Cebrián Ruiz','fiesta','fiestas_wiki','Emilio Cebrián Ruiz (Toledo, Castilla-La Mancha, 30 de julio de 1900-Liria, Comunidad Valenciana, 3 de octubre de 1943)​ fue un compositor español de temas populares, en especial, pasodobles. Algunas de sus obras han trascendido y se han convertido en himnos oficiales como el de la ciudad de Jaén, Toledo o Baeza.',NULL,NULL,'https://es.wikipedia.org/wiki/Emilio_Cebrián_Ruiz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186464,'43065','Emilio García Armenta','fiesta','fiestas_wiki','Emilio García Armenta (Montilla, 20 de julio de 1908-Sevilla, 18 de julio de 1971) fue un orfebre especializado en temas de la Semana Santa sevillana y maestro de la Escuela de Artes y Oficios Artísticos de Sevilla.',NULL,NULL,'https://es.wikipedia.org/wiki/Emilio_García_Armenta','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186465,'06018','Emérita Lúdica','fiesta','fiestas_wiki','Emerita Lvdica es un festival de recreación histórica sobre el mundo romano celebrado anualmente en el mes de mayo en la ciudad de Mérida (España). Fue declarada fiesta de Interés Turístico Regional de Extremadura en 2022 y en la edición de 2024 contó con más de 130 000 visitantes. La XV edición del festival se…',NULL,NULL,'https://es.wikipedia.org/wiki/Emérita_Lúdica','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186466,'43055','Encamisada de Falset','fiesta','fiestas_wiki','La Encamisada de Falset es una fiesta celebrada en el municipio de Falset, Tarragona (España)​ durante el fin de semana más cercano al día de San Antonio Abad, es decir en la segunda o tercera semana de enero.​ La fiesta, declarada Fiesta Tradicional de Interés Nacional,​​ puede considerarse una variedad de las…',41.14619,0.82008,'https://es.wikipedia.org/wiki/Encamisada_de_Falset','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186467,'50190','Encierro andando de Novallas','fiesta','fiestas_wiki','El encierro andando es un festejo popular taurino que se celebra en la localidad Novallas (Zaragoza) cada 15 de septiembre durante las Fiestas de la Cruz y consiste en el traslado del ganado desde el corral de la dehesa hasta el casco urbano.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierro_andando_de_Novallas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186468,'31104','Encierro del Pilón','fiesta','fiestas_wiki','El Encierro del Pilón, oficialmente denominado como "El encierro del pilón de Falces", es un festejo popular taurino celebrado en la localidad navarra de Falces durante las fiestas patronales en honor a la Virgen de Nieva.',42.41872177,-1.80846928,'https://es.wikipedia.org/wiki/Encierro_del_Pilón','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186469,'18154','Encierros Taurinos de La Peza','fiesta','fiestas_wiki','Los Encierros Taurinos de La Peza (Granada) son un festejo popular taurino que se celebra durante las fiestas patronales en honor a Nuestra Señora la Virgen del Rosario y del Santísimo Cristo de la Misericordia, que tienen lugar en el mes de octubre.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_Taurinos_de_La_Peza','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186470,'13040','Encierros al Estilo Fernanduco de Fernán Caballero','fiesta','fiestas_wiki','Los encierros al estilo fernanduco son un festejo popular taurino celebrado en la localidad de Fernán Caballero (Ciudad Real) durante las fiestas patronales en honor a San Agustín, el 30 de agosto.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_al_Estilo_Fernanduco_de_Fernán_Caballero','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186471,'90332','Encierros de Almodóvar del Campo','fiesta','fiestas_wiki','Los encierros de Almodóvar del Campo (Ciudad Real, España) son un festejo popular que se celebran en torno al 12 de septiembre y se engloban en unas fiestas dedicadas a la figura del toro, por lo que la mayoría de las actividades giran en torno a este animal.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Almodóvar_del_Campo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186472,'90243','Encierros de Ampuero','fiesta','fiestas_wiki','Los encierros de Ampuero son un festejo popular taurino celebrados en la localidad de Ampuero (Cantabria, España) con motivo de la festividad de la Virgen Niña, a principios de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Ampuero','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186473,'30011','Encierros de Blanca','fiesta','fiestas_wiki','Los encierros de Blanca se celebran en la localidad murciana de Blanca (España) con motivo de sus fiestas patronales en honor a San Roque entre los días 10 y 14 de agosto, en las que el aspecto taurino tiene una gran importancia, ya que celebra unos encierros que datan de 1658, por lo que supera ampliamente los…',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Blanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186474,'19053','Encierros de Brihuega','fiesta','fiestas_wiki','Los encierros de Brihuega (Guadalajara, España) son un festejo popular taurino que se celebra en dicha localidad durante las fiestas patronales en honor a la Virgen de la Peña.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Brihuega','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186475,'30013','Encierros de Calasparra','fiesta','fiestas_wiki','Los encierros de Calasparra son un festejo popular taurino que se celebra en la localidad de Calasparra (Murcia, España) del 3 al 8 de septiembre con motivo de la celebración de la Virgen de la Esperanza.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Calasparra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186476,'40063','Encierros de Cuéllar','fiesta','fiestas_wiki','Los encierros de Cuéllar son una fiesta popular española declarada de Interés Turístico Internacional​ que se celebra el último fin de semana de agosto en la ciudad segoviana de Cuéllar (Castilla y León, España), y están considerados los encierros más antiguos de España, pues hasta el momento ninguna ciudad ha…',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Cuéllar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186477,'02011','Encierros de Elche de la Sierra','fiesta','fiestas_wiki','Los encierros de Elche de la Sierra (Albacete, España) son un festejo popular taurino que se celebra durante la festividad de San Blas (3 de febrero) y en las fiestas en honor a la Virgen de los Dolores y al Cristo de la Consolación (del 15 al 18 de septiembre).',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Elche_de_la_Sierra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186478,'19130','Encierros de Guadalajara','fiesta','fiestas_wiki','Los encierros de Guadalajara son un festejo popular que se celebra en la localidad de Guadalajara (Castilla-La Mancha, España) del 13 al 16 de septiembre con motivo de la Feria de la Antigua en honor a la Virgen de la Antigua.​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Guadalajara');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186479,'47085','Encierros de Medina del Campo','fiesta','fiestas_wiki','Los encierros de Medina del Campo (Valladolid, España) son un festejo popular taurino que se celebra durante las fiestas patronales en honor a San Antolín, del 1 al 8 de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Medina_del_Campo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186480,'30028','Encierros de Moratalla','fiesta','fiestas_wiki','Los encierros de Moratalla, también conocidos como Fiesta de la Vaca, son un festejo popular que se celebra en la localidad de Moratalla (Murcia, España) del 11 al 17 de julio en honor al Santísimo Cristo del Rayo.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Moratalla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186481,'47104','Encierros de Olmedo','fiesta','fiestas_wiki','Los encierros tradicionales de Olmedo o simplemente encierros de Olmedo son un festejo popular taurino que se celebran en la localidad de Olmedo (Valladolid, España) el 29 y 30 de septiembre en honor a sus patronos, san Miguel y san Jerónimo, y el 10 de octubre con motivo de la conmemoración de la coronación…',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Olmedo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186482,'12085','Encierros de Oropesa del Mar','fiesta','fiestas_wiki','La localidad castellonense de Oropesa del Mar (España) celebra todos los años, con motivo de la festividad de San Jaime, patrón de la localidad, unos encierros muy peculiares que atraen a numerosos aficionados de la comarca​ y que fueron declarados Fiesta de Interés Turístico Provincial el 11 de junio de 2013.​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Oropesa_del_Mar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186483,'90641','Encierros de Pamplona','fiesta','fiestas_wiki','Los encierros de Pamplona son una celebración taurina, quizá la más popular y conocida a nivel mundial, de las Fiestas de San Fermín de Pamplona (Navarra, España). En rigor, es un desencajonamiento taurino, es decir, la acción de desembarcar toros de lidia en la plaza de toros,​ que en el caso de la capital navarra…',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_Pamplona','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186484,'28134','Encierros de San Sebastián de los Reyes','fiesta','fiestas_wiki','Los encierros de San Sebastián de los Reyes son una tradición popular española que fue declarada por el Pleno del Ayuntamiento Bien de Interés Cultural.​ Asimismo, las fiestas en las que se enmarca este espectáculo taurino están declaradas de Interés Turístico Nacional de la Comunidad de Madrid que se celebran a…',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_de_San_Sebastián_de_los_Reyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186485,'46044','Encierros y capeas de Ayora','fiesta','fiestas_wiki','Los encierros y capeas es un festejo popular que se celebra en la localidad de Ayora (provincia de Valencia) del 8 al 15 de agosto en honor a la Virgen de la Asunción.​',NULL,NULL,'https://es.wikipedia.org/wiki/Encierros_y_capeas_de_Ayora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186486,'09174','Encuentro Internacional de Nombres Raros','fiesta','fiestas_wiki','El Encuentro Internacional de Nombres Raros es un evento que se realizó por primera vez en Huerta de Rey (Burgos, España). Esta localidad es famosa en España por tener una gran población con nombres pocos comunes. La finalidad del evento fue el que las personas con nombres poco frecuentes se pudieran conocer y…',NULL,NULL,'https://es.wikipedia.org/wiki/Encuentro_Internacional_de_Nombres_Raros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186487,'38012','Enrique González Bethencourt','fiesta','fiestas_wiki','Enrique González Bethencourt (El Toscal, Santa Cruz de Tenerife, 23 de septiembre de 1924 - Santa Cruz de Tenerife, 13 de mayo de 2010) fue el fundador y director de la Afilarmónica NiFú-NiFá,​ siendo considerado el padre de las murgas de Canarias.​​ Asimismo fue una de las personalidades más importantes y queridas…',NULL,NULL,'https://es.wikipedia.org/wiki/Enrique_González_Bethencourt','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186488,'10096','Enrique Pérez Comendador','fiesta','fiestas_wiki','Enrique Pérez Comendador (Hervás, 17 de noviembre de 1900-Madrid, 2 de marzo de 1981) fue un escultor español de la Escuela sevillana de escultura.',NULL,NULL,'https://es.wikipedia.org/wiki/Enrique_Pérez_Comendador','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186489,'09473','Enrique Villegas Vélez','fiesta','fiestas_wiki','Enrique Villegas Vélez, más conocido como Enrique Villegas (Ayamonte, Huelva, 31 de mayo de 1923-Cádiz, 21 de mayo de 2015​), fue un músico, letrista español, poeta y uno de los compositores más importantes del Carnaval de Cádiz. Exponente de esta fiesta.',NULL,NULL,'https://es.wikipedia.org/wiki/Enrique_Villegas_Vélez','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186490,'26010','Entierro de Genarín','fiesta','fiestas_wiki','El Entierro de Genarín es una procesión profana que se celebra cada año en la ciudad española de León. Tiene lugar la noche del Jueves al Viernes Santo y rememora, en tono socarrón, la vida y el fallecimiento de Genaro Blanco Blanco, hombre común cuya vida se convirtió en leyenda, a la vez que se constituye como…',42.5989,-5.5669,'https://es.wikipedia.org/wiki/Entierro_de_Genarín','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186491,'30030','Entierro de la Sardina en Murcia','fiesta','fiestas_wiki','El Entierro de la Sardina es una fiesta pagana que se celebra en la ciudad de Murcia (España) durante las Fiestas de Primavera y cuyo acto central es un gran desfile de carrozas que culmina con la quema de la sardina el sábado siguiente a la Semana Santa. Está declarada Fiesta de Interés Turístico Internacional.',37.9861,-1.1303,'https://es.wikipedia.org/wiki/Entierro_de_la_Sardina_en_Murcia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186492,'44088','Entierro de la cuba','fiesta','fiestas_wiki','El Entierro de la Cuba es la actividad con la que se suelen concluir las fiestas populares en la mayoría de municipios de La Rioja, en muchos pueblos de Burgos sobre todo de la Sierra y Pinares y en algunos otros lugares de España. Es una forma de despedir los días alegres precedentes y afrontar la realidad…',NULL,NULL,'https://es.wikipedia.org/wiki/Entierro_de_la_cuba');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186493,'41042','Entornao','fiesta','fiestas_wiki','Un entornao es un dulce típico de Fuentes de Andalucía, pueblo de la provincia de Sevilla, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Entornao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186494,'46257','Entrada de Toros al Estilo Calijó','fiesta','fiestas_wiki','La Entrada de Toros al Estilo Calijó de Càlig (Castellón) es un festejo popular taurino que se celebra durante las Fiestas Patronales en honor a San Lorenzo, a principios de agosto. Esta fiesta, que se celebra desde mediados del siglo pasado, da inicio a las tardes de vacas y toros, con la entrada al municipio de…',NULL,NULL,'https://es.wikipedia.org/wiki/Entrada_de_Toros_al_Estilo_Calijó','Interés Turístico Regional');
