INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186496,'12104','Entrada de toros y caballos','fiesta','fiestas_wiki','La Entrada de toros y caballos es una fiesta popular española que se celebra en la localidad castellonense de Segorbe (Comunidad Valenciana) resultado de la evolución del traslado de reses para ser corridas en un recinto cerrado o plaza de toros. Esta celebración está declarada Fiesta de Interés Turístico, Fiesta…',39.8519,-0.4896,'https://es.wikipedia.org/wiki/Entrada_de_toros_y_caballos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186497,'40093','Entroido','fiesta','fiestas_wiki','El entroido, antroido, entroiro, entruido o entrudio​ es una fiesta popular de carnaval en Galicia, con tintes particulares y diferenciados entre las diversas localidades. Algunos ayuntamientos gallegos declararon festivos locales alguno de los días de carnaval (lunes o martes de Carnaval) en 2015.​ Nueve son los…',NULL,NULL,'https://es.wikipedia.org/wiki/Entroido');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186498,'32032','Entroido de Ginzo de Limia','fiesta','fiestas_wiki','El entroido de Ginzo de Limia es una festividad de origen popular que se celebra durante el carnaval, en la localidad española de Ginzo de Limia, en Galicia.',NULL,NULL,'https://es.wikipedia.org/wiki/Entroido_de_Ginzo_de_Limia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186499,'32039','Entroido de Laza','fiesta','fiestas_wiki','El Entroido de Laza es una festividad de carácter tradicional que durante los días anteriores al Miércoles de Ceniza se realiza en el pueblo de Laza (Orense) España. Es considerado el Carnaval con mayor antigüedad y esplendor de Galicia. El punto álgido de la fiesta se encuentra la noche del viernes anterior al…',NULL,NULL,'https://es.wikipedia.org/wiki/Entroido_de_Laza','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186500,'27047','Entroido de Salcedo','fiesta','fiestas_wiki','El Entroido de Salcedo es una celebración tradicional festiva del Entroido que tiene lugar en la parroquia de Salcedo, en el municipio lucense de Puebla del Brollón, en Galicia, España. El personaje principal de este carnaval es el Oso de Salcedo. Las peculiaridades de la celebración del carnaval en la parroquia de…',NULL,NULL,'https://es.wikipedia.org/wiki/Entroido_de_Salcedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186501,'32092','Entroido de Villarino de Conso','fiesta','fiestas_wiki','El entroido de Villarino de Conso es el conjunto de celebraciones populares que tienen lugar en la localidad española de Villarino de Conso durante el carnaval.',42.17694444,-7.17111111,'https://es.wikipedia.org/wiki/Entroido_de_Villarino_de_Conso','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186502,'22002','Ermita de El Rocío','fiesta','fiestas_wiki','La ermita del Rocío, denominada oficialmente como santuario de Nuestra Señora del Rocío, es un templo católico situado en la aldea de El Rocío, Almonte, provincia de Huelva. El santuario actual fue diseñado por Antonio Delgado y Roig y Alberto Balbontín de Orta y se terminó en 1969.​ En la ermita se venera la…',37.13070973,-6.48502118,'https://es.wikipedia.org/wiki/Ermita_de_El_Rocío','IT Internacional');
