INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186504,'41027','Escardiel','fiesta','fiestas_wiki','La Virgen de Escardiel es una advocación mariana que se venera en la Ermita de Escardiel, a 5 kilómetros de la localidad de Castilblanco de los Arroyos (Sevilla). Se trata de una pequeña talla, popular en la provincia de Sevilla, y en su honor se celebra la Romería de Nuestra Señora de Escardiel.',NULL,NULL,'https://es.wikipedia.org/wiki/Escardiel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186505,'03007','Escenificación del hallazgo de la Virgen del Sufragio (Benidorm)','fiesta','fiestas_wiki','La escenificación del hallazgo de la Virgen del Sufragio (conocida en valenciano como Mare de Déu del Sofratge) es una representación teatral que recrea la aparición de la imagen de la patrona de Benidorm en una embarcación a la deriva. Se celebra anualmente durante las Festes Majors Patronals de Benidorm, del 13…',NULL,NULL,'https://es.wikipedia.org/wiki/Escenificación_del_hallazgo_de_la_Virgen_del_Sufragio_(Benidorm)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186506,'50178','Escuadra de moros y cristianos','fiesta','fiestas_wiki','Se denomina escuadra a los componentes de una comparsa, filada o cábila que participan en los desfiles de las fiestas de moros y cristianos. Está formada por 10 o 15 festeros que, bien aisladamente, o en bloques de varias escuadras se sitúan tras un cabo de escuadra y desfilan al ritmo de las marchas moras, en el…',NULL,NULL,'https://es.wikipedia.org/wiki/Escuadra_de_moros_y_cristianos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186507,'02001','Escuela Taurina de Albacete','fiesta','fiestas_wiki','La Escuela Taurina de Albacete es una escuela de tauromaquia destinada a la formación de toreros con sede en la ciudad española de Albacete.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Escuela_Taurina_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186508,'37011','Escuela de imaginería de Salamanca','fiesta','fiestas_wiki','Grupo de escultores imagineros que trabajaron en Salamanca, concretamente en un taller sito el Patio de Escuelas desde 1939, realizando numerosas e importantes tallas religiosas para toda España.',NULL,NULL,'https://es.wikipedia.org/wiki/Escuela_de_imaginería_de_Salamanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186509,'41022','Esperanza Elena Caro','fiesta','fiestas_wiki','Esperanza Elena Caro (La Campana, provincia de Sevilla, 4 de septiembre de 1906-Sevilla, 6 de marzo de 1985) fue una bordadora española del siglo XX que realizó importantes trabajos destinados en su mayor parte a organizaciones religiosas, principalmente hermandades de la Semana Santa de Sevilla y Andalucía.​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Esperanza_Elena_Caro','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186510,'38012','Esperanza Macarena de Santa Cruz de Tenerife','fiesta','fiestas_wiki','María Santísima de la Esperanza Macarena es una advocación mariana de gran veneración en la ciudad canaria de Santa Cruz de Tenerife (España). La imagen es una réplica de la afamada Esperanza Macarena de Sevilla, siendo fruto de la devoción universal que recibe esta advocación. Fue realizada en 1958 por Antonio…',NULL,NULL,'https://es.wikipedia.org/wiki/Esperanza_Macarena_de_Santa_Cruz_de_Tenerife');
