INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186512,'48014','Espicha','fiesta','fiestas_wiki','Una espicha es una reunión festiva asturiana en la que se bebe sidra.​​ Se celebra en un lagar (llagar en asturiano) con el objetivo de abrir o «espichar» un tonel o barrica de sidra, una pipa, como se suele llamar a esos grandes recipientes de unos quinientos litros, donde el zumo de manzana fermenta durante dos o…',NULL,NULL,'https://es.wikipedia.org/wiki/Espicha');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186513,'46079','Estación de penitencia','fiesta','fiestas_wiki','La estación de penitencia es el nombre que se da a la procesión que las hermandades pasionistas realizan en Semana Santa por las calles, siempre y cuando durante su recorrido la cofradía haga visita (de aquí el término "estación") al menos a un templo. En caso de no producirse dicha estación, el término procesión…',NULL,NULL,'https://es.wikipedia.org/wiki/Estación_de_penitencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186514,'33014','Estafeta (calle)','fiesta','fiestas_wiki','Estafeta es el nombre de una famosa calle de la ciudad de Pamplona, la capital de la Comunidad Foral de Navarra (España), debido a que es una por las que discurre el encierro de San Fermín.',42.81694444,-1.64166667,'https://es.wikipedia.org/wiki/Estafeta_(calle)','IT Internacional');
