INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186524,'12027','Fallas de Benicarló','fiesta','fiestas_wiki','Las Fallas de Benicarló se celebran entre la última semana de febrero o la primera de marzo hasta el día de San José, el 19 de marzo. En estos días, que comienzan con la multitudinaria cabalgata del Ninot, tienen lugar gran cantidad de actos comenzando por la plantà, continuando con pasacalles, despertàs,…',40.41861111,0.42305556,'https://es.wikipedia.org/wiki/Fallas_de_Benicarló','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186525,'03017','Fallas de Elda','fiesta','fiestas_wiki','Las Fallas de Elda son unas fiestas que se celebran anualmente en la ciudad española de Elda. Su celebración tiene lugar la tercera semana de septiembre, y consisten en la planta y posterior quema de monumentos artísticos de madera y cartón. Los monumentos suelen constar de una alta estructura central de madera, y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fallas_de_Elda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186526,'46131','Fallas de Gandía','fiesta','fiestas_wiki','Las Fallas de Gandía son una festividad tradicional que se celebra anualmente en la ciudad de Gandía, en la Comunidad Valenciana, España. Esta celebración tiene lugar del 15 al 19 de marzo y, estando profundamente arraigada a la tradición valenciana combina arte, creatividad y sátira y da voz a los sentimientos de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fallas_de_Gandía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186527,'45017','Fallas de Játiva','fiesta','fiestas_wiki','Las Fallas de Játiva (Falles de Xàtiva en valenciano) son una fiesta que se celebra del 15 al 19 de marzo en la ciudad de Játiva, en la Comunidad Valenciana, en honor a San José.',38.9887,-0.5192,'https://es.wikipedia.org/wiki/Fallas_de_Játiva','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186528,'46186','Fallas de Paiporta','fiesta','fiestas_wiki','Las Fallas de Paiporta (en valenciano Falles de Paiporta), son las fiestas que en honor a San José se celebran en el municipio valenciano de Paiporta (España), concretamente durante el mes de marzo, desde el día 1 de marzo hasta concluir el día 19 de marzo (festividad del santo).',NULL,NULL,'https://es.wikipedia.org/wiki/Fallas_de_Paiporta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186529,'12089','Fallas de Peñíscola','fiesta','fiestas_wiki','Las Fallas de Peñíscola fueron una fiesta, basada en las Fallas de Valencia, que se celebró en la localidad española de Peñíscola entre 2003 y 2010, siendo este el último año en el que tuvo lugar.​ En los años en los que se celebraron constaban de una sola comisión, denominada Falla Peñíscola y plantaba sus dos…',NULL,NULL,'https://es.wikipedia.org/wiki/Fallas_de_Peñíscola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186530,'90361','Fallas de Torrente','fiesta','fiestas_wiki','Las Fallas de Torrente (en valenciano Falles de Torrent), son las fiestas que se celebran en Torrente, y al igual que las Fallas de Valencia, se celebran del 15 al 19 de marzo en honor a San José. Cuentan con 29 comisiones falleras, que plantan 58 fallas (29 mayores y 29 infantiles). En cuanto al censo de falleras…',39.4365,-0.4679,'https://es.wikipedia.org/wiki/Fallas_de_Torrente','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186531,'46250','Fallas de Valencia','fiesta','fiestas_wiki','Las Fallas de Valencia (Falles en valenciano) son unas fiestas que se celebran del 1 al 19 de marzo y que suponen una arraigada tradición en la ciudad española de Valencia. Oficialmente empiezan el último domingo de febrero con el acto de la crida (en valenciano; ''pregón o llamada'', en español). Actualmente, esta…',39.47,-0.3764,'https://es.wikipedia.org/wiki/Fallas_de_Valencia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186532,'12126','Fallas de Vall de Uxó','fiesta','fiestas_wiki','Las Fallas de Vall de Uxó (en valenciano Falles de la Vall d''Uixó), son las fiestas que en honor a San José se celebran en el municipio castellonense de Vall de Uxó (España), concretamente durante el mes de marzo y culminando el día 19 (festividad del santo). Dentro de la comarca de la Plana Baja, le acompañan en…',NULL,NULL,'https://es.wikipedia.org/wiki/Fallas_de_Vall_de_Uxó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186533,'46250','Fallera mayor de Valencia','fiesta','fiestas_wiki','La figura de fallera mayor se da en Valencia y es la mayor representante de una comisión fallera, durante los festejos y actividades que dicha comisión realiza durante el año que dure su reinado, también ejercerá de representante ante otras comisiones falleras u otros eventos a los que la comisión sea invitada.…',NULL,NULL,'https://es.wikipedia.org/wiki/Fallera_mayor_de_Valencia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186534,'40181','Federico Coullaut-Valera','fiesta','fiestas_wiki','Federico Coullaut-Valera Mendigutia (Madrid; 25 de abril de 1912 - La Granja de San Ildefonso, Real Sitio de San Ildefonso; 13 de octubre de 1989), escultor e imaginero español.',NULL,NULL,'https://es.wikipedia.org/wiki/Federico_Coullaut-Valera','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186535,'01003','Feira Franca Medieval (Betanzos)','fiesta','fiestas_wiki','La Feira Franca Medieval es un evento festivo que tiene lugar en el casco antiguo de la localidad española de Betanzos (La Coruña), recreando durante tres días un mercado medieval. Se celebra con carácter anual, el segundo fin de semana de julio.',NULL,NULL,'https://es.wikipedia.org/wiki/Feira_Franca_Medieval_(Betanzos)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186536,'36011','Feira Franca de Pontevedra','fiesta','fiestas_wiki','La Feira Franca de Pontevedra es una fiesta medieval que se celebra en la ciudad española de Pontevedra el viernes por la tarde y el sábado del primer fin de semana de septiembre.​ Está ambientada en la Edad Media e incluye un mercado medieval, un torneo de caballería, espectáculos de cetrería, puestos de comida,…',42.43138889,-8.64388889,'https://es.wikipedia.org/wiki/Feira_Franca_de_Pontevedra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186537,'05122','Felices Pascuas','fiesta','fiestas_wiki','Felices Pascuas es una película española estrenada el 13 de diciembre de 1954, dirigida por Juan Antonio Bardem, en la que fue su primera película dirigida en solitario y protagonizada en los papeles principales por Julia Martínez y Bernard La Jarrige.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Felices_Pascuas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186538,'28161','Feria Barroca (Valdemoro)','fiesta','fiestas_wiki','La Feria Barroca de Valdemoro es un mercado artesano ambientado en el siglo XVII que se celebra en la plaza de la Constitución del municipio. De carácter anual, tiene lugar a mediados del mes de octubre. Fue recuperada en 2004, y su origen proviene del Privilegio de Feria otorgado por el rey Felipe III de España a…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_Barroca_(Valdemoro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186539,'08113','Feria Mediterránea de Manresa','fiesta','fiestas_wiki','La Fira Mediterrània de Manresa es un mercado de propuestas artísticas que utilizan la raíz, la tradición y la cultura popular como motor creativo. Se celebra anualmente desde el año 1998 y se ha convertido en un marco de intercambios entre profesionales del sector que venden y compran espectáculos. La mayoría de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_Mediterránea_de_Manresa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186540,'08279','Feria Modernista de Tarrasa','fiesta','fiestas_wiki','La Feria Modernista de Tarrasa se ha convertido en pocos años en uno de los más destacados eventos turísticos de España, que atrae cada año en el mes de mayo más de cien mil visitantes, durante un fin de semana lleno de actividades culturales, gastronómicas, infantiles, espectáculos, exposiciones... Es ésta la gran…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_Modernista_de_Tarrasa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186541,'16002','Feria Real de Algeciras','fiesta','fiestas_wiki','La Feria Real de Algeciras es la más importante de las fiestas celebradas en la localidad andaluza de Algeciras. La primera Feria Real de Algeciras se celebró con Permiso Real los tres primeros días de junio de 1850 como feria de ganado al norte de la ciudad en la zona conocida como El Calvario, junto al camino de…',36.14013889,-5.45741667,'https://es.wikipedia.org/wiki/Feria_Real_de_Algeciras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186542,'02001','Feria Taurina de Albacete','fiesta','fiestas_wiki','La Feria Taurina de Albacete, también conocida como Feria de la Virgen de Los Llanos, es el conjunto de festejos taurinos que se celebran en la plaza de toros de Albacete (España) durante diez días consecutivos, del 8 al 17 de septiembre, en honor a la Virgen de Los Llanos, patrona de la capital, dentro de los…',38.997125,-1.87033611,'https://es.wikipedia.org/wiki/Feria_Taurina_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186543,'41091','Feria de Abril','fiesta','fiestas_wiki','La Feria de Abril o Feria de Sevilla es una fiesta de primavera que se celebra anualmente en la ciudad de Sevilla (Comunidad autónoma de Andalucía, España), donde el público se reúne en un gran recinto denominado Real de la Feria, con calles engalanadas con farolillos y con casetas efímeras, por las que durante el…',37.37111111,-5.9975,'https://es.wikipedia.org/wiki/Feria_de_Abril','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186544,'08194','Feria de Abril de Cataluña','fiesta','fiestas_wiki','La Feria de Abril de Cataluña (en catalán y oficialmente: Fira d''Abril de Catalunya)​ es una fiesta popular de tradición andaluza que se celebra en Barcelona anualmente, durante 10 días entre abril y mayo, en un recinto ferial del área metropolitana de la ciudad, donde se instalan numerosas casetas y atracciones.…',41.40657416,2.22225103,'https://es.wikipedia.org/wiki/Feria_de_Abril_de_Cataluña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186545,'02001','Feria de Albacete','fiesta','fiestas_wiki','La Feria de Albacete es la fiesta grande , declarada de Interés Turístico Internacional, que se celebra anualmente del 7 al 17 de septiembre en honor a la Virgen de los Llanos en la ciudad española de Albacete.​ Se desarrolla principalmente en el área de más de 180 000 m²​ comprendida por el Recinto Ferial de…',38.997191,-1.870404,'https://es.wikipedia.org/wiki/Feria_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186546,'04004','Feria de Almería','fiesta','fiestas_wiki','La Feria de Almería es la fiesta grande de la ciudad española de Almería capital de la provincia homónima en la comunidad de Andalucía, España. Esta tiene lugar a partir de la segunda quincena del mes de agosto, comenzando concretamente dos viernes antes al último domingo de agosto, en honor a la patrona de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Almería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186547,'06049','Feria de Artesanía de Castilla-La Mancha Artesana','fiesta','fiestas_wiki','La Feria de Artesanía de Castilla-La Mancha Artesana, también conocida como Feria de Artesanía de Albacete, es una feria de artesanía internacional que se celebra anualmente en la ciudad española de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Artesanía_de_Castilla-La_Mancha_Artesana','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186548,'14021','Feria de Córdoba (España)','fiesta','fiestas_wiki','La Feria de Nuestra Señora de la Salud, más conocida como la Feria de Córdoba, es una feria que se celebra en Córdoba, España durante la última semana del mes de mayo.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Córdoba_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186549,'46250','Feria de Julio de Valencia','fiesta','fiestas_wiki','En 1870 el Ayuntamiento de Valencia propuso celebrar una feria anual y una exposición de toda clase de productos durante el mes de julio para animar la capital y atraer a los forasteros. La Feria se organizó alrededor del ciclo taurino de San Jaime, dando lugar a una de las primeras ferias en las que se daban…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Julio_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186550,'06049','Feria de La Ascensión','fiesta','fiestas_wiki','La Feria de La Ascensión es una fiesta que se celebra en la localidad asturiana de Oviedo. Los inicios de la fiesta se remontan al siglo XVI iniciándose como un certamen ganadero. La fiesta se celebra unos cuarenta días después de la celebración de la Semana Santa, con motivo del Día de la Ascensión.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_La_Ascensión','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186551,'52001','Feria de Melilla','fiesta','fiestas_wiki','La Feria de Melilla, también conocida como la Feria de Septiembre, es una de las festividades más importantes de la ciudad autónoma de Melilla, celebrada en honor a su Patrona, la Virgen de la Victoria. Esta festividad tiene sus raíces en el siglo XVI y ha evolucionado a lo largo de los siglos hasta convertirse en…',35.29444444,-2.93491667,'https://es.wikipedia.org/wiki/Feria_de_Melilla','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186552,'30030','Feria de Murcia','fiesta','fiestas_wiki','La Feria de Septiembre o Feria de Murcia es una fiesta de fin del verano que se celebra anualmente en la ciudad de Murcia (Comunidad autónoma de Murcia, España), donde el público se reúne en diversos recintos a lo largo del cauce urbano del río Segura, con calles engalanadas con luces y casetas efímeras de diversa…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Murcia','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186553,'29067','Feria de Málaga','fiesta','fiestas_wiki','La Feria de Málaga o Feria de Agosto es la celebración de la entrada de los Reyes Católicos a la ciudad el 19 de agosto de 1487. Comienza el segundo viernes de agosto, con el espectáculo de los fuegos artificiales.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186554,'44206','Feria de San Agustín','fiesta','fiestas_wiki','La Real Feria y Fiestas de San Agustín, Feria de San Agustín o, simplemente, Feria de Linares es la fiesta más importante de Linares que se celebra entre los días 27 de agosto al 1 de septiembre desde agosto de 1734 en Linares (Jaén) España. En ella se puede disfrutar de una amplia oferta de ocio, desde conciertos…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_San_Agustín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186555,'11031','Feria de San Fernando (Cáceres)','fiesta','fiestas_wiki','La Feria de San Fernando o Feria de mayo, es un acontecimiento festivo de la ciudad extremeña de Cáceres que se celebra alrededor del 30 de mayo.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_San_Fernando_(Cáceres)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186556,'03904','Feria de San Isidro','fiesta','fiestas_wiki','La Feria de San Isidro es una serie de festejos taurinos que se celebran en la plaza de toros de las Ventas de Madrid, entre mayo y junio, en torno a la festividad de San Isidro Labrador (15 de mayo), el santo patrono de la capital española. Inicialmente denominada Feria de Madrid, con el tiempo se ha convertido en…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_San_Isidro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186557,'07049','Feria de San Juan (Badajoz)','fiesta','fiestas_wiki','La Feria de San Juan de Badajoz, también conocida como Feria de Badajoz, es la fiesta local de Badajoz (España), que recibe su nombre en honor al patrón de la Diócesis de Badajoz, San Juan Bautista (el patrón de la capital pacense es San José), siendo el día grande el 24 de junio.​ La tradicional Feria de San Juan…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_San_Juan_(Badajoz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186558,'06049','Feria de San Lucas (Jaén)','fiesta','fiestas_wiki','La Feria de San Lucas (Jaén) es de las últimas de las ferias de primavera y verano de Andalucía, además de la última feria taurina de la temporada.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_San_Lucas_(Jaén)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186559,'11032','Feria de Sanlúcar de Barrameda','fiesta','fiestas_wiki','La Feria de la Manzanilla, o simplemente la Feria de Sanlúcar, es una fiesta que se celebra anualmente la ciudad española de Sanlúcar de Barrameda. Su nombre se refiere a la manzanilla con su propia denominación de origen (Manzanilla de Sanlúcar) que se cría exclusivamente en esta ciudad. La feria tiene lugar…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Sanlúcar_de_Barrameda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186560,'06049','Feria de Santa Lucía','fiesta','fiestas_wiki','La Feria de Santa Lucía se celebra el 13 de diciembre en los municipios de Zumárraga y Urrechu (Urretxu) de la provincia de Guipúzcoa en el País Vasco, norte de España. Sus inicios se remontan a 1717 en Urechu y actualmente es una de las ferias más importantes del País Vasco y del conjunto de España.​ Es un…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Santa_Lucía','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186561,'06049','Feria de Santo Tomás','fiesta','fiestas_wiki','La Feria de Santo Tomás de Mondragón (Guipúzcoa) España. Se celebraba allá por el siglo XIV, por lo que se deduce que es la principal y más antigua de Guipúzcoa, más aún que la de San Sebastián. Originalmente su duración era de 3 días, 21, 22 y 23, pero hoy sólo se celebra el día 22, según parece para no coincidir…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Santo_Tomás');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186562,'20069','Feria de Santo Tomás de San Sebastián','fiesta','fiestas_wiki','La Feria de Santo Tomás en San Sebastián (España) tiene lugar el 21 de diciembre y marca el inicio de la Navidad.​ Durante este día, San Sebastián se transforma en un mercado rural en el que la protagonista indiscutible es la chistorra.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Santo_Tomás_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186563,'03012','Feria de Todos los Santos de Cocentaina','fiesta','fiestas_wiki','La Feria de Todos los Santos de Cocentaina (conocida en valenciano como Fira de Tots Sants) es una concentración lúdica y comercial que se celebra en la población de Cocentaina (Comunidad Valenciana, España). Fue creada en el año 1346 por privilegio real concedido por Pedro IV de Aragón al conde de Cocentaina,…',38.74419,-0.44003,'https://es.wikipedia.org/wiki/Feria_de_Todos_los_Santos_de_Cocentaina','IT Internacional');
