INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186565,'06049','Feria de botijero','fiesta','fiestas_wiki','La Feria de botijero es una feria que se celebra en Zamora desde la época de los Reyes Católicos como una feria franca.​ Se celebra con carácter anual, a comienzos del mes de abril. En la localidad de Ciudad Rodrigo se celebra también la feria de botijero o botijeros, que recibe su nombre por la venta de éstos…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_botijero');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186566,'06049','Feria de capones, aves de corral y motivos navideños de Valls','fiesta','fiestas_wiki','La Feria de capones, aves de corral y motivos navideños de Valls es el mercado de Navidad de esta localidad de Cataluña. La ciudad de Valls celebra el fin de semana anterior a la Navidad, tanto el sábado como el domingo, durante la mañana y la tarde, esta feria de aves de corral. Esta clase de ferias tenían lugar…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_capones,_aves_de_corral_y_motivos_navideños_de_Valls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186567,'06049','Feria de la Inmaculada de Elda','fiesta','fiestas_wiki','La Feria de la Inmaculada es una feria celebrada en España, en la ciudad de Elda, provincia de Alicante. Es una feria de una notable antigüedad entre las ferias españolas, datando su origen en el año 1466.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_la_Inmaculada_de_Elda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186568,'06049','Feria de la Miel (Boal)','fiesta','fiestas_wiki','La Feria de la Miel es un certamen apícola celebrado en la localidad asturiana de Boal, generalmente el último fin de semana de octubre o primero de noviembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_la_Miel_(Boal)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186569,'06049','Feria de la mula','fiesta','fiestas_wiki','La feria de la mula es una feria celebrada 6 de octubre en Arenas (Málaga) España. La feria tiene como objetivo recuperar las labores agrícolas que tradicionalmente se realizaban con ayuda de mulas y difundir su conocimiento entre las nuevas generaciones, así como rendir homenaje a éste animal que tanto ayudó a los…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_la_mula');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186570,'29072','Feria de la vendimia (Mollina)','fiesta','fiestas_wiki','La Feria de la vendimia es una feria celebrada en Mollina (Málaga) España. Mollina es un pequeño pueblo situado en el norte de la provincia de Málaga, próximo a la ciudad de Antequera que presume de ser la única localidad malagueña que produce el 80 % del vino con Denominación de Origen "Málaga, Sierras de Málaga y…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_la_vendimia_(Mollina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186571,'29067','Feria de los Pueblos y Ciudades de Málaga','fiesta','fiestas_wiki','La Feria de los Pueblos y las Ciudades de Málaga, o simplemente Feria de los Pueblos, es una feria que se celebra anualmente en la ciudad andaluza de Málaga, España. Esta feria tiene como protagonistas a los municipios de la provincia de Málaga y está organizada por la Diputación Provincial. Las últimas ediciones…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_los_Pueblos_y_Ciudades_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186572,'21041','Feria de otoño y del caballo de Huelva','fiesta','fiestas_wiki','La Feria de Otoño y del Caballo de Huelva es una celebración popular que tiene lugar anualmente en la ciudad de Huelva, en la comunidad autónoma de Andalucía, alrededor del doce de octubre.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_otoño_y_del_caballo_de_Huelva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186573,'11020','Feria del Caballo','fiesta','fiestas_wiki','La Feria del Caballo es una feria que se celebra cada mes de mayo en Jerez de la Frontera (Andalucía, España).​ Declarada de Interés Turístico Internacional,​​ se trata, junto con la Semana Santa de una de las mayores y más importante fiesta de la ciudad.',36.69647222,-6.12697222,'https://es.wikipedia.org/wiki/Feria_del_Caballo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186574,'49275','Feria del ajo de Zamora','fiesta','fiestas_wiki','La Feria del ajo de Zamora (denominada igualmente Feria de San Pedro) es un festival anual que se celebrada desde el siglo XIX en la calle de las Tres Cruces de la capital zamorana. En este evento los agricultores presentan la producción de ajo (allium sativum) de la temporada.​ Se vende ajo a granel, o en forma de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_del_ajo_de_Zamora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186575,'90031','Feria del atún de Barbate','fiesta','fiestas_wiki','La feria del atún junto con la feria del Carmen son las festividades más importantes de Barbate (Cádiz) España.​',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_del_atún_de_Barbate');
