INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186578,'29054','Feria internacional de los pueblos','fiesta','fiestas_wiki','La feria internacional de los pueblos es una muestra de carácter étnico celebrada en Mijas y Fuengirola, en la provincia de Málaga, España. En la muestra se dan cita más de treinta países para mostrar su cultura. Se exponen trajes típicos, artesanía y gastronomía, así como músicas y bailes en escenarios de la…',36.54833333,-4.61963889,'https://es.wikipedia.org/wiki/Feria_internacional_de_los_pueblos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186579,'06049','Feria taurina','fiesta','fiestas_wiki','Se denomina feria taurina a los ciclos en los que se celebran festejos taurinos que habitualmente tienen lugar con motivo de las fiestas locales o patronales que se celebran en diversos países de Hispanoamérica y en España, Portugal u Occitania (al sur de Francia), entre otros.​ Los festejos que pueden comprender…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_taurina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186580,'07048','Feria taurina de San José','fiesta','fiestas_wiki','La Feria de San José o también conocida por Feria de Fallas, o Feria taurina de Fallas es una serie de festejos taurinos que se celebran en la Plaza de Toros de Valencia, durante la semana fallera y los días posteriores, en torno a la festividad de San José (19 de marzo). La Feria de San José es la primera de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_taurina_de_San_José','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186581,'16007','Feria y Fiestas de San Antonio (Chiclana de la Frontera)','fiesta','fiestas_wiki','La Feria de San Antonio se celebra en la ciudad de Chiclana de la Frontera (Cádiz) España. Se celebra a mediados del mes de junio. Se trata de una fiesta de gran tradición y popularidad.',36.4255436,-6.15467723,'https://es.wikipedia.org/wiki/Feria_y_Fiestas_de_San_Antonio_(Chiclana_de_la_Frontera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186582,'35018','Feria y Fiestas de San Bartolomé (Martos)','fiesta','fiestas_wiki','La Feria y Fiestas de San Bartolomé es la fiesta grande de Martos, en la provincia de Jaén (España). Generalmente se suele celebrar del 23 al 27 de agosto de cada año, aunque es variable dependiendo del día de la semana en que caiga la festividad de San Bartolomé. Actualmente se lleva a cabo en el recinto ferial de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_y_Fiestas_de_San_Bartolomé_(Martos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186583,'12100','Feria y Fiestas de San Mateo','fiesta','fiestas_wiki','Las Ferias y Fiestas San Mateo son unas celebraciones llevadas a cabo en la ciudad de Fregenal de la Sierra y están comprendidas normalmente entre el 21 y el 25 de septiembre, aunque siempre buscan el fin de semana más cercano a la festividad de San Mateo.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_y_Fiestas_de_San_Mateo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186584,'21041','Ferias de Andalucía','fiesta','fiestas_wiki','Las ferias andaluzas tienen especial significación por los elementos culturales específicos que aportan a la cultura e idiosincrasia andaluza; tanto los heredados de las ferias originales, de origen ganadero y religioso; como los añadidos por ciertas celebraciones más recientes con motivación diversa (como las…',NULL,NULL,'https://es.wikipedia.org/wiki/Ferias_de_Andalucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186585,'22039','Ferias de Ayerbe','fiesta','fiestas_wiki','Ricardo Monreal narraba en septiembre de 1933 que, el 30 de junio de 1510, el rey don Fernando El Católico concedió en Monzón, al señor de Ayerbe, don Hugo Jordán de Urriés (VIII Señor), el privilegio de celebrar dos ferias cada año, aprovechándose del impuesto de los derechos de feria. Ayerbe cuestionó los…',NULL,NULL,'https://es.wikipedia.org/wiki/Ferias_de_Ayerbe');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186586,'24202','Feriona','fiesta','fiestas_wiki','La feriona es actualmente el acontecimiento más importante del noroeste de la provincia de León. Se celebra en la localidad de Villablino el 12 de octubre, día de la Virgen del Pilar, y resulta ser una festividad con gran afluencia de público. Según estimaciones no oficiales en el año 2005 asistieron una media de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feriona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186587,'23059','Fernando Marmolejo Camargo','fiesta','fiestas_wiki','Fernando Marmolejo Camargo (Sevilla, 10 de diciembre de 1915 - Santiponce, 20 de septiembre de 2006) fue un orfebre español del siglo XX.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Fernando_Marmolejo_Camargo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186588,'11031','Fernando Ortiz (escultor)','fiesta','fiestas_wiki','Fernando Ortiz (Málaga; 1717-Málaga,1771) fue un escultor español y académico de la Real Academia de Bellas Artes de San Fernando (Madrid) desde 1756.',NULL,NULL,'https://es.wikipedia.org/wiki/Fernando_Ortiz_(escultor)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186589,'16007','Fernando Quiñones','fiesta','fiestas_wiki','Fernando Quiñones Chozas (Chiclana de la Frontera, Cádiz, 2 de marzo de 1930-Cádiz, 17 de noviembre de 1998) fue un escritor español que cultivó diversos géneros literarios, entre ellos la novela, el relato, la poesía y el teatro.',NULL,NULL,'https://es.wikipedia.org/wiki/Fernando_Quiñones','IT Internacional');
