INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186594,'34003','Festa dos Fachós','fiesta','fiestas_wiki','La Festa dos Fachós de Castro Caldelas se celebra el 19 de enero​ en la víspera del día de San Sebastián, comienza con la caída del sol y se prolonga durante la noche.',NULL,NULL,'https://es.wikipedia.org/wiki/Festa_dos_Fachós');
