INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186598,'06006','Festival Flamenco Mártir Santa Eulalia','fiesta','fiestas_wiki','El Festival Flamenco Mártir Santa Eulalia fue un festival de música flamenca celebrado en Mérida (España) desde 1989 hasta 2010. Durante sus veinte ediciones reunió a cantaores, guitarristas y bailarines provenientes principalmente de las provincias de Badajoz, Sevilla y Murcia, así como de otras zonas de Andalucía.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Flamenco_Mártir_Santa_Eulalia','Interés Turístico Regional');
