INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186602,'43148','Festival Internacional de Dixieland de Tarragona','fiesta','fiestas_wiki','El Festival Internacional de Dixieland de Tarragona, que se celebra la semana anterior a la de Pascua y acoge un centenar de actividades y conciertos, 25 formaciones y 175 músicos, nace en 1994 en Tarragona, una ciudad donde desde la restauración de los ayuntamientos democráticos, el jazz se había recuperado como…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Dixieland_de_Tarragona');
