INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186604,'39075','Festival Internacional de Santander','fiesta','fiestas_wiki','El Festival Internacional de Santander (FIS) es un festival de música que se celebra todos los años en la ciudad de Santander y la comunidad autónoma de Cantabria (España), desde mediados del siglo XX.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Santander');
