INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186606,'06010','Festival Internacional de la Sierra','fiesta','fiestas_wiki','El Festival Internacional de la Sierra FESTISIERRA se crea en el año 1980 con el sobrenombre de Festival de Bailes y Canciones Populares de Extremadura y desde entonces lleva celebrándose en la localidad de Fregenal de la Sierra cada año y siendo declarado en el 2018 Fiestas de Interés Turístico Nacional (España).…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_la_Sierra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186607,'19138','Festival Medieval de Hita','fiesta','fiestas_wiki','El Festival Medieval de Hita es una fiesta de interés turístico nacional​ que se celebra el primer sábado de julio en la localidad española de Hita, en la provincia de Guadalajara. Toda la escenificación gira en torno al Libro de buen amor del arcipreste de Hita y a la Edad Media.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Medieval_de_Hita','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186608,'02001','Festival Nacional de Bandas de Música de Albacete','fiesta','fiestas_wiki','El Festival Nacional de Bandas de Música de Albacete es un evento musical que se celebra anualmente en la ciudad española de Albacete.​​​ Nació en 1911 y en 2011 el festival alcanzó su 100.ª edición. Organizado por la Banda Sinfónica Municipal de Albacete, en él participan las mejores bandas de música de España,…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Nacional_de_Bandas_de_Música_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186609,'37243','Festival Nacional de la Jota','fiesta','fiestas_wiki','El Festival Nacional de la Jota es un certamen español de música y baile en torno a la jota castellana que se celebra cada año en la villa segoviana de Cuéllar, Castilla y León, y cuya primera edición fue realizada en 1968. Su primera edición tuvo lugar durante los encierros de Cuéllar de 1968, estuvo organizada…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Nacional_de_la_Jota','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186610,'26004','Festival de Exaltación del Botillo','fiesta','fiestas_wiki','El Festival de Exaltación del Botillo, declarado de Interés Turístico Nacional en 2014​​ y Fiesta de Interés Turístico Internacional en 2025,​ se celebra en el mes de febrero, fecha que puede variar en función de la Semana Santa, en la localidad de Bembibre del Bierzo, en la Provincia de León.​ En octubre de 2025…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Exaltación_del_Botillo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186611,'15061','Festival de Ortigueira','fiesta','fiestas_wiki','El Festival Internacional do Mundo Celta de Ortigueira, también conocido como Festival de Ortigueira, es un festival anual gratuito de música folk tradicional de las naciones celtas, fundado en 1978 por el personal de la Escola de gaitas de Ortigueira. Se suele celebrar el segundo fin de semana de cada julio en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Ortigueira','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186612,'10037','Festival de Teatro Clásico de Cáceres','fiesta','fiestas_wiki','El Festival de Teatro Clásico de Cáceres es un acontecimiento cultural que se celebra cada año en la localidad de Cáceres, en España, durante las noches del mes de junio.​ Este es uno de los principales festivales de teatro clásico que se celebran en Extremadura. Mientras que el Festival Internacional de Teatro…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Teatro_Clásico_de_Cáceres','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186613,'06014','Festival de la Canción de Extremadura','fiesta','fiestas_wiki','El Festival de la Canción de Extremadura es un certamen musical anualmente celebrado en el Cine-Teatro Balboa de la ciudad de Jerez de los Caballeros (Badajoz, España) que tiene lugar cada noviembre teniendo 16 finalistas. El Festival nació para promover la música en Extremadura.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_la_Canción_de_Extremadura','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186614,'04063','Festival de la Sidra','fiesta','fiestas_wiki','El Festival de la Sidra de Nava fue creado en 1969 por el entonces alcalde del concejo, José María Caso Mayor, hoy día, es una de las fiestas más importantes de Asturias y atrae a miles de personas cada año. En el festival, que dura varios días y se celebra en verano, se celebran conciertos, hay cata de sidra y se…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_la_Sidra','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186615,'45106','Festival de la luna mora','fiesta','fiestas_wiki','El festival de la luna mora es un festival celebrado en Guaro, en la provincia de Málaga, España. La programación del festival incluye conciertos de música andalusí, sefardí y andaluza, así como representaciones de teatro, exposiciones, talleres, degustaciones, danza del vientre y zoco morisco de artesanía, todo…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_la_luna_mora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186616,'14021','Festival de los Patios Cordobeses','fiesta','fiestas_wiki','El Festival de los Patios Cordobeses es un concurso de patios de Córdoba (España) celebrado desde 1921 y que se realiza, generalmente, durante la primera y segunda semana del mes de mayo. Los participantes decoran y abren sus patios gratuitamente para que puedan ser visitados dentro del horario establecido para tal…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_los_Patios_Cordobeses','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186617,'08302','Festival del Arroz con Leche','fiesta','fiestas_wiki','El Festival del Arroz con Leche es un evento gastronómico que se celebra en el concejo de Cabranes, en Asturias (España), coincidiendo con la fiesta local de San Francisco de Paula. Se comenzó a celebrar en el año 1980, En el transcurso del Festival, durante la mañana del domingo, la Cofradía del Arroz con Leche…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_del_Arroz_con_Leche','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186618,'30041','Festival del Cante de las Minas','fiesta','fiestas_wiki','El Festival Internacional del Cante de las Minas es un certamen español de flamenco que se celebra cada año en La Unión, Región de Murcia, y cuya primera edición fue realizada el 13 de octubre de 1961.​ El festival nació como un concurso de canto gracias al impulso que dieron figuras como el cantaor Juanito…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_del_Cante_de_las_Minas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186619,'39075','Festival del Mar (Santander)','fiesta','fiestas_wiki','El Festival del Mar es un conjunto de acontecimientos que se celebra cada cuatro años en Santander. La primera edición se desarrolló en el verano de 2005, año en el que la ciudad celebró el 250 aniversario de la concesión del título de Ciudad a Santander en 1755 por el rey Fernando VI. Se trata de una de la citas…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_del_Mar_(Santander)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186620,'90271','Festival del ajo asado','fiesta','fiestas_wiki','El Día del ajo asado es una festividad típica del municipio de Arnedo (La Rioja, España) en homenaje al ajo verde o tierno, hortaliza cultivada tradicionalmente allí y que tradicionalmente se asa en las brasas como parte del asado tradicional riojano.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_del_ajo_asado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186621,'16007','Festividad de Nuestra Señora del Carmen','fiesta','fiestas_wiki','La Festividad de Nuestra Señora del Carmen se celebra en la ciudad española de Chiclana de la Frontera y es una fiesta de gran tradición marinera, ya que la Virgen del Carmen es la Patrona de los marineros. Esta festividad está entre las siete fiestas principales de la ciudad de Chiclana de la Frontera y es la…',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_Nuestra_Señora_del_Carmen');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186622,'46250','Festividad de San Vicente Ferrer (Valencia)','fiesta','fiestas_wiki','Prolongando la Semana Santa, el segundo lunes de Pascua se levantan altares en calles y plazas de Valencia. Se conmemora la festividad de San Vicente Ferrer, patrón de la comunidad y canonizado en el siglo XV por el Papa Calixto III. Es costumbre visitar el Pouet de Sant Vicent en su casa natal convertida en…',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_San_Vicente_Ferrer_(Valencia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186623,'48078','Festividad de la Virgen de la Guía (Portugalete)','fiesta','fiestas_wiki','La fiesta religiosa en honor a la Virgen de la Guía se celebra en Portugalete el 1 de julio. Es una fiesta muy entrañable y tradicional en Portugalete. La fiesta se celebra en el Casco Viejo de la localidad y de manera principal en la calle Coscojales (la talla de la Virgen está en dicha calle, en una hornacina…',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_la_Virgen_de_la_Guía_(Portugalete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186624,'46250','Festividad de la Virgen de los Desamparados','fiesta','fiestas_wiki','La festividad de la Virgen de los Desamparados se celebra el segundo domingo de mayo en la ciudad de Valencia (España). Esta festividad cuenta con los momentos más esperados de un día especialmente emotivo, en el que miles y miles de valencianos se vuelcan para rendir homenaje a su patrona. Destacan los siguientes…',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_la_Virgen_de_los_Desamparados');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186625,'07049','Festividad de las Cuarenta Horas','fiesta','fiestas_wiki','Las Cuarenta Horas (denominada también Festividad de las Cuarenta Horas) es una celebración litúrgica extendida en especial desde el siglo XVII. Era muy popular en Zamora, donde, por regla general, tenía como escenario la iglesia de San Juan de Puerta Nueva siendo su componente musicológico muy importante.',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_las_Cuarenta_Horas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186626,'38027','Festividad de los Mayos','fiesta','fiestas_wiki','La Festividad de los Mayos, también conocida como Los Mayos o como Fiestas de Mayo, es una fiesta popular de orígenes ancestrales. Esta celebración primaveral generalmente se hacía coincidir con el primer domingo de dicho mes y tenía antiguamente connotaciones rituales totémicas a la divinidad primaveral o de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Festividad_de_los_Mayos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186627,'48078','Festividades de Portugalete','fiesta','fiestas_wiki','La noble villa de Portugalete provincia de Vizcaya, España. Celebra a lo largo del año diversas festividades.',NULL,NULL,'https://es.wikipedia.org/wiki/Festividades_de_Portugalete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186628,'23050','Fides Sancti Regni','fiesta','fiestas_wiki','El Fides Sancti Regni o la Fe del Santo Reino fue un acto extraordinario organizado en la ciudad andaluza de Jaén el 15 de junio de 2013. Fue convocado por la Diócesis de Jaén con motivo del Año de la Fe, proclamado por el papa Benedicto XVI. La Agrupación de Cofradías se encargó de su organización. El acto tuvo…',NULL,NULL,'https://es.wikipedia.org/wiki/Fides_Sancti_Regni','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186629,'46253','Fiesta Mayor de Canovelles','fiesta','fiestas_wiki','La Fiesta Mayor de Canovelles se celebra la última semana de julio, y reúne gente proveniente de todo el Vallés Oriental. Se divide de manera simbólica en dos bandos; los Cans y las Ovelles.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_Canovelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186630,'08096','Fiesta Mayor de Granollers','fiesta','fiestas_wiki','La Fiesta Mayor de Granollers es una de las fiestas más populares de Cataluña. Se divide en dos colores, los Blancs y los Blaus. Se celebra siempre en la última semana de agosto de cada año a partir del último jueves.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_Granollers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186631,'43123','Fiesta Mayor de Reus','fiesta','fiestas_wiki','La Fiesta Mayor de Reus, (Fiesta Mayor de San Pedro) está considerada la fiesta más grande de Reus (Tarragona) España. Declarada Fiesta Patrimonial de Interés Nacional por la Generalidad de Cataluña, tiene decenas de actos, los cuales giran alrededor de la «tronada».​ Tiene lugar el día 29 de junio. Aunque las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_Reus','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186632,'25207','Fiesta Mayor de Solsona','fiesta','fiestas_wiki','La Fiesta Mayor de Solsona o Festa Major de Solsona, es una fiesta tradicional y popular que se celebra a la ciudad española de Solsona (Lérida) Durante la festividad de la Virgen del Claustro (Mare de Déu del Claustre), patrona de Solsona. La celebración tiene lugar a Solsona durante los días 7, 8 y 9 de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_Solsona','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186633,'90963','Fiesta Mayor de la Bisbal del Ampurdán','fiesta','fiestas_wiki','La Fiesta Mayor de La Bisbal del Ampurdán (en catalán: la Bisbal d''Empordà) es una fiesta tradicional y popular que se celebra en esta localidad, capital de la comarca del Bajo Ampurdán, durante la festividad de la Asunción de María. Es una de las fiestas más conocidas del Bajo Ampurdán y de las comarcas…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_la_Bisbal_del_Ampurdán');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186634,'33024','Fiesta de Antroxu (Gijón)','fiesta','fiestas_wiki','El Antroxu de Gijón, Asturias (España) es una fiesta declarada de interés turístico regional. El Antroxu es el nombre asturiano del período que comprende los tres días anteriores al Miércoles de Ceniza, día en que empieza la cuaresma, y que es precedido por el Martes de Carnaval, periodo en el que se celebran las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Antroxu_(Gijón)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186635,'05008','Fiesta de L''Amuravela','fiesta','fiestas_wiki','La fiesta de L''Amuravela es una fiesta que se celebra en la localidad asturiana de Cudillero todos los años el 29 de junio, festividad de San Pedro, patrón del pueblo. L''Amuravela fue declarada Fiesta de Interés Turístico Nacional en 1976.​ Durante cuatro días se celebra las festividades de San Pedro, San Pablo y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_L''Amuravela','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186636,'33034','Fiesta de La Regalina','fiesta','fiestas_wiki','La fiesta de la Regalina, La Riégala o Santa María de Riégala es una fiesta que se celebra en el pueblo de Cadavedo situado en el concejo de Valdés (Asturias, España). Se trata de una fiesta al aire libre que se celebra en un campo situado a la vera de la Ermita de Santa María de Riégala (campo de La Garita). La…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_La_Regalina','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186637,'28056','Fiesta de La Vaquilla (Fresnedillas de la Oliva)','fiesta','fiestas_wiki','La Fiesta de «La Vaquilla» en honor a San Sebastián, de Fresnedillas de la Oliva (Madrid), es una celebración invernal que tiene lugar en este pueblo de la Sierra de Guadarrama. Se considera que se trata de una manifestación importante de las fratrías y otros ritos de paso ancestrales de raíz celta, y forma parte…',40.4881,-4.16972,'https://es.wikipedia.org/wiki/Fiesta_de_La_Vaquilla_(Fresnedillas_de_la_Oliva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186638,'35023','Fiesta de Las Marías','fiesta','fiestas_wiki','La fiesta de Las Marías es un acto de índole festivo y religioso, realizado con motivo de una multitudinaria promesa a la Virgen de Guía en Santa María de Guía de Gran Canaria. Se conmemora la Festividad del Dulce Nombre de María. Se realiza el tercer fin de semana del mes de septiembre.',28.13888889,-15.6325,'https://es.wikipedia.org/wiki/Fiesta_de_Las_Marías','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186639,'26064','Fiesta de Los Marchos','fiesta','fiestas_wiki','La fiesta de Los Marchos se celebra en Fuenmayor la noche del siete de diciembre, y consiste en quemar al toque de las campanas los montones de broza y todo lo que no sirve en las casas.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Los_Marchos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186640,'06006','Fiesta de Los Palomos (Badajoz)','fiesta','fiestas_wiki','La Fiesta de Los Palomos (también referenciado como L@s Palom@s), conocida en sus primeras ediciones como Caravana de Palomos, es una popular fiesta que se celebra en la ciudad de Badajoz (España), desde 2011, en favor de la igualdad y la diversidad del colectivo LGTBI, teniendo como centro neurálgico de la fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Los_Palomos_(Badajoz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186641,'33036','Fiesta de Nuestra Señora de Andrín','fiesta','fiestas_wiki','La Fiesta de Nuestra Señora de Andrín se celebra en Andrín el 15 de agosto, en el concejo asturiano de Llanes. La fiesta consiste en un pasacalles con bandas de gaitas por el pueblo, más tarde se celebra la misa solemne dedicada a la Virgen, la que se caracteriza por la asistencia de jóvenes vestidas con el traje…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Nuestra_Señora_de_Andrín','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186642,'05006','Fiesta de Nuestra Señora del Carmen (Cangas del Narcea)','fiesta','fiestas_wiki','La Fiesta de Nuestra Señora del Carmen o La Descarga es una fiesta que se celebra en la localidad asturiana de Cangas del Narcea. La fiesta se celebra el día del Carmen, el 16 de julio. La fiesta comienza el día 14 de julio, se realiza el pregón y una descarga, seguidos del desfile de las numerosas peñas que…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Nuestra_Señora_del_Carmen_(Cangas_del_Narcea)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186643,'06030','Fiesta de Nuestra Señora del Cébrano','fiesta','fiestas_wiki','La fiesta de Nuestra Señora del Cébrano se celebra el día 15 de agosto en el pueblo de Carrea en el concejo asturiano de Teverga. La Virgen es la patrona del concejo y tiene su imagen situada en la capilla de este pequeño pueblo. La fiesta consiste en una jira a la ermita con una romería popular.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Nuestra_Señora_del_Cébrano','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186644,'33034','Fiesta de Nuestra Señora del Rosario (Luarca)','fiesta','fiestas_wiki','Las fiestas de Nuestra Señora del Rosario, de tradición marinera, se celebran en la localidad asturiana de Luarca, en el concejo de Valdés. Están declaradas de Interés Turístico Nacional siendo además las fiestas de mayor tradición de la villa.​ Resulta prácticamente imposible de situar los inicios de estas…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Nuestra_Señora_del_Rosario_(Luarca)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186645,'21031','Fiesta de San Andrés (Encinasola)','fiesta','fiestas_wiki','La fiesta de San Andrés es una festividad popular que se celebra anualmente en el municipio onubense de Encinasola el fin de semana del 30 de noviembre en honor a San Andrés Apóstol, patrón de Encinasola.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Andrés_(Encinasola)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186646,'28125','Fiesta de San Antonio (Robledo de Chavela)','fiesta','fiestas_wiki','La Fiesta de Santa Antonia se celebra el día 13 de junio en Robledo de Chavela (Madrid, España). La víspera de ese día, se sube a la Ermita de Santa Antonia a buscar a la santa, al que se le baja en procesión hasta el pueblo, quedando ubicado en uno de los altares de la Iglesia de la Asunción de Nuestra Señora. El…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Antonio_(Robledo_de_Chavela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186647,'07046','Fiesta de San Antonio Abad (Canals)','fiesta','fiestas_wiki','San Antonio Abad es una fiesta que se celebra en enero en Canals, un municipio de la provincia de Valencia, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Antonio_Abad_(Canals)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186648,'46163','Fiesta de San Antonio de Masalfasar','fiesta','fiestas_wiki','La fiesta de San Antonio o popularmente fiesta de Sant Antoni de Masalfasar se celebra en el mes de enero en honor a san Antonio Abad.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Antonio_de_Masalfasar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186649,'05005','Fiesta de San Antonio de Padua (Cangas de Onís)','fiesta','fiestas_wiki','La fiesta de San Antonio de Padua se celebra el 13 de junio en la localidad de Cangas de Onís en Asturias. En la víspera del día trece se celebra la tradicional hoguera denominada Joguera. El día grande se caracteriza porque los vecinos de la ciudad se visten con el traje típico de cangas.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Antonio_de_Padua_(Cangas_de_Onís)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186650,'90158','Fiesta de San Blas (Ateca)','fiesta','fiestas_wiki','La Fiesta de San Blas se celebra en Ateca, municipio de la comunidad de Calatayud, situada en la provincia de Zaragoza de la comunidad autónoma de Aragón, España y de la que se tiene noticia escrita desde el año 1460.​',41.32909,-1.78634889,'https://es.wikipedia.org/wiki/Fiesta_de_San_Blas_(Ateca)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186651,'07049','Fiesta de San Juan','fiesta','fiestas_wiki','La Fiesta de San Juan, también llamada la Víspera de San Juan o la Noche de San Juan, es la celebración que tiene lugar anualmente en la víspera de la festividad cristiana del nacimiento de san Juan el Bautista el día 24 de junio.​​ Algunos vinculan la festividad, o algunas de sus celebraciones, a ritos de origen…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Juan');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186652,'07037','Fiesta de San Martín (Mercadal)','fiesta','fiestas_wiki','Las fiestas de San Martín de Mercadal, que se celebran el tercer fin de semana de julio, tienen un origen medieval y en ellas los caballos y sus jinetes salen vestidos de gala con sus crines trenzadas, llevando ornamentos diversos y banderas de colores: flocs (lazos) en los laterales y estell (espejos) en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Martín_(Mercadal)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186653,'08003','Fiesta de San Medín','fiesta','fiestas_wiki','La Fiesta de San Medín (en catalán: Festa de Sant Medir) se celebra el 3 de marzo en el distrito de Gracia, en Barcelona.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Medín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186654,'90439','Fiesta de San Roque (Alhaurín el Grande)','fiesta','fiestas_wiki','La Fiesta de San Roque es una celebración que tiene lugar en la localidad de Alhaurín el Grande (Málaga) España. La devoción a este santo tuvo gran importancia en el pasado. Los habitantes de esta localidad levantaron en su honor una capilla u oratorio situada en el Camino de Antequera, la cual se hallaba ya…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Alhaurín_el_Grande)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186655,'11033','Fiesta de San Roque (Betanzos)','fiesta','fiestas_wiki','La Fiesta de San Roque es una celebración que tiene lugar en Betanzos (La Coruña).',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Betanzos)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186656,'03049','Fiesta de San Roque (Callosa de Segura)','fiesta','fiestas_wiki','La Fiesta de San Roque es una celebración que tiene lugar en Callosa de Segura (Alicante), de donde es patrón. Cuenta la leyenda que se apareció en la madrugada del 16 de noviembre de 1409 en un corral o establo que había en las ruinas del antiguo castillo-fortaleza (el más grande y antiguo de la provincia de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Callosa_de_Segura)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186657,'11033','Fiesta de San Roque (Firgas)','fiesta','fiestas_wiki','La Fiesta de San Roque es una celebración que tiene lugar en Firgas, municipio situado al norte de la isla de Gran Canaria, del que es patrón. Durante todo el mes de agosto se celebran las fiestas por el santo, siendo los días grandes el 15 y el 16 (día de San Roque). Su veneración viene dada por una plaga de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Firgas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186658,'11033','Fiesta de San Roque (Llanes)','fiesta','fiestas_wiki','La Fiesta de San Roque se celebra el día 16 de agosto en la localidad asturiana de Llanes. La fiesta tiene su punto principal de encuentro en la plaza de Parres Sobrino y en la Capilla dedicada a San Roque. La celebración comienza a primeras horas de la mañana con una potente descarga de cohetes, tras la descarga…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Llanes)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186659,'11033','Fiesta de San Roque (Palazuelos)','fiesta','fiestas_wiki','La Fiesta de San Roque es una celebración que tiene lugar en la localidad de Palazuelos (Guadalajara). Consiste en la quema anual de un boto en honor al santo en la medianoche del día 15 de agosto, justo cuando se convierte en día 16. La quema no se realiza ante la imagen que se conserva en la iglesia parroquial, y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Palazuelos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186660,'11033','Fiesta de San Roque (Tolox)','fiesta','fiestas_wiki','La Fiesta de San Roque, conocida como la Cohetá, es una celebración que tiene lugar cada 16 de agosto en Tolox (Málaga, España), de donde es patrón. El acto principal de la festividad es una procesión con la talla de San Roque, acompañada por miles de cohetes, aproximadamente 50.000,​ que los vecinos hacen estallar…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_San_Roque_(Tolox)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186661,'10079','Fiesta de Santa Isabel (Garganta la Olla)','fiesta','fiestas_wiki','La fiesta de la Visitación de la Virgen a su prima Santa Isabel es el nombre que se da a un conjunto heterogéneo de celebraciones que tienen lugar durante los primeros cuatro días de julio en la villa española de Garganta la Olla, en la provincia de Cáceres. Es la fiesta principal de la villa y en ella tienen lugar…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Santa_Isabel_(Garganta_la_Olla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186662,'13009','Fiesta de Santiago el Verde','fiesta','fiestas_wiki','La Fiesta de Santiago el Verde (también conocida como día del Sotillo) fue una romería celebrada en Madrid el día uno de mayo, en el entorno de la ermita de San Felipe y Santiago (conocida popularmente como ermita de Santiago el Verde), junto al río Manzanares. Muy popular en los siglos xvi y xvii, fue glosada por…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_Santiago_el_Verde');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186663,'90090','Fiesta de la Aceituna','fiesta','fiestas_wiki','La Fiesta de la Aceituna es una celebración festiva típica del municipio de Martos (Jaén) España. Dicha fiesta simboliza el inicio oficial de la campaña de recolección de la aceituna y tiene el objetivo de rendir homenaje a los aceituneros y aceituneras que trabajan en la campaña.​ Cuenta con más de treinta años de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Aceituna');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186664,'12027','Fiesta de la Alcachofa','fiesta','fiestas_wiki','La Fiesta de la Alcachofa es una celebración gastronómica que se celebra durante el mes de enero en la localidad de Benicarló (Castellón),​​​​ dedicada a la promoción de la Alcachofa de Benicarló y su Denominación de Origen Protegida (DOP), la única de la provincia de Castellón.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Alcachofa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186665,'36011','Fiesta de la Almeja','fiesta','fiestas_wiki','La Fiesta de la Almeja de Carril (en gallego y oficialmente Festa da Ameixa de Carril) es una fiesta gastronómica de interés turístico de Galicia, que se celebra en el pueblo marinero de Carril, perteneciente al municipio de Villagarcía de Arosa (Pontevedra) España. Esta fiesta existe desde 1992.​ Más información…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Almeja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186666,'11020','Fiesta de la Bulería','fiesta','fiestas_wiki','La Fiesta de la Bulería es una cita flamenca, de cante y baile, que tiene lugar en Jerez de la Frontera (Andalucía, España) cada mes de septiembre, dentro de las conocidas Fiestas de la Vendimia.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Bulería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186667,'90778','Fiesta de la Candelaria','fiesta','fiestas_wiki','La Candelaria es una fiesta popular celebrada por los católicos, que celebra la Presentación de Jesús en el Templo, la Purificación de la Virgen después del parto y la Virgen de la Candelaria, advocación mariana aparecida en Tenerife (Islas Canarias) en el siglo XV. Tiene lugar el 2 de febrero, y en algunos lugares…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Candelaria','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186668,'31169','Fiesta de la Cereza','fiesta','fiestas_wiki','La Fiesta de la cereza o Día de la cereza es una fiesta de interés turístico celebrada en la localidad navarra de Milagro.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Cereza','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186669,'40057','Fiesta de la Coca','fiesta','fiestas_wiki','La fiesta de la Coca es una celebración de origen pagano que tiene lugar en el ayuntamiento pontevedrés de Redondela y, que tiene lugar el día del Corpus Christi. El origen de esta celebración reside en la leyenda mitológica de la coca, un ser de la mitología gallega que vive en las aguas del mar o de los ríos. Fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Coca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186670,'90863','Fiesta de la Cruz en Ademuz','fiesta','fiestas_wiki','La Fiesta de la Cruz o Cruz de Mayo es una celebración que a modo de romería se realiza en Ademuz, provincia de Valencia, (Comunidad Valenciana, España). La fiesta tiene lugar el día 3 de mayo, y consiste en la subida al cerro del Castillo de Ademuz, donde se hallan las ruinas de la Ermita de Santa Bárbara del…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Cruz_en_Ademuz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186671,'39095','Fiesta de la Gaita Cántabra','fiesta','fiestas_wiki','La Fiesta de la Gaita Cántabra es un certamen de tipo folclórico organizada anualmente desde 2003 por el Ayuntamiento de Val de San Vicente con la colaboración de la Consejería de Cultura del Gobierno de Cantabria. Su objetivo es extender el uso de dicho instrumento, y en él participan gaiteros de toda Cantabria,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Gaita_Cántabra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186672,'10087','Fiesta de la Hispanidad (Guadalupe)','fiesta','fiestas_wiki','La Fiesta de la Hispanidad se celebra cada 12 de octubre desde 1928. Desde entonces se conmemora en Guadalupe (Extremadura, España) la coronación canónica de la Virgen de Guadalupe como Reina de la Hispanidad (también denominada "Reina de las Españas"), por el Primado de España, el Cardenal Pedro Segura (legado…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Hispanidad_(Guadalupe)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186673,'47186','Fiesta de la ITA','fiesta','fiestas_wiki','La fiesta de la ITA es una fiesta universitaria celebrada con carácter anual en la ciudad de Palencia (Castilla y León, España). Su organización corre a cargo de los estudiantes de la Escuela Técnica Superior de Ingenierías Agrarias de Palencia, un centro del campus de Palencia adscrito a la Universidad de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_ITA');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186674,'28045','Fiesta de la Maya (Colmenar Viejo)','fiesta','fiestas_wiki','La Fiesta de la Maya de Colmenar Viejo (Madrid, España) se celebra cada 2 de mayo con exhibiciones de mayas en altares florales elaborados para la ocasión. Está declarada Fiesta de interés turístico de la Comunidad de Madrid y tiene una gran tradición en la historia de Colmenar Viejo, gira en torno a las niñas y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Maya_(Colmenar_Viejo)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186675,'28079','Fiesta de la Natividad de la Virgen del Puerto','fiesta','fiestas_wiki','Las fiestas de la Natividad de la Virgen del Puerto (denominada popularmente como Fiestas de la Melonera) son unas fiestas dedicadas a la Virgen del Puerto, se celebran en el distrito de Arganzuela (Madrid, España) a mediados de septiembre (generalmente del 11 al 14).​ Tiene una cercanía temporal con la celebración…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Natividad_de_la_Virgen_del_Puerto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186676,'10037','Fiesta de la Primavera de Cáceres','fiesta','fiestas_wiki','La Fiesta de la Primavera de Cáceres es el mayor festival universitario no solo de Extremadura, sino de toda la zona suroeste del país. Se celebra coincidiendo cada año con los primeros días de la estación primaveral por parte de todos los estudiantes de la Universidad de Extremadura y atrae a público de todas las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Primavera_de_Cáceres','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186677,'24120','Fiesta de la Trashumancia (Prioro)','fiesta','fiestas_wiki','La Fiesta de la Trashumancia es una celebración cultural, etnográfica y ganadera que se celebra anualmente en el municipio de Prioro (León, España). Su finalidad es homenajear la tradición trashumante, actividad que durante siglos constituyó uno de los pilares económicos y sociales de la montaña oriental leonesa.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Trashumancia_(Prioro)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186678,'28045','Fiesta de la Vaquilla (Colmenar Viejo)','fiesta','fiestas_wiki','La Fiesta de la Vaquilla es una celebración que se realiza en Colmenar Viejo, Comunidad de Madrid, el último sábado de enero de cada año (hasta el año 2016 se celebraba el 2 de febrero).',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Vaquilla_(Colmenar_Viejo)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186679,'11020','Fiesta de la Vendimia (Jerez de la Frontera)','fiesta','fiestas_wiki','Las Fiestas de la Vendimia de Jerez de la Frontera fue declarada Fiesta de interés Turístico Internacional en 1980. Antiguamente fue conocida como Feria de la Vendimia y recientemente también se la conoce como Fiestas de Otoño,​ siendo un conjunto de celebraciones que se llevan a cabo en Jerez de la Frontera…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Vendimia_(Jerez_de_la_Frontera)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186680,'46213','Fiesta de la Vendimia (Requena)','fiesta','fiestas_wiki','La Fiesta de la vendimia son las fiestas centrales y más populares de Requena (Valencia). Se celebran durante la última semana de agosto y primeros días de septiembre. Su duración es de 5 días, aunque en realidad, Requena se está de fiesta durante muchos más días, pues los anteriores a la Fiesta de la Vendimia se…',39.4885,-1.1023,'https://es.wikipedia.org/wiki/Fiesta_de_la_Vendimia_(Requena)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186681,'33036','Fiesta de la Virgen de la Guía','fiesta','fiestas_wiki','La Fiesta de la Virgen de la Guía se celebra en la localidad asturiana de Llanes. La fiesta se celebra el día 8 de septiembre. El 15 de octubre de 2016, la imagen de la Virgen de Guía, fue Coronada Canónicamente por el Arzobispo de Oviedo, Don Jesús Sanz Montes, en la Basílica de Santa María de la Asunción de Llanes.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Virgen_de_la_Guía','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186682,'06010','Fiesta de la Virgen de la Salud (Fregenal de la Sierra)','fiesta','fiestas_wiki','Desde el treinta de agosto y hasta el ocho de septiembre se celebra una de las fiestas más antiguas y genuinas de la ciudad de Fregenal de la Sierra (Badajoz), las Fiestas en Honor a la Virgen de la Salud. De ella destaca un grupo de danzantes conocidos popularmente como los Danzaores de la Virgen de la Salud que…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Virgen_de_la_Salud_(Fregenal_de_la_Sierra)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186683,'46105','Fiesta de la Virgen del Castillo (Cullera)','fiesta','fiestas_wiki','La Fiesta de la Virgen del Castillo o Fiestas Patronales de Cullera son las fiestas mayores de la ciudad y están dedicadas a la Mare de Déu del Castell, Virgen de la Encarnación y Patrona de Cullera, popularmente conocida como «La Moreneta».​ Una gran celebración que integra tanto tradición y devoción por la…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Virgen_del_Castillo_(Cullera)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186684,'39075','Fiesta de la Virgen del Mar (Santander)','fiesta','fiestas_wiki','La fiesta de la Virgen del Mar, en honor a la Virgen del Mar, es la efemérides en honor a la patrona de Santander (declarada como tal desde 1980), que se celebra el lunes siguiente al domingo de Pentecostés. Los orígenes de la devoción santanderina a la Virgen del Mar no se conocen con certeza. Los primeros datos…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Virgen_del_Mar_(Santander)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186685,'29025','Fiesta de la bicicleta','fiesta','fiestas_wiki','La fiesta de la bicicleta es un evento lúdico y deportivo que se desarrolla en el municipio malagueño de Benalmádena, España. Esta fiesta está organizada por el Ayuntamiento de Benalmádena y varias empresas del municipio y en ella el principal protagonista es la bicicleta. La actividad central coincide con un paseo…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_bicicleta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186686,'29057','Fiesta de la castaña','fiesta','fiestas_wiki','La fiesta de la castaña es una fiesta celebrada en varios puntos de la provincia de Málaga, España, sobre todo en los municipios de Pujerra, Alcaucín y Genalguacil.​ La fiesta celebra el fin de la recogida de la castaña, producto de gran importancia en la economía de la zona. Se desarrolla a principios de noviembre…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_castaña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186687,'29092','Fiesta de la chanfaina','fiesta','fiestas_wiki','La fiesta de la chanfaina es una jornada gastronómica que se celebra a finales de noviembre en el municipio de Totalán (Málaga) España.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_chanfaina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186688,'46250','Fiesta de la manzana esperiega','fiesta','fiestas_wiki','La Feria de la Manzana Esperiega es un festejo anual en homenaje a esta fruta mítica que tiene lugar en los pueblos del Rincón de Ademuz, provincia de Valencia (Comunidad Valenciana, España). La celebración la organiza la Asociación Turística del Rincón de Ademuz (ATRA),​ incluye actos lúdico-festivos y comerciales…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_manzana_esperiega');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186689,'13018','Fiesta de la matanza','fiesta','fiestas_wiki','La fiesta de la matanza es una jornada gastronómica celebrada anualmente en febrero en Ardales (Málaga) y en otros municipios de España, como Valdepeñas en la provincia de Jaen. Su principal protagonista es el embutido y la carne de porcino, pero en ella también hay lugar para el aceite, la repostería, las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_matanza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186690,'30041','Fiesta de la música en Villagarcía de Arosa','fiesta','fiestas_wiki','La Fiesta de la música en Villagarcía de Arosaes una fiesta popular e internacional. "Iniciada en Francia en 1982 como “Fiesta de la Música” e instituida como celebración europea en 1985 (Año Europeo de la Música), cada solsticio de verano, el 21 de junio, la Unión Europea celebra una jornada destinada a promover…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_música_en_Villagarcía_de_Arosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186691,'29067','Fiesta de la naranja','fiesta','fiestas_wiki','La fiesta de la naranja es una fiesta celebrada en Coín (Málaga) España.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_naranja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186692,'29099','Fiesta de la pasa','fiesta','fiestas_wiki','La fiesta de la pasa es una fiesta celebrada en los municipios españoles de El Borge (Málaga) y La Viñuela (Málaga). Durante la fiesta los habitantes de los pueblos reciben a los visitantes en la calle, ofreciendo guisos con carnes, vinos de la zona y pasas. Además, se hacen demostraciones de las tareas que se…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_pasa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186693,'40063','Fiesta de las Candelas (Cuéllar)','fiesta','fiestas_wiki','La Fiesta de las Candelas es una manifestación cultural de carácter religioso que se lleva a cabo anualmente en la villa castellano y leonesa de Cuéllar (Segovia) España y en Palencia (Palencia), España, el día de 2 de febrero en honor de la Virgen de las Candelas. La imagen mariana se custodia en la iglesia de San…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_Candelas_(Cuéllar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186694,'33060','Fiesta de las Cebollas Rellenas','fiesta','fiestas_wiki','La Fiesta de las Cebollas Rellenas es una fiesta gastronómica que se celebra a finales del mes de noviembre en El Entrego (San Martín del Rey Aurelio, Asturias) y tiene como protagonista a este plato típico de la gastronomía de Asturias.​​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_Cebollas_Rellenas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186695,'31078','Fiesta de las Cortes del 24 de septiembre','fiesta','fiestas_wiki','La Fiesta de las Cortes del 24 de septiembre es la fiesta oficial de la localidad gaditana de San Fernando. Se celebra todos los 24 de septiembre, conmemorando el aniversario del juramento por parte de los diputados de la Constitución española de 1812 (cuando la ciudad era capital de España por la invasión francesa…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_Cortes_del_24_de_septiembre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186696,'30030','Fiesta de las Cuadrillas','fiesta','fiestas_wiki','La Fiesta de las Cuadrillas es un festival de música tradicional que se celebra el último domingo de enero en la pedanía caravaqueña de Barranda en la Región de Murcia.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_Cuadrillas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186697,'46250','Fiesta de las reverencias (Mas del Olmo)','fiesta','fiestas_wiki','La Fiesta de las reverencias es una romería que se celebra por Pascua Granada (Pentecostés) en Mas del Olmo, aldea de Ademuz, provincia de Valencia, (Comunidad Valenciana, España). Se desarrolla en las proximidades de Mas del Olmo, entre los vecinos de Sesga que acuden en romería y los de Mas del Olmo, que salen a…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_reverencias_(Mas_del_Olmo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186698,'46070','Fiesta de les Alfàbegues (Bétera)','fiesta','fiestas_wiki','La Fiesta de les Alfàbegues, albahacas en castellano, es una festividad que se celebra en agosto en Bétera, España.​ Fue declarada fiesta de Interés Turístico Autonómico en 2007.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_les_Alfàbegues_(Bétera)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186699,'90565','Fiesta de los Arrieros','fiesta','fiestas_wiki','La fiesta de los Arrieros (en catalán: Festa dels Traginers) es una fiesta celebrada en el municipio de Balsareny, Barcelona, el último domingo antes del Carnaval. Su propósito es homenajear el antiguo gremio de los arrieros,​ claves en el desarrollo del comercio y la comunicación en las zonas rurales de esta…',41.86583333,1.87694444,'https://es.wikipedia.org/wiki/Fiesta_de_los_Arrieros','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186700,'33031','Fiesta de los Huevos Pintos','fiesta','fiestas_wiki','La fiesta los Güevos Pintos (en asturiano) se celebra en las localidades asturianas de Pola de Siero, concejo de Siero, y Sama, concejo de Langreo.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_los_Huevos_Pintos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186701,'09018','Fiesta de los Jefes','fiesta','fiestas_wiki','La Fiesta de los Jefes es una celebración del municipio burgalés de Santo Domingo de Silos (Castilla y León, España). El pueblo, por el que transcurre el Camino del Cid,​ es conocido por el Monasterio de Santo Domingo de Silos y se encuentra situado en el enclave natural de La Yecla. Recuperó esta fiesta con el…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_los_Jefes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186702,'08172','Fiesta de los Piratas de Premiá de Mar','fiesta','fiestas_wiki','La fiesta de los piratas es una festividad que se celebra en la localidad de Premiá de Mar, en la provincia de Barcelona.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_los_Piratas_de_Premiá_de_Mar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186703,'37300','Fiesta de los calvotes (castañas)','fiesta','fiestas_wiki','La fiesta de los calvotes es un acontecimiento popular que tiene su origen en el municipio salmantino de Lagunilla (Salamanca). Se festeja el fin de semana que coincide con la festividad de Todos los Santos.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_los_calvotes_(castañas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186704,'37300','Fiesta de los enharinados','fiesta','fiestas_wiki','La fiesta de "Los Enharinados (els Enfarinats)" o de la "Justicia Nueva" (Justícia Nova), se celebra cada 28 de diciembre (festividad de los Santos Inocentes) en Ibi (Alicante, Comunidad Valenciana). Esta celebración se enmarca dentro de lo que son las fiestas de invierno de esta villa. Se trata de una fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_los_enharinados');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186705,'36011','Fiesta del Agua de Villagarcía de Arosa','fiesta','fiestas_wiki','A Festa da Auga (La Fiesta del Agua en castellano) es una fiesta popular celebrada el día 16 de agosto en Villagarcía de Arosa, ciudad española de la provincia de Pontevedra, en la que después de trasladar a la figura de San Roque, el santo copatrono de la ciudad, de la iglesia parroquial de "Santa Eulalia de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Agua_de_Villagarcía_de_Arosa','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186706,'90288','Fiesta del Alba','fiesta','fiestas_wiki','La fiesta de la Virgen de Alba se celebra el día 15 de agosto en la sierra del Aramo, en el concejo de Quirós, en Asturias. La fiesta homenajea a la Virgen de Alba, celebrándose en su capilla. Durante todo el día se celebran diferentes actos culturales y religiosos como son la solemne misa en honor de la Virgen.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Alba','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186707,'05002','Fiesta del Antroxu (Avilés)','fiesta','fiestas_wiki','La fiesta del Antroxu de Avilés está declarada como de interés turístico regional. La fiesta es una sucesión de actos, llenándose la ciudad del ambiente festivo durante una semana. El Antroxu es dirigido por los Reyes del Goxu y la Faba, posición de honor a la que al año se debe renunciar en favor de un nuevo…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Antroxu_(Avilés)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186708,'33049','Fiesta del Asturcón','fiesta','fiestas_wiki','La Fiesta del Asturcón es una festividad celebrada en el concejo asturiano de Piloña que conmemora la raza equina autóctona de la región: el Asturcón, que estuvo en riesgo de desaparición. Hoy en día se puede encontrar en estado semisalvaje por la zona del Sueve. En 1994 fue declarada Fiesta de Interés Turístico…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Asturcón','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186709,'05002','Fiesta del Bollo','fiesta','fiestas_wiki','La Fiesta de El Bollo se celebra en la localidad asturiana de Avilés. La fiesta se celebra el domingo y lunes de Pascua siendo el colofón a las fiestas de Semana Santa en la villa.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Bollo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186710,'09003','Fiesta del Capitán','fiesta','fiestas_wiki','Fiesta del Capitán (Frías, Burgos) es una fiesta declarada de interés turístico de Castilla y León en la que se rememora la resistencia de los fredenses ante las actuaciones del conde de Haro (s. XV). También se le suman algunos elementos de la guerra de la Independencia y de las carlistas.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Capitán','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186711,'35020','Fiesta del Charco','fiesta','fiestas_wiki','La Fiesta del Charco o de la Embarbascá es una tradición festiva, con siglos de historia, que se lleva a cabo en el municipio de La Aldea de San Nicolás de la isla de Gran Canaria, cada 11 de septiembre para celebrar las fiestas patronales de San Nicolás de Tolentino.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Charco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186712,'36024','Fiesta del Cocido de Lalín','fiesta','fiestas_wiki','La Fiesta del Cocido de Lalín es una fiesta gastronómica gallega que se celebra cada año el domingo antes del Entroido.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Cocido_de_Lalín','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186713,'49017','Fiesta del Cordero','fiesta','fiestas_wiki','La Fiesta del Cordero en el Monte Lagüezos​ se celebra en la cima del monte de La Cobertoria, en la Sierra del Aramo.​ entre los concejos asturianos de Quirós y Lena, y cerca del de Riosa en Asturias, España. Se llega al Monte Lagüezos subiendo el Alto de la Cobertoria. Para ello se sigue la carretera que une la…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Cordero','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186714,'10079','Fiesta del Cristo (Garganta la Olla)','fiesta','fiestas_wiki','La fiesta del Cristo es una ceremonia folclórica que se celebra anualmente el 13 y 14 de setiembre en la villa española de Garganta la Olla, en la provincia de Cáceres. Es una fiesta eminentemente religiosa en honor al Santísimo Cristo del Humilladero, que forma la celebración local de la Exaltación de la Santa…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Cristo_(Garganta_la_Olla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186715,'07040','Fiesta del Estandarte','fiesta','fiestas_wiki','La Fiesta del Estandarte (en catalán: Festa de l''Estandard) o Fiesta de la Conquista es una celebración que tiene lugar en Palma de Mallorca cada 31 de diciembre con el motivo de conmemorar la caída y captura de la ciudad por parte de las tropas de Jaime I de Aragón durante la conquista de la isla de Mallorca que…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Estandarte','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186716,'13061','Fiesta del Mayo Manchego','fiesta','fiestas_wiki','La Fiesta del Mayo Manchego es una Fiesta de Interés Turístico Nacional que rememora la antigua festividad de los mayos en la región de La Mancha que se celebra actualmente en el municipio español de Pedro Muñoz. Las fiestas empiezan el 30 de abril hasta el 1 de mayo, pero se organiza una degustación de gastronomía…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Mayo_Manchego');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186717,'03040','Fiesta del Medievo de Villena','fiesta','fiestas_wiki','La Fiesta del Medievo de Villena es una celebración cultural y festiva de temática medieval que se celebra anualmente durante el segundo fin de semana de marzo en el Casco Histórico de Villena, declarado Bien de Interés Cultural, en la provincia de Alicante, España.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Medievo_de_Villena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186718,'29067','Fiesta del Monfí','fiesta','fiestas_wiki','La Fiesta del Monfí es una fiesta anual celebrada en octubre en el municipio español de Cútar (Málaga). Durante dos días, sábado y domingo, Cútar se engalana al estilo árabe, sus calles empinadas se llenan de puestos ambulantes que venden todo lo relacionado con la cultura andalusí, como piezas de artesanía en…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Monfí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186719,'36023','Fiesta del Monte','fiesta','fiestas_wiki','La Fiesta del Monte de Santa Tecla, conocida coloquialmente como Fiesta del Monte (Festa do Monte o Festa do Monte de Santa Tegra en gallego), es una fiesta popular que se celebra cada mes de agosto en la localidad española de La Guardia, en la provincia de Pontevedra.',41.8921208,-8.8708071,'https://es.wikipedia.org/wiki/Fiesta_del_Monte','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186720,'40063','Fiesta del Niño de la Bola','fiesta','fiestas_wiki','La Fiesta del Niño de la Bola es una manifestación cultural que se lleva a cabo en la villa segoviana de Cuéllar (Segovia) España. Los días de Año Nuevo y Reyes, en honor del Niño Jesús, aquí llamado Niño Jesús de la Bola, pues porta en su mano izquierda un globo terráqueo, representando por lo tanto una imagen…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Niño_de_la_Bola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186721,'90090','Fiesta del Olivo','fiesta','fiestas_wiki','La Fiesta del Olivo se celebra cada año desde 1957 en la localidad de Mora, en la provincia de Toledo, comunidad autónoma de Castilla-La Mancha, España. Es una fiesta declarada de Interés Turístico Nacional y conocida por conjugar tradiciones y momentos de ocio. Sus orígenes datan de la fiesta que antiguamente…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Olivo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186722,'39055','Fiesta del Orujo','fiesta','fiestas_wiki','La Fiesta del Orujo se realiza cada año el segundo fin de semana de noviembre en Potes, capital de la comarca de Liébana, Cantabria (España). Esta festividad, que comenzó en 1991, consiste en la degustación del orujo que se produce en esta comarca, acompañado de música tradicional, mercados tradicionales, y por…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Orujo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186723,'04078','Fiesta del Pan y del Queso','fiesta','fiestas_wiki','La Fiesta del Pan y del Queso es una romería que cada 6 de agosto se celebra en la villa de Quel, en La Rioja (España). Se desarrolla junto a la ermita del Santo Cristo de Quel, desde la que se lanza pan y queso a quienes esperan para recogerlo. Originaria de 1479, posee la peculiaridad de ser una de las fiestas…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Pan_y_del_Queso','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186724,'32083','Fiesta del Pastor','fiesta','fiestas_wiki','La Fiesta del Pastor se celebra todos los años, el día [30 de octubre] en la Vega de Enol, al lado de los lagos de Covadonga, Picos de Europa, en el Principado de Asturias. El primer año en el que se celebró la fiesta fue en [1939]. Fue declarada Fiesta de Interés Turístico en 1965, a día de hoy son declaradas de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Pastor','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186725,'16007','Fiesta del Pescado a la Teja','fiesta','fiestas_wiki','La Fiesta del Pescado a la Teja tuvo lugar en la Bodega Las Albinas en la calle Arroyuelo de Chiclana de la Frontera (Cádiz, España) entre 1952 y 1970 el primer domingo después del día de Reyes. La fiesta fue ideada por los propietarios de dicha bodega, Pepe Virués Vela y Manolo Moreno Verdugo. Durante esta fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Pescado_a_la_Teja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186726,'34182','Fiesta del Pimiento de Torquemada','fiesta','fiestas_wiki','La Fiesta del Pimiento de Torquemada es una feria de carácter gastronómico de gran repercusión dentro y fuera de la provincia de Palencia. El año 2011 fue su XVIII edición, y cada año su aforo va aumentando.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Pimiento_de_Torquemada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186727,'08067','Fiesta del Pino','fiesta','fiestas_wiki','La fiesta del Pino es una fiesta anual celebrada en Centellas, en la provincia de Barcelona, España, cada 30 de diciembre, declarada Fiesta Tradicional de Interés Nacional el 17 de noviembre de 1987 y reclassificada como Fiesta patrimonial de interés nacional el 25 de mayo de 2010.',41.79944444,2.22166667,'https://es.wikipedia.org/wiki/Fiesta_del_Pino','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186728,'43148','Fiesta del Renacimiento','fiesta','fiestas_wiki','La Fiesta del Renacimiento (en catalán Festa del Renaixement) de Tortosa (Tarragona, España). Se celebra desde 1996 y ostenta el reconocimiento de haber sido declarada Fiesta de Interés Turístico Nacional​ y Fiesta de Interés Turístico de Cataluña. Decenas de actores y espectáculos, centenares de ciudadanos y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Renacimiento','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186729,'20069','Fiesta del Robo de San Sebastián (Caniles)','fiesta','fiestas_wiki','La Fiesta del Robo de San Sebastián es una celebración popular de carácter religioso que se celebra en la localidad española de Caniles (Granada). Se trata de una fiesta patronal en honor a San Sebastián, copatrón de Caniles junto con San Antonio.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Robo_de_San_Sebastián_(Caniles)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186730,'38027','Fiesta del Sagrado Corazón de El Paso','fiesta','fiestas_wiki','La Fiesta del Sagrado Corazón de El Paso, es una celebración anual que tiene lugar en el municipio de El Paso, La Palma, en honor del Sagrado Corazón de Jesús.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Sagrado_Corazón_de_El_Paso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186731,'47186','Fiesta del Vítor','fiesta','fiestas_wiki','El Vítor, también conocido como Procesión Cívica "El Vítor", es una fiesta declarada de Interés Turístico Nacional​ que se celebra cada 27 de septiembre en Mayorga, un municipio de la provincia de Valladolid, en Castilla y León, España.​​​ Se trata de una procesión cívica, que data del año 1650 cuando los vecinos…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_Vítor','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186732,'36011','Fiesta del albariño','fiesta','fiestas_wiki','La fiesta del albariño es la fiesta vinícola más antigua de Galicia, la segunda de España y está dentro del conjunto de Fiestas de Interés Turístico Nacional.​ Se celebra en la villa de Cambados (Pontevedra) España. Y desde 2018 declarada de interés turístico internacional. El origen de esta fiesta fue un desafío…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_albariño','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186733,'46250','Fiesta del arroz','fiesta','fiestas_wiki','La fiesta del Arroz se celebra en el mes de septiembre en Sueca, municipio perteneciente a la provincia de Valencia (España). Sueca es conocida como la ciudad arrocera de España. Durante los días que se celebra la fiesta del Arroz, se rinde culto a este cultivo, que es la base de su economía local.​ Desde su…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_arroz','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186734,'46235','Fiesta del arroz (Sueca)','fiesta','fiestas_wiki','La Fiesta del Arroz de Sueca es una fiesta que se celebra en el mes de septiembre en Sueca, un pueblo de Valencia, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_arroz_(Sueca)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186735,'22074','Fiesta del campo','fiesta','fiestas_wiki','La fiesta del campo es una jornada gastronómica celebrada en Benamargosa (Málaga) España. Su principal protagonista son los productos del ecológicos locales y la dieta mediterránea. Está declarada Fiesta de Singularidad Turístico Provincial.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_campo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186736,'29059','Fiesta del chuchete','fiesta','fiestas_wiki','La fiesta del chuchete es una fiesta tradicional de la localidad española de Humilladero (Málaga). Se celebra el domingo de carnaval sobre el mediodía. Es una tradición recuperada de antaño y consiste en lanzarse botijos los unos a los otros puestos en corro hasta que el botijo se rompa.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_chuchete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186737,'90538','Fiesta del jamón de La Cañiza','fiesta','fiestas_wiki','La fiesta del jamón de La Cañiza se celebra anualmente en La Cañiza, una población de la comarca de Paradanta, en la provincia de Pontevedra. La primera edición tuvo lugar en 1966, y desde entonces se celebra anualmente durante agosto.​​ El clima de A Cañiza, frío y seco, es idóneo para el curado de buena calidad…',42.21277778,-8.27444444,'https://es.wikipedia.org/wiki/Fiesta_del_jamón_de_La_Cañiza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186738,'17204','Fiesta del vino del Ulla','fiesta','fiestas_wiki','La fiesta del vino del Ulla (Festa do viño da Ulla en gallego) es una fiesta gastronómica que se celebra todos los años el segundo domingo de abril en la localidad de San Miguel de Sarandón, en el ayuntamiento de Vedra, provincia de La Coruña (España). La fiesta lleva organizándose desde el año 1980; solo…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_vino_del_Ulla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186739,'21055','Fiestas Colombinas','fiesta','fiestas_wiki','Las Fiestas Colombinas son las celebraciones que anualmente se realizan en la ciudad de Huelva para conmemorar los diferentes hechos históricos relacionados con la llamada "Gesta Descubridora". Suelen durar una semana desde los últimos de julio a los primeros agosto, siendo el día grande el 3 de agosto,​ fecha en…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_Colombinas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186740,'43161','Fiestas Decenales de la Virgen de la Candela de Valls','fiesta','fiestas_wiki','Las Fiestas Decenales de la Virgen de la Candela de Valls, en la comarca del Alto Campo, dentro de la provincia de Tarragona, Españase celebran cada 10 años. Tienen su origen en la devoción que la ciudad tiene hacia la Virgen de la Candela. Constan documentalmente las súplicas dirigidas a la Virgen por parte de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_Decenales_de_la_Virgen_de_la_Candela_de_Valls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186741,'50297','Fiestas Goyescas','fiesta','fiestas_wiki','Las Fiestas Goyescas son unas fiestas celebradas en Zaragoza,​ como homenaje al artista aragonés Francisco de Goya, que tuvieron su primera edición en 2022. Se celebran durante el último fin de semana del mes de abril.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_Goyescas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186742,'38037','Fiestas Lustrales de la Bajada de la Virgen de las Nieves','fiesta','fiestas_wiki','Las Fiestas Lustrales de la Bajada de la Virgen de las Nieves es una festividad popular tradicional que tiene lugar en la localidad canaria de Santa Cruz de La Palma, cada lustro entre los meses de julio y agosto. La última edición de las fiestas tuvo lugar en 2025, siendo la próxima en 2030. En estas fiestas se…',28.68416944,-17.765,'https://es.wikipedia.org/wiki/Fiestas_Lustrales_de_la_Bajada_de_la_Virgen_de_las_Nieves','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186743,'38005','Fiestas Lustrales en honor al Cristo de la Misericordia','fiesta','fiestas_wiki','Las Fiestas Lustrales en honor al Santísimo Cristo de la Misericordia es una festividad popular tradicional que tiene lugar cada lustro, en la Villa de Garachico al norte de la isla de Tenerife (Islas Canarias, España), entre los meses de julio y agosto, siendo la última celebración en el año 2025 y siendo la…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_Lustrales_en_honor_al_Cristo_de_la_Misericordia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186744,'20076','Fiestas Vascas de Ordizia','fiesta','fiestas_wiki','La Feria Extraordinaria de Fiestas Vascas de Ordizia, comúnmente conocida como Euskal Jaiak o Fiestas Vascas de Ordizia, son unas fiestas populares que se celebran en el mes de septiembre en la localidad guipuzcoana de Villafranca de Ordizia. Estas fiestas tienen su origen en la Feria Extraordinaria, un mercado de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_Vascas_de_Ordizia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186745,'02001','Fiestas de Albacete','fiesta','fiestas_wiki','Las fiestas y tradiciones de Albacete de mayor interés turístico, sociológico y cultural tienen una raíz preferentemente religiosa o taurina. Entre todas ellas, sobresale por encima de las demás la famosa Feria de Albacete, declarada de Interés Turístico Internacional, que tiene lugar cada año del 7 al 17 de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186746,'46022','Fiestas de Alfafar','fiesta','fiestas_wiki','Alfafar tiene una larga tradición cultural que se ha manifestado a lo largo de la historia a través de las Fiestas Patronales y Populares del municipio. En los actos programados en esas fechas hay una especial participación de entidades y asociaciones que hace de nuestra población una singularidad propia. Además de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Alfafar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186747,'16002','Fiestas de Algeciras','fiesta','fiestas_wiki','En el conjunto de las fiestas de Algeciras se encuentran muchas que por su particular importancia o modo de celebrarse constituyen una seña de identidad de esta localidad andaluza. Son especialmente importantes por su limitada área de distribución las fiestas del arrastre de latas, las adas o los tosantos que…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Algeciras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186748,'08003','Fiestas de Andalucía','fiesta','fiestas_wiki','Las Fiestas de Andalucía son tanto religiosas como profanas. El arte y las costumbres populares tienen un escenario de encuentro en las ferias andaluzas, originariamente ferias de ganado. Entre las más famosas están la feria de Abril de Sevilla -extendida a Madrid y Barcelona por el gran número de inmigrantes…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Andalucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186749,'50227','Fiestas de Astures y Romanos','fiesta','fiestas_wiki','Las Fiestas de Astures y Romanos son una fiesta que se celebra en la ciudad española de Astorga (León) a finales de julio. En ella se rememora el pasado más antiguo de la ciudad:​ el desarrollo de los capítulos bélicos de las guerras asturcántabras y la fundación de Asturica Augusta.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Astures_y_Romanos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186750,'24013','Fiestas de Beas de Segura','fiesta','fiestas_wiki','Fiestas de Beas de Segura, España, son variadas, de distinto género y durante todo el año.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Beas_de_Segura');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186751,'02001','Fiestas de El Salvador','fiesta','fiestas_wiki','Las Fiestas de El Salvador son las fiestas mayores de La Roda (Albacete, España), que se celebran anualmente del 29 de julio al 6 de agosto en honor a su patrón El Salvador.​​​​ El tradicional desfile inaugural da el pistoletazo de salida a las fiestas, que incluyen numerosas actividades: toros, vaquillas,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_El_Salvador');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186752,'28065','Fiestas de Getafe','fiesta','fiestas_wiki','En el municipio de Getafe (Madrid, España) se celebran las siguientes fiestas:',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Getafe');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186753,'08003','Fiestas de Gracia (Barcelona)','fiesta','fiestas_wiki','Las Fiestas de Gracia o Fiesta Mayor de Gracia (en catalán: Festa Major de Gràcia) es una fiesta popular celebrada en el distrito de Gracia de Barcelona desde el 15 de agosto y por un plazo de entre siete y diez días. Su elemento más distintivo es la ornamentación de calles, pero también se celebran conciertos,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Gracia_(Barcelona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186754,'30011','Fiestas de La Blanca','fiesta','fiestas_wiki','Las Fiestas en honor a la Virgen Blanca, se celebran en Vitoria (Álava), España, desde 1884. Tienen su comienzo la víspera, el día 4 de agosto en la Plaza de la Virgen Blanca, situada en el corazón de la ciudad, donde miles de vitorianos y visitantes se reúnen para iniciar las fiestas con la bajada de Celedón.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_La_Blanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186755,'36011','Fiestas de La Peregrina','fiesta','fiestas_wiki','Las Fiestas de La Peregrina son las fiestas patronales y principales fiestas de la ciudad española de Pontevedra, que se celebran anualmente durante nueve días a partir del segundo sábado de agosto en honor a la Virgen Peregrina, patrona de la provincia de Pontevedra.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_La_Peregrina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186756,'03088','Fiestas de La Virgen de Orito','fiesta','fiestas_wiki','Las fiestas en honor a la Virgen de Orito se celebran en Monforte del Cid, en la pedanía de Orito, los días anteriores al 8 de septiembre, día de la festividad de Nuestra Señora de Orito. Los actos tradicionales son: Pasacalles por la mañana y almuerzo general en la Plaza Mayor. Después se celebra la misa y, a…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_La_Virgen_de_Orito');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186757,'42164','Fiestas de Las Candelas y San Blas (San Leonardo de Yagüe)','fiesta','fiestas_wiki','Las Fiestas de Las Candelas y San Blas, popularmente conocidas como Las Candelas y San Blas son una celebración en honor a la Virgen de la Candelaria, San Blas, Los Capones y Virgen de Santa Águeda que tiene lugar anualmente en la villa española de San Leonardo de Yagüe en la comunidad autónoma de Castilla y León,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Las_Candelas_y_San_Blas_(San_Leonardo_de_Yagüe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186758,'46184','Fiestas de Moros y Cristianos de Onteniente','fiesta','fiestas_wiki','Las Fiestas de Moros y Cristianos de Ontinyent en valenciano Moros i Cristians d’Ontinyent, son el conjunto de actos que se realizan en la localidad de Onteniente, Valencia, que se celebran anualmente durante el mes de agosto. Los festejos tienen su inicio el tercer domingo de agosto, viviendo todo su esplendor…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Moros_y_Cristianos_de_Onteniente','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186759,'28092','Fiestas de Móstoles','fiesta','fiestas_wiki','Las principales fiestas de Móstoles, municipio de la Comunidad de Madrid, son el día de la Virgen de los Santos, las conmemorativas del levantamiento del 2 de mayo y la Fiesta del Agua.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Móstoles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186760,'46029','Fiestas de Nuestra Señora de la Salud','fiesta','fiestas_wiki','Las fiestas del aniversario del Hallazgo de Nuestra Señora de la Salud, o como son más conocidas, las Fiestas de Nuestra Señora de la Salud se celebran entre el 29 de agosto y el 8 de septiembre en Algemesí (Comunidad Valenciana) , destacando la trilogía de días 6, 7 y 8 de septiembre. Estas fiestas se celebran…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Nuestra_Señora_de_la_Salud');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186761,'28079','Fiestas de Nuestra Señora del Carmen (Madrid)','fiesta','fiestas_wiki','Fiestas de Nuestra Señora del Carmen, son unas fiestas patronales celebradas en honor a la Virgen del Carmen, en cuatro distritos de Madrid: el Puente de Vallecas, en Chamberí, La Latina y Villaverde Alto.​ Se conocen popularmente como fiestas del Carmen, o, en Puente de Vallecas, fiestas de la Karmela (o…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Nuestra_Señora_del_Carmen_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186762,'30030','Fiestas de Primavera de Murcia','fiesta','fiestas_wiki','Las Fiestas de Primavera se celebran en Murcia la semana posterior a la Semana Santa. Estas son las celebraciones más importantes de la capital murciana, junto a la Feria de Murcia. Aún siendo oficialmente un evento de la ciudad de Murcia, estas fiestas primaverales transcienden lo local, adquiriendo también un…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Primavera_de_Murcia','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186763,'50297','Fiestas de Primavera de Zaragoza','fiesta','fiestas_wiki','Zaragoza, como la mayoría de municipios de Aragón, tenía sus fiestas Mayores (las fiestas del Pilar) y sus fiestas menores (las de Primavera). No se sabe con certeza cuando comenzaron a realizarse, pero sí se tienen documentos gráficos desde 1900 en los que se pueden leer referencias a las festividades de abril.…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Primavera_de_Zaragoza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186764,'02001','Fiestas de San Antón de Albacete','fiesta','fiestas_wiki','Las Fiestas de San Antón de Albacete, también conocidas como Día de San Antón o simplemente San Antón, son una festividad popular que se celebra anualmente el 17 de enero en honor a San Antonio Abad en la ciudad española de Albacete.​​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Antón_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186765,'23050','Fiestas de San Antón de Jaén','fiesta','fiestas_wiki','Las Fiestas de San Antón es una festividad que tiene lugar en Jaén (Andalucía, España), la noche del 16 al 17 de enero, en la víspera de la festividad de San Antón. Es Fiesta de Interés Turístico Nacional desde 2019.​​ Desde 1984, se lleva a cabo la Carrera Urbana Internacional Noche de San Antón que acompaña las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Antón_de_Jaén','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186766,'26089','Fiestas de San Bernabé (Logroño)','fiesta','fiestas_wiki','Las Fiestas de San Bernabé son las fiestas patronales de la ciudad española de Logroño. Se celebran en torno al día 11 de junio, festividad de San Bernabé, patrón de la ciudad, en conmemoración de la victoria durante el cerco de Logroño de 1521. Forman, junto con el Día de La Rioja, que se celebra el día 9, un…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Bernabé_(Logroño)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186767,'50165','Fiestas de San Blas y Santa Águeda (Mequinenza)','fiesta','fiestas_wiki','Las Fiestas de San Blas y Santa Águeda es una celebración del municipio de Mequinenza en la provincia de Zaragoza, comunidad autónoma de Aragón que consiste en una festividad que forma parte de la tradición histórica de la localidad por su antigüedad y continuidad a través del tiempo y por la originalidad y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Blas_y_Santa_Águeda_(Mequinenza)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186768,'28079','Fiestas de San Cayetano','fiesta','fiestas_wiki','Las Fiestas de San Cayetano (denominada también popularmente como Verbena de San Cayetano) es una festividad celebrada en las calles cercanas a la iglesia parroquial de San Cayetano (Madrid) en honor de San Cayetano de Thiene.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Cayetano');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186769,'46250','Fiestas de San Gil','fiesta','fiestas_wiki','Las Fiestas de San Gil es una fiesta de carácter religioso y festivo que se celebra el primer fin de semana de septiembre en Enguera, un municipio de la provincia de Valencia (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Gil');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186770,'03904','Fiestas de San Isidro Labrador','fiesta','fiestas_wiki','Las fiestas de San Isidro son unas fiestas patronales en honor a Isidro Labrador,​ patrón de Madrid y celebradas en torno al 15 de mayo. Este festejo incluye romerías, verbenas, atracciones y diversos espectáculos tradicionales definidores del «casticismo madrileño». En su esencia se desarrollan en el barrio de San…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Isidro_Labrador');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186771,'34023','Fiestas de San Juan Bautista (Baños de Cerrato)','fiesta','fiestas_wiki','Las Fiestas de San Juan Bautista de Baños de Cerrato, perteneciente al municipio Venta de Baños, en la provincia de Palencia, en la comunidad autónoma de Castilla y León, se celebran el 24 de junio, en la que se ejecuta el rito mozárabe en la iglesia de San Juan de Baños desde 1974. La idea de realizar este rito…',41.92083333,-4.47236111,'https://es.wikipedia.org/wiki/Fiestas_de_San_Juan_Bautista_(Baños_de_Cerrato)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186772,'07050','Fiestas de San Juan Bautista (La Encina)','fiesta','fiestas_wiki','Las Fiestas de San Juan Bautista son las fiestas patronales de La Encina, Villena (Alicante). Se celebran cada año durante el jueves, viernes, sábado y domingo siguientes al 24 de junio.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Juan_Bautista_(La_Encina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186773,'02001','Fiestas de San Juan de Albacete','fiesta','fiestas_wiki','Las Fiestas de San Juan de Albacete son las fiestas que se celebran anualmente en la ciudad española de Albacete la semana del 24 de junio en honor a su patrón San Juan Bautista. Con una duración de una semana, constan de una amplia variedad de actividades culturales hasta llegar a su punto culminante la noche de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Juan_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186774,'09337','Fiestas de San Juan del Monte','fiesta','fiestas_wiki','Las fiestas de San Juan del Monte se celebran en la ciudad de Miranda de Ebro, provincia de Burgos (España), el lunes de Pentecostés y el fin de semana que le precede. Su origen se remonta a la Edad Media y es la romería más antigua e importante del norte español. En 2015 fueron declaradas Fiestas de Interés…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Juan_del_Monte','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186775,'07049','Fiestas de San Juan o de la Madre de Dios','fiesta','fiestas_wiki','Las Fiestas de San Juan o de la Madre de Dios se celebran en Soria (España). Comienzan el jueves posterior a la festividad de Sanjuanes (último miércoles de junio), o en esta misma fecha si es coincidente con jueves. Desde el año 1956 se añade a la programación el denominado miércoles "El Pregón", por delante de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Juan_o_de_la_Madre_de_Dios');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186776,'22125','Fiestas de San Lorenzo (Huesca)','fiesta','fiestas_wiki','Las Fiestas de San Lorenzo son las fiestas patronales de Huesca celebradas en honor a San Lorenzo que tienen lugar del 9 al 15 de agosto.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Lorenzo_(Huesca)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186777,'28079','Fiestas de San Lorenzo (Madrid)','fiesta','fiestas_wiki','Las Fiestas de San Lorenzo son la celebración más popular y antigua del barrio de Lavapiés (Madrid) y se celebran cada 10 de agosto en honor a San Lorenzo,​ dentro de una ''trilogía'' que completan las Fiestas de la Paloma y las Fiestas de San Cayetano.​ Desde finales del siglo XX se instala una verbena en la plaza…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Lorenzo_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186778,'12100','Fiestas de San Mateo (Logroño)','fiesta','fiestas_wiki','Las Fiestas de San Mateo de la ciudad española de Logroño tienen lugar en la semana natural que engloba el día 21 de septiembre, día que el santoral dedica al apóstol. A pesar de la creencia popular, no son las fiestas patronales de la ciudad, las cuales se celebran en 11 de junio, festividad de San Bernabé, patrón…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Mateo_(Logroño)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186779,'12100','Fiestas de San Mateo (Oviedo)','fiesta','fiestas_wiki','Las Fiestas de San Mateo de la ciudad asturiana de Oviedo (España) tienen lugar en la semana que comienza el 14 de septiembre, día de la exaltación de la Santa Cruz - en sus orígenes la fiesta de la ciudad - y que culmina el día 21 de septiembre, día que el santoral católico dedica al apóstol.​ A pesar de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Mateo_(Oviedo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186780,'05219','Fiestas de San Pascual','fiesta','fiestas_wiki','Las Fiestas de San Pascual Bailón también conocidas como «El Zarrón» son unas fiestas populares celebradas en la Villa de Almazán (Soria) los días 17 y 18 de mayo en honor a San Pascual Bailón, el patrón de los pastores. Es una tradición folclórica ligada a ritos agrícolas y ganaderos. Estas fiestas fueron…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Pascual');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186781,'12040','Fiestas de San Pedro (Grao de Castellón)','fiesta','fiestas_wiki','Las fiestas de San Pedro (en valenciano festes de Sant Pere) son las fiestas patronales de la población del Grao en el municipio de Castellón de la Plana (España). Están dedicadas a San Pedro, patrón de los pescadores, principal oficio de los habitantes del lugar durante décadas. Tienen una duración de 10 días…',39.97486,0.01161,'https://es.wikipedia.org/wiki/Fiestas_de_San_Pedro_(Grao_de_Castellón)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186782,'11033','Fiestas de San Roque (Calatayud)','fiesta','fiestas_wiki','Las fiestas en honor a San Roque de Calatayud (Zaragoza) son los principales festejos de esta ciudad aragonesa y están declaradas Fiestas de Interés Turístico Regional, contando con una gran cantidad de visitantes, que en su mayoría son de la comarca de Calatayud, Teruel y Zaragoza. Se desarrollan a mediados de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Roque_(Calatayud)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186783,'48078','Fiestas de San Roque (Portugalete)','fiesta','fiestas_wiki','Las Fiestas de San Roque se llevan celebrando en el municipio del País Vasco de Portugalete (Vizcaya) España, desde hace siglos.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Roque_(Portugalete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186784,'03088','Fiestas de San Roque de Monforte del Cid','fiesta','fiestas_wiki','En Monforte del Cid son conocidas como las fiestas del verano, se celebran durante una semana teniendo como día principal el 16 de agosto, festividad de San Roque con gran devoción popular y religiosa.​​​​​ Las Fiestas de San Roque, las segundas en importancia del pueblo, tienen también gran arraigo y tradición…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Roque_de_Monforte_del_Cid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186785,'42173','Fiestas de San Saturio (Soria)','fiesta','fiestas_wiki','Las fiestas de San Saturio son las fiestas patronales de Soria (España), en honor a San Saturio, cuya efeméride es el día 2 de octubre. Se celebran del 1 al 5 de octubre aunque las actividades que se extienden a los fines de semana anteriores y posteriores a estos días. El programa de fiestas está cargado de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Saturio_(Soria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186786,'28134','Fiestas de San Sebastián de los Reyes','fiesta','fiestas_wiki','Comienza el ciclo con las fiestas en honor del santo patrón de la ciudad: San Sebastián Mártir. Tienen lugar los días 19 y 20 de enero, y están dedicadas a la celebración religiosa, (misa y procesión con la imagen del santo por las principales calles del casco antiguo), y con sus orquestas que amenizan las noches…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_San_Sebastián_de_los_Reyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186787,'12126','Fiestas de San Vicente Ferrer de Vall de Uxó','fiesta','fiestas_wiki','Las Fiestas Patronales en honor de san Vicent Ferrer son las Fiestas Mayores de primavera de Vall de Uxó, en la Plana Baja. Durante dos semanas, la ciudad cambia su fisonomía con un completísimo programa de actos, destacando entre ellos los famosos Bous al carrer. La gran tradición y su gran calidad le valieron el…',39.8236,-0.2317,'https://es.wikipedia.org/wiki/Fiestas_de_San_Vicente_Ferrer_de_Vall_de_Uxó','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186788,'10165','Fiestas de Santa Ana','fiesta','fiestas_wiki','Las Fiestas de Santa Ana son una celebración en honor a Santa Ana, patrona de la ciudad de Tudela, en la Comunidad Foral de Navarra. La fiesta empieza con el cohete anunciador que se lanza desde la Plaza de los Fueros cada 24 de julio a las 12 horas, finalizando el 30 de julio a las 24 horas con el tradicional…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Santa_Ana','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186789,'08003','Fiestas de Santa Eulalia','fiesta','fiestas_wiki','Las fiestas de Santa Eulalia son unas fiestas patronales en honor a Eulalia de Barcelona, celebradas en esta ciudad en torno al 12 de febrero. De menor formato que las Fiestas de la Merced —la otra patrona barcelonesa— las de Santa Eulalia se consideran las fiestas de invierno de Barcelona,​ aunque en esencia se…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Santa_Eulalia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186790,'43148','Fiestas de Santa Tecla','fiesta','fiestas_wiki','Las Fiestas de Santa Tecla de Tarragona tienen lugar alrededor de la fecha del 23 de septiembre, jornada central de la celebración. Duran diez días completos más la noche entera del 22 al 23 de septiembre. Son la fiesta grande de la ciudad de Tarragona, y gozan de los reconocimientos de Fiestas de interés turístico…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Santa_Tecla','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186791,'35018','Fiestas de Sants','fiesta','fiestas_wiki','Las Fiestas de Sants o Fiesta Mayor de Sants (en catalán: Festa Major de Sants) se celebra en el barrio de Sants (Barcelona) el día de san Bartolomé (24 de agosto). Su elemento más distintivo es la ornamentación de calles, pero también se celebran conciertos, bailes populares, exhibiciones castelleras, gigantes y…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Sants');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186792,'28148','Fiestas de Torrejón de Ardoz','fiesta','fiestas_wiki','En Torrejón de Ardoz (Madrid, España) se celebran a lo largo del año las siguientes fiestas: La Semana Santa, declarada en el año 2014 Fiesta de Interés Turístico Regional. Varias Procesiones recorren las calles del Municipio, organizadas por la Hermandad de la Vera Cruz y Ntra. Sra.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Torrejón_de_Ardoz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186793,'28161','Fiestas de Valdemoro','fiesta','fiestas_wiki','En el municipio de Valdemoro tienen lugar las siguientes fiestas: San Marcos (25 de abril): Fiesta popular que se celebra anualmente en el Parque Bolitas del Airón. Tiene su origen en las celebraciones agrícolas que ofrecían rogativas para garantizar la prosperidad de los campos. En la actualidad se celebran…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Valdemoro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186794,'03021','Fiestas de invierno de Ibi','fiesta','fiestas_wiki','Las fiestas de invierno o «Festes d''hivern», más conocidas como de Santa Llúcia i Nadal, son un conjunto de actos de carácter folclórico y tradicional que se celebran en Ibi (Alicante), entre los días 13 de diciembre y 6 de enero.​Son conocidas por la proclamación de los reyes de las danzas y el resto de bailadores…',38.62722222,-0.57527778,'https://es.wikipedia.org/wiki/Fiestas_de_invierno_de_Ibi','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186795,'30005','Fiestas de la Bruja','fiesta','fiestas_wiki','Las fiestas de la Bruja son una celebración que tiene lugar a finales de mayo en la localidad española de Alcantarilla (Murcia).',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Bruja','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186796,'38010','Fiestas de la Cruz','fiesta','fiestas_wiki','La Fiestas de la Cruz es una de los principales eventos del calendario festivo (el 2 y el 3 de mayo cada año)​ de la Villa de Los Realejos, en Tenerife, Islas Canarias, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Cruz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186797,'12040','Fiestas de la Magdalena','fiesta','fiestas_wiki','La Feria y Fiestas de la Magdalena (en valenciano: Fira i festes de la Magdalena) son las fiestas mayores de la ciudad española de Castellón de la Plana. Se trata de unas fiestas de carácter fundacional que conmemoran el traslado de la población de la montaña al llano que, según la leyenda, tuvo lugar el tercer fin…',39.985981,-0.037439,'https://es.wikipedia.org/wiki/Fiestas_de_la_Magdalena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186798,'08003','Fiestas de la Merced','fiesta','fiestas_wiki','La Merced, en catalán La Mercè, es la fiesta mayor de la ciudad de Barcelona, España. Se celebra cada año alrededor del 24 de septiembre, día de la Virgen de la Merced. Dura cerca de una semana y tiene lugar en diversos espacios públicos de la ciudad.​ Reúne anualmente entre 1.5 y 2 millones de personas en torno a…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Merced','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186799,'28079','Fiestas de la Paloma','fiesta','fiestas_wiki','Las Fiestas de la Paloma o Verbena de la Paloma es una celebración veraniega localizada en su origen en el antiguo barrio de Calatrava, en las inmediaciones de la calle de Toledo y la plaza de la Cebada, administrativamente barrio de La Latina del distrito centro en Madrid.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Paloma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186800,'37273','Fiestas de la Sagrada Familia y el Santísimo Cristo','fiesta','fiestas_wiki','Las fiestas de la Sagrada Familia y el Santísimo, son una de las dos fiestas patronales de Vall de Uxó, municipio de la Comunidad Valenciana, España, y declaradas de Interés Turístico Nacional desde el 2004.​ El atractivo de la fiesta reside en sus actos religiosos; como el Rosario de la Aurora, la Misa Pontifical,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Sagrada_Familia_y_el_Santísimo_Cristo','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186801,'04029','Fiestas de la Santísima y Vera Cruz','fiesta','fiestas_wiki','Las Fiestas Patronales de la Santísima y Vera Cruz de Caravaca se celebran del 1 al 5 de mayo en esta localidad del noroeste de la Región de Murcia en España. Están declaradas como Patrimonio Inmaterial de la humanidad por la UNESCO. Las fiestas conmemoran la aparición de la Santísima y Vera Cruz de Caravaca, que…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Santísima_y_Vera_Cruz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186802,'49021','Fiestas de la Veguilla','fiesta','fiestas_wiki','Las Fiestas de la Veguilla son las fiestas patronales de Benavente que se celebran el llamado “Lunes de Pascuilla” en honor de la Virgen de la Vega. Actualmente han sido declaradas de interés turístico regional por la Junta de Castilla y León.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Veguilla','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186803,'30043','Fiestas de la Virgen (Yecla)','fiesta','fiestas_wiki','Las Fiestas de la Virgen se celebran en la ciudad de Yecla durante los días 5, 6, 7, 8 y 21 de diciembre, en honor a la Inmaculada Concepción. Están declaradas como fiestas Interés Turístico Internacional ​ y Bien de Interés Cultural.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Virgen_(Yecla)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186804,'30036','Fiestas de la Virgen del Carmen (San Pedro del Pinatar)','fiesta','fiestas_wiki','Las Fiestas de la Virgen del Carmen son unas fiestas de tradición marinera que se celebran cada año el 16 de julio en San Pedro del Pinatar y con las que se homenajea a la patrona de la ciudad.​ Desde 1965 está declarada Fiesta de interés turístico regional de la Región de Murcia.​',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Virgen_del_Carmen_(San_Pedro_del_Pinatar)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186805,'24013','Fiestas de san Marcos en Beas de Segura','fiesta','fiestas_wiki','Las Fiestas en Honor a San Marcos, con el "toro ensogao" como protagonista, son una de las fiestas populares españolas más arraigadas, que se celebran en el municipio de Beas de Segura, en la provincia de Jaén (comunidad autónoma de Andalucía), entre los días 22 al 25 de abril, corriendo los toros ensogados por las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_san_Marcos_en_Beas_de_Segura','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186806,'28125','Fiestas de verano en Robledo de Chavela','fiesta','fiestas_wiki','En el municipio de Robledo de Chavela (Madrid, España) se celebran en verano las siguientes fiestas: Corpus Christi, con la confección de altares populares y el tapizado de las calles con pétalos de rosas por los niños que han hecho la Primera Comunión. Fiesta de San Antonio (desde el 13 de junio). Festival de…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_verano_en_Robledo_de_Chavela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186807,'29003','Fiestas del Motín','fiesta','fiestas_wiki','Las Fiestas del Motín son una celebración que tiene lugar los primeros días de septiembre en la ciudad española de Aranjuez.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_del_Motín','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186808,'50297','Fiestas del Pilar','fiesta','fiestas_wiki','Las Fiestas del Pilar son las fiestas patronales de Zaragoza (Aragón, España) que se celebran en honor de la Virgen del Pilar, patrona de la ciudad. Tienen lugar la semana del 12 de octubre en que se celebra la fiesta patronal. Por lo general, las fiestas comienzan el fin de semana anterior al día 12 y se prolongan…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_del_Pilar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186809,'19130','Fiestas del Santo Niño','fiesta','fiestas_wiki','Las fiestas del Santo Niño son unas fiestas, declaradas el 11 de febrero de 1986 como de interés turístico regional,​ que se celebran cada primer domingo de septiembre en el municipio español de Majaelrayo situado en el norte de la provincia de Guadalajara. La encargada de organizar la celebración es la Hermandad…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_del_Santo_Niño','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186810,'33013','Fiestas medievales de Olite','fiesta','fiestas_wiki','Las Fiestas medievales de Olite son una celebración de Interés Turístico de Navarra que se celebran desde 1994, fecha en la que se conmemoró el 555 aniversario de las bodas de Carlos, Príncipe de Viana, y la princesa borgoñesa Inés de Cleves el 30 de septiembre de 1439.​ Son unas fiestas que buscan devolver el…',42.4802284,-1.6595357,'https://es.wikipedia.org/wiki/Fiestas_medievales_de_Olite','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186811,'30017','Fiestas patronales de Cehegín','fiesta','fiestas_wiki','Las Fiestas Patronales de Cehegín son el conjunto de festividades celebradas en la localidad de Cehegín, que abarcan la semana del 8 al 14 de septiembre. Se celebran de forma anual y en conmemoración de la Virgen de las Maravillas, patrona del municipio. Los habitantes del municipio (‘’cehegineros’’) pueden…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_patronales_de_Cehegín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186812,'07049','Fiestas patronales de Menorca','fiesta','fiestas_wiki','Las fiestas patronales de Menorca son de tradición centenaria que tienen su origen en las Fiestas de San Juan, que se celebran en Ciudadela, isla de Menorca, en España, desde el siglo XIV. El principal protagonista de las fiestas es el caballo. Los jinetes cajeros (o caixers), vestidos de blanco y negro, van sobre…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_patronales_de_Menorca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186813,'24001','Fiestas populares de Albanchez de Mágina','fiesta','fiestas_wiki','Procesión de los Hachones - 3 de mayo. Con la procesión del Rosarío de Los Hachones se inician las fiestas patronales de San Francisco de Paula, celebradas del 3 al 6 de mayo. Los participantes recorren las calles portando los hachones, teas hechas con esparto y pez.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_populares_de_Albanchez_de_Mágina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186814,'30033','Fiestas y Festivales de Puerto Lumbreras','fiesta','fiestas_wiki','A lo largo del año se celebran en Puerto Lumbreras (Región de Murcia, España) diferentes festividades que con el paso del tiempo han arraigado en el sentir local, atrayendo además a numerosos visitantes de las comarcas vecinas.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_y_Festivales_de_Puerto_Lumbreras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186815,'36011','Fiestas, romerías y festivales de Pontevedra','fiesta','fiestas_wiki','La ciudad española de Pontevedra es conocida por la gran diversidad de fiestas, romerías y celebraciones tradicionales que tienen lugar en todos sus barrios y parroquias a lo largo del año, muchas de ellas con siglos de historia y una sólida tradición.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas,_romerías_y_festivales_de_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186816,'36015','Fiestas, romerías y festivales de Vigo','fiesta','fiestas_wiki','La ciudad de Vigo es conocida por la gran variedad de fiestas, romerías y celebraciones tradicionales que se celebran en todos los barrios y parroquias del municipio a lo largo de todo el año, de las cuales muchas de ellas son celebraciones centenarias y de gran tradición.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas,_romerías_y_festivales_de_Vigo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186817,'49067','Filandorra','fiesta','fiestas_wiki','La Filandorra es una mascarada invernal que se celebra el 26 de diciembre en el municipio español de Ferreras de Arriba (Zamora Castilla y León). En la comarca de La Carballeda.',NULL,NULL,'https://es.wikipedia.org/wiki/Filandorra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186818,'07023','Firó de Sóller','fiesta','fiestas_wiki','El Firó de Sóller es una fiesta de moros y cristianos que se celebra cada año en Sóller para conmemorar la victoria contra los corsarios otomanos ocurrida el día de san Poncio de 1561. La festividad se ha celebrado de forma continuada desde el año siguiente de los hechos, aunque el formato actual se remonta a…',NULL,NULL,'https://es.wikipedia.org/wiki/Firó_de_Sóller');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186819,'10069','Flama del Canigó','fiesta','fiestas_wiki','La Flama del Canigó (en castellano: Llama del Canigó) es una ceremonia iniciada en 1963 por Francesc Pujade, Esteve Albert y Josep Deloncle, e impulsada por la organización Òmnium Cultural, vinculada al solsticio de verano y que tiene lugar en diversos territorios catalanoparlantes cada año, entre el 22 y el 23 de…',NULL,NULL,'https://es.wikipedia.org/wiki/Flama_del_Canigó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186820,'16009','Fletilla','fiesta','fiestas_wiki','Ramón Díaz Gómez (Cádiz, 23 de diciembre de 1908 - ibídem, septiembre de 1997) ha pasado a la historia del carnaval de Cádiz por su apodo: Fletilla, gracias a su gran trayectoria el carnaval y la popularidad de sus letras.',NULL,NULL,'https://es.wikipedia.org/wiki/Fletilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186821,'27016','Folión de Carros','fiesta','fiestas_wiki','El Folión de Carros (en gallego: Folión dos Carros) es un evento, declarado Bien de Interés Turístico en mayo de 2002​ y Bien de Interés Cultural en 2019,​ que se celebra durante las fiestas patronales de Chantada (Lugo) en agosto. Se trata de un desfile de carrozas, sobre las que se recrean escenas tradicionales…',NULL,NULL,'https://es.wikipedia.org/wiki/Folión_de_Carros','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186822,'04063','Francesco Maria Maggio','fiesta','fiestas_wiki','Francesco Maria Maggio (Génova, 1705-Cádiz, 1780) fue un escultor italiano que, asentado en Cádiz, formó parte del grupo de imagineros conocido como círculo gaditano-genovés.',NULL,NULL,'https://es.wikipedia.org/wiki/Francesco_Maria_Maggio','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186823,'41091','Francisca de Paula Zuloaga','fiesta','fiestas_wiki','Francisca de Paula Zuloaga Sánchez (1761-1848) fue una reconocida bordadora​ de origen vasco​ radicada en la ciudad de Sevilla, donde regentó junto a su hermana Rita uno de los talleres más reconocidos en Sevilla en la primera mitad del siglo XIX,​ y considerado como parte del inicio del bordado sevillano.​',NULL,NULL,'https://es.wikipedia.org/wiki/Francisca_de_Paula_Zuloaga','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186824,'90288','Francisco Alba Medina','fiesta','fiestas_wiki','Francisco José María del Sagrado Corazón de Jesús Alba Medina, más conocido como Paco Alba (Conil de la Frontera, 23 de abril de 1918-Cádiz, 15 de enero de 1976), fue un músico, letrista español, compositor de coplas de carnaval.',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Alba_Medina','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186825,'41024','Francisco Buiza','fiesta','fiestas_wiki','Francisco Buiza Fernández (Carmona, 23 de abril de 1922 - Sevilla, 1 de marzo de 1983) fue un escultor e imaginero español que se dedicó fundamentalmente a la talla de imágenes religiosas, aunque también realizó esculturas sobre otros temas.',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Buiza','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186826,'21041','Francisco Garfias López','fiesta','fiestas_wiki','Francisco Garfias López (Moguer, (Huelva), 6 de diciembre de 1920 - 26 de octubre de 2010),​ fue un poeta español, ganador del Premio Nacional de Literatura en 1971. Cursó estudios de Filosofía y Letras, y de Periodismo en Madrid.',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Garfias_López','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186827,'03044','Francisco Grau Vegara','fiesta','fiestas_wiki','Francisco Grau Vegara (Bigastro, Alicante, 22 de enero de 1947​- Madrid, 21 de julio de 2019) fue un músico y militar español conocido por en 1997 haber sido el arreglista de la versión actual del Himno Nacional de España (La Marcha Real), cuyo arreglo lo hizo en tres versiones: para orquesta, para banda de música…',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Grau_Vegara','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186828,'11031','Francisco Montero Galvache','fiesta','fiestas_wiki','Francisco Montero Galvache (San Fernando, 8 de mayo de 1917 - Sevilla, 29 de septiembre de 1999) fue un escritor, novelista, poeta y periodista español. A lo largo de su carrera llegó a colaborar con numerosos medios, ejerciendo también de comentarista de eventos taurinos y deportivos.',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Montero_Galvache','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186829,'09003','Francisco Palma Burgos','fiesta','fiestas_wiki','Francisco Palma Burgos (Málaga, 12 de febrero de 1918–Úbeda, 31 de diciembre de 1985) fue un escultor, imaginero​ y pintor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Palma_Burgos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186830,'02004','Francisco Salzillo','fiesta','fiestas_wiki','Francisco Salzillo y Alcaraz (Murcia, 12 de mayo de 1707-Murcia, 2 de marzo de 1783) fue un escultor barroco español, considerado como el más representativo imaginero del siglo XVIII español y uno de los más grandes del Barroco. Salzillo se dedicó en exclusiva a la temática religiosa y supo transmitir a su estilo…',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_Salzillo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186831,'47186','Francisco del Rincón (escultor)','fiesta','fiestas_wiki','Francisco del Rincón (h.1567-1608) fue un escultor español del siglo XVII, con taller en la ciudad de Valladolid, considerado uno de los grandes maestros de la escuela castellana del primer Barroco. Se le reconoce como una figura fundamental en el pasaje del Manierismo (últimos años del Renacimiento) al Barroco en…',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_del_Rincón_(escultor)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186832,'08240','Freixenet','fiesta','fiestas_wiki','Freixenet (AFI: /ˌfɾəʃə''nɛt/) es una empresa española productora de cava y otros vinos espumosos y tranquilos, con sede en San Sadurní de Noya, en la provincia de Barcelona. Está presidida, desde noviembre de 2021, por Alfred Oetker, y completan el Consejo de Administración Pedro Ferrer, José María Ferrer y Carl…',41.420179,1.792177,'https://es.wikipedia.org/wiki/Freixenet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186833,'26010','Frisuelos','fiesta','fiestas_wiki','Los frisuelos (frixuelos en asturiano o jisuelos en cántabro) son un tipo de postre, típico en las regiones españolas de Asturias, Cantabria y León. Está hecho a base de harina, leche y huevos. Son típicos de las celebraciones de Antroxu (carnaval) y de las Comadres en Asturias.',NULL,NULL,'https://es.wikipedia.org/wiki/Frisuelos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186834,'20069','Fuegos artificiales de San Sebastián','fiesta','fiestas_wiki','El concurso de fuegos artificiales de San Sebastián en el País Vasco (España) es uno de los certámenes pirotécnicos más antiguos y prestigiosos de España. Se celebra anualmente en agosto, en el marco de la Semana Grande, y es organizado por el Ayuntamiento de San Sebastián.​ Los fuegos se lanzan desde los jardines…',NULL,NULL,'https://es.wikipedia.org/wiki/Fuegos_artificiales_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186835,'47093','Función de la Cruz de Montemayor de Pililla','fiesta','fiestas_wiki','La fiesta de la Función de la Cruz, o simplemente «La Función», como habitualmente se la conoce en la localidad, consiste en un conjunto de actividades religiosas y festivas; desde sus orígenes existen pruebas documentales de estas celebraciones y desde al menos el siglo XVII, han sido seña de identidad y cohesión…',NULL,NULL,'https://es.wikipedia.org/wiki/Función_de_la_Cruz_de_Montemayor_de_Pililla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186836,'04043','Félix Granda','fiesta','fiestas_wiki','Félix Granda Buylla (Pola de Lena, 21 de febrero de 1868 – Madrid, 23 de febrero de 1954), fue un sacerdote, escultor, pintor y orfebre español, que fundó el taller de arte litúrgico Talleres de Arte que dirigió hasta su muerte.',NULL,NULL,'https://es.wikipedia.org/wiki/Félix_Granda','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186837,'04043','Félix Revello de Toro','fiesta','fiestas_wiki','Félix Revello de Toro (Málaga, 10 de junio de 1926) es un pintor español. Su primera exposición tendría lugar en 1938, cuando contaba con 12 años. A los 16 recibe su primer encargo profesional para una hermandad local.',NULL,NULL,'https://es.wikipedia.org/wiki/Félix_Revello_de_Toro','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186838,'35016','Gala Drag Queen de Las Palmas de Gran Canaria','fiesta','fiestas_wiki','La Gala Drag Queen es un evento del carnaval de Las Palmas de Gran Canaria. Consiste en un espectáculo musical, en el que el acontecimiento principal es un concurso de drag queens, amenizado con otras actuaciones de cantantes y números de baile. La gala primigenia de 1998 fue una idea original de la periodista…',NULL,NULL,'https://es.wikipedia.org/wiki/Gala_Drag_Queen_de_Las_Palmas_de_Gran_Canaria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186839,'45168','Gigantes y Cabezudos de Toledo','fiesta','fiestas_wiki','Los gigantones y cabezudos son, junto con la Tarasca, los personajes más llamativos de la fiesta con ocasión de la Procesión del Corpus Christi de Toledo, Fiesta de Interés Turístico Internacional. Estas imágenes están construidas en los años 80 por la Junta pro-Corpus de Toledo con un armazón de varas de mimbre y…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantes_y_Cabezudos_de_Toledo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186840,'12012','Gigantes y cabezudos','fiesta','fiestas_wiki','Los gigantes y cabezudos son una tradición popular celebrada en muchas fiestas locales de España y en menor medida en otras regiones de Europa Occidental e Hispanoamérica. La tradición consiste en hacer desfilar ciertas figuras bailando y animando, los gigantes, o persiguiendo a la gente que acude a la celebración.…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantes_y_cabezudos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186841,'29001','Gigantes y cabezudos de Alcalá de Henares','fiesta','fiestas_wiki','La comparsa de gigantes y cabezudos de Alcalá de Henares es un espectáculo lúdico de gran tradición y expectación en las fiestas populares de Alcalá de Henares en la comunidad autónoma de Madrid en España, sobre todo entre el público infantil. Participa en su máximo esplendor en las Ferias de finales de agosto,…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantes_y_cabezudos_de_Alcalá_de_Henares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186842,'28079','Gigantes y cabezudos de Madrid','fiesta','fiestas_wiki','Los gigantes y cabezudos son una tradición muy arraigada en España. La comparsa de Madrid se estrenó en 1967 y desde entonces amenizan las castizas fiestas de San Isidro. Su residencia habitual se encuentra en el Museo de artes y tradiciones de Madrid (calle Carlos Arniches 3), donde pueden ser visitados por el…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantes_y_cabezudos_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186843,'20069','Gigantes y cabezudos de San Sebastián','fiesta','fiestas_wiki','La comparsa de gigantes y cabezudos de San Sebastián está formada por ocho gigantes y catorce cabezudos. Su estreno por las calles donostiarras fue en 1982. Desde entonces se ha ido consolidando como el elemento más significativo de la Semana Grande de su ciudad, protagonizando la Semana Gigante.',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantes_y_cabezudos_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186844,'39075','Gigantillas','fiesta','fiestas_wiki','Gigantillas es el nombre que popularmente se da a los gigantes y cabezudos en la ciudad de Santander (Cantabria), España. En la actualidad el Ayuntamiento de Santander junto con la Asociación Gigantes y Cabezudos de Santander está recuperando esta tradición de más de 200 años de historia en la ciudad. Para ello se…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantillas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186845,'26010','Gigantón','fiesta','fiestas_wiki','Se llama gigantón o gigante a unas figuras antropomóficas gigantescas que puede portar una persona en procesiones y actos festivos. Los gigantones, enanos, dragones, la tarasca, la mulassa, el león y demás figuras que preceden a las procesiones del Corpus Christi simbolizan, en el imaginario católico, la idolatría…',NULL,NULL,'https://es.wikipedia.org/wiki/Gigantón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186846,'12084','Gomaespuma (programa de radio)','fiesta','fiestas_wiki','Gomaespuma fue un programa de radio español que, desde diferentes emisoras (Antena 3 de Radio, Onda Cero, M80 Radio), se emitió desde principios de la década de 1980 hasta el 27 de julio de 2007 en Onda Cero. También se llama así a los locutores de dicho programa, a la fundación dirigida por estos, al programa de…',NULL,NULL,'https://es.wikipedia.org/wiki/Gomaespuma_(programa_de_radio)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186847,'38011','Gran Poder de Dios','fiesta','fiestas_wiki','El Gran Poder de Dios es una imagen de Jesucristo pensante que se encuentra en la ciudad de Puerto de la Cruz (Tenerife, Canarias, España). La imagen se encuentra en la Iglesia de Nuestra Señora de la Peña de Francia. Su cofradía es la Hermandad del Gran Poder de Dios.',NULL,NULL,'https://es.wikipedia.org/wiki/Gran_Poder_de_Dios');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186848,'90453','Guardiola Fantoni','fiesta','fiestas_wiki','Guardiola Fantoni es el nombre con el que se conoce a la ganadería brava española de los Herederos de don Salvador Guardiola Fantoni y que está inscrita dentro de la Unión de Criadores de Toros de Lidia. Los toros de este hierro, que pertenecen al encaste Villamarta, pastan en las fincas de El Toruño (Utrera,…',NULL,NULL,'https://es.wikipedia.org/wiki/Guardiola_Fantoni','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186849,'39025','Guerras Cántabras (fiesta)','fiesta','fiestas_wiki','Las Guerras Cántabras es una recreación histórica representada en Los Corrales de Buelna, en la comunidad autónoma de Cantabria, durante los dos últimos fines de semana de agosto. La fiesta es de marcado carácter histórico, representando los acontecimientos bélicos de las guerras cántabras, que mantuvieron hace…',NULL,NULL,'https://es.wikipedia.org/wiki/Guerras_Cántabras_(fiesta)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186850,'03012','Gustavo Pascual Falcó','fiesta','fiestas_wiki','Gustavo Pascual Falcó (Cocentaina, España, 15 de mayo de 1909 - Cocentaina, 17 de abril de 1946) fue un compositor, conocido especialmente por sus pasodobles Paquito el Chocolatero y El Bequetero.',NULL,NULL,'https://es.wikipedia.org/wiki/Gustavo_Pascual_Falcó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186851,'28079','Gustavo Villapalos','fiesta','fiestas_wiki','Gustavo Villapalos Salas (Madrid, 15 de octubre de 1949-Madrid, 14 de junio de 2021) fue un historiador del derecho, catedrático y político español.',NULL,NULL,'https://es.wikipedia.org/wiki/Gustavo_Villapalos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186852,'41053','Hermanas Antúnez','fiesta','fiestas_wiki','Las Hermanas Antúnez fueron dos bordadoras españolas del siglo XIX. Se llamban Josefa Antúnez Meléndez y Ana Antúnez Meléndez. Nacieron en Lebrija (provincia de Sevilla) los años 1833 y 1836. Confeccionaron en el último tercio del siglo XIX diferentes obras artísticas de gran mérito, la mayoría bordados destinados…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermanas_Antúnez','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186853,'47186','Hermandad Penitencial de Nuestro Padre Jesús atado a la Columna','fiesta','fiestas_wiki','La Hermandad del Penitencial de Nuestro Padre Jesús atado a la Columna es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_Penitencial_de_Nuestro_Padre_Jesús_atado_a_la_Columna','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186854,'43138','Hermandad Penitencial de Santa Cruz (Alicante)','fiesta','fiestas_wiki','La Hermandad Penitencial de Santa Cruz es una cofradía de la Semana Santa de Alicante (España), fundada en 1945. Está vinculada al barrio de Santa Cruz, ubicado en las faldas del Castillo de Santa Bárbara, y organiza la procesión que se celebra cada Miércoles Santo durante la Semana Santa alicantina.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_Penitencial_de_Santa_Cruz_(Alicante)','Interés Turístico Regional');
