INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186857,'14065','Hermandad Sacramental del Rocío','fiesta','fiestas_wiki','La Cofradía del Rocío cuyo nombre oficial y completo es Real, Ilustre y Venerable Hermandad Sacramental de Nuestro Padre Jesús Nazareno de los Pasos en el Monte Calvario y María Santísima del Rocío Coronada es una hermandad religiosa o cofradía con sede canónica en la Iglesia de San Lázaro, en el barrio de La…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_Sacramental_del_Rocío','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186858,'10037','Hermandad Universitaria de Jesús Condenado (Cáceres)','fiesta','fiestas_wiki','La Hermandad Universitaria de Jesús Condenado es una hermandad de la Semana Santa de Cáceres, en Extremadura; erigida canónicamente el 31 de marzo de 2011. Recorrió por primera vez la madrugada del 6 de abril de 2012, saliendo desde la Casa de los Hermanos de la Cruz Blanca.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_Universitaria_de_Jesús_Condenado_(Cáceres)','IT Internacional');
