INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186860,'41041','Hermandad de "La Borriquita" (Estepa)','fiesta','fiestas_wiki','La Hermandad de "La Borriquita" es una cofradía de Semana Santa establecida en la ciudad de Estepa, fundada en 1954 en la Parroquia de San Sebastián desde donde realiza estación de penitencia cada Domingo de Ramos.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_"La_Borriquita"_(Estepa)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186861,'41041','Hermandad de "Las Angustias" (Estepa)','fiesta','fiestas_wiki','La Hermandad de "Las Angustias" es una cofradía de Semana Santa establecida en la ciudad de Estepa, fundada en 1955 en la Ermita de Santa Ana desde donde realiza estación de penitencia cada Lunes Santo.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_"Las_Angustias"_(Estepa)','IT Nacional');
