INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186864,'03064','Hermandad de Bendición y Esperanza','fiesta','fiestas_wiki','La Hermandad de penitencia Bendición y Esperanza es una corporación católica ubicada en la Parroquia de Jesús Obrero de Sevilla, en el barrio del Polígono Sur.​ Realiza una procesión anual en la tarde del Viernes de Dolores, formando parte de las Vísperas de la Semana Santa de Sevilla.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_Bendición_y_Esperanza','IT Internacional');
