INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(186878,'22006','Hermandad de Nuestra Señora de las Angustias (Ayamonte)','fiesta','fiestas_wiki','La Hermandad de Nuestra Señora de las Angustias, es la Hermandad de la Patrona y alcaldesa perpetua de Ayamonte. Tiene estatutos aprobados con fecha de 7 de septiembre de 1875.​ Celebra su fiesta principal el 8 de septiembre, día de la Natividad de Nuestra Señora. La Hermandad venera a su titular, Nuestra Señora de…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_Nuestra_Señora_de_las_Angustias_(Ayamonte)');
