INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186918,'11020','Hermandad de la Entrega de Guadalcacín (Jerez)','fiesta','fiestas_wiki','La Hermandad de la Entrega es una cofradía católica que realiza una procesión anual durante la tarde del Sábado Santo, en las vísperas de la Semana Santa de Jerez de la Frontera, ya que todavía no tiene el permiso para realizar estación de penitencia a la Santa Iglesia Catedral.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Entrega_de_Guadalcacín_(Jerez)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186919,'21041','Hermandad de la Esperanza (Huelva)','fiesta','fiestas_wiki','La Hermandad de la Esperanza (Huelva) es una agrupación religiosa católica española fundada entre 1893 y 1894 en la antigua Iglesia Conventual de San Francisco (Huelva) que realiza una procesión anual durante la Semana Santa en la tarde y noche del Miércoles Santo.​',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Esperanza_(Huelva)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186920,'06030','Hermandad de la Esperanza de Triana','fiesta','fiestas_wiki','La Hermandad de la Esperanza de Triana es una cofradía católica del barrio de Triana, en Sevilla, Andalucía, España. La Virgen tiene devoción y arraigo siendo una de las más famosas de la ciudad y es popularmente conocida como la Reina de Triana. Tiene su sede en la capilla de los Marineros.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Esperanza_de_Triana','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186921,'10037','Hermandad de la Esperanza del Vivero (Cáceres)','fiesta','fiestas_wiki','La Venerable Hermandad y Cofradía de Nazarenos de Nuestro Padre Jesús de la Humildad en su Prendimiento y María Santísima del Dulce Nombre de Esperanza es una hermandad de la Semana Santa de Cáceres, en Extremadura; fundada originalmente en 2008. Su sede canónica se encuentra en la parroquia del Beato Marcelo…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Esperanza_del_Vivero_(Cáceres)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186922,'45065','Hermandad de la Estrella (Granada)','fiesta','fiestas_wiki','La Cofradía de Nazarenos de Nuestro Padre Jesús de la Pasión y María Santísima de la Estrella es una hermandad de penitencia de la ciudad de Granada. Su sede es la iglesia de San Cristóbal situada en la parte alta del Albaicín. Su primera salida fue en el año 1980 en la jornada del Viernes Santo al año siguiente…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Estrella_(Granada)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186923,'11020','Hermandad de la Estrella (Jerez)','fiesta','fiestas_wiki','La Hermandad de la Borriquita, también conocida como Hermandad de la Estrella, es una cofradía católica que realiza una procesión anual durante la tarde del Domingo de Ramos de la Semana Santa de Jerez de la Frontera.',36.68632264,-6.13919841,'https://es.wikipedia.org/wiki/Hermandad_de_la_Estrella_(Jerez)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(186924,'45065','Hermandad de la Estrella (Sevilla)','fiesta','fiestas_wiki','La Hermandad de la Estrella es una cofradía que procesiona en la Semana Santa de Sevilla, Andalucía, España. Fue fundada en 1560 en Triana, desde donde realiza estación de penitencia a la catedral de Sevilla cada Domingo de Ramos.​ Es la segunda cofradía que pasa por las calles de Triana después de Pasión y Muerte…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_de_la_Estrella_(Sevilla)','IT Internacional');
