INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187032,'29067','Hermandad del Sepulcro (Málaga)','fiesta','fiestas_wiki','La Hermandad del Sepulcro, cuya denominación oficial es Real Hermandad de Nuestro Padre Jesús del Santo Sepulcro y Nuestra Señora de la Soledad, es la hermandad oficial de Málaga, miembro de la Agrupación de Cofradías y participante de la Semana Santa malagueña.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Sepulcro_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187033,'03027','Hermandad del Silencio (Orihuela)','fiesta','fiestas_wiki','La Hermandad del Silencio es una agrupación pasional fundada en el año 1940. Desfila el Jueves Santo en la Semana Santa de Orihuela.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Silencio_(Orihuela)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187034,'41091','Hermandad del Silencio (Sevilla)','fiesta','fiestas_wiki','La Hermandad de El Silencio es una cofradía católica de Sevilla, Andalucía, España. Tiene su sede canónica en la iglesia de San Antonio Abad. Hace estación de penitencia durante la madrugada del Viernes Santo.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Silencio_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187035,'50297','Hermandad del Silencio (Zaragoza)','fiesta','fiestas_wiki','La Cofradía de Nuestro Padre Jesús de la Agonía y Nuestra Señora del Rosario en sus Misterios Dolorosos o del Silencio fundada en 1944 como cofradía penitencial, es una de las 25 participantes en la Semana Santa zaragozana.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Silencio_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187036,'11020','Hermandad del Soberano Poder (Jerez)','fiesta','fiestas_wiki','La Hermandad del Soberano Poder es una cofradía católica que realiza una procesión anual durante la tarde del Miércoles Santo de la Semana Santa de Jerez de la Frontera.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Soberano_Poder_(Jerez)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187037,'41091','Hermandad del Sol (Sevilla)','fiesta','fiestas_wiki','La Hermandad del Sol es una cofradía católica de Sevilla, Andalucía, España. Procesiona en la Semana Santa el Sábado Santo. Su nombre completo es Hermandad Sacramental de la Inmaculada Concepción de María Santísima de la Salud y Cofradía de Nazarenos del Triunfo de la Santa Cruz, Santo Cristo Varón de Dolores de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Sol_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187038,'11020','Hermandad del Transporte (Jerez)','fiesta','fiestas_wiki','La Hermandad del Transporte es una cofradía católica que realiza una procesión anual durante la tarde del Domingo de Ramos de la Semana Santa de Jerez de la Frontera.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Transporte_(Jerez)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187039,'29067','Hermandad del Traslado (Málaga)','fiesta','fiestas_wiki','La Hermandad del Santo Traslado y Ntra Sra de la Soledad, conocida como Hermandad de la Soledad de San Pablo, cuya denominación oficial es Real, Ilustre y Venerable Hermandad del Santo Traslado y Nuestra Señora de la Soledad , es una hermandad de Málaga, miembro de la Agrupación de Cofradías, que participa en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Traslado_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187040,'41091','Hermandad del Valle (Sevilla)','fiesta','fiestas_wiki','La Hermandad del Valle es una cofradía católica de Sevilla, Andalucía, España. Procesiona en Semana Santa el Jueves Santo. Tiene su sede en la iglesia de la Anunciación.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_del_Valle_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187041,'04063','Hermandad y Cofradía de Nazarenos de Nuestro Señor Jesús de la Humildad entregado por el Sanedrín y de María Santísima d','fiesta','fiestas_wiki','La Hermandad y Cofradía de Nazarenos de Nuestro Señor Jesús de la Humildad entregado por el Sanedrín y de María Santísima del Dulce Nombre fundada en 1993, es una cofradía que participa en los actos de la Semana Santa de Zaragoza (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_y_Cofradía_de_Nazarenos_de_Nuestro_Señor_Jesús_de_la_Humildad_entregado_por_el_Sanedrín_y_de_María_Santísima_del_Dulce_Nombre','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187042,'02001','Hermandad y Cofradía de San Juan Evangelista (Albacete)','fiesta','fiestas_wiki','La Hermandad y Cofradía de San Juan Evangelista es una cofradía de la Semana Santa de Albacete (España).​​​ Tiene su sede canónica en la Catedral de San Juan Bautista de Albacete. Fue fundada en 1926. Cuenta con una imagen: San Juan Evangelista (1942).',NULL,NULL,'https://es.wikipedia.org/wiki/Hermandad_y_Cofradía_de_San_Juan_Evangelista_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187043,'06022','Hermanos Calatrava','fiesta','fiestas_wiki','Manuel García Lozano (1939) (Manolo) y Francisco García Lozano (1942) (Paco), conocidos artísticamente como Hermanos Calatrava, (nacidos en Villanueva de la Serena, Badajoz) son dos humoristas, parodistas y cantantes españoles.',NULL,NULL,'https://es.wikipedia.org/wiki/Hermanos_Calatrava','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187044,'27066','Historia de la Semana Santa de Vivero','fiesta','fiestas_wiki','La historia de la Semana Santa de Vivero se remonta hasta el siglo XIII, cuando se fundaron las dos cofradías más antiguas que organizan sus procesiones. Alcanzó un gran esplendor en el siglo XVIII, cuando la Venerable Orden Tercera Franciscana y la Cofradía del Rosario empezaron a incorporar nuevas imágenes.',NULL,NULL,'https://es.wikipedia.org/wiki/Historia_de_la_Semana_Santa_de_Vivero','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187045,'47186','Historia de la Semana Santa en Valladolid','fiesta','fiestas_wiki','La Historia de la Semana Santa de Valladolid se remonta al siglo XV, cuando se comenzaron a organizar las primeras procesiones, y fue durante el siglo XVII cuando logró su mayor esplendor escultórico. Tras decaer en el siglo XIX, fue en 1920 cuando se impulsó la Procesión General del Viernes Santo, que reúne a…',NULL,NULL,'https://es.wikipedia.org/wiki/Historia_de_la_Semana_Santa_en_Valladolid','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187046,'25001','Hoguera de los Quintos','fiesta','fiestas_wiki','La Hoguera de los Quintos es una antigua tradición que entronca directamente con los antiguos rituales prerromanos de la celebración de los solsticios: en el solsticio de invierno (que tiene lugar unos días antes del 31 de diciembre) se encendían hogueras, que simbolizaban que el sol, a partir de ese momento,…',NULL,NULL,'https://es.wikipedia.org/wiki/Hoguera_de_los_Quintos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187047,'03003','Hogueras de Alicante','fiesta','fiestas_wiki','Las Hogueras de San Juan (en valenciano, Fogueres de Sant Joan) son las fiestas que se celebran en la ciudad española de Alicante por San Juan del 20 al 24 de junio. Son las fiestas oficiales de la ciudad, declaradas de Interés Turístico Internacional en 1983​ y Bien de Interés Cultural Inmaterial en 2014.​ Su…',38.3453,-0.4831,'https://es.wikipedia.org/wiki/Hogueras_de_Alicante','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187048,'07049','Hogueras de San Juan en Guipúzcoa','fiesta','fiestas_wiki','Las Hogueras de San Juan en Guipúzcoa (España) constituyen uno de los rituales humanos más antiguos y representativos de la región, profundamente vinculados a creencias paganas precristianas. ​ Celebradas durante la noche del 23 de junio, estas hogueras tienen un origen que se remonta a tiempos remotos de probable…',NULL,NULL,'https://es.wikipedia.org/wiki/Hogueras_de_San_Juan_en_Guipúzcoa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187049,'29067','Hombres de trono','fiesta','fiestas_wiki','Hombres de trono es la denominación usada en la ciudad de Málaga para designar a quienes cargan las imágenes en las procesiones religiosas desde el exterior del trono (o plataforma sobre la que van elevadas) sosteniendo un varal con uno de sus hombros.​​ El trono lleva al menos un varal en corrido bajo cada uno de…',NULL,NULL,'https://es.wikipedia.org/wiki/Hombres_de_trono','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187050,'14067','Huevada','fiesta','fiestas_wiki','La Procesión de San Isidro Chiquito comienda a las 21:00h , organizada por la hermandad de San Isidro Labrador lleva a la imagen de San Isidro en versión pequeña hasta el lugar donde se celebra la ,Huevada, también llamada Gran Huevada, es una fiesta popular de Villafranca de Córdoba (Córdoba) España, que se…',NULL,NULL,'https://es.wikipedia.org/wiki/Huevada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187051,'28079','Humilladero de Nuestra Señora de la Soledad','fiesta','fiestas_wiki','El humilladero de Nuestra Señora de la Soledad es una pequeña capilla situada en el número 44 de la calle de Fuencarral de Madrid, esquina a la antigua calle de Santa María del Arco.​ Fue construida en 1712 debido a que en las inmediaciones existía un cuadro de la Virgen de Nuestra Señora de la Soledad, al que los…',40.42311,-3.70063,'https://es.wikipedia.org/wiki/Humilladero_de_Nuestra_Señora_de_la_Soledad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187052,'02001','Ibercut','fiesta','fiestas_wiki','Ibercut, también referida como Feria Internacional de Cuchillería de Albacete, es una feria internacional de cuchillería que se celebra anualmente en la ciudad española de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Ibercut','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187053,'47186','Iglesia de San Andrés (Valladolid)','fiesta','fiestas_wiki','La iglesia de San Andrés de Valladolid es una iglesia parroquial católica situada en la diócesis de Valladolid. Situada en la plaza de San Andrés, cerca de la comercial calle Mantería, es una de las iglesias de mayor tamaño de la ciudad. Es el referente del barrio que la rodea, San Andrés-Caño Argales, el cual toma…',41.648075,-4.72191111,'https://es.wikipedia.org/wiki/Iglesia_de_San_Andrés_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187054,'47186','Ilustre Cofradía Penitencial de Nuestra Señora de las Angustias','fiesta','fiestas_wiki','La Ilustre Cofradía Penitencial de Nuestra Señora de las Angustias es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid (España).',41.65393056,-4.72407222,'https://es.wikipedia.org/wiki/Ilustre_Cofradía_Penitencial_de_Nuestra_Señora_de_las_Angustias','IT Internacional');
