INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187056,'43065','Ilustre y Venerable Cofradía del Santísimo Cristo del Calvario y Nuestra Señora de la Amargura','fiesta','fiestas_wiki','La Ilustre y Venerable Cofradía del Santísimo Cristo del Calvario y Nuestra Señora de la Amargura de Baeza es una asociación pública de fieles de la Iglesia católica que se rige por los estatutos aprobados por el obispo de Jaén, Santiago García Aracil, el 1 de febrero de 1989. Rinde culto a una imagen de Jesús vivo…',NULL,NULL,'https://es.wikipedia.org/wiki/Ilustre_y_Venerable_Cofradía_del_Santísimo_Cristo_del_Calvario_y_Nuestra_Señora_de_la_Amargura','Interés Turístico Regional');
