INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187058,'29094','Israel Cornejo Sánchez','fiesta','fiestas_wiki','Israel Cornejo Sánchez (Vélez-Málaga, 7 de septiembre de 1979) es un escultor e imaginero español. Se graduó en talla en madera y dorado y policromía en la Escuela de Arte «San Telmo» de Málaga y en la Universidad de Málaga. Asistió al taller del imaginero Juan Ventura.',NULL,NULL,'https://es.wikipedia.org/wiki/Israel_Cornejo_Sánchez','IT Internacional');
