INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187061,'20069','Jaime Azpilicueta','fiesta','fiestas_wiki','Jaime Azpilicueta Pérez (n. San Sebastián; 1941) es un director de teatro español.',NULL,NULL,'https://es.wikipedia.org/wiki/Jaime_Azpilicueta','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187062,'10037','Jarramplas','fiesta','fiestas_wiki','Jarramplas es una fiesta que se celebra en la localidad española de Piornal en la provincia de Cáceres. Está declarada como Fiesta de Interés Turístico de Extremadura y Fiesta de Interés Turístico Nacional.​ Se celebra cada 19 y 20 de enero.',NULL,NULL,'https://es.wikipedia.org/wiki/Jarramplas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187063,'31135','Javier Osuna','fiesta','fiestas_wiki','Javier Osuna (1961) es un presentador de radio, escritor e investigador centrado en la difusión del Carnaval de Cádiz, en el cual también ha participado como chirigotero en la controvertida chirigota de 1986 ''Los tontos de capirote''.',NULL,NULL,'https://es.wikipedia.org/wiki/Javier_Osuna','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187064,'31135','Javier Ruibal','fiesta','fiestas_wiki','Francisco Javier Ruibal de Flores Calero (El Puerto de Santa María, Cádiz, 15 de mayo de 1955), más conocido como Javier Ruibal, es un cantautor y arreglista español que combina estilos de flamenco, sefardí-magrebí, jazz y rock.',NULL,NULL,'https://es.wikipedia.org/wiki/Javier_Ruibal','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187065,'11038','Jesulín de Ubrique','fiesta','fiestas_wiki','Jesús Janeiro Bazán, conocido como Jesulín de Ubrique en los carteles (Ubrique, Cádiz, 9 de enero de 1974), es un torero retirado y personaje mediático español. Lideró el escalafón taurino durante tres años consecutivos en los años 90.',NULL,NULL,'https://es.wikipedia.org/wiki/Jesulín_de_Ubrique','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187066,'16009','Jesús Bienvenido','fiesta','fiestas_wiki','Jesús Bienvenido Saucedo (Cádiz, 12 de agosto de 1976) es un cantante y compositor español, autor de comparsas y chirigotas, muy ligado al Carnaval de Cádiz.',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_Bienvenido','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187067,'24086','Jesús Nazareno de las Torres','fiesta','fiestas_wiki','Jesús Nazareno de las Torres es la imagen titular de la Ilustre Archicofradía y antigua Hermandad del Dulce Nombre de Nuestro Padre Jesús Nazareno de las Torres. La sagrada imagen de Nuestro Padre Jesús Nazareno de las Torres, fue realizada por el escultor nacido en Álora José Navas-Parejo Pérez y se procesionó por…',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_Nazareno_de_las_Torres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187068,'21064','Jesús Quintero','fiesta','fiestas_wiki','Jesús Rodríguez Quintero (San Juan del Puerto, Huelva, 18 de agosto de 1940 – Ubrique, Cádiz, 3 de octubre de 2022),​​ más conocido como Jesús Quintero o El Loco de la Colina, fue un periodista, director y presentador de programas de radio y televisión español.​',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_Quintero','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187069,'41091','Jesús Rosado','fiesta','fiestas_wiki','Jesús Rosado Borja (Écija, Sevilla) es un bordador y restaurador español.',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_Rosado','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187070,'34120','Jesús camino del Calvario (Palencia)','fiesta','fiestas_wiki','Jesús camino del Calvario, también conocido como Camino del Calvario y La Verónica, es una obra realizada por José de Rozas, Antonio Vázquez y Bernardo López de Frías entre 1694 y 1696.',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_camino_del_Calvario_(Palencia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187071,'24002','Jesús de la Pasión','fiesta','fiestas_wiki','Nuestro Padre Jesús de la Pasión es una escultura de madera policromada, fechada hacia 1610-1615,​ obra de Juan Martínez Montañés (Alcalá la Real, Jaén, 1568 - Sevilla, 18 de junio de 1649) que representa a Jesús con la cruz a cuestas. Fue encargada por la Hermandad de Pasión de Sevilla para representar la Quinta…',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_de_la_Pasión','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187072,'41091','Jesús de la Sentencia (Sevilla)','fiesta','fiestas_wiki','Jesús de la Sentencia, formalmente titulado Nuestro Padre Jesús de la Sentencia, es una escultura de estilo barroco que representa a Jesucristo maniatado en el momento en que un sanedrita judío lee su sentencia. Es uno de los titulares de la Hermandad de la Esperanza Macarena, se encuentra situado en su capilla de…',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_de_la_Sentencia_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187073,'41091','Jesús del Gran Poder (Sevilla)','fiesta','fiestas_wiki','Jesús del Gran Poder, formalmente titulado Nuestro Padre Jesús del Gran Poder, es una escultura realizada en madera policromada de 1,81 metros de alto, obra del cordobés Juan de Mesa fechada en el año 1620. Es titular de la Hermandad de Jesús del Gran Poder. Es la imagen con mayor devoción de la ciudad de Sevilla,…',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_del_Gran_Poder_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187074,'41091','Jesús del Silencio (Sevilla)','fiesta','fiestas_wiki','Jesús del Silencio en el desprecio de Herodes es una imagen de Jesús de Nazaret que se venera en la capilla sacramental de la iglesia de San Juan de la Palma en Sevilla, Andalucía, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Jesús_del_Silencio_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187075,'02071','Jira de Castandiello','fiesta','fiestas_wiki','La Jira de Castandiello, o Jira de San Pedro, es una tradicional romería que se celebra el último día de las fiestas de San Pedro de La Felguera, Asturias, desde 1923.​ Dependiendo del año, se celebra entre finales de junio y principios de julio.',NULL,NULL,'https://es.wikipedia.org/wiki/Jira_de_Castandiello');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187076,'48020','Joaquín Bilbao','fiesta','fiestas_wiki','Joaquín Bilbao Martínez (Sevilla, 27 de agosto de 1864-Sevilla, 30 de enero de 1934)​​ fue un escultor español, hermano del pintor Gonzalo Bilbao.​ Su obra más conocida es la estatua ecuestre de san Fernando que se encuentra en la plaza Nueva de Sevilla, frente al Ayuntamiento.',NULL,NULL,'https://es.wikipedia.org/wiki/Joaquín_Bilbao','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187077,'28079','Joaquín Calvo Sotelo','fiesta','fiestas_wiki','Joaquín Calvo Sotelo (La Coruña, 5 de marzo de 1905 - Madrid, 7 de abril de 1993) fue un dramaturgo y periodista español, hermano del político José Calvo Sotelo y tío de Leopoldo Calvo-Sotelo.',NULL,NULL,'https://es.wikipedia.org/wiki/Joaquín_Calvo_Sotelo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187078,'16009','Joaquín Fernández Garaboa','fiesta','fiestas_wiki','Joaquín Fernández Garaboa, más conocido en el mundo del carnaval como El Quini (Cádiz, 25 de mayo de 1924 - ibídem, 24 de febrero de 1998), fue un director y músico de coros español.',NULL,NULL,'https://es.wikipedia.org/wiki/Joaquín_Fernández_Garaboa','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187079,'21054','Joaquín Moreno Daza','fiesta','fiestas_wiki','Francisco Joaquín Moreno Daza (Isla Cristina, 19 de marzo de 1919 - Sevilla, 22 de diciembre de 1995), fue un escultor español especializado en imaginería religiosa que estuvo afincado en La Palma del Condado, lugar donde instaló su taller en 1954.',NULL,NULL,'https://es.wikipedia.org/wiki/Joaquín_Moreno_Daza','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187080,'16009','Joaquín Quiñones','fiesta','fiestas_wiki','Joaquín Quiñones Madera nació en Cádiz el 24 de mayo de 1951.​ Destaca su gran aportación al Carnaval de Cádiz. Su primera agrupación data del año 1971 (Los Cenacheros). Durante su carrera, ha obtenido cinco primeros premios​ en el concurso oficial de agrupaciones que se celebra en el Gran Teatro Falla: en 1982…',NULL,NULL,'https://es.wikipedia.org/wiki/Joaquín_Quiñones','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187081,'31232','Jornadas de Exaltación de la Verdura','fiesta','fiestas_wiki','Las Jornadas de Exaltación de la Verdura de Tudela y la Ribera, oficialmente denominada Jornadas de Exaltación y Fiestas de la Verdura,​ es una fiesta de interés turístico celebrada tradicionalmente en la localidad navarra de Tudela, que se ha extendido a otras localidades de la Ribera de Navarra.​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Jornadas_de_Exaltación_de_la_Verdura','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187082,'33031','Jornadas de su Excelencia La Fabada','fiesta','fiestas_wiki','Las Jornadas de su Excelencia La Fabada es una fiesta gastronómica declarada de Interés Turístico Regional, que se celebra cada mes de diciembre en La Felguera, concejo asturiano de Langreo (España).​ Están dedicadas al plato más conocido de la cocina asturiana, la Fabada.',NULL,NULL,'https://es.wikipedia.org/wiki/Jornadas_de_su_Excelencia_La_Fabada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187083,'45065','Jornadas escocesas','fiesta','fiestas_wiki','Es una Fiesta de Singularidad Turística Provincial que se celebra en Teba, Málaga, también llamadas Jornadas Escocesas o Douglas Days Teba. Con esta celebración, el municipio de Teba rememora las hazañas del escocés Sir James Douglas que, portando el corazón embalsamado del rey de Escocia, Robert de Bruce,…',NULL,NULL,'https://es.wikipedia.org/wiki/Jornadas_escocesas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187084,'26034','Jornadas medievales de Briones','fiesta','fiestas_wiki','Las jornadas medievales son una actividad que desde 1996 se realiza anualmente el sábado y domingo de la tercera semana de junio en la localidad de Briones en La Rioja (España). En ellas participa la gran mayoría de la población, ambientando el municipio en el siglo XIV para mostrar los diferentes oficios y…',NULL,NULL,'https://es.wikipedia.org/wiki/Jornadas_medievales_de_Briones','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187085,'41091','José Antonio Navarro Arteaga','fiesta','fiestas_wiki','José Antonio Navarro Arteaga (Barrio de Triana, Sevilla, 1965) es un escultor español especializado en imaginería religiosa. A los 15 años ingresó como aprendiz en el taller del escultor Juan Ventura, discípulo a su vez de Francisco Buiza, a partir de 1986 comenzó a trabajar de forma independiente en su propio taller.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Antonio_Navarro_Arteaga','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187086,'46250','José Capuz','fiesta','fiestas_wiki','José Capuz Mamano (en valenciano, Josep Capuz i Mamano; Valencia, 29 de agosto de 1884-Madrid, 9 de marzo de 1964) fue un escultor español.​​',NULL,NULL,'https://es.wikipedia.org/wiki/José_Capuz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187087,'18012','José Font Marimont','fiesta','fiestas_wiki','José Font Marimont (Puigcerdá, 1839-Sevilla, 1898​) fue un músico y compositor español nacido en Cataluña y afincado en Sevilla, ciudad donde desarrolló gran parte de su actividad artística. Había ingresado en el Ejército el 16 de noviembre de 1855, y asumió el cargo de músico mayor militar el 13 de febrero de 1875…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Font_Marimont','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187088,'18087','José Gabriel Martín Simón','fiesta','fiestas_wiki','José Gabriel Martín Simón (Granada, 1896 - 1971), escultor español. Simón como era conocido en los ambientes artísticos de la ciudad, se le puede considerar uno de los últimos representantes de la gran escuela imaginera granadina, que se prolonga durante cuatro siglos hasta la renovación plástica que tiene lugar…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Gabriel_Martín_Simón','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187089,'43065','José García Roldán','fiesta','fiestas_wiki','José García Roldán fue un escultor y tallista español del siglo XX, que realizó parte de su obra en Sevilla (Andalucía).',NULL,NULL,'https://es.wikipedia.org/wiki/José_García_Roldán','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187090,'04063','José María Martín Delgado','fiesta','fiestas_wiki','José María Martín Delgado (Málaga, Málaga, 26 de junio de 1947). Licenciado en Derecho por la Universidad de Granada en 1969 con la calificación de sobresaliente. Graduado Social por la Universidad de Granada en 1969.',NULL,NULL,'https://es.wikipedia.org/wiki/José_María_Martín_Delgado','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187091,'04063','José María Souvirón','fiesta','fiestas_wiki','José María Souvirón Huelín (Málaga, 26 de octubre de 1904-Málaga, 23 de agosto de 1973) fue un escritor, ensayista y crítico español.',NULL,NULL,'https://es.wikipedia.org/wiki/José_María_Souvirón','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187092,'43161','José María Valls Satorres','fiesta','fiestas_wiki','José María Valls Satorres (Alcoy, 1945) es un compositor valenciano de música de moros y cristianos.',NULL,NULL,'https://es.wikipedia.org/wiki/José_María_Valls_Satorres','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187093,'28079','José Moreno Carbonero','fiesta','fiestas_wiki','José Moreno Carbonero (Málaga, 28 de marzo de 1860-Madrid, 15 de abril de 1942) fue un pintor español, especializado en retratos y temas históricos. Se encuadra dentro de la Escuela malagueña de pintura.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Moreno_Carbonero','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187094,'13004','José Mota','fiesta','fiestas_wiki','José Sánchez Mota (Montiel, Ciudad Real, 30 de junio de 1965), conocido como José Mota, es un humorista, actor —también de doblaje—, imitador, director y guionista español. Se le conoce por haber sido miembro, junto con Juan Muñoz, del dúo humorístico Cruz y Raya entre 1989 y 2007. Desde 2007 ha desarrollado su…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Mota','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187095,'08141','José Navas-Parejo','fiesta','fiestas_wiki','José Navas Parejo (Álora, Málaga, 22 de octubre de 1883 - Granada, 10 de marzo de 1953) fue un escultor y orfebre español. A partir de 1939 pasaría a llamarse oficialmente José Navas-Parejo Pérez.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Navas-Parejo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187096,'41050','José Peña Herrera','fiesta','fiestas_wiki','José Peña Herrera (Cádiz, 27 de abril de 1921 - 8 de julio de 2002), más conocido como El Peña, fue una figura destacada en el mundo carnavalesco gaditano. Nació en la Posada del Arco de Garaicochea, en el corazón de un barrio gaditano de gran tradición carnavalera. Hijo de Eduardo Peña y Carmen Herrera y modelista…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Peña_Herrera','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187097,'02001','José Rodríguez Fernández-Andes','fiesta','fiestas_wiki','Manuel José Rodríguez Fernández-Andes (Sevilla, 29 de junio de 1908-Madrid, 20 de febrero de 1950) fue un imaginero sevillano cuya obra se centra principalmente en su ciudad natal y en la de Hellín (Albacete), aunque también destacan obras suyas en Madrid, donde residió la segunda etapa de su vida siendo hermano…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Rodríguez_Fernández-Andes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187098,'03902','José Sánchez Lozano','fiesta','fiestas_wiki','José Sánchez Lozano (1904-1995). Imaginero español, nacido en el Pilar de la Horadada (Alicante) que por aquel entonces pertenecía a Orihuela, España.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Sánchez_Lozano','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187099,'41095','José Utrera Molina','fiesta','fiestas_wiki','José Utrera Molina (Málaga, 12 de abril de 1926-Nerja, 22 de abril de 2017) fue un abogado y político español, que tuvo un papel destacado durante la dictadura de Franco. Procedente del movimiento juvenil falangista, fue gobernador civil de Ciudad Real, Burgos y Sevilla, y posteriormente desempeñaría los cargos de…',NULL,NULL,'https://es.wikipedia.org/wiki/José_Utrera_Molina','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187100,'28079','José Zahonero','fiesta','fiestas_wiki','José Zahonero de Robles y Díaz​ (Ávila, 1853-Madrid, 1931) fue un escritor y periodista español, uno de los representantes del naturalismo.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Zahonero','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187101,'20907','José de las Cuevas Velázquez-Gaztelu','fiesta','fiestas_wiki','José de las Cuevas Velázquez-Gaztelu (Madrid, 1918 - Arcos de la Frontera (Cádiz), 3 de octubre de 1992). Periodista y escritor español. Su obra (parte importante de la misma en colaboración con su hermano, Jesús de las Cuevas) está referida a Andalucía, y a la recuperación del léxico de la Andalucía rural.',NULL,NULL,'https://es.wikipedia.org/wiki/José_de_las_Cuevas_Velázquez-Gaztelu','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187102,'16089','Juan Abascal Fuentes','fiesta','fiestas_wiki','Juan Abascal Fuentes (Sevilla, 26 de julio de 1922-Sevilla, 4 de agosto de 2003)​ fue un profesor, escultor e imaginero español.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Abascal_Fuentes','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187103,'47186','Juan Agapito y Revilla','fiesta','fiestas_wiki','Juan Agapito y Revilla (Valladolid, 13 de diciembre de 1867- Valladolid, 7 de diciembre de 1944) fue un historiador y arquitecto español, conocido por su revisión de la historia de Valladolid y por su labor como arquitecto del Ayuntamiento de Valladolid. Fue además, director del Museo Provincial de Bellas Artes…',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Agapito_y_Revilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187104,'28079','Juan Cantó Francés','fiesta','fiestas_wiki','Juan Cantó Francés, también conocido como Joan Cantó Francés (Alcoy, 1856 – Madrid, 1903) fue un compositor y pedagogo musical. Se le considera autor de la primera pieza compuesta especialmente para la fiesta de Moros y Cristianos de Alcoy.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Cantó_Francés','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187105,'16009','Juan Carlos Aragón','fiesta','fiestas_wiki','Juan Carlos Aragón Becerra (Cádiz, 26 de mayo de 1967 - Cádiz, 17 de mayo de 2019​) fue un filósofo, profesor, poeta, escritor, trovador y músico gaditano, autor de más de 40 comparsas y chirigotas del Carnaval de Cádiz.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Carlos_Aragón','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187106,'41091','Juan Carrero Rodríguez','fiesta','fiestas_wiki','Juan Carrero Rodríguez (Sevilla, 16 de mayo de 1934-ibídem, 13 de junio de 2006), historiador y cofrade. Comienza a participar en el mundo cofradiero en el año 1953. Desde entonces recibe sus enseñanzas en los talleres dedicados a la artesanía propia de estas corporaciones, que le sirve para conocer sus entresijos…',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Carrero_Rodríguez','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187107,'30030','Juan González Moreno','fiesta','fiestas_wiki','Juan González Moreno (Aljucer, Murcia, 11 de abril de 1908 - Murcia, 10 de enero de 1996), fue un destacado escultor español del siglo XX.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_González_Moreno','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187108,'11033','Juan Luis Galiardo','fiesta','fiestas_wiki','Juan Luis Galiardo Comes (San Roque, Cádiz, 2 de marzo de 1940-Madrid, 22 de junio de 2012)​ fue un actor y productor español de cine, teatro y televisión.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Luis_Galiardo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187109,'46160','Juan Manuel Miñarro López','fiesta','fiestas_wiki','Juan Manuel Miñarro López (Sevilla, 29 de enero de 1954) es un escultor e imaginero español discípulo de Francisco Buiza.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Manuel_Miñarro_López','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187110,'46160','Juan Manuel Rodríguez Ojeda','fiesta','fiestas_wiki','Juan Manuel Rodríguez Ojeda (1853-1930) fue un bordador y diseñador español que contribuyó con sus obras e innovaciones al cambio estético que se produjo en las hermandades de la Semana Santa de Sevilla en los primeros años del siglo XX.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Manuel_Rodríguez_Ojeda','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187111,'41091','Juan Miguel Sánchez','fiesta','fiestas_wiki','Juan Miguel Sánchez Fernández (Puerto de Santa María, 1900-Sevilla, 1973) fue un pintor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Miguel_Sánchez','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187112,'31078','Juan Vargas Cortés','fiesta','fiestas_wiki','Juan Vargas, escultor español, de etnia gitana, nacido en Málaga el 24 de junio de 1900 y fallecido en Mijas (Málaga) el 21 de noviembre de 1980.',NULL,NULL,'https://es.wikipedia.org/wiki/Juan_Vargas_Cortés','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187113,'10086','Judiada de La Granja','fiesta','fiestas_wiki','La judiada de La Granja es una fiesta gastronómica celebrada en la provincia española de Segovia desde 1976 con motivo de las fiestas en honor a San Luis.',NULL,NULL,'https://es.wikipedia.org/wiki/Judiada_de_La_Granja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187114,'13027','Juego de las caras','fiesta','fiestas_wiki','El juego de Las Caras es un juego de azar y tradición que se celebra el Viernes Santo por la mañana en la localidad española de Calzada de Calatrava, la cual quintuplica su población durante este evento. Se utilizan dos monedas de cobre de la época de Alfonso XII. Es la única fiesta profana que se celebra en…',NULL,NULL,'https://es.wikipedia.org/wiki/Juego_de_las_caras','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187115,'37207','Juegos Moriscos de Abén Humeya','fiesta','fiestas_wiki','Los Juegos Moriscos de Abén Humeya son un evento histórico-deportivo celebrado anualmente en el municipio de Purchena (Almería, España) desde 1993. Se desarrollan durante el mes de julio y han sido declarados de "Interés Turístico Nacional de Andalucía". Los Juegos Moriscos constituyen una muestra del legado…',NULL,NULL,'https://es.wikipedia.org/wiki/Juegos_Moriscos_de_Abén_Humeya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187116,'40131','Julio Monterrubio Fernández','fiesta','fiestas_wiki','Julio Monterrubio Fernández (El Escorial, 4 de marzo de 1953) es un artista fallero jubilado. Yerno del golpista Antonio Tejero. Se inicia en el taller de Ramón Primo Ferri, en Alcira, completando su formación en la Ciudad del Artista Fallero de Valencia en los talleres de Josep Pascual Ibáñez y Josep Martínez Mollà.',NULL,NULL,'https://es.wikipedia.org/wiki/Julio_Monterrubio_Fernández','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187117,'16009','Julio Pardo Merelo','fiesta','fiestas_wiki','Julio Pardo Merelo (Cádiz, 31 de marzo de 1955, Ibidem, 11 de febrero de 2023),​ fue un autor de coros español, en el Carnaval de Cádiz (si bien ha colaborado en otras modalidades del Carnaval), así como compositor para varios cantantes del panorama musical español.',NULL,NULL,'https://es.wikipedia.org/wiki/Julio_Pardo_Merelo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187118,'06006','Julián Quintanilla','fiesta','fiestas_wiki','Julián Quintanilla (Badajoz, 1975), autor y director teatral, escritor, compositor, guionista y director de cine español.',NULL,NULL,'https://es.wikipedia.org/wiki/Julián_Quintanilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187119,'46102','Junta Central Fallera','fiesta','fiestas_wiki','La Junta Central Fallera es el organismo que regula y coordina la fiesta de las fallas en la ciudad de Valencia. De la entidad dependen las comisiones falleras de la capital valenciana, Burjasot, Mislata, Chirivella y Cuart de Poblet. La Junta Central Fallera fue creada en 1939,​ sustituyendo al Comité Central…',NULL,NULL,'https://es.wikipedia.org/wiki/Junta_Central_Fallera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187120,'47186','Junta Pro Semana Santa de España','fiesta','fiestas_wiki','La Junta Pro Semana Santa de España es una entidad fundada en noviembre de 1994 con sede en la ciudad de Valladolid​ que tiene entre sus objetivos la investigación, el conocimiento y la promoción de las diversas manifestaciones culturales y religiosas relacionadas con la Semana Santa en España.​ Su presidente es…',NULL,NULL,'https://es.wikipedia.org/wiki/Junta_Pro_Semana_Santa_de_España','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187121,'46250','Junta de hermandades y cofradías de Semana Santa de la Diócesis de Valencia','fiesta','fiestas_wiki','La Junta de hermandades y cofradías de Semana Santa de la Diócesis de Valencia,​ fundada el 28 de noviembre de 1976, con el fin de organizar actividades conjuntas e intercambiar experiencias por parte de las Cofradías de Semana Santa de la Diócesis de Valencia, organiza anualmente una asamblea, una exposición y una…',NULL,NULL,'https://es.wikipedia.org/wiki/Junta_de_hermandades_y_cofradías_de_Semana_Santa_de_la_Diócesis_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187122,'45168','Junta pro-Corpus de Toledo','fiesta','fiestas_wiki','La Junta pro-Corpus de Toledo es la institución que históricamente se encarga de organizar y adornar las calles del casco histórico de Toledo para la Procesión del Corpus Christi de Toledo. Para ello elabora o restaura los distintos elementos ornamentales que se colocan en las semanas anteriores por las distintas…',NULL,NULL,'https://es.wikipedia.org/wiki/Junta_pro-Corpus_de_Toledo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187123,'36011','La Arribada','fiesta','fiestas_wiki','La Arribada es una fiesta que se celebra en Bayona (provincia de Pontevedra, Galicia, España), con motivo de la llegada de Martín Alonso Pinzón a esa villa el 1 de marzo de 1493 tras el descubrimiento de América. La fecha de la fiesta varía cada año y se celebra el primer sábado o domingo de marzo. Si el día 1 de…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Arribada','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187124,'33044','La Balesquida','fiesta','fiestas_wiki','La fiesta de la Balesquida, también conocida como Martes de Campo o Martes del Bollo es una fiesta que se celebra en la capital del Principado de Asturias, Oviedo (España), a finales de mayo o principios de junio coincidiendo con el primer martes posterior a pentecostés, siendo día no laborable en la ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Balesquida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187125,'06022','La Carrerita (Villanueva de la Serena)','fiesta','fiestas_wiki','En Villanueva de la Serena (Badajoz), tradición datada en el siglo XVIII consistente en conmemorar la resurrección del Señor en la mañana del Domingo de Pascua. El nombre procede de la carrera que realizan los portadores del anda de la Virgen de la Aurora al encuentro de la imagen de Cristo Resucitado, para…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Carrerita_(Villanueva_de_la_Serena)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187126,'37300','La Castañá','fiesta','fiestas_wiki','La Castañá es una fiesta popular que se celebra en Calamonte, una población de Extremadura (España), muy cercana a Mérida, el primer sábado del mes de noviembre, después del Día de Todos Los Santos. Los grupos de amigos se reúnen en los corralones, que previamente han decorado, y celebran fiestas que duran toda la…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Castañá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187127,'47086','La Crucifixión (Medina de Rioseco)','fiesta','fiestas_wiki','La Crucifixión, también conocido como Lanzada de Longinos, El Longinos o La Lanzada, es una obra realizada por Andrés de Oliveros en 1673 y modificada por Francisco Díez de Tudanca en 1675 y por Tomás de Sierra en 1696. Portado el Viernes Santo por la Hermandad de la Crucifixión del Señor, el grupo escultórico está…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Crucifixión_(Medina_de_Rioseco)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187128,'37273','La Elevación de la Cruz (Francisco del Rincón)','fiesta','fiestas_wiki','La Elevación de la Cruz es una obra realizada por Francisco del Rincón entre 1604 y 1606. Portado el Viernes Santo en la Procesión General de la Sagrada Pasión del Redentor por la Cofradía de la Exaltación de la Santa Cruz y Nuestra Señora de los Dolores, el grupo escultórico está ubicado en el Museo Nacional de…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Elevación_de_la_Cruz_(Francisco_del_Rincón)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187129,'06091','La Encamisá de Navalvillar de Pela','fiesta','fiestas_wiki','La Encamisá o Carrera de San Antón es una fiesta popular que se celebra en la localidad extremeña de Navalvillar de Pela (Badajoz) España. La fiesta tiene la consideración de Fiesta de Interés Turístico de Extremadura y se celebra cada 16 de enero, en víspera de San Antón, patrón de la localidad.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Encamisá_de_Navalvillar_de_Pela','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187130,'10189','La Encamisá de Torrejoncillo','fiesta','fiestas_wiki','La Encamisá es una fiesta de Extremadura que se celebra la noche de cada 7 de diciembre en el municipio español de Torrejoncillo (Cáceres).​',NULL,NULL,'https://es.wikipedia.org/wiki/La_Encamisá_de_Torrejoncillo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187131,'90314','La Endiablada','fiesta','fiestas_wiki','La Endiablada es el nombre dado a una manifestación festiva de tradición inmemorial celebrada en Almonacid del Marquesado, provincia de Cuenca, durante los días 1, 2 y 3 de febrero en honor a la Virgen Candelaria y San Blas. Durante estos tres días, aproximadamente 130 "diablos", ataviados con trajes de llamativos…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Endiablada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187132,'03040','La Entrada','fiesta','fiestas_wiki','La Entrada es un pasodoble compuesto por Quintín Esquembre y dedicado a las fiestas de moros y cristianos de su Villena natal, estrenado el 5 de septiembre de 1925 en Villena.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Entrada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187133,'47186','La Entrada Triunfal de Jesús en Jerusalén (Valladolid)','fiesta','fiestas_wiki','La Entrada Triunfal de Jesús en Jerusalén, también conocido como La Borriquilla, es una obra realizada aproximadamente en el periodo 1542-1550 y atribuida a Francisco Giralte, siendo modificada probablemente por Francisco del Rincón hacia 1600. Procesionado el Domingo de Ramos por la Cofradía Penitencial de la…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Entrada_Triunfal_de_Jesús_en_Jerusalén_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187134,'34120','La Erección de la Cruz (Palencia)','fiesta','fiestas_wiki','La Erección de la Cruz, también conocido como El Levantamiento de Cristo en la Cruz, es una obra realizada por Lucas Sanz de Torrecilla entre 1614 y 1615. Portado el Viernes Santo por la Cofradía de Nuestro Padre Jesús Nazareno y Nuestra Madre la Virgen de la Amargura, el grupo escultórico está ubicado en una…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Erección_de_la_Cruz_(Palencia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187135,'46072','La Mahoma','fiesta','fiestas_wiki','La Mahoma es un muñeco, con figura humana caracterizada a estilo musulmán, que representa al Bando Moro en las Fiestas de Moros y Cristianos de ciertas localidades de Alicante y Valencia como Benejama, Biar, Bocairente, Castalla, Bañeres y Villena. El uso del término en femenino se debe a que la Mahoma no…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Mahoma','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187136,'30016','La Mar de Músicas','fiesta','fiestas_wiki','La Mar de Músicas es un festival de música de carácter anual, celebrado en el mes de julio en la ciudad española de Cartagena desde 1995 y organizado por el Ayuntamiento de Cartagena a través de su Concejalía de Cultura junto a diversos patrocinadores. Dedicado eminente, aunque no exclusivamente, a la World Music o…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Mar_de_Músicas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187137,'02001','La Mulilla','fiesta','fiestas_wiki','La Mulilla es una conjunto escultórico situado en la ciudad española de Albacete.​​​ Representa dos caballos trotando a tamaño natural que simbolizan la gran vinculación de la Feria de Albacete con el mundo equino desde sus orígenes. Se encuentra elevada sobre un pedestal que constituye su base. Fue inaugurada en…',38.998522,-1.870876,'https://es.wikipedia.org/wiki/La_Mulilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187138,'41091','La Navidad en sus manos','fiesta','fiestas_wiki','La Navidad en sus manos es una película española​ de Comedia y Navidad dirigida por Joaquín Mazón y protagonizada por Ernesto Sevilla, Santiago Segura, Unax Hayden, Meri Anglés, Pablo Chiapella, María Botto y Emilio Gavira.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Navidad_en_sus_manos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187139,'16078','La Pamplonesa','fiesta','fiestas_wiki','La Pamplonesa es una de las bandas más antiguas de Pamplona con 100 años de historia y se encarga de poner música a diversos actos a lo largo del año, en especial en los Sanfermines los cuales le dan mucha de la fama que ostentan en la cuenca, además dan diversos conciertos a lo largo del año.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Pamplonesa','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187140,'08147','La Pasión de Olesa de Montserrat','fiesta','fiestas_wiki','La Pasión de Olesa de Montserrat es una representación teatral de gran formato que narra la Pasión y muerte de Jesús y que se representa anualmente en la localidad de Olesa de Montserrat los meses de marzo y abril. Sus orígenes se remontan a 1538, que es el año de la referencia documental más antigua encontrada…',41.542598,1.894763,'https://es.wikipedia.org/wiki/La_Pasión_de_Olesa_de_Montserrat','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187141,'47186','La Quinta Angustia (Gregorio Fernández)','fiesta','fiestas_wiki','La Quinta Angustia, también conocida como Nuestra Señora de la Piedad o la Piedad, es una obra realizada por Gregorio Fernández hacia 1625. Está ubicada en la Iglesia de San Martín de Valladolid (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/La_Quinta_Angustia_(Gregorio_Fernández)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187142,'49275','La Redención','fiesta','fiestas_wiki','Redención es un paso procesional tallado por Mariano Benlliure para la Cofradía de Jesús Nazareno de Zamora.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Redención','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187143,'29084','La Ronda (León)','fiesta','fiestas_wiki','La Ronda es un acto que se desarrolla en la ciudad de León durante la Semana Santa, en la madrugada del Viernes Santo. Es un acto singular y único, reflejo de la gran tradición que envuelve la Semana Santa leonesa. Está organizada por la Cofradía del Dulce Nombre de Jesús Nazareno.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Ronda_(León)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187144,'29056','La Toma de Gaucín','fiesta','fiestas_wiki','La Toma de Gaucín es una fiesta celebrada anualmente en Gaucín, en la que se recrea la toma del pueblo por las tropas francesas napoleónicas en 1810. La fiesta consiste en la representación de varios episodios de la Guerra de la Independencia Española y conmemora el levantamiento de la Serranía de Ronda contra el…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Toma_de_Gaucín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187145,'44216','La Vaquilla del Ángel','fiesta','fiestas_wiki','La Vaquilla del Ángel​ es la fiesta de mayor arraigo en la ciudad de Teruel. Dedicadas al santo Ángel Custodio, patrono de la ciudad, rememoran la legendaria fundación de Teruel por parte de unos caballeros aragoneses tras tomar la fortaleza musulmana a la que les condujo un toro bravo. El festejo más arcaico es el…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Vaquilla_del_Ángel','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187146,'06009','La Velá de Don Benito','fiesta','fiestas_wiki','La Velá de Don Benito es una celebración festiva de carácter religioso y popular que tiene lugar en Don Benito (provincia de Badajoz, España) en honor a la patrona de la ciudad, Nuestra Señora la Virgen de las Cruces.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Velá_de_Don_Benito','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187147,'39046','La Vijanera','fiesta','fiestas_wiki','La Vijanera (a veces también llamada Viejanera, Vejanera, Bejanera o Vejenera) es una mascarada de invierno que se desarrolla en la localidad española de Silió que pertenece al municipio de Molledo y se sitúa en la parte sureste del Valle de Iguña, en Cantabria. La tradición se celebra siempre el primer domingo de…',NULL,NULL,'https://es.wikipedia.org/wiki/La_Vijanera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187148,'05122','La bicicleta (tango)','fiesta','fiestas_wiki','La bicicleta es un tango del coro de 1897 «Los Abanicos», cuyo autor del mismo es Antonio Rodríguez Martínez, conocido como el «Tío de la Tiza». Como se ve en la letra del tango, el tango habla de un tema novedoso para la época que es la aparición de las bicicletas por la ciudad; de igual manera, la parte final del…',NULL,NULL,'https://es.wikipedia.org/wiki/La_bicicleta_(tango)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187149,'31078','La morisma','fiesta','fiestas_wiki','La Morisma es una obra de teatro de origen popular que tradicionalmente se ha representado en Aínsa el día de la Exaltación de la Santa Cruz. Su origen se halla en el dance aragonés. En el siglo XVII las Cortes primero y la Corona después, subvencionaron este teatro público.',NULL,NULL,'https://es.wikipedia.org/wiki/La_morisma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187150,'03027','La pesá','fiesta','fiestas_wiki','La pesá es una tradición de la comarca española del Vega Baja del Segura. En su capital, Orihuela, es típica del día de San Antonio,​ mientras que a Catral es típica del día de Santa Águeda.​ Parecida a la mocadorada, que incluye diferentes tipos de dulces, como las Bolas de San Antón, bolas de caramelo artesanal​…',NULL,NULL,'https://es.wikipedia.org/wiki/La_pesá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187151,'36011','Laconada','fiesta','fiestas_wiki','La laconada es una costumbre social culinaria en torno a la preparación del lacón con grelos (denominada también como laconada con grelos).​ Propia de las poblaciones rurales de Galicia y de los lugares donde existan inmigrantes gallegos. Se muestra más en el interior de la comunidad, en especial en la provincia de…',NULL,NULL,'https://es.wikipedia.org/wiki/Laconada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187152,'24115','Lambrión chupacandiles','fiesta','fiestas_wiki','El Lambrión o Llambrión chupacandiles es un nazareno que en la ciudad de Ponferrada, provincia de León, España anuncia la próxima celebración de la Semana Santa.',NULL,NULL,'https://es.wikipedia.org/wiki/Lambrión_chupacandiles','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187153,'17006','Lanzamiento de cabra','fiesta','fiestas_wiki','El lanzamiento de cabra (poéticamente llamado «el salto de la cabra»​) fue un acto tradicional llevado a cabo en el municipio español de Manganeses de la Polvorosa (provincia de Zamora), celebrado el cuarto domingo de enero, en el que un grupo de jóvenes (quintos) arrojaban a una cabra viva desde lo alto del…',NULL,NULL,'https://es.wikipedia.org/wiki/Lanzamiento_de_cabra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187154,'20070','Las Bodas de Isabel de Segura','fiesta','fiestas_wiki','Las Bodas de Isabel de Segura es una fiesta anual de interés turístico nacional que se celebra en febrero en la ciudad española de Teruel.',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Bodas_de_Isabel_de_Segura','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187155,'38020','Las Burras de Güímar','fiesta','fiestas_wiki','Las Burras de Güímar es una representación teatral que se desarrolla en el marco del carnaval de esta localidad tinerfeña el día del entierro de la sardina, es decir, el viernes que sigue al martes de Carnaval.​',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Burras_de_Güímar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187156,'26010','Las Cabezadas','fiesta','fiestas_wiki','Las Cabezadas es el nombre de una ceremonia civil y religiosa que se celebra en la ciudad de León (España) el domingo más próximo a la festividad de San Isidoro, cuya fecha es el 26 de abril. El nombre proviene de las reverencias —tres por cada parte— realizadas con una inclinación exagerada. Estas reverencias son…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Cabezadas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187157,'14065','Las Cantaderas','fiesta','fiestas_wiki','La fiesta de las Cantaderas​ o ceremonial del Foro u Oferta es el nombre que recibe una ceremonia civil y religiosa que se celebra en la ciudad de León (España) el domingo anterior a la festividad de San Froilán, que se celebra el día 5 de octubre. Según la tradición popular, esta fiesta conmemora la victoria…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Cantaderas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187158,'20069','Las Carantoñas','fiesta','fiestas_wiki','Las Carantoñas es una fiesta declarada de Interés Turístico Nacional que se celebra los días 20 y 21 de enero en la localidad española de Acehúche, en honor a su patrón, San Sebastián.',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Carantoñas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187159,'41075','Las Carreritas (Pilas)','fiesta','fiestas_wiki','"Las Carreritas", fiesta conmemorativa de la Resurrección de Jesús, tiene lugar el Domingo de Resurrección en la localidad de Pilas (Sevilla). Representa un encuentro entre la Virgen de Belén y Jesús Resucitado, que tiene lugar en la Plaza Mayor del pueblo. Son representados mediante dos pasos, que corren (de ahí…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Carreritas_(Pilas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187160,'28079','Las Mayas','fiesta','fiestas_wiki','Las Mayas es una festividad que se celebra uno de los primeros domingos del mes de mayo principalmente en el barrio de Lavapiés (Madrid), en la plaza de su nombre y en las calles aledañas del Barrio y de Salitre, en torno a la iglesia de San Lorenzo.​ Este día, y por la mañana, casa del barrio adorna y engalana a…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Mayas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187161,'45165','Las Mondas','fiesta','fiestas_wiki','Las Mondas son las fiestas que se celebran en el municipio Castellano-manchego de Talavera de la Reina (Toledo) España, el sábado posterior a la Semana Santa. La celebración simboliza el culto a Nuestra Señora del Prado y el engalanamiento de calles y plazas con la bandera azul y blanca de Talavera y que simboliza…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Mondas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187162,'10125','Las Purificás de Monroy','fiesta','fiestas_wiki','La fiesta de Las Purificás de Monroy es una ceremonia folclórica que se celebra anualmente el 2 de febrero en la iglesia de Santa Catalina de la villa española de Monroy, en la provincia de Cáceres. Está considerada una de las celebraciones tradicionales de la fiesta de las Candelas mejor conservadas de…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_Purificás_de_Monroy');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187163,'16078','Las turbas','fiesta','fiestas_wiki','Las Turbas es una parte esencial de la procesión Camino del Calvario, la cual se celebra la madrugada del Viernes Santo en la ciudad española de Cuenca. Forma parte de la Semana Santa de esa ciudad, que está declarada de interés turístico internacional, y es su procesión más conocida. El desfile conmemoró en 2016…',NULL,NULL,'https://es.wikipedia.org/wiki/Las_turbas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187164,'29067','Leonardo Fernández González','fiesta','fiestas_wiki','Leonardo Fernández González (Málaga, 1944) es un pintor realista español conocido, entre otras obras, por su pintura religiosa.',NULL,NULL,'https://es.wikipedia.org/wiki/Leonardo_Fernández_González','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187165,'33066','Les Carroces de Valdesoto','fiesta','fiestas_wiki','La fiesta de Les Carroces de Valdesoto se celebra en el pueblo de Valdesoto, en el concejo de Siero en Asturias desde 1950 siempre el lunes siguiente al segundo domingo de agosto, poniendo broche final a las fiestas de San Félix y verbenas que comienzan el viernes anterior al día de las carrozas. Esta celebridad ha…',NULL,NULL,'https://es.wikipedia.org/wiki/Les_Carroces_de_Valdesoto','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187166,'08003','Les Santes','fiesta','fiestas_wiki','Les Santes es la fiesta mayor de la ciudad de Mataró (Barcelona), España. Que se celebra del 24 al 29 de julio en honor de Santa Juliana y Santa Semproniana. Los últimos años ya hay actividades unos días antes, Les Santes Esportivas desde el 11 de julio o las Dissantes, organizadas con la colaboración de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Les_Santes','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187167,'28079','Licinio de la Fuente','fiesta','fiestas_wiki','Licinio de la Fuente y de la Fuente (Noez, 7 de agosto de 1923 - Madrid, 26 de febrero de 2015) fue un político, abogado del Estado, y empresario español. Ejerció de ministro de Trabajo durante la dictadura franquista.',NULL,NULL,'https://es.wikipedia.org/wiki/Licinio_de_la_Fuente','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187168,'26010','Limonada de vino','fiesta','fiestas_wiki','La limonada, limonada de vino, limoná o limonada de Semana Santa es una bebida tradicional española elaborada a partir de vino, limones, azúcar y canela (a veces, fruta, pasas o higos).​​ Se sirve en Semana Santa, aunque en ocasiones se bebe en cualquier acontecimiento festivo sin necesidad de ser un evento…',NULL,NULL,'https://es.wikipedia.org/wiki/Limonada_de_vino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187169,'26010','Loles León','fiesta','fiestas_wiki','María Dolores León Rodríguez, más conocida como Loles León (Barcelona, 1 de agosto de 1950), es una actriz española de cine, televisión, teatro y radio. Famosa por ser una de las chicas Almodóvar y por sus papeles en televisión, principalmente el de Paloma Hurtado en la serie de televisión Aquí no hay quien viva y…',NULL,NULL,'https://es.wikipedia.org/wiki/Loles_León','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187170,'34120','Longinos (Palencia)','fiesta','fiestas_wiki','Longinos, también conocido como La Lanzada, es una obra realizada por José de Rozas y Antonio Vázquez entre 1691 y 1692.',NULL,NULL,'https://es.wikipedia.org/wiki/Longinos_(Palencia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187171,'16009','Los Beatles de Cádiz','fiesta','fiestas_wiki','Los Beatles de Cádiz fue un grupo musical que se formó a raíz de la comparsa gaditana de Enrique Villegas, Los escarabajos trillizos. Participaron en el carnaval de Cádiz en 1965, obteniendo el segundo premio en la modalidad de comparsas en el COAC. En esos carnavales quisieron representar a la famosa banda…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Beatles_de_Cádiz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187172,'39032','Los Campanos','fiesta','fiestas_wiki','La "Fiesta de Los Campanos" en Abiada, municipio de la Hermandad de Campoo de Suso, en Cantabria. Se celebra cada año, desde 1840, el primer domingo de septiembre. Es una fiesta con gran sabor rústico y una de las más tradicionales y arraigadas de Cantabria, y concretamente de la comarca de Campoo.',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Campanos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187173,'46160','Los Chunguitos','fiesta','fiestas_wiki','Los Chunguitos es un grupo español de rumba, integrado en sus inicios por los hermanos Salazar: Enrique (9 de septiembre de 1956 - 24 de junio de 1982), Juan (20 de agosto de 1954) y José (12 de septiembre de 1958). Tras el fallecimiento en 1982 de Enrique, compositor y vocalista, entró a formar parte del grupo…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Chunguitos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187174,'30016','Los Coloraos','fiesta','fiestas_wiki','La Real, Muy Ilustre, Venerable y Antiquísima Archicofradía de la Preciosísima Sangre de Nuestro Señor Jesucristo, conocida popularmente como Los Coloraos, es la cofradía penitencial más antigua de la ciudad de Murcia (España) y de toda la diócesis de Cartagena, datándose su fundación en 1411. Su actividad más…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Coloraos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187175,'10105','Los Escobazos','fiesta','fiestas_wiki','Los escobazos es una Fiesta de Interés Turístico Nacional​ que se desarrolla anualmente al caer la noche del 7 de diciembre hasta la madrugada del 8 de diciembre, día de la festividad de la Inmaculada Concepción, en el municipio de Jarandilla de la Vera (Cáceres), España.',40.12612475,-5.66036811,'https://es.wikipedia.org/wiki/Los_Escobazos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187176,'33035','Los Exconxuraos','fiesta','fiestas_wiki','Los Esconxuraos (Los Excomulgados en asturiano) es una fiesta de Interés Turístico Regional que se celebra el primer fin de semana de julio en el concejo asturiano de Llanera.',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Exconxuraos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187177,'38009','Los Indianos','fiesta','fiestas_wiki','Los Indianos es una fiesta tradicional de la isla de La Palma que se realiza todos los años como homenaje a Cuba y como una parodia a los canarios regresados de Latinoamérica,​ y que a su regreso hacían alarde y ostentación de la riqueza obtenida en aquellas tierras, ambientado en los siglos XIX y XX.​​ Uno de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Indianos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187178,'02001','Los Invasores (Albacete)','fiesta','fiestas_wiki','Los Invasores es un mercado al aire libre que se monta todos los martes del año en la ciudad española de Albacete. Ubicado en el histórico entorno de los Ejidos de la Feria y parte del Recinto Ferial, es el mercado más grande de Castilla-La Mancha y uno de los más grandes de España. En su más de medio siglo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Invasores_(Albacete)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187179,'02001','Los Mayos (Albacete)','fiesta','fiestas_wiki','Los Mayos es una fiesta popular que se celebra anualmente en la ciudad española de Albacete. Es una de las tradiciones populares de la capital.',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Mayos_(Albacete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187180,'10127','Los Negritos de San Blas','fiesta','fiestas_wiki','La fiesta de Los Negritos de San Blas es una fiesta que se celebra en la localidad extremeña de Montehermoso (Cáceres) los días 2 y 3 de febrero en honor a San Blas.',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Negritos_de_San_Blas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187181,'04065','Los Pastorcillos','fiesta','fiestas_wiki','Els Pastorets es una representación teatral típica de las fiestas de Navidad en muchos lugares de Cataluña. El argumento combina los contenidos del nacimiento de Jesús, la lucha del bien contra el mal entre ángeles y demonios, y diversas historias y diálogos de los pastores que rememoran la primera Navidad. A…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Pastorcillos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187182,'12055','Los Peregrinos de Useras','fiesta','fiestas_wiki','Los Peregrinos de Useras (Els Pelegrins de les Useres en valenciano) es una fiesta de carácter religioso que se celebra anualmente en la localidad española de Useras, Castellón, el último viernes de abril. Se trata de una peregrinación de 28 kilómetros con un desnivel de 1000 metros que se inicia a las 7 de la…',40.211895,-0.254848,'https://es.wikipedia.org/wiki/Los_Peregrinos_de_Useras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187183,'26142','Los Picaos de San Vicente de la Sonsierra','fiesta','fiestas_wiki','Los Picaos son una penitencia de la religión cristiana, profesada en la actualidad únicamente en la localidad de San Vicente de la Sonsierra, en La Rioja (España). Se realiza durante procesiones y Viacrucis. Consiste en la autoflagelación de la espalda, de un grupo de personas como acto de fe y de forma voluntaria,…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_Picaos_de_San_Vicente_de_la_Sonsierra','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187184,'18122','Los incensarios de Loja','fiesta','fiestas_wiki','Los incensarios de Loja son grupos de portadores de incensarios que realizan rituales religiosos durante la Semana Santa de Loja, en la provincia de Granada (España). Los Incensiarios son grupos de ocho hombres que danzan y cantan, de forma independiente a la procesión, durante el Martes, Miércoles, Jueves y…',NULL,NULL,'https://es.wikipedia.org/wiki/Los_incensarios_de_Loja','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187185,'11027','Luis Galán','fiesta','fiestas_wiki','Luis Galán Pérez (nacido el 7 de noviembre de 1962 en El Puerto de Santa María (Provincia de Cádiz), España) es un reconocido autor del Carnaval de Cádiz además de articulista. En la década de los 80 se convirtió en baluarte de las letras del Carnaval Portuense, destacando por sus letras comprometidas, incisivas y…',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Galán','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187186,'46160','Luis Manuel Rivero Ramos','fiesta','fiestas_wiki','Luis Manuel Rivero Ramos (Tarragona, 1979) es una persona destacada en el carnaval de Cádiz.​',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Manuel_Rivero_Ramos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187187,'29901','Luis Merino Bayona','fiesta','fiestas_wiki','Luis Francisco Merino Bayona (Málaga, 17 de diciembre de 1938) es un abogado y político español. Se inició en política en el Movimiento de la época franquista. Fue elegido consejero local del Movimiento por Málaga en 1971 y posteriormente teniente de alcalde de Torremolinos hasta 1977.[cita requerida] Fue alcalde…',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Merino_Bayona','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187188,'11033','Luis Ortega Bru','fiesta','fiestas_wiki','Luis Ortega Bru (San Roque, Cádiz, 16 de septiembre de 1916-Sevilla, 21 de noviembre de 1982) fue un imaginero y escultor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Ortega_Bru','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187189,'41091','Luis Álvarez Duarte','fiesta','fiestas_wiki','Luis Álvarez Duarte (Sevilla, 22 de mayo de 1950-Sevilla, 13 de septiembre de 2019)​​ fue un escultor, imaginero y restaurador español.',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Álvarez_Duarte','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187190,'11024','Lunes de Quasimodo','fiesta','fiestas_wiki','El Lunes de Quasimodo es una romería que se celebra el segundo lunes después del Domingo de Resurrección en la localidad gaditana de Olvera; en la cual los olvereños se reúnen en los alrededores de la ermita de Nuestra Señora de los Remedios, para dar gracias por las lluvias que pusieron fin a una prolongada y…',NULL,NULL,'https://es.wikipedia.org/wiki/Lunes_de_Quasimodo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187191,'05182','Machurreros de Pedro Bernardo','fiesta','fiestas_wiki','Los machurreros son unos enigmáticos personajes enmascarados, protagonistas de la mascarada invernal de la localidad de Pedro Bernardo, en la provincia de Ávila.',NULL,NULL,'https://es.wikipedia.org/wiki/Machurreros_de_Pedro_Bernardo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187192,'37011','Magosto','fiesta','fiestas_wiki','El magosto, magüesto,​ magosta, magostu, magüestu, amagüestu o castanyada es una fiesta tradicional en algunas regiones del noroeste de España, como Galicia,​ Cantabria, Asturias, León,​norte de Palencia,​ Zamora,​​ Salamanca,​​ Cataluña y Cáceres (Las Hurdes, Carbajo),​ así como Canarias (Los Finaos).​ Se trata de…',NULL,NULL,'https://es.wikipedia.org/wiki/Magosto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187193,'90024','Manaies','fiesta','fiestas_wiki','Los "armats", "manaies" (en Gerona) o "manages" (en Verges) son los soldados romanos que, tradicionalmente desfilan por Semana Santa en algunos pueblos y ciudades de Cataluña. En algunos lugares, como Badalona o Besalú, también se denominan estaferms.',NULL,NULL,'https://es.wikipedia.org/wiki/Manaies');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187194,'46077','Mano a Mano de Buñol','fiesta','fiestas_wiki','El Mano a Mano de Buñol es un concierto y tradición musical que se celebra anualmente durante el mes de agosto en Buñol, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Mano_a_Mano_de_Buñol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187195,'32002','Mantecado','fiesta','fiestas_wiki','En Cuba, España, Filipinas, México, Republica Dominicana y Venezuela se conoce por mantecado un sabor de helado El mantecado es un dulce típico de la repostería española, caracterizado por ser amasado con manteca de cerdo y consumido en cualquier época del año, especialmente en Navidad. Su origen es andaluz, unos…',NULL,NULL,'https://es.wikipedia.org/wiki/Mantecado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187196,'06003','Manuel Alcántara (escritor)','fiesta','fiestas_wiki','Manuel Porras Alcántara​ (Málaga, 10 de enero de 1928-Málaga, 17 de abril de 2019)​ fue un periodista y poeta español. Publicó al menos un artículo diario en diversos periódicos nacionales durante más de sesenta años sin interrupción,​ convirtiéndose en el columnista de mayor longevidad y audiencia de España.​…',NULL,NULL,'https://es.wikipedia.org/wiki/Manuel_Alcántara_(escritor)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187197,'46160','Manuel Font Fernández de la Herranz','fiesta','fiestas_wiki','Manuel Font Fernández de la Herranz (Málaga, 22 de diciembre de 1862-Sevilla, 5 de marzo de 1943) fue un músico y compositor español perteneciente a la dinastía de los Font, hijo de José Font Marimont y padre de Manuel Font de Anta y José Font de Anta. Aunque malagueño de nacimiento, desarrolló gran parte de su…',NULL,NULL,'https://es.wikipedia.org/wiki/Manuel_Font_Fernández_de_la_Herranz','IT Internacional');
