INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187203,'39075','Manuel Santander Cahué','fiesta','fiestas_wiki','Manuel Santander Cahué, más conocido como Manolo Santander (Cádiz, 21 de noviembre de 1962​-ib., 3 de septiembre de 2019),​ fue un chirigotero español del Carnaval de Cádiz, reconocido como uno de los grandes estandartes de la chirigota clásica viñera, y creador del himno oficioso del Cádiz Club de Fútbol.​',NULL,NULL,'https://es.wikipedia.org/wiki/Manuel_Santander_Cahué','IT Internacional');
