INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187205,'19130','Maratón de los Cuentos','fiesta','fiestas_wiki','El Maratón de los Cuentos es un festival de narración oral que se realiza cada año en el palacio del Infantado de Guadalajara (España) durante el segundo o tercer fin de semana de junio. Reúne a contadores de cuentos o cuentacuentos de todo el mundo que narran de forma ininterrumpida durante el fin de semana.…',NULL,NULL,'https://es.wikipedia.org/wiki/Maratón_de_los_Cuentos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187206,'16106','Mari Carmen y sus muñecos','fiesta','fiestas_wiki','María del Carmen Martínez-Villaseñor Barrasa (Horcajo de Santiago, Cuenca, 4 de mayo de 1943 - Puerto de la Cruz, Tenerife, 15 de junio de 2023)​ fue una ventrílocua y humorista española, conocida por su número artístico como Mari Carmen y sus muñecos.​',NULL,NULL,'https://es.wikipedia.org/wiki/Mari_Carmen_y_sus_muñecos','IT Internacional');
