INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187221,'03064','María Santísima de los Dolores de Triana','fiesta','fiestas_wiki','María Santísima de los Dolores de Triana es una imagen de la Virgen María, que se venera en la ermita de san Telmo, también parroquia de San Bernando, del barrio de Triana de Las Palmas de Gran Canaria, Diócesis de Canarias.',NULL,NULL,'https://es.wikipedia.org/wiki/María_Santísima_de_los_Dolores_de_Triana');
