INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187225,'26010','Mascaradas en Castilla y León','fiesta','fiestas_wiki','Mascaradas en Castilla y León es la denominación dada por la Junta de Castilla y León para la agrupación de algunas mascaradas existentes en Castilla y León que se pretenden declarar, de forma conjunta, Bien de Interés Cultural de carácter inmaterial por considerarlas manifestaciones culturales de notable valor…',NULL,NULL,'https://es.wikipedia.org/wiki/Mascaradas_en_Castilla_y_León');
