INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187227,'46079','Mascletá','fiesta','fiestas_wiki','Una mascletá​ (del valenciano mascletà) es un disparo pirotécnico que conforma una composición muy ruidosa y rítmica que se dispara con motivos festivos en plazas y calles, normalmente durante el día; es típica de la región española de la Comunidad Valenciana. Recibe su denominación de los masclets (petardos de una…',NULL,NULL,'https://es.wikipedia.org/wiki/Mascletá');
