INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187229,'26010','Matar judíos','fiesta','fiestas_wiki','Se denomina «matar judíos» a una tradición que se celebra en la provincia de León (España) consistente en beber limonada de vino durante Semana Santa.​',NULL,NULL,'https://es.wikipedia.org/wiki/Matar_judíos','IT Internacional');
