INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187231,'45168','Mazapán','fiesta','fiestas_wiki','El mazapán es un dulce cuyos ingredientes principales son almendras, azúcar y huevo, en distinta proporción dependiendo de la receta.​ En España es un postre tradicional navideño, aunque en Toledo, lugar en el que la primera referencia escrita de este producto se remonta al año 1512, se consume todo el año.​ Hay…',NULL,NULL,'https://es.wikipedia.org/wiki/Mazapán');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187232,'46212','Mensaje de Navidad de Su Majestad el Rey','fiesta','fiestas_wiki','El Mensaje de Navidad de Su Majestad el Rey, comúnmente conocido como discurso de Navidad, es un mensaje televisivo realizado por el monarca de España y emitido en diferido ante todo el país por los medios de comunicación, a las 21:00 horas en la Nochebuena, víspera del día de Navidad. La Casa Real propone…',NULL,NULL,'https://es.wikipedia.org/wiki/Mensaje_de_Navidad_de_Su_Majestad_el_Rey');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187233,'04043','Mensajeros de paz','fiesta','fiestas_wiki','Mensajeros de paz es una película cómica española estrenada el 9 de diciembre de 1957, dirigida por José María Elorrieta y protagonizada por Rafael Luis Calvo, Félix Dafauce y Antonio Almorós.​',NULL,NULL,'https://es.wikipedia.org/wiki/Mensajeros_de_paz');
