INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187235,'10195','Merche','fiesta','fiestas_wiki','Mercedes Trujillo Callealta (Cádiz, 14 de junio de 1974), más conocida como Merche, es una cantautora, productora y presentadora española. La artista gaditana es autora de la totalidad de los temas incluidos en sus álbumes. Merche era popular mucho antes de que comenzase a aparecer en televisión, aunque fue este…',NULL,NULL,'https://es.wikipedia.org/wiki/Merche','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187236,'36015','Merdeiro','fiesta','fiestas_wiki','El merdeiro es un personaje del entroido de Vigo de carácter popular que desapareció durante la década de 1920 debido a ordenanzas municipales que atacaban su figura así como otras costumbres transgresoras de la fiesta.​ Después de ocho décadas en el olvido, la figura del merdeiro volvió a resurgir a comienzos del…',NULL,NULL,'https://es.wikipedia.org/wiki/Merdeiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187237,'49275','Merlú','fiesta','fiestas_wiki','En la Semana Santa de Zamora (España), el Merlú es el nombre que reciben aquellas parejas de congregantes de la Cofradía de Jesús Nazareno cuya labor consiste en reunir a los demás hermanos para comenzar el desfile procesional.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Merlú','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187238,'41041','Micaela Ruiz Téllez','fiesta','fiestas_wiki','Filomena Micaela Ruiz Téllez (Estepa, España; 1821-1904), apodada La Colchona, fue una mujer pionera que dio inicio a la comercialización de los mantecados de Estepa, que hasta entonces eran un dulce navideño de elaboración casera para consumo en el hogar.',NULL,NULL,'https://es.wikipedia.org/wiki/Micaela_Ruiz_Téllez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187239,'28079','Miguel Bosé','fiesta','fiestas_wiki','Luis Miguel González Bosé​ (Ciudad de Panamá, 3 de abril de 1956), conocido como Miguel Bosé o Miguel Dominguín Bosé, es un cantante, compositor, músico y actor.​ Nacido en la Ciudad de Panamá y criado entre Madrid (España) y Bogotá (Colombia), comenzó su carrera artística en 1973 como actor, participando durante…',NULL,NULL,'https://es.wikipedia.org/wiki/Miguel_Bosé','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187240,'07005','Miguel Durán Campos','fiesta','fiestas_wiki','Miguel Durán Campos (Azuaga, Badajoz, 2 de julio de 1955) es un abogado y empresario español.',NULL,NULL,'https://es.wikipedia.org/wiki/Miguel_Durán_Campos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187241,'29067','Miguel Pérez Díaz','fiesta','fiestas_wiki','Miguel Pérez Díaz (Málaga, 3 de enero de 1976) es un compositor y pianista español.',NULL,NULL,'https://es.wikipedia.org/wiki/Miguel_Pérez_Díaz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187242,'09218','Milagros de San Vicente','fiesta','fiestas_wiki','Los Milagros de San Vicente Ferrer, conocidos popularmente y por sus autores como Miracles de Sant Vicent Ferrer (nombre en valenciano), son representaciones teatrales infantiles que se realizan en las calles de Valencia, en unos escenarios artesanales decorados con temática religiosa conocidos como Altars de Sant…',NULL,NULL,'https://es.wikipedia.org/wiki/Milagros_de_San_Vicente');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187243,'03016','Misterio de Elche','fiesta','fiestas_wiki','El Misterio de Elche (Misteri d''Elx en valenciano) es un drama sacro-lírico religioso que recrea la Dormición, Asunción y Coronación de la Virgen María. Dividida en dos actos o jornadas, la obra se escenifica cada 14 y 15 de agosto en el interior de la Basílica de Santa María, en la ciudad de Elche (Alicante).…',38.26694444,-0.69833333,'https://es.wikipedia.org/wiki/Misterio_de_Elche','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187244,'31183','Misterio de Obanos','fiesta','fiestas_wiki','El Misterio de Obanos (conocido también como Misterio de San Guillén y Santa Felicia), es una representación teatral de gran formato realizada al aire libre, que se escenificó en Obanos (Navarra, España) entre los años 1965 y 2008 (en varias épocas), y que actualmente está organizada por la Fundación Misterio de…',NULL,NULL,'https://es.wikipedia.org/wiki/Misterio_de_Obanos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187245,'46241','Mojiganga de Titaguas','fiesta','fiestas_wiki','La Mojiganga de Titaguas es una tradición cultural de este municipio de la comarca de los Serranos.',NULL,NULL,'https://es.wikipedia.org/wiki/Mojiganga_de_Titaguas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187246,'02001','Molino de la Feria','fiesta','fiestas_wiki','El Molino de la Feria es uno de los monumentos más representativos de la ciudad española de Albacete.',38.996159,-1.861758,'https://es.wikipedia.org/wiki/Molino_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187247,'49219','Momotxorro','fiesta','fiestas_wiki','El Momotxorro es un personaje de origen desconocido del carnaval de Alsasua: es una persona con cuernos de toro, piel de oveja latxa, cencerros... La costumbre desapareció en la década de 1930, y se recuperó en 1980, aunque esto no gustó a la gente anciana del lugar, ya que el recuerdo de esos personajes iba unido…',NULL,NULL,'https://es.wikipedia.org/wiki/Momotxorro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187248,'02001','Monumento a Chicuelo II','fiesta','fiestas_wiki','El monumento a Chicuelo II es una escultura taurina situada en la ciudad española de Albacete.​​​ Representa al legendario torero albaceteño Chicuelo II, al que homenajea, dando un pase con la muleta. Fue inaugurada en 1961. Está realizada en piedra por el escultor Fernando Colominas.',38.997102,-1.864188,'https://es.wikipedia.org/wiki/Monumento_a_Chicuelo_II','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187249,'02001','Monumento a Dámaso González','fiesta','fiestas_wiki','El monumento a Dámaso González es una escultura taurina situada en la ciudad española de Albacete.​​​ Representa al torero Dámaso González, al que homenajea, en el momento de realizar su peculiar péndulo con el que enganchaba al toro a la muleta. Gran amigo del ilustrísimo goyo "El Fuma Vaper" Fue inaugurada en…',38.997406,-1.864411,'https://es.wikipedia.org/wiki/Monumento_a_Dámaso_González','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187250,'30016','Monumento al Procesionista (Cartagena)','fiesta','fiestas_wiki','El monumento al Procesionista es un grupo escultórico de bronce de Manuel Ardil Pagán expuesto en la Plaza de San Sebastián de la ciudad española de Cartagena (Región de Murcia), en la confluencia de las calles Aire, Honda, Jara, Mayor, Puerta de Murcia y Villamartín. La obra muestra en tamaño natural a un adulto…',37.6016,-0.98686667,'https://es.wikipedia.org/wiki/Monumento_al_Procesionista_(Cartagena)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187251,'12012','Monumento fallero','fiesta','fiestas_wiki','Una falla o monumento fallero es una obra artística, satírica y efímera generalmente de grandes dimensiones (entre tres y veinte metros de altura, aunque pueden ser mayores) con figuras llamadas ninots, las cuales rodean una o más figuras centrales (llamados remates) que se plantan en las calles durante la fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Monumento_fallero');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187252,'29067','Moraga (Andalucía)','fiesta','fiestas_wiki','Una moraga es una fiesta tradicional nocturna realizada generalmente en la playa, típica de la costa de la provincia de Málaga y otros puntos del litoral mediterráneo de Andalucía,​ en España. La fiesta ha ido evolucionando a lo largo de la historia. En el siglo XIX, se realizaba tras la recogida de la red lanzada…',NULL,NULL,'https://es.wikipedia.org/wiki/Moraga_(Andalucía)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187253,'50178','Moros y Cristianos de Alcoy','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Alcoy, en valenciano Moros i Cristians d''Alcoi, son una fiesta que tiene lugar en la ciudad de Alcoy (Alicante), Comunidad Valenciana, España y que incluyen la representación de la lucha entre dos bandos, musulmán y cristiano.',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Alcoy','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187254,'50178','Moros y Cristianos de Alicante','fiesta','fiestas_wiki','Los Moros y Cristianos son una fiesta popular que se celebra en cinco de los barrios de la ciudad española de Alicante, en la que se representa la lucha entre dos bandos, el musulmán y el cristiano. El día 6 de diciembre, con motivo de la festividad del patrón de Alicante, san Nicolás, se realiza un desfile…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Alicante');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187255,'03061','Moros y Cristianos de Almoradí','fiesta','fiestas_wiki','Los Moros y Cristianos de Almoradí es la fiesta más conocida de la localidad. Se empezó a celebrar en 1979 y en ella se representa la reconquista del pueblo Almoradí cuando se encontraba bajo el dominio árabe en el siglo XIV. Esta reconquista la llevó a cabo Jaime I el Conquistador y más tarde fue su nieto, Jaime…',38.10972222,-0.78944444,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Almoradí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187256,'50178','Moros y Cristianos de Bañeres','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Bañeres (en valenciano Moros i Cristians de Banyeres de Mariola), son una fiesta que tiene lugar en la ciudad de Bañeres (Alicante), Comunidad Valenciana, España y que incluyen la representación de la lucha entre dos bandos, musulmán y cristiano.',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Bañeres','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187257,'02009','Moros y Cristianos de Caudete','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Caudete (Castilla-La Mancha, España), declaradas de Interés Turístico Regional el 28 de julio de 1987,​ cuentan con una antigüedad de más de 400 años. Celebradas entre el 5 y el 10 de septiembre, su primera referencia documental es de 1588. Cada septiembre, estas Fiestas…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Caudete','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187258,'03012','Moros y Cristianos de Cocentaina','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Cocentaina (en valenciano Moros i Cristians de Cocentaina) son una fiesta que tiene lugar en la villa valenciana de Cocentaina. Se celebran en agosto en honor al patrón, San Hipólito de Roma, y durante su trascurso dos bandos (moro y cristiano) representan el saqueo islámico y…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Cocentaina','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187259,'50178','Moros y Cristianos de Elda','fiesta','fiestas_wiki','Los Moros y Cristianos de Elda son una importante fiesta popular de la ciudad de Elda (Alicante), en España. Se celebran entre la última semana de mayo y primera semana de junio durante 5 días de manera anual. Declaradas de «Interés Turístico Internacional », conmemoran la festividad de San Antón, el patrón de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Elda','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187260,'03088','Moros y Cristianos de Monforte del Cid','fiesta','fiestas_wiki','Las Fiestas de Moros y Cristianos de Monforte del Cid se celebran del 5 al 9 de diciembre en honor a la Purísima Concepción, patrona de la villa, y fueron declaradas de INTERÉS TURÍSTICO PROVINCIAL según Resolución de 15 de enero de 2009, de la consejera de Turismo y presidenta de la Agencia Valenciana del Turismo.',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Monforte_del_Cid','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187261,'03090','Moros y Cristianos de Muchamiel','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Muchamiel (en valenciano, Mutxamel), provincia de Alicante, son las fiestas mayores en honor a la patrona del municipio, la Virgen de Loreto (en valenciano, la Mare de Déu de Loreto). Desde hace más de 150 años, los festeros y vecinos de Muchamiel celebran esta festividad…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Muchamiel','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187262,'30030','Moros y Cristianos de Murcia','fiesta','fiestas_wiki','Moros y Cristianos de Murcia es una fiesta que tiene lugar en la ciudad de Murcia, Región de Murcia, España declarada como Fiesta de Interés Turístico Internacional en 2025.​',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Murcia','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187263,'03027','Moros y Cristianos de Orihuela','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Orihuela (también conocidas como Fiestas de la Reconquista) son unas fiestas que tienen lugar en la ciudad de Orihuela (Alicante), Comunidad Valenciana, España, que incluyen la representación de la lucha entre dos bandos, musulmán y cristiano,y conmemoran la conquista de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Orihuela','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187264,'03104','Moros y Cristianos de Petrel','fiesta','fiestas_wiki','Los Moros y Cristianos de Petrel en honor a san Bonifacio Mártir son unas fiestas que tienen lugar en la localidad española de Petrel (Alicante) del jueves al lunes del fin de semana más cercano al 14 de mayo, festividad del patrón de la población. Estas fiestas están catalogadas como de Interés Turístico.​ En el…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Petrel','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187265,'50178','Moros y Cristianos de San Vicente del Raspeig','fiesta','fiestas_wiki','Las fiestas de Moros y cristianos de San Vicente del Raspeig se celebran el martes siguiente al Domingo de Resurrección hasta el martes siguiente, en honor al patrón San Vicente Ferrer y fueron declaradas interés turístico provincial en 2007.',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_San_Vicente_del_Raspeig','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187266,'50178','Moros y Cristianos de Sax','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Sax se celebran del 1 al 5 de febrero en honor a San Blas, patrón de la villa, desde 1627.​ Aunque el comienzo data de esa fecha, la estructura actual de las fiestas comienza a forjarse a finales del siglo XVIII y principios del siglo XIX. Rememoran la Reconquista de Sax por las…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Sax','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187267,'04084','Moros y Cristianos de Sierro','fiesta','fiestas_wiki','Las fiestas de moros y cristianos del localidad española de Sierro, en Almería, se celebran cada año durante el primer fin de semana de septiembre.​ Es un evento cultural importante por su carga histórica y tradicional. Los textos de la relación que se conservan fueron transcritos en 1950. Consiste en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Sierro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187268,'50178','Moros y Cristianos de Villajoyosa','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de Villajoyosa, celebradas en honor a Santa Marta del 24 al 31 de julio, fueron declaradas de Interés Turístico Internacional en el año 2003. Estas fiestas, que en Villajoyosa tienen una antigüedad de 250 años, rememoran un importante ataque realizado por los piratas berberiscos,…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Villajoyosa','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187269,'03040','Moros y Cristianos de Villena','fiesta','fiestas_wiki','La fiesta de Moros y Cristianos de Villena se celebra del 4 al 9 de septiembre en honor a Nuestra Señora de las Virtudes, patrona de la ciudad y está reconocida como Fiesta de Interés Turístico Nacional.​ Es una multitudinaria representación de varios millares de personas, con unos 15.000 participantes en los…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_de_Villena','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187270,'50178','Moros y Cristianos en la Comunidad Valenciana','fiesta','fiestas_wiki','Los Moros y Cristianos son una fiesta caracterizada por estar fuertemente arraigada a la historia. En el caso concreto de la fiesta en la Comunidad Valenciana, puede considerarse como un juego de guerras, una imitación de la guerra, la mayor conquista para las tierras valencianas. Cuando Jaime I conquistó las…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_Cristianos_en_la_Comunidad_Valenciana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187271,'50178','Moros y cristianos','fiesta','fiestas_wiki','Los Moros y Cristianos son un tipo de fiesta en la que se rememora cada año las conquistas y encuentros entre cristianos y musulmanes en la península ibérica, de manera que muestra y representa una parte de la historia de muchas localidades tanto dentro como fuera de España.​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_cristianos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187272,'50178','Moros y cristianos de Caravaca','fiesta','fiestas_wiki','La festividad de moros y cristianos de Caravaca es un evento festero que tiene lugar los días 2, 3 y 4 de mayo en el municipio de Caravaca de la Cruz (Murcia) España, en el marco de las fiestas patronales en honor a la Santísima y Vera Cruz de Caravaca, entre los días 1 y 5 de mayo.',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_cristianos_de_Caravaca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187273,'50178','Moros y cristianos del Castillo de La Rábita','fiesta','fiestas_wiki','Las fiestas de Moros y Cristianos de La Rábita, popularmente conocida como Balandrilla de los Gatos,​ son una fiesta que tiene lugar en la localidad española de La Rábita (provincia de Granada), y que incluyen la representación de la batalla naval entre dos bandos de la Reconquista del Reino de Granada: el musulmán…',NULL,NULL,'https://es.wikipedia.org/wiki/Moros_y_cristianos_del_Castillo_de_La_Rábita');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187274,'29003','Motín de Aranjuez','fiesta','fiestas_wiki','El motín de Aranjuez ocurrió entre el 18 y el 19 de marzo de 1808 por las calles de esta localidad madrileña. El motín se desencadenó en protesta por la política de Manuel Godoy, «favorito» de Carlos IV. El resultado fue que Godoy fue apresado y que el rey Carlos IV abdicó el 19 de marzo la Corona de España en…',NULL,NULL,'https://es.wikipedia.org/wiki/Motín_de_Aranjuez','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187275,'30016','Mucho Más Mayo','fiesta','fiestas_wiki','Mucho Más Mayo (M+M o MMM) es un festival público de arte emergente celebrado en la ciudad española de Cartagena y organizado por el Ayuntamiento de Cartagena, a través de sus concejalías de Cultura y de Juventud. Desde sus comienzos, el festival ha servido como un laboratorio de proyectos culturales para la…',NULL,NULL,'https://es.wikipedia.org/wiki/Mucho_Más_Mayo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187276,'46213','Muestra del Embutido Artesano y de Calidad','fiesta','fiestas_wiki','La Muestra del Embutido Artesano y de Calidad es una fiesta popular y tradición gastronómica que se celebra en la estación invernal en la localidad de Requena (Comunidad Valenciana), España.',NULL,NULL,'https://es.wikipedia.org/wiki/Muestra_del_Embutido_Artesano_y_de_Calidad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187277,'46029','Muixeranga de Algemesí','fiesta','fiestas_wiki','La muixeranga de Algemesí es un conjunto de actividades que se integran en las Fiestas de la Virgen de la Salud en Algemesí, España. Incluyen danzas y torres humanas con elementos comunes con actividades festivas de otras comarcas valencianas.​ La Muixeranga de Algemesí fue declarada Patrimonio Cultural Inmaterial…',NULL,NULL,'https://es.wikipedia.org/wiki/Muixeranga_de_Algemesí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187278,'46235','Muixeranga de Sueca','fiesta','fiestas_wiki','La Muixeranga de Sueca es una danza que se compone de un conjunto de cuadros plásticos con intencionalidad representativa que participan en las procesiones de la Virgen de Sales, la fiesta más grande de Sueca, el 8 de septiembre.​ La Muixeranga es un conjunto de bailes originarios de los castillos humanos de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Muixeranga_de_Sueca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187279,'35016','Murga Los Chancletas','fiesta','fiestas_wiki','La Murga Los Chancletas es un grupo del carnaval canario del género murga, que se fundó en septiembre del año 1980, siendo los carnavales de 1981 cuando participaría por primera vez en concurso.​ En la actualidad es una de las murgas veteranas del Carnaval de Las Palmas de Gran Canaria, llevando en 2023, 43…',NULL,NULL,'https://es.wikipedia.org/wiki/Murga_Los_Chancletas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187280,'38012','Murga Los Diablos Locos','fiesta','fiestas_wiki','Murga Los Diablos Locos (también Asociación Cultural Murga Diablos Locos), es una Murga que participa como grupo en el Carnaval de Santa Cruz de Tenerife. Fundada en 1970 en el barrio santacrucero de la Cuesta de Piedra por Domingo Santos López, siendo el gran artífice de la vida de esta murga a lo largo de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Murga_Los_Diablos_Locos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187281,'26004','Museo de Arte Sacro de Bembibre','fiesta','fiestas_wiki','El Museo de Arte Sacro de Bembibre, también conocido como Museo de Arte Sacro “El Santo”​ o Museo de la Semana Santa,​ ubicado en la Villa de Bembibre, se sitúa en el antiguo emplazamiento del Museo "Alto Bierzo", anteriormente las antiguas escuelas municipales y, retrocediendo aún más en el tiempo, la ermita de…',42.614598,-6.411957,'https://es.wikipedia.org/wiki/Museo_de_Arte_Sacro_de_Bembibre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187282,'49275','Museo de Semana Santa de Zamora','fiesta','fiestas_wiki','El Museo de Semana Santa de Zamora fue creado en 1957 por la Junta Pro Semana Santa de la ciudad con el fin de conservar y exhibir al público los pasos procesionales de las cofradías, hasta entonces alojados en diversos locales, llamados, en Zamora, popularmente, paneras. En algunos casos los distintos grupos…',41.50333333,-5.74805556,'https://es.wikipedia.org/wiki/Museo_de_Semana_Santa_de_Zamora','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187283,'29067','Museo de la Semana Santa (Málaga)','fiesta','fiestas_wiki','El Museo de la Semana Santa de Málaga está situado en el centro histórico de la ciudad, en el inmueble del antiguo Hospital de San Julián. Se trata de un museo religioso, inaugurado en 2010. EStá gestionado por la Agrupación de Cofradías y expone una colección de piezas de la historia de las cofradías y de la…',36.72355556,-4.42238889,'https://es.wikipedia.org/wiki/Museo_de_la_Semana_Santa_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187284,'03027','Museo de la Semana Santa (Orihuela)','fiesta','fiestas_wiki','El Museo de la Semana Santa de Orihuela está situado en el solar de la Iglesia de Nuestra Señora de la Merced, que aún conserva su fachada renacentista del siglo XVI. Supone un conjunto de arte sacro de gran importancia a nivel nacional y con un amplio periodo cronológico, pues sus fondos contienen obras que van…',38.086367,-0.943884,'https://es.wikipedia.org/wiki/Museo_de_la_Semana_Santa_(Orihuela)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187285,'33076','Museo de la Semana Santa (Villaviciosa)','fiesta','fiestas_wiki','El Museo de la Semana Santa de Villaviciosa se encuentra en la localidad asturiana de Villaviciosa. El museo fue creado por la cofradía de Nuestro Padre Jesús Nazareno fundada en 1668, y abarca una sala de exposición. En esta sala de exposición se muestra una colección del patrimonio cofrade con piezas de…',43.4784751,-5.4340559,'https://es.wikipedia.org/wiki/Museo_de_la_Semana_Santa_(Villaviciosa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187286,'46250','Museo de la Semana Santa Marinera','fiesta','fiestas_wiki','El Museo de la Semana Santa Marinera es un museo permanente que reúne gran parte del importante patrimonio artístico que posee la Semana Santa Marinera de Valencia. También alberga exposiciones temporales referidas a dicha festividad. El museo está ubicado en un antiguo molino de arroz, rehabilitado a tal efecto.',39.46316667,-0.33194444,'https://es.wikipedia.org/wiki/Museo_de_la_Semana_Santa_Marinera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187287,'16078','Museo de la Semana Santa de Cuenca','fiesta','fiestas_wiki','El Museo de la Semana Santa de Cuenca es un museo en España dedicado a la Semana Santa de Cuenca, declarada Fiesta de Interés Turístico Internacional, y situado en la ciudad homónima. Fue inaugurado el 10 de mayo de 2007.​ El museo se ubica en las dos primeras plantas del que fue el Palacio de Girón y Cañizares o…',40.07611111,-2.13278056,'https://es.wikipedia.org/wiki/Museo_de_la_Semana_Santa_de_Cuenca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187288,'21042','Museo del Carnaval (Isla Cristina)','fiesta','fiestas_wiki','El museo del Carnaval de Isla Cristina (Huelva, España), fue inaugurado en el año 2007 en un antiguo patio de vecinos del siglo XIX que fue rehabilitado a principios del siglo XXI.',37.20375,-7.327799,'https://es.wikipedia.org/wiki/Museo_del_Carnaval_(Isla_Cristina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187289,'06006','Museo del Carnaval de Badajoz','fiesta','fiestas_wiki','El Museo del Carnaval de Badajoz representa, de una forma dinámica, uno de los mejores carnavales de España, fiesta declarada en la localidad de Interés Turístico Internacional.​',38.87541465,-6.97491002,'https://es.wikipedia.org/wiki/Museo_del_Carnaval_de_Badajoz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187290,'03002','Museu Alcoià de la Festa','fiesta','fiestas_wiki','El Museu Alcoià de la Festa (MAF) es: Museo Alcoyano de la Fiesta, de Alcoy (Alicante), Comunidad Valenciana es un museo dedicado íntegramente a las fiestas de Moros y Cristianos de Alcoy, en donde el visitante puede experimentar todos los detalles, aspectos y sentimientos que rodean a la fiesta.',38.70052778,-0.47297222,'https://es.wikipedia.org/wiki/Museu_Alcoià_de_la_Festa','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187291,'49275','Museu Ibérico da Máscara e do Traje','fiesta','fiestas_wiki','El Museo Ibérico da Máscara e do Traje es un museo dedicado a la divulgación de las tradiciones relacionadas con las máscaras de Trás-os-Montes, en Portugal, y las mascaradas de la provincia de Zamora, en España. El museo está ubicado en una casa tradicional de la ciudad vieja de Braganza, en el interior del Castillo.',41.803964,-6.749656,'https://es.wikipedia.org/wiki/Museu_Ibérico_da_Máscara_e_do_Traje','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187292,'30003','Mussona','fiesta','fiestas_wiki','La Mussona es uno de los personajes que representan el Carnaval de Águilas, y una de las máscaras más antiguas de dichas fiestas. Es una figura, mitad humana mitad animal, que representa la dualidad entre el hombre civilizado y el lado salvaje que todo ser humano lleva en su interior.',NULL,NULL,'https://es.wikipedia.org/wiki/Mussona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187293,'50297','Muy Ilustre y Antiquísima Cofradía del Santo Sepulcro de Nuestro Señor Jesucristo','fiesta','fiestas_wiki','Cofradía del Santo Sepulcro de Nuestro Señor Jesucristo​ cuyos orígenes se remontan al siglo XIII, es una cofradía no penitencial de Semana Santa en Zaragoza que procesiona un Cristo Yacente, con un Santo Sepulcro de Zaragoza. No está integrada en la Junta Coordinadora de Cofradías de la Semana Santa de Zaragoza.',NULL,NULL,'https://es.wikipedia.org/wiki/Muy_Ilustre_y_Antiquísima_Cofradía_del_Santo_Sepulcro_de_Nuestro_Señor_Jesucristo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187294,'46212','Muy Ilustre, Antiquísima y Real Hermandad de la Preciosísima Sangre de Nuestro Señor Jesucristo y Madre de Dios de Miser','fiesta','fiestas_wiki','La Muy Ilustre, Antiquísima y Real Hermandad de la Preciosísima Sangre de Nuestro Señor Jesucristo y Madre de Dios de Misericordia o simplemente Hermandad de la Sangre de Cristo cuyos orígenes se remontan al año 1280, es la cofradía penitencial decana de la ciudad de Zaragoza y la que organiza y ordena la Procesión…',NULL,NULL,'https://es.wikipedia.org/wiki/Muy_Ilustre,_Antiquísima_y_Real_Hermandad_de_la_Preciosísima_Sangre_de_Nuestro_Señor_Jesucristo_y_Madre_de_Dios_de_Misericordia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187295,'35016','NIA','fiesta','fiestas_wiki','Estefanía Correia González (Las Palmas de Gran Canaria, 2 de enero de 1994), conocida monónimamente como Nia —estilizado en mayúsculas—, es una cantante, compositora, presentadora, actriz, empresaria y modelo española, conocida por ser la ganadora de la undécima edición del concurso televisivo Operación Triunfo y…',NULL,NULL,'https://es.wikipedia.org/wiki/NIA','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187296,'15065','Nalaya Brown','fiesta','fiestas_wiki','Natalia Rodríguez Padrón (Tenerife, 19 de noviembre de 1983), conocida como Nalaya Brown, o simplemente Nalaya, es una cantante y compositora española de soul, jazz y música pop-dance.',NULL,NULL,'https://es.wikipedia.org/wiki/Nalaya_Brown','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187297,'18902','Naseiro','fiesta','fiestas_wiki','La Romería do Naseiro, popularmente conocida como Romaxe do Bo Xantar (en español: Romería del buen comer), es una festividad que se celebra a finales del mes de agosto (el día grande es siempre el cuarto domingo del mes de agosto, aunque comienza el viernes anterior y dura hasta el martes siguiente), en el valle…',NULL,NULL,'https://es.wikipedia.org/wiki/Naseiro','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187298,'04065','Navidad','fiesta','fiestas_wiki','La Navidad (del latín nativitas, «nacimiento») es una fiesta anual que conmemora el nacimiento de Jesucristo y que se celebra principalmente el 25 de diciembre​ como fiesta religiosa y cultural entre miles de millones de personas de todo el mundo. Fiesta central del año litúrgico en el cristianismo, sigue al tiempo…',NULL,NULL,'https://es.wikipedia.org/wiki/Navidad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187299,'25001','Navidad en el País Vasco','fiesta','fiestas_wiki','La Navidad en el País Vasco comienza con la Fiesta de Santo Tomás, el 21 de diciembre, una celebración en la que la mayoría de la gente sale a la calle​para bailar y comer talo con txistorra (un tipo de chorizo vasco). Llevan un traje tradicional llamado vestido de casera. Para las chicas consiste en una falda…',NULL,NULL,'https://es.wikipedia.org/wiki/Navidad_en_el_País_Vasco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187300,'29067','Nazareno','fiesta','fiestas_wiki','Los nazarenos son los hermanos de una cofradía que hacen la estación de penitencia en la Semana Santa española (y en la de algunos países hispanoamericanos como Colombia y Guatemala) con la indumentaria que figura en las reglas de la hermandad.​ Aunque lo más habitual es emplear el término nazarenos, en Galicia son…',NULL,NULL,'https://es.wikipedia.org/wiki/Nazareno');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187301,'18087','Nicolás Prados López','fiesta','fiestas_wiki','Nicolás Prados López (Granada; 12 de diciembre de 1913- Granada, 14 de diciembre de 1990)​ fue un pintor, escultor e imaginero español.',NULL,NULL,'https://es.wikipedia.org/wiki/Nicolás_Prados_López','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187302,'07049','Ninot','fiesta','fiestas_wiki','Un ninot (del valenciano "muñeco")​ es cada una de las figuras de cartón piedra u otros materiales que componen una falla.​ El ninot es confeccionado con materiales combustibles que generalmente ocupa la base de las Fallas de Valencia y Hogueras de San Juan en Alicante. Con carácter crítico o burlesco, aparecen en…',NULL,NULL,'https://es.wikipedia.org/wiki/Ninot','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187303,'03096','Nit dels Fatxos','fiesta','fiestas_wiki','La Nit dels Fatxos es un festejo popular que se celebra en la localidad alicantina de Onil y que se encuentra relacionado con la cultura del fuego.',NULL,NULL,'https://es.wikipedia.org/wiki/Nit_dels_Fatxos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187304,'11031','Niña Pastori','fiesta','fiestas_wiki','María Rosa García García (San Fernando, 15 de enero de 1978), conocida artísticamente como Niña Pastori, es una cantaora de flamenco española que ha vendido más de 2 millones de copias en sus casi 30 años de carrera.',NULL,NULL,'https://es.wikipedia.org/wiki/Niña_Pastori','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187305,'90288','Noche de la Alborada','fiesta','fiestas_wiki','La Noche de la Alborada (conocida en valenciano como Nit de l''Albada o Nit de l''Albà) es un acto festivo realizado en la ciudad española de Elche (provincia de Alicante) y preludia las fiestas patronales de la ciudad en honor a la Virgen de la Asunción. Se celebra el día 13 de agosto. Desde 2021 está declarada como…',NULL,NULL,'https://es.wikipedia.org/wiki/Noche_de_la_Alborada','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187306,'46079','Noche de la Roa','fiesta','fiestas_wiki','La Noche de la Roa (Nit de la Roà en valenciano) se celebra en Elche (Comunidad Valenciana, España) la noche y madrugada comprendida entre el 14 y el 15 de agosto, en la cual se produce la tradicional procesión en honor a la Virgen de la Asunción, patrona de la ciudad. En esta ceremonia, miles de ilicitanos…',NULL,NULL,'https://es.wikipedia.org/wiki/Noche_de_la_Roa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187307,'29086','Noche de las candelas','fiesta','fiestas_wiki','La noche de las candelas es una fiesta celebrada en Sayalonga, Comares, y otros puntos de la Axarquía, en la provincia de Málaga, España. Durante la fiesta se quema todo lo que ya no sirve. Se encienden así numerosas fogatas que iluminan los montes y cerros de casi toda la comarca de la Axarquía.',NULL,NULL,'https://es.wikipedia.org/wiki/Noche_de_las_candelas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187308,'46250','Noche de reyes (película)','fiesta','fiestas_wiki','Noche de reyes es una película española de 2001 dirigida por Miguel Bardem. Se trata del segundo trabajo en solitario de Bardem tras La mujer más fea del mundo. Aunque está ambientada en las fechas navideñas, en realidad fue rodada en Valencia y Madrid durante agosto de 2001 y los actores debieron soportar las…',NULL,NULL,'https://es.wikipedia.org/wiki/Noche_de_reyes_(película)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187309,'37011','Nochevieja Universitaria','fiesta','fiestas_wiki','La Nochevieja Universitaria también conocida como Cotillón Salamanca, es un evento que se celebra en la ciudad de Salamanca, Castilla y León, España cada año desde el 2005 en la que se reunían unos cientos universitarios. La celebración tiene lugar siempre el penúltimo jueves lectivo del mes de diciembre,…',NULL,NULL,'https://es.wikipedia.org/wiki/Nochevieja_Universitaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187310,'11020','Nuestra Señora de Consolación (Jerez de la Frontera)','fiesta','fiestas_wiki','Nuestra Señora de Consolación es una advocación mariana de gran raigambre en Jerez de la Frontera, venerada en el Real Convento de Santo Domingo y reconocida como copatrona de la ciudad. La imagen, de pequeño tamaño, está realizada en alabastro y responde a modelos góticos del siglo XV, constituyendo una de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_Consolación_(Jerez_de_la_Frontera)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187311,'11020','Nuestra Señora de Guadalupe (Jerez de la Frontera)','fiesta','fiestas_wiki','Nuestra Señora de Guadalupe es una imagen mariana de estilo gótico, datada en el siglo XIV, considerada la talla mariana más antigua conservada en Jerez de la Frontera y una de las devociones históricas más relevantes vinculada al Santuario de San Lucas.',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_Guadalupe_(Jerez_de_la_Frontera)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187312,'28125','Nuestra Señora de Navahonda (Robledo de Chavela)','fiesta','fiestas_wiki','Nuestra Señora de Navahonda es la patrona de Robledo de Chavela (Madrid, España), cuya imagen puede venerarse en la Ermita de Navahonda. La tradición sobre la imagen de la Virgen de Navahonda se remonta a los tiempos en que Robledo de Chavela pertenecía aún a Segovia. En el valle de Navahonda, se encontró una talla…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_Navahonda_(Robledo_de_Chavela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187313,'04063','Nuestra Señora de la Esperanza (Alicante)','fiesta','fiestas_wiki','Nuestra Señora de la Esperanza es una advocación de la Virgen María que se venera en la iglesia de la Misericordia de la ciudad de Alicante (España). Es la imagen titular de la Hermandad del Gran Poder y la Esperanza, con la que realiza su estación de penitencia la tarde-noche del Domingo de Ramos, dentro de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_la_Esperanza_(Alicante)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187314,'41091','Nuestra Señora de la Esperanza (Triana)','fiesta','fiestas_wiki','Nuestra Señora de la Esperanza también conocida como La Esperanza de Triana es una representación de la Virgen María que se venera en Sevilla en el barrio de Triana, considerada una de las devociones más importantes de Triana y de las imágenes marianas más veneradas de Sevilla.[cita requerida] Es la titular de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_la_Esperanza_(Triana)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187315,'35026','Nuestra Señora de la Soledad (Telde)','fiesta','fiestas_wiki','Nuestra Señora de la Soledad​​​​ es una imagen que representa a la Virgen María en su Soledad tras la muerte del su Hijo, la imagen mariana se venera en la capilla de su mismo nombre en la basílica de san Juan Bautista en el municipio de Telde (Gran Canaria, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_la_Soledad_(Telde)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187316,'35016','Nuestra Señora de la Soledad de la Portería','fiesta','fiestas_wiki','Nuestra Señora de la Soledad de la Portería es una imagen de la Virgen María venerada en la parroquia de san Francisco de Asís y santuario mariano de Nuestra Señora de la Soledad​​ en la ciudad de Las Palmas de Gran Canaria en la isla de Gran Canaria.',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_la_Soledad_de_la_Portería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187317,'38012','Nuestra Señora de las Angustias (La Republicana)','fiesta','fiestas_wiki','La imagen de Nuestra Señora la Virgen de las Angustias es una escultura que representa a la Virgen María que se venera en la Parroquia de Nuestra Señora del Pilar, en Santa Cruz de Tenerife (isla de Tenerife, Canarias, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_las_Angustias_(La_Republicana)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187318,'41091','Nuestra Señora de las Mercedes (Santa Genoveva)','fiesta','fiestas_wiki','Nuestra Señora de las Mercedes es una advocación de la Virgen María que se venera en la iglesia de Santa Genoveva de la ciudad de Sevilla (España). Es la imagen titular de la Hermandad de Santa Genoveva, con la que realiza su estación de penitencia el día de Lunes Santo, dentro de los actos de celebración de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_las_Mercedes_(Santa_Genoveva)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187319,'90488','Nuestra Señora de los Dolores (Alba de Tormes)','fiesta','fiestas_wiki','Nuestra Señora de los Dolores es una talla anónima de los siglos xvii o xviii. Portada el Viernes Santo, la imagen está ubicada en la Iglesia de San Juan de Alba de Tormes, en Salamanca (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_los_Dolores_(Alba_de_Tormes)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187320,'03064','Nuestra Señora de los Dolores (Catedral de Canarias)','fiesta','fiestas_wiki','Nuestra Señora de los Dolores o Dolorosa de Luján Pérez​​​​​ es una imagen de la Virgen María que se encuentra en la capilla del mismo nombre en la Catedral de Canarias (Las Palmas de Gran Canaria, España). Es una talla completa ejecutada en madera de cedro policromada y estofada, realizada por el imaginero José…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_los_Dolores_(Catedral_de_Canarias)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187321,'03064','Nuestra Señora de los Dolores (La Genovesa)','fiesta','fiestas_wiki','Nuestra Señora de Los Dolores es una imagen de la Virgen María que se venera en la parroquia matriz de san Agustín de Hipona de la ciudad de Las Palmas de Gran Canaria, popularmente conocida como "la Genovesa" por su procedencia de la ciudad italiana de Génova.​',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_los_Dolores_(La_Genovesa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187322,'03064','Nuestra Señora de los Dolores (La Predilecta)','fiesta','fiestas_wiki','Nuestra Señora de los Dolores es una imagen de la Virgen María que se venera en la Parroquia Matriz de Nuestra Señora de la Concepción de la ciudad de San Cristóbal de La Laguna (Tenerife, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_los_Dolores_(La_Predilecta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187323,'38026','Nuestra Señora de los Dolores (Parroquia de la Concepción de La Orotava)','fiesta','fiestas_wiki','Nuestra Señora de los Dolores es una imagen de la Virgen María que se venera en la parroquia matriz de Nuestra Señora de la Concepción​ de la Villa de la Orotava, Tenerife, Canarias.',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_los_Dolores_(Parroquia_de_la_Concepción_de_La_Orotava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187324,'30030','Nuestra Señora del Carmen (Beniaján)','fiesta','fiestas_wiki','Nuestra Señora la Santísima Virgen Coronada del Carmen y de las Benditas Ánimas del Purgatorio es patrona de la villa de Beniaján, localidad​ española del municipio de Murcia, emplazada en la Huerta de Murcia. La iconografía del grupo escultórico que se venera en Beniaján, de gran espectacularidad y belleza,…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestra_Señora_del_Carmen_(Beniaján)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187325,'33007','Nuestra Señora del Puy','fiesta','fiestas_wiki','Nuestra Señora del Puy,​ Santa María del Puy​​ o simplemente Virgen del Puy es una talla gótica y una advocación de la Virgen María, y la patrona de Estella. La imagen se venera en Basílica de Nuestra Señora del Puy está en lo alto de la ciudad, cerca del colegio denominado en su honor Nuestra Señora del Puy. Esta…',42.67562117,-2.02984061,'https://es.wikipedia.org/wiki/Nuestra_Señora_del_Puy');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187326,'38012','Nuestro Padre Jesús Cautivo (Santa Cruz de Tenerife)','fiesta','fiestas_wiki','La imagen de Nuestro Padre Jesús Cautivo es una talla que representa a Jesucristo cautivo que se venera en la Iglesia Matriz de la Concepción de la ciudad de Santa Cruz de Tenerife (Islas Canarias, España), siendo el titular de la Real Cofradía de Jesús Cautivo y la Esperanza Macarena, filial de la Hermandad de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_Cautivo_(Santa_Cruz_de_Tenerife)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187327,'22006','Nuestro Padre Jesús Nazareno (Ayamonte)','fiesta','fiestas_wiki','Nuestro Padre Jesús Nazareno, conocido popularmente como Padre Jesús, es una escultura que representa a Jesucristo. Recibe culto católico en la Capilla del Socorro de Ayamonte y es titular de la Hermandad de Padre Jesús.',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_Nazareno_(Ayamonte)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187328,'34120','Nuestro Padre Jesús Nazareno (Palencia)','fiesta','fiestas_wiki','Nuestro Padre Jesús Nazareno, también conocido como «El Viejo»​ y «El Abuelo»,​ es una obra realizada por Tomás de Sierra entre 1716 y 1717. Portada el Viernes Santo por la Cofradía de Nuestro Padre Jesús Nazareno y Nuestra Madre la Virgen de la Amargura, la imagen está ubicada en la Capilla de Jesús Nazareno de…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_Nazareno_(Palencia)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187329,'41095','Nuestro Padre Jesús Redentor Cautivo (Utrera)','fiesta','fiestas_wiki','Nuestro Padre Jesús Redentor Cautivo o simplemente Cautivo de Utrera es una imagen que representa a Jesús de Nazaret y que evoca el pasaje del evangelio en el cual Jesús queda cautivo y abandonado por sus discípulos.',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_Redentor_Cautivo_(Utrera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187330,'14021','Nuestro Padre Jesús de la Humildad y Paciencia (Córdoba)','fiesta','fiestas_wiki','Nuestro Padre Jesús de la Humildad y Paciencia es una advocación cristífera venerada en la ciudad de Córdoba. La Imagen del Señor fue realizada por el imaginero Juan Martínez Cerrillo en 1943, es Titular de la Hermandad de la Paz y Esperanza. Tiene Capilla en la Iglesia del Santo Ángel (Hermanos Capuchinos).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_de_la_Humildad_y_Paciencia_(Córdoba)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187331,'41091','Nuestro Padre Jesús de la Redención (Sevilla)','fiesta','fiestas_wiki','Nuestro Padre Jesús de la Redención en el beso de Judas es una imagen que representa a Jesús de Nazaret en el momento inicial de su pasión cuando Judas Iscariote lo entrega con un beso.​ La imagen es obra de Antonio Castillo Lastrucci, realizada en 1958.​ La imagen se venera en la Iglesia de Santiago el Mayor, en…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_de_la_Redención_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187332,'35016','Nuestro Padre Jesús de la Salud (Las Palmas de Gran Canaria)','fiesta','fiestas_wiki','La imagen de Nuestro Padre Jesús de la Salud, obra del escultor e imaginero sevillano José Paz Vélez, se venera en la parroquia de Santo Domingo de Guzmán en Vegueta, en la ciudad de Las Palmas de Gran Canaria, España. Es el titular de la Real e Ilustre Hermandad y Cofradía de Nazarenos de Nuestro Padre Jesús de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_de_la_Salud_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187333,'41091','Nuestro Padre Jesús de la Salud (Montes de Oca)','fiesta','fiestas_wiki','Nuestro Padre Jesús de la Salud, también conocido como «Manué»,​ fue una obra atribuida a José Montes de Oca y realizada posiblemente en 1738. Destruida en 1936, estaba ubicada en la Iglesia de San Román de Sevilla (Andalucía, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_de_la_Salud_(Montes_de_Oca)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187334,'06006','Nuestro Padre Jesús del Amparo (Badajoz)','fiesta','fiestas_wiki','Nuestro Padre Jesús del Amparo es una talla religiosa perteneciente a la Hermandad y Cofradía de penitencia de Nuestro Padre Jesús del Amparo, Dulce Nombre del Señor, Santísimo Cristo de la Fe y Nuestra Señora de la Piedad, María Santísima del Mayor Dolor (Hermandad de Santo Domingo (Badajoz)) de la ciudad de…',NULL,NULL,'https://es.wikipedia.org/wiki/Nuestro_Padre_Jesús_del_Amparo_(Badajoz)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187335,'49275','Obisparra','fiesta','fiestas_wiki','La Obisparra es una procesión pagana en forma de mascarada de carácter jocoso y festivo que se celebra en los periodos invernales de algunos pueblos de las comarcas de Aliste, y La Carballeda y Sanabria (Zamora).​ Posee algunos personajes fijos que aparecen en la procesión con una simbología clara: la Filandorra,…',NULL,NULL,'https://es.wikipedia.org/wiki/Obisparra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187336,'02001','Ofrenda de flores a la Virgen de los Llanos','fiesta','fiestas_wiki','La ofrenda de flores a la Virgen de los Llanos es una de las tradiciones más populares, arraigadas y multitudinarias de la ciudad española de Albacete. Se desarrolla con una periodicidad anual en el marco de la Feria de Albacete, declarada de Interés Turístico Internacional.',NULL,NULL,'https://es.wikipedia.org/wiki/Ofrenda_de_flores_a_la_Virgen_de_los_Llanos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187337,'50297','Ofrenda de frutos a Nuestra Señora del Pilar','fiesta','fiestas_wiki','La ofrenda de frutos es una celebración que tiene lugar en Zaragoza (España) todos los años con motivo de las fiestas del Pilar. Se discute la fecha del origen de esta tradición, pero hay constancia de que al menos se celebra desde 1949.​ Las casas regionales afincadas en la capital aragonesa son las protagonistas…',NULL,NULL,'https://es.wikipedia.org/wiki/Ofrenda_de_frutos_a_Nuestra_Señora_del_Pilar','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187338,'90436','Oktoberfest de Algarrobo','fiesta','fiestas_wiki','La Oktoberfest de Algarrobo es una fiesta celebrada en Algarrobo (Málaga) España. Se trata de una fiesta pensada para promover la cultura alemana en la Costa del Sol. En ella se dan a conocer especialidades culinarias de la zona sur de Alemania como weisswurst, chucrut, scheweinebraten y knödel además de la típica…',NULL,NULL,'https://es.wikipedia.org/wiki/Oktoberfest_de_Algarrobo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187339,'22124','Oración en el huerto de Getsemaní (Francisco Salzillo)','fiesta','fiestas_wiki','La oración en el huerto, realizado por el escultor murciano Francisco Salzillo, es uno de los siete pasos procesionales que formaban la serie encargada por la cofradía de Nuestro padre Jesús Nazareno de Murcia.',NULL,NULL,'https://es.wikipedia.org/wiki/Oración_en_el_huerto_de_Getsemaní_(Francisco_Salzillo)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187340,'29067','Orden de Servitas (Málaga)','fiesta','fiestas_wiki','La Orden de Servitas, cuya denominación oficial es Venerable Orden Tercera de Siervos de María Santísima de los Dolores, es una corporación nazarena de la ciudad de Málaga, que participa en su Semana Santa.',NULL,NULL,'https://es.wikipedia.org/wiki/Orden_de_Servitas_(Málaga)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187341,'28079','Orgullo de Madrid','fiesta','fiestas_wiki','Las Fiestas del Orgullo de Madrid, conocidas popularmente como el Orgullo LGTB​ de Madrid y por su acrónimo MADO (Madrid Orgullo),​ son las fiestas celebradas por el barrio de Chueca, en el centro de Madrid el fin de semana posterior al 28 de junio, Día Internacional del Orgullo LGBTIQ+.​ Es el evento celebrado por…',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187342,'46250','Orgullo de Valencia','fiesta','fiestas_wiki','El Orgullo de Valencia es una fiesta reivindicativa que se celebra en junio en la capital de la Comunidad Valenciana (España), en el marco del Día Internacional del Orgullo LGBT del 28 de junio.​ La entidad Lambda organiza muchas de las marchas y manifestaciones, que se llevan celebrando en la ciudad desde 1979.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Orgullo_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187343,'16009','Orquesta Caballati','fiesta','fiestas_wiki','La Orquesta Caballati, o Cuarteto Caballati como era conocida en sus inicios, es una agrupación musical que interpreta principalmente conocidas coplas del carnaval de Cádiz, versionadas con un peculiar estilo a través de instrumentos de viento (clarinete, trompeta, saxofón, etc.) y la clásica formación carnavalesca…',NULL,NULL,'https://es.wikipedia.org/wiki/Orquesta_Caballati','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187344,'16009','Pablo Carbonell','fiesta','fiestas_wiki','Pablo Carbonell Sánchez-Gijón (Cádiz, 28 de julio de 1962) es un cantante, humorista y actor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Pablo_Carbonell','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187345,'09180','Padre no hay más que uno 3','fiesta','fiestas_wiki','Padre no hay más que uno 3 es una película de comedia navideña española de 2022 dirigida y protagonizada por Santiago Segura. Es una secuela de los éxitos de taquilla Padre no hay más que uno y Padre no hay más que uno 2: La llegada de la suegra. El reparto lo completan personajes de la talla de Toni Acosta, Carlos…',NULL,NULL,'https://es.wikipedia.org/wiki/Padre_no_hay_más_que_uno_3');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187346,'05247','Palos de pollo','fiesta','fiestas_wiki','Los palos pollo es una actividad tradicional de muchos pueblos valencianos consistente en que un grupo de jóvenes construyen algún tipo de estructura con sus cuerpos con la intención de coger un premio, habitualmente un pollo, durante la celebración de una festividad. La realización de la torre se hace de forma…',NULL,NULL,'https://es.wikipedia.org/wiki/Palos_de_pollo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187347,'46242','Pan de san Antonio (Torrebaja)','fiesta','fiestas_wiki','El Pan de san Antonio es una celebración socio-religiosa tradicional de Torrebaja, aunque no exclusiva de esta población del Rincón de Ademuz, (Comunidad Valenciana, España). Consiste en el reparto de pan dormido por san san Antón, acto que tiene lugar en la onomástica del santo (17 de enero), y corre a cargo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Pan_de_san_Antonio_(Torrebaja)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187348,'13004','Pandorga (Ciudad Real)','fiesta','fiestas_wiki','La Pandorga es una multitudinaria fiesta popular de la localidad manchega de Ciudad Real, que se celebra cada año el 31 de julio. Tiene su origen en la ofrenda de flores y productos del campo de la población hacía a la Virgen del Prado, patrona de la ciudad. Es el principal acto de la Pandorga que se realiza…',NULL,NULL,'https://es.wikipedia.org/wiki/Pandorga_(Ciudad_Real)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187349,'43138','Panes de la caridad (Mas del Olmo)','fiesta','fiestas_wiki','La fiesta de los Panes de la caridad es una celebración festivo-religiosa que tiene lugar en Mas del Olmo, aldea de Ademuz, provincia de Valencia, (Comunidad Valenciana, España). La tradicional romería se celebra anualmente, en la onomástica de santa Bárbara, el (4 de diciembre).',NULL,NULL,'https://es.wikipedia.org/wiki/Panes_de_la_caridad_(Mas_del_Olmo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187350,'03012','Paquito el Chocolatero','fiesta','fiestas_wiki','Paquito el Chocolatero es una composición musical española creada en 1937 por el compositor español Gustavo Pascual Falcó, nacido en 1909 en la localidad de Cocentaina, provincia de Alicante, Comunidad Valenciana, escrita con el aire de un pasodoble español. Fue estrenada en las fiestas de Moros y Cristianos de su…',NULL,NULL,'https://es.wikipedia.org/wiki/Paquito_el_Chocolatero');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187351,'90444','Partir la vieja','fiesta','fiestas_wiki','Partir la Vieja, también llamada Día de la Vieja es una fiesta tradicional de varios municipios del sudeste español (Andalucía oriental), como en el municipio de Arriate, en la provincia de Málaga, Andalucía, donde se viene celebrando año tras año desde fechas anteriores al 1700.​ La Iglesia en aquellos años era…',NULL,NULL,'https://es.wikipedia.org/wiki/Partir_la_vieja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187352,'36011','Pascua Xoven Arousa','fiesta','fiestas_wiki','La Pascua Xoven de Arousa​ (Pascua Joven de Arosa en castellano) nació de la mano de D. Jaime Vaamonde Souto (1942-2013) en Villagarcía de Arosa, ciudad española de la provincia de Pontevedra y es realizada cada año como actividad juvenil, festiva y religiosa, siendo la convivencia juvenil cristiana de mayor…',NULL,NULL,'https://es.wikipedia.org/wiki/Pascua_Xoven_Arousa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187353,'02001','Paseo de la Feria','fiesta','fiestas_wiki','El paseo de la Feria o paseo Ferial es uno de los paseos más emblemáticos de la ciudad española de Albacete. Es una gran explanada alargada peatonal con forma triangular y gran longitud de 600 metros con el vértice superior al este, en la calle Feria, y la base al oeste, en la avenida Arquitecto Julio Carrilero.',38.996625,-1.86500556,'https://es.wikipedia.org/wiki/Paseo_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187354,'28079','Pasión Vega','fiesta','fiestas_wiki','Ana María Alías Vega (Madrid, 23 de abril de 1976), más conocida por su nombre artístico Pasión Vega, es una cantante española de música popular.',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_Vega','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187355,'39020','Pasión Viviente de Castro-Urdiales','fiesta','fiestas_wiki','La Pasión Viviente de Castro-Urdiales es una representación de la Pasión de Cristo, desde la última cena hasta su crucifixión, muerte y resurrección, que se celebra la mañana de Viernes Santo en la ciudad española de Castro-Urdiales, Cantabria. La duración aproximada de la representación es de cuatro horas y media.…',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_Viviente_de_Castro-Urdiales','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187356,'16134','Pasión Viviente de Motilla del Palancar','fiesta','fiestas_wiki','La Pasión Viviente de Motilla del Palancar es una representación de la Pasión de Cristo, donde se representa desde la Entrada Triunfal de Jesús en Jerusalén hasta su Crucifixión y Muerte. La función tiene lugar por las calles del municipio, en varios puntos del casco histórico. La Pasión motillana está declarada…',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_Viviente_de_Motilla_del_Palancar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187357,'06093','Pasión Viviente de Oliva de la Frontera','fiesta','fiestas_wiki','La Pasión Viviente de Oliva de la Frontera es una representación de la Pasión de Cristo, desde la Entrada Triunfal en Jerusalén hasta su Crucifixión y Muerte, celebrada en la localidad de Oliva de la Frontera (Badajoz, España) cada Semana Santa, siendo una de las más longevas y participativas de las que se celebran…',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_Viviente_de_Oliva_de_la_Frontera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187358,'48090','Pasión Viviente de Valmaseda','fiesta','fiestas_wiki','La Pasión Viviente de Balmaseda es un vía crucis que se representa todos los años en la localidad vasca de Valmaseda (Vizcaya). Es la pasión viviente más antigua y más conocida del País Vasco, y uno de los actos más populares de la Semana Santa vasca.',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_Viviente_de_Valmaseda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187359,'08076','Pasión de Esparraguera','fiesta','fiestas_wiki','La Pasión de Esparreguera (la Passió d''Esparreguera en catalán) es una representación de la Pasión de Cristo, realizada con escenografía propiamente teatral y con varios intérpretes. El pueblo de Esparreguera se moviliza para hacer realidad las representaciones. Independientemente de los textos, el hecho…',NULL,NULL,'https://es.wikipedia.org/wiki/Pasión_de_Esparraguera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187360,'02025','Paso Gordo (Tobarra)','fiesta','fiestas_wiki','Paso Gordo es el nombre popular que recibe la Hermandad de la Caída de Jesús y Cristo Resucitado de Tobarra (Albacete), aunque propiamente dicho, de los dos tronos con que desfila la hermandad, solamente se hace referencia al trono de la Caída. La Semana Santa de Tobarra está Declarada de Interés Turístico Nacional…',NULL,NULL,'https://es.wikipedia.org/wiki/Paso_Gordo_(Tobarra)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187361,'07049','Paso Nuevo de Nuestra Señora y San Juan','fiesta','fiestas_wiki','El Paso Nuevo de Nuestra Señora y San Juan es una obra realizada en el periodo 1650-1661 y atribuida a Francisco Díez de Tudanca y su taller. Procesionado en Semana Santa por la Cofradía de las Siete Palabras, el grupo escultórico está ubicado en el Museo Nacional de Escultura, en Valladolid (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Paso_Nuevo_de_Nuestra_Señora_y_San_Juan','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187362,'42165','Paso del Fuego y Fiestas de las Móndidas','fiesta','fiestas_wiki','El Paso del Fuego y Fiestas de las Móndidas, también conocidas como Fiestas de San Juan, es una celebración en honor a San Juan Bautista y la Virgen de la Peña que tiene lugar anualmente en la villa española de San Pedro Manrique en la comunidad autónoma de Castilla y León, provincia de Soria. El Paso del Fuego es…',42.03111111,-2.23166667,'https://es.wikipedia.org/wiki/Paso_del_Fuego_y_Fiestas_de_las_Móndidas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187363,'16007','Patrona de Chiclana de la Frontera','fiesta','fiestas_wiki','La Patrona de Chiclana de la Frontera es la Virgen de los Remedios, que procesiona cada 8 de septiembre por las calles de dicha ciudad. La imagen de la Virgen de los Remedios se encuentra en la Parroquia de la Santísima Trinidad, templo del siglo XVII, aunque la imagen fue encontrada en el siglo XVI por unos…',NULL,NULL,'https://es.wikipedia.org/wiki/Patrona_de_Chiclana_de_la_Frontera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187364,'08005','Patum de Berga','fiesta','fiestas_wiki','La Fiesta de la Patum de Berga es una celebración tradicional que se realiza durante las fiestas del Corpus Christi en la localidad catalana de Berga. Ha sido declarada por la Unesco Patrimonio Cultural Inmaterial de la Humanidad el día 25 de noviembre del año 2005 e inscrita en 2008 en su lista representativa​ y…',42.104342,1.846237,'https://es.wikipedia.org/wiki/Patum_de_Berga','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187365,'16009','Paz Padilla','fiesta','fiestas_wiki','María de la Paz Padilla Díaz, conocida artísticamente como Paz Padilla (Cádiz, 26 de septiembre de 1969), es una actriz, presentadora de televisión y empresaria española.​',NULL,NULL,'https://es.wikipedia.org/wiki/Paz_Padilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187366,'45034','Pecados y Danzantes de Camuñas','fiesta','fiestas_wiki','Pecados y Danzantes de Camuñas es una fiesta declarada de interés turístico, que se celebra en el municipio castellanomanchego de Camuñas, en la provincia de Toledo en España.',NULL,NULL,'https://es.wikipedia.org/wiki/Pecados_y_Danzantes_de_Camuñas','IT Nacional');
