INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187368,'21041','Pedro Gómez y Gómez','fiesta','fiestas_wiki','Pedro Gómez y Gómez (Huelva, 1888 - 1961). Artista nacido en Huelva y perteneciente al grupo de pintores locales entre los que se encuentran, entre otros, Enrique García Orta, Sebastián García Vázquez, Manuel Cruz Fernández, Rafael Cortés Moreno y Antonio Brunt. Se formó en la Escuela de Pintura de Huelva, donde se…',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_Gómez_y_Gómez','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187369,'41091','Pedro Morales Muñoz','fiesta','fiestas_wiki','Pedro Morales Muñoz (Lopera, Jaén, 24 de enero de 1923-Sevilla, 30 de junio de 2017)​ fue un compositor, director de orquesta y director de bandas militares. Como compositor, escribió pasodobles, zarzuelas, marchas procesionales, marchas militares, canción española y fantasías, además de variados arreglos y…',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_Morales_Muñoz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187370,'36053','Pedro Payán Sotomayor','fiesta','fiestas_wiki','Pedro Manuel Payán Sotomayor (n. Cádiz; 1937). Profesor de Lengua Española de la Universidad de Cádiz.',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_Payán_Sotomayor','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187371,'29067','Pedro Pérez Hidalgo','fiesta','fiestas_wiki','Pedro Pérez Hidalgo (Málaga, 1912 - Málaga, 2005) fue un imaginero malagueño, destacado por su labor de tallista, realizando gran número de tronos, pasos, imágenes y restauraciones de obras en la posguerra.',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_Pérez_Hidalgo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187372,'29067','Pedro Sáenz Sáenz','fiesta','fiestas_wiki','Pedro Sáenz Sáenz (Málaga, 14 de octubre de 1863-Málaga, 10 de enero de 1927) fue un pintor prerrafaelista español.',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_Sáenz_Sáenz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187373,'18087','Pedro de Mena','fiesta','fiestas_wiki','Pedro de Mena y Medrano (Granada, agosto de 1628 - Málaga, 13 de octubre de 1688) fue un escultor del barroco español. Pedro de Mena se dedicó principalmente a la realización de imaginería religiosa, oficio al que también se había dedicado su padre, Alonso de Mena, y de quien heredó un taller en Granada. Además,…',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_de_Mena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187374,'29067','Pedro de Zayas','fiesta','fiestas_wiki','Pedro de Zayas (Úbeda, ¿?-Málaga, 1649) fue un escultor castellano del siglo xvii, que inició la saga o dinastía de artistas de Zayas.',NULL,NULL,'https://es.wikipedia.org/wiki/Pedro_de_Zayas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187375,'32085','Peliqueiro','fiesta','fiestas_wiki','Se llama peliqueiro o piliqueiro al traje característico del carnaval de Laza; es similar al cigarrón del carnaval de Verín. En 1912 fueron a Laza desde la parroquia de Castro de Laza unos 10 peliqueiros, mientras que en Laza mismo solo había unos cuatro o cinco. En aquel entonces los trajes eran alquilados por…',NULL,NULL,'https://es.wikipedia.org/wiki/Peliqueiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187376,'90778','Peregrinación a Candelaria','fiesta','fiestas_wiki','La peregrinación a Candelaria (llamada popularmente Caminata a Candelaria) es una marcha de carácter religioso que se realiza cada año en la noche del 14 al 15 de agosto en Tenerife (Canarias, España) hacia el municipio de Candelaria, lugar donde se encuentra la imagen de la Patrona de Canarias, la Virgen de…',NULL,NULL,'https://es.wikipedia.org/wiki/Peregrinación_a_Candelaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187377,'12026','Perfecto Artola Prats','fiesta','fiestas_wiki','Perfecto Artola Prats (Benasal, 30 de diciembre de 1904- Málaga, 23 de octubre de 1992) fue un músico y compositor español.​',NULL,NULL,'https://es.wikipedia.org/wiki/Perfecto_Artola_Prats','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187378,'10212','Peropalo','fiesta','fiestas_wiki','Peropalo es el nombre con el que se conoce a un muñeco, de tamaño natural, en torno al cual gira siempre el carnaval en Villanueva de la Vera, localidad de la provincia de Cáceres, en la comunidad autónoma de Extremadura (España). La fiesta consiste básicamente en una serie de ritos que se organizan en torno al…',NULL,NULL,'https://es.wikipedia.org/wiki/Peropalo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187379,'02001','Pincho de la Feria','fiesta','fiestas_wiki','Se conoce con el nombre de Pincho de la Feria a tres elementos históricos de la ciudad española de Albacete.​ Uno de ellos es el centenario pincho del Templete de la Feria (1912), el más antiguo de los tres. Según el libro Evocaciones y recuerdos albaceteños de Alberto Mateos Arcángel este es el verdadero Pincho de…',38.997199,-1.870439,'https://es.wikipedia.org/wiki/Pincho_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187380,'47186','Pingüinos (concentración motera)','fiesta','fiestas_wiki','Pingüinos es una concentración anual de aficionados a la motocicleta de todo el mundo, que se celebra desde 1982, el segundo fin de semana de cada enero, durante cuatro días en la provincia de Valladolid, comunidad autónoma de Castilla y León, España. Se trata de la concentración motera invernal más importante del…',NULL,NULL,'https://es.wikipedia.org/wiki/Pingüinos_(concentración_motera)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187381,'07049','Plantá','fiesta','fiestas_wiki','La plantá (del verbo plantar; en valenciano, plantà) es el acto de alzar una falla o una hoguera, en las fiestas falleras o en las Hogueras de San Juan, fiestas celebradas respectivamente en marzo y en junio en distintas localidades de la Comunidad Valenciana (España). La plantá se considera, actualmente, el…',NULL,NULL,'https://es.wikipedia.org/wiki/Plantá','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187382,'33014','Plaza de toros Monumental de Pamplona','fiesta','fiestas_wiki','La plaza de toros de Pamplona es el coso taurino proyectado en 1920 en el Segundo Ensanche de Pamplona para festejar las corridas de toros. Se trata de una plaza de toros de primera categoría, con un aforo de unos 19 720 espectadores por lo que se trata de la cuarta mayor del mundo por aforo, tras las de México…',42.815866,-1.639548,'https://es.wikipedia.org/wiki/Plaza_de_toros_Monumental_de_Pamplona','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187383,'02001','Plaza de toros de Albacete','fiesta','fiestas_wiki','La plaza de toros de Albacete es el coso taurino de la ciudad española de Albacete. Popularmente conocida como «La Chata»,[¿Por qué?] José María de Cossío la calificó como «una de las más excelentes de España» en su monumental tratado taurino El Cossío.​ Entre otros elementos, destaca por la cantidad de festejos…',38.9975,-1.86361111,'https://es.wikipedia.org/wiki/Plaza_de_toros_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187384,'40063','Plaza de toros de Cuéllar','fiesta','fiestas_wiki','La plaza de Toros de Cuéllar es la sede de las corridas de toros que se realizan en la villa segoviana de Cuéllar (Castilla y León), teniendo especial relevancia para los aficionados las que se celebran durante los Encierros de Cuéllar.',41.40317222,-4.30814722,'https://es.wikipedia.org/wiki/Plaza_de_toros_de_Cuéllar','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187385,'90480','Plácido','fiesta','fiestas_wiki','Plácido es una película española dirigida en 1961 por Luis García Berlanga.',NULL,NULL,'https://es.wikipedia.org/wiki/Plácido');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187386,'37011','Poeta ante la Cruz','fiesta','fiestas_wiki','Poeta ante la Cruz es un acto religioso y cultural organizado por la Real Cofradía del Cristo Yacente de la Misericordia y de la Agonía Redentora de Salamanca desde 1986. Cada año la cofradía designa a un poeta que declama sus versos ante el Cristo de la Agonía redentora la tarde del Domingo de Pasión. Las…',NULL,NULL,'https://es.wikipedia.org/wiki/Poeta_ante_la_Cruz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187387,'46218','Porrat de San Macià','fiesta','fiestas_wiki','El "Porrat de San Macià" (San Matías) o Porrat del Interior, que se realiza en Rótova, cuenta con más de cien años de antigüedad y está considerado uno de los más importantes y concurridos dentro de la Ruta de los "Porrats de la Safor", que se celebran de enero a septiembre y que engloba una decena de pequeñas…',38.9325,-0.25805556,'https://es.wikipedia.org/wiki/Porrat_de_San_Macià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187388,'37300','Porrate','fiesta','fiestas_wiki','Un porrate (en valenciano porrat) es una feria que se celebra en la festividad de un santo.​ Se trata de una tradición festiva de la Comunidad Valenciana, España. Su elemento más característico es el mercado al aire libre donde se ponen a la venta productos tradicionales, dulces y frutos secos, y su origen se…',NULL,NULL,'https://es.wikipedia.org/wiki/Porrate');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187389,'45168','Porta Cirio Pascual de la Catedral de Toledo','fiesta','fiestas_wiki','El Porta Cirio Pascual de la Catedral de Toledo es un candelero pascual monumental, de varios metros de altura, hecho a comienzos del siglo XIX en madera policromada, que ha sido restaurado en el siglo XXI y se halla expuesto en el Trascoro de la Catedral de Toledo.​',39.857064,-4.023922,'https://es.wikipedia.org/wiki/Porta_Cirio_Pascual_de_la_Catedral_de_Toledo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187390,'12040','Portal de la Purísima','fiesta','fiestas_wiki','El portal de la Purísima fue una de las puertas de la muralla medieval de Castellón de la Plana (España). Era la puerta situada al norte de las dos con las que contaba la calle Enmedio. Tras su derribo a finales del siglo XVIII su memoria ha permanecido en la cultura popular de los castellonenses a través de la…',39.9885875,-0.03723389,'https://es.wikipedia.org/wiki/Portal_de_la_Purísima');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187391,'06049','Primer Corte de la Miel','fiesta','fiestas_wiki','El Primer Corte de la Miel es una feria gastronómica que se celebra en la localidad española de Ayora.​ El 30 de mayo de 2016 apareció publicada en el Diario Oficial de la Comunidad Valenciana la resolución del 29 de marzo de 2016 por la cual la Presidencia de la Generalidad otorgaba la declaración de Fiesta de…',NULL,NULL,'https://es.wikipedia.org/wiki/Primer_Corte_de_la_Miel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187392,'09139','Primitivo Lázaro','fiesta','fiestas_wiki','Primitivo Lázaro Martínez (Fuentemolinos, Burgos, 2 de marzo de 1909 — Huelva, 10 de mayo de 1997) fue un compositor y pianista español. Ciego desde los tres años de edad, estudió solfeo y piano en el Real Conservatorio de Madrid. Desde 1936 a 1938 residió en la ciudad de Salamanca, donde formó su propia orquesta.',NULL,NULL,'https://es.wikipedia.org/wiki/Primitivo_Lázaro','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187393,'37273','Procesión General de la Sagrada Pasión del Redentor','fiesta','fiestas_wiki','La Procesión General de la Sagrada Pasión del Redentor es una procesión en la que participan todas las cofradías de la Semana Santa de Valladolid, y que se celebra por la tarde del Viernes Santo. Destaca entre todas las procesiones que tienen lugar en España por la cantidad (33 pasos) y calidad de sus obras, muchas…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_General_de_la_Sagrada_Pasión_del_Redentor','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187394,'50297','Procesión General del Santo Entierro (Zaragoza)','fiesta','fiestas_wiki','La Procesión General del Santo Entierro de Cristo es el origen de los cortejos procesionales en la ciudad de Zaragoza.​ Es la procesión más antigua de la ciudad y el acto más multitudinario de la Semana Santa en Zaragoza. Data de 1617 y está organizada por la Hermandad de la Sangre de Cristo. Esta procesión sale de…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_General_del_Santo_Entierro_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187395,'23050','Procesión Magna de 2025 en Jaén','fiesta','fiestas_wiki','Es una Procesión Magna organizada por la diócesis de Jaén con motivo del Jubileo de 2025. Tendrá lugar en la ciudad de Jaén, el próximo 4 de octubre de 2025. Se representarán los veinte misterios del Santo Rosario, mediante veinte imágenes titulares de cofradías y hermandades de la diócesis.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_Magna_de_2025_en_Jaén','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187396,'44046','Procesión de la Buena Muerte','fiesta','fiestas_wiki','La Procesión de la Buena Muerte es una procesión de la Semana Santa de Valladolid organizada por la Venerable Cofradía de la Preciosísima Sangre de Nuestro Señor Jesucristo en la noche del Lunes Santo. El único paso que alumbra la cofradía en esta procesión es el Santo Cristo del Olvido, portado por doce personas.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_de_la_Buena_Muerte','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187397,'47186','Procesión de las Palmas','fiesta','fiestas_wiki','La Procesión de las Palmas tiene lugar el Domingo de Ramos en Valladolid. Tras las dos procesiones que tienen lugar el Viernes de Dolores y la del Sábado de Pasión, es la cuarta de la Semana Santa de Valladolid. Parte de la Santa Iglesia Catedral a las doce de la mañana, terminada la Bendición de Ramos, con el paso…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_de_las_Palmas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187398,'26010','Procesión de los Pasos','fiesta','fiestas_wiki','La Procesión de los Pasos es un desfile religioso penitencial que se celebra en la ciudad de León con objetivo de conmemorar la Pasión de Cristo y Muerte de Cristo. Dicho acto se celebra el Viernes Santo durante la Semana Santa desde el año 1611. Está organizado por la Cofradía del Dulce Nombre de Jesús Nazareno.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_de_los_Pasos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187399,'03016','Procesión del Domingo de Ramos en Elche','fiesta','fiestas_wiki','Se denomina Procesión del Domingo de Ramos de Elche o Procesión de las Palmas a la celebración del primer día de la Semana Santa Ilicitana, Domingo de Ramos, en la ciudad española de Elche, declarada de Interés Turístico Internacional, en que se representa la entrada de Jesús triunfante en Jerusalén. En esta…',38.2669,-0.6983,'https://es.wikipedia.org/wiki/Procesión_del_Domingo_de_Ramos_en_Elche','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187400,'37011','Procesión del Encuentro (Salamanca)','fiesta','fiestas_wiki','La Procesión del Encuentro también conocida como Procesión del Resucitado de Salamanca, se celebra en la mañana del Domingo de Resurrección, cerrando la celebración de la Semana Santa en la ciudad, organizada por la Cofradía de la Vera Cruz.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Encuentro_(Salamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187401,'50297','Procesión del Encuentro (Zaragoza)','fiesta','fiestas_wiki','La Procesión del Encuentro de la Semana Santa en Zaragoza se remonta al siglo XVIII cuando la organizaba en la Venerable Orden Tercera,​ y como tal se siguió celebrando hasta la instauración de la II República española, si bien hubo años, debido a la Guerra de la Independencia o a motivos de penuria económica que…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Encuentro_(Zaragoza)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187402,'90930','Procesión del Humo','fiesta','fiestas_wiki','La procesión del humo es una celebración que se realiza el último domingo de noviembre en Arnedillo (comunidad autónoma de La Rioja, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Humo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187403,'48020','Procesión del Nazareno, Bilbao','fiesta','fiestas_wiki','La Procesión del Nazareno es una tradición que se celebra el lunes siguiente al Domingo de Ramos en los barrios de Bilbao La Vieja, San Francisco y Zabala de Bilbao. Es considerada una de las cinco procesiones más importantes de la Semana Santa bilbaína.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Nazareno,_Bilbao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187404,'30016','Procesión del Santo Entierro (Cartagena)','fiesta','fiestas_wiki','Cada Semana Santa, en la noche del Viernes Santo, la Real e Ilustre Cofradía de Nuestro Padre Jesús Nazareno (conocida popularmente como Cofradía de los Marrajos o Cofradía Marraja) pone en la calle la procesión del Santo Entierro, una de las dos más antiguas de la ciudad de Cartagena, cuyas procesiones están…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Santo_Entierro_(Cartagena)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187405,'37011','Procesión del Santo Entierro (Salamanca)','fiesta','fiestas_wiki','La Procesión del Santo Entierro es un desfile religioso penitencial que se celebra en Salamanca la tarde del Viernes Santo. Se organiza desde 1615 y su cofradía titular es la Vera Cruz. Es la procesión de Semana Santa más antigua que conserva la ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Santo_Entierro_(Salamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187406,'47186','Procesión del Santísimo Rosario del Dolor (Valladolid)','fiesta','fiestas_wiki','La Procesión del Santísimo Rosario del Dolor es una procesión de la Semana Santa de Valladolid que se desarrolla en la tarde del Lunes Santo y en la que participan seis cofradías, cada una portando un paso, representando los Misterios Dolorosos del Rosario: la Oración en el Huerto, el Azotamiento del Señor, la…',NULL,NULL,'https://es.wikipedia.org/wiki/Procesión_del_Santísimo_Rosario_del_Dolor_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187407,'02001','Puerta de Hierros de Albacete','fiesta','fiestas_wiki','La Puerta de Hierro es una puerta monumental de la ciudad española de Albacete, que sirve de entrada principal a su histórico recinto ferial. Situada en el castizo barrio Feria de la capital albaceteña, tiene unas dimensiones de 25 metros de altura por 36 metros de largo y es uno de los símbolos más emblemáticos de…',38.996966,-1.868349,'https://es.wikipedia.org/wiki/Puerta_de_Hierros_de_Albacete','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187408,'09144','Pulpo a la gallega','fiesta','fiestas_wiki','El pulpo a la gallega (en gallego polbo á feira, «pulpo a la feria») es un plato tradicional de Galicia y básico en su gastronomía,​ aunque su consumo se ha generalizado por toda España. Se trata de un plato festivo elaborado con pulpo cocido entero (generalmente en ollas de cobre) que está presente en las fiestas,…',NULL,NULL,'https://es.wikipedia.org/wiki/Pulpo_a_la_gallega','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187409,'15059','Pértiga (liturgia)','fiesta','fiestas_wiki','Una pértiga es, en el contexto de varias tradiciones católicas de España, una vara larga a veces revestida de plata con la que un pertiguero o persona designada puede transmitir algunas órdenes básicas en las procesiones y otros actos, actuando en algún modo como maestro de ceremonia.​ El pertiguero percute el…',NULL,NULL,'https://es.wikipedia.org/wiki/Pértiga_(liturgia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187410,'46250','Pío Mollar Franch','fiesta','fiestas_wiki','Pío Mollar Franch (Valencia, 1878 – Valencia, 28 de agosto de 1953) fue un escultor e imaginero español.',NULL,NULL,'https://es.wikipedia.org/wiki/Pío_Mollar_Franch','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187411,'21061','Quema de las Gamonitas','fiesta','fiestas_wiki','La Quema de las Gamonitas es una festividad popular de carácter anual que se celebra en varios municipios de la provincia de Huelva la noche del 7 de diciembre. Esta denominación es usada en El Condado de Huelva, donde es celebrada en Rociana del Condado y en Bollullos Par del Condado, mientras que en los…',37.3087079,-6.5974266,'https://es.wikipedia.org/wiki/Quema_de_las_Gamonitas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187412,'30038','Quema del raspajo','fiesta','fiestas_wiki','La Quema del raspajo es una antigua tradición de la localidad murciana de Las Torres de Cotillas, en España, que actualmente se alegoriza con la quema de un espantapájaros gigante, como colofón a las fiestas patronales en honor a Nuestra Señora de la Salceda y que procede de una antigua tradición que daba nombre a…',NULL,NULL,'https://es.wikipedia.org/wiki/Quema_del_raspajo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187413,'50222','Quinto (juego)','fiesta','fiestas_wiki','El quinto es un juego típico de las fechas navideñas que se juega en varias localidades del Vallés Occidental, de Ampurdán, del Garraf, y de otras comarcas catalanas. También es popular en Francia y en Valonia (Bélgica). Dependiendo de la zona, se le conoce también por otros nombres, como "Quine" (en francés…',NULL,NULL,'https://es.wikipedia.org/wiki/Quinto_(juego)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187414,'03040','Quintín Esquembre','fiesta','fiestas_wiki','Quintín Esquembre Sáez (Villena, 30 de marzo de 1885-Madrid, 1965) fue un compositor español, guitarrista y finalmente chelista de la Orquesta Nacional de Madrid.​',NULL,NULL,'https://es.wikipedia.org/wiki/Quintín_Esquembre','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187415,'09062','Quivaca','fiesta','fiestas_wiki','La Quivaca es un ser o personaje de aspecto vacuno que forma parte del carnaval de Rabanera del Pinar (provincia de Burgos, comunidad autónoma de Castilla y León, España). La quivaca persigue a los vecinos que acuden al carnaval. Es semejante a la tarasca de las localidades vecinas, como la de Hacinas y Cabezón de…',NULL,NULL,'https://es.wikipedia.org/wiki/Quivaca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187416,'11027','Rafael Alberti','fiesta','fiestas_wiki','Rafael Alberti Merello (El Puerto de Santa María, 16 de diciembre de 1902-El Puerto de Santa María, 28 de octubre de 1999) fue un escritor español, reconocido como poeta, miembro de la generación del 27; considerado uno de los mayores literatos de la Edad de Plata de la literatura española.​ Miembro activo del…',NULL,NULL,'https://es.wikipedia.org/wiki/Rafael_Alberti','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187417,'41087','Rafael Blas Rodríguez','fiesta','fiestas_wiki','Rafael Blas Rodríguez (Sanlúcar la Mayor, 1885-Sevilla, 1961) fue un pintor español que destacó como muralista.',NULL,NULL,'https://es.wikipedia.org/wiki/Rafael_Blas_Rodríguez','IT Internacional');
