INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187419,'33044','Rally Ciudad de Oviedo de 1967','fiesta','fiestas_wiki','El Rally Ciudad de Oviedo de 1967, oficialmente 4.º Rally Ciudad de Oviedo, fue la cuarta edición y la octava cita de la temporada 1967 del Campeonato de España de Rally.',NULL,NULL,'https://es.wikipedia.org/wiki/Rally_Ciudad_de_Oviedo_de_1967','Interés Turístico Regional');
