INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187423,'33044','Rally Ciudad de Oviedo de 1972','fiesta','fiestas_wiki','El Rally Ciudad de Oviedo de 1972, oficialmente 9.º Rallye Ciudad de Oviedo, fue la novena edición y la decimocuarta cita de la temporada 1972 del Campeonato de España de Rally. Se celebró del 7 al 8 de septiembre y contó con un itinerario de nueve tramos que sumaban un total de 109 km cronometrados.​​ En el primer…',NULL,NULL,'https://es.wikipedia.org/wiki/Rally_Ciudad_de_Oviedo_de_1972','Interés Turístico Regional');
