INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187432,'29084','Rally Princesa de Asturias de 2021','fiesta','fiestas_wiki','El Rally Princesa de Asturias de 2021 fue la 58.º edición y séptima ronda de la temporada 2021 del Súper Campeonato de España de Rally. Se celebró del 9 al 11 de septiembre y contó con un itinerario de once tramos que sumaban un total de 152,51 km cronometrados.',NULL,NULL,'https://es.wikipedia.org/wiki/Rally_Princesa_de_Asturias_de_2021','Interés Turístico Regional');
