INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187449,'46212','Real y Calasancia Cofradía del Prendimiento del Señor y el Dolor de la Madre de Dios','fiesta','fiestas_wiki','La Real y Calasancia Cofradía del Prendimiento del Señor y el Dolor de la Madre de Dios es una de las 25 cofradías penitenciales existentes en la Semana Santa zaragozana. Fue fundada en 1947 por 136 exalumnos de las Escuelas Pías de Zaragoza, en cuya iglesia han tenido siempre su sede canónica.',NULL,NULL,'https://es.wikipedia.org/wiki/Real_y_Calasancia_Cofradía_del_Prendimiento_del_Señor_y_el_Dolor_de_la_Madre_de_Dios','IT Internacional');
