INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187472,'30035','Romería de San Blas de Santiago de la Ribera','fiesta','fiestas_wiki','La Romería de San Blas de Santiago de la Ribera es una fiesta popular de San Javier donde se traslada la imagen de San Blas desde la iglesia de Santiago de la Ribera a la ermita. Se celebra cada año el 3 de febrero con motivo de la conmemoración del santo.​ Desde 2004 está declarada Fiesta de interés turístico…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Blas_de_Santiago_de_la_Ribera','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187473,'28513','Romería de San Eugenio','fiesta','fiestas_wiki','La romería de San Eugenio (denominada también como romería de la Bellota) es una celebración festiva de la ciudad de Madrid de finales del mes de noviembre.​ Se celebra en honor a san Eugenio, obispo de Toledo, cuya fiesta, en el anterior calendario litúrgico, estaba fijada en el día 15 de dicho mes. El centro de…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Eugenio');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187474,'10203','Romería de San Isidro (Valencia de Alcántara)','fiesta','fiestas_wiki','La Romería de San Isidro Labrador es una fiesta de interés turístico regional que se celebra en el mes de mayo en Valencia de Alcántara, en la provincia de Cáceres, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Isidro_(Valencia_de_Alcántara)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187475,'14040','Romería de San Isidro Labrador (Montalbán de Córdoba)','fiesta','fiestas_wiki','La Romería de San Isidro Labrador es una romería de carácter popular que se celebra cada 15 de mayo en Montalbán de Córdoba (España).​',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Isidro_Labrador_(Montalbán_de_Córdoba)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187476,'11026','Romería de San Isidro Labrador (Prado del Rey)','fiesta','fiestas_wiki','La Romería de San Isidro Labrador es una Romería de carácter popular que se celebra cada 15 de mayo en Prado del Rey. Actos Empieza el sábado por la tarde donde se suele celebrar una misa romera, copando la noche actuaciones musicales y el baile. El domingo tiene lugar la salida procesional de San Isidro Labrador a…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Isidro_Labrador_(Prado_del_Rey)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187477,'03904','Romería de San Isidro de Badajoz','fiesta','fiestas_wiki','La Romería de San Isidro de Badajoz es la tradicional Romería en honor a San Isidro Labrador celebrada en Badajoz (España), en la dehesa municipal de Tres Arroyos (a unos 4 km del centro urbano), siendo la segunda romería más importante de la localidad después de la Romería de Bótoa. Aunque la fiesta de San Isidro…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Isidro_de_Badajoz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187478,'05219','Romería de San Pascual','fiesta','fiestas_wiki','La Romería de San Pascual es una festividad religiosa y popular que se celebra anualmente el 17 de mayo en la pedanía de Orito, perteneciente al municipio de Monforte del Cid (Alicante) España.​​ Esta romería, que data desde 1637, es una de las más antiguas y concurridas de la Comunidad Valenciana, atrayendo a…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Pascual','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187479,'27047','Romería de San Vitoiro','fiesta','fiestas_wiki','La Romería de San Vitoiro es una festividad que se celebra anualmente en el municipio lucense de Puebla del Brollón, Galicia (España), el 27 de agosto, día festivo local. Tiene lugar junto a una pequeña capilla situada en un valle entre montañas, junto al río Saa, a unos 8 km de la capitalidad municipal. San…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_San_Vitoiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187480,'27047','Romería de Santa Lucía','fiesta','fiestas_wiki','La Romería de Santa Lucía se celebraba en Santalla de Rei, en el municipio lucense de Puebla del Brollón, el penúltimo sábado de agosto en honor a Santa Lucía. La fiesta se celebraba antiguamente el 26 de septiembre y seguía el 27. Era costumbre que vecinos de otras aldeas de la zona fueran a comer al campo de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_Santa_Lucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187481,'90312','Romería de Santerón','fiesta','fiestas_wiki','La Romería de Santerón es una peregrinación a la Ermita de Santerón, situada en el término municipal de Algarra, provincia de Cuenca (Comunidad de Castilla-La Mancha, España). La celebración festivo-religiosa más importante tiene lugar cada siete años -del 16 al 26 de septiembre- y consiste en ir por la imagen de…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_Santerón','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187482,'38046','Romería de Tegueste','fiesta','fiestas_wiki','La Romería de Tegueste o Romería en Honor a San Marcos Evangelista, es una romería popular que se celebra el último domingo de abril en el municipio de Tegueste (Tenerife, Canarias, España). La Romería en honor a San Marcos Evangelista es una de las romerías más populares de la isla y del archipiélago. Miles de…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_Tegueste','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187483,'41038','Romería de Valme','fiesta','fiestas_wiki','La Romería de Valme es una manifestación de religiosidad popular andaluza en honor de la Virgen de Valme que se celebra cada año en la localidad de Dos Hermanas (Sevilla) el tercer domingo de octubre. Aunque erróneamente muchas personas ajenas a la ciudad de Dos Hermanas suelen creer que la Virgen de Valme es la…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_Valme','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187484,'28079','Romería de la Cara de Dios','fiesta','fiestas_wiki','La romería de la Cara de Dios fue una romería celebrada en la ciudad española de Madrid durante la Semana Santa, el día del Viernes Santo.',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_la_Cara_de_Dios');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187485,'28131','Romería de la Virgen de Gracia','fiesta','fiestas_wiki','La Romería de la Virgen de Gracia se celebra el segundo domingo de septiembre. Es la patrona del Real Sitio de San Lorenzo de El Escorial y está declarada Fiesta de Interés Turístico Nacional.',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_la_Virgen_de_Gracia','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187486,'28125','Romería de la Virgen de Navahonda','fiesta','fiestas_wiki','La Romería de la Virgen de Navahonda es una vistosa romería celebrada en primavera en el municipio de Robledo de Chavela (Madrid) España. Desde el año 1113, que discurre por el popular camino de Navahonda (sendero GR-10, de Valencia a Lisboa, camino que utilizaban en otros tiempos, como vía pecuaria, los…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_la_Virgen_de_Navahonda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187487,'16122','Romería de la Virgen del Henar','fiesta','fiestas_wiki','La Romería de la Virgen del Henar, también conocida como Romería del Henar o simplemente El Henar es una romería que se celebra en la pradera del Santuario de Nuestra Señora del Henar, perteneciente al municipio segoviano de Cuéllar (Castilla y León). Se celebra en honor de la Virgen del Henar, una advocación…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_la_Virgen_del_Henar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187488,'37300','Romería de los Santos Mártires de Valdecuna','fiesta','fiestas_wiki','La Romería de los Santos Mártires de Valdecuna es una fiesta española que se celebra cada año el 27 de septiembre en los alrededores del Santuario de San Cosme y San Damián de Insierto, en el Valle de Cuna y Cenera de Asturias.​​ En 1969 fue declarada de Fiesta de Interés Turístico.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_los_Santos_Mártires_de_Valdecuna','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187489,'90506','Romería de los Viriatos','fiesta','fiestas_wiki','La romería de los Viriatos, o de los Pendones, es una romería popular celebrada en honor de la virgen del Castillo el primer domingo de junio en el municipio de Fariza de la provincia de Zamora (Castilla y León, España).​ Declarada de interés turístico regional por la Junta de Castilla y León, cuenta con la…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_de_los_Viriatos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187490,'16122','Romería del Pino','fiesta','fiestas_wiki','La Romería de Nuestra Señora del Pino o Romería del Pino se trata de una manifestación religiosa y popular en honor de la Virgen del Pino. La romería ofrenda se realiza cada 7 de septiembre, vísperas de la festividad de la Virgen del Pino, en la Villa Mariana de Teror. Se trata de una romería impulsada por el…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_del_Pino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187491,'38020','Romería del Socorro','fiesta','fiestas_wiki','La Romería de la Bajada de la Virgen del Socorro, es una romería de carácter popular que se celebra en el mes de septiembre en el municipio de Güímar (Tenerife, Canarias, España). Declarada también Fiestas de Interés Turístico Regional. Es considerada la romería más antigua de todo el Archipiélago Canario,​​ además…',28.32924444,-16.36336944,'https://es.wikipedia.org/wiki/Romería_del_Socorro','Interés Turístico Regional');
