INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187493,'90536','Romería vikinga de Catoira','fiesta','fiestas_wiki','La Romería vikinga de Catoira (oficialmente en gallego, Romaría viquinga de Catoira) es una fiesta profana que se celebra en Catoira, España, en los entornos del castellum honesti, las actuales Torres de Oeste, cada primer domingo de agosto desde 1961, recordando el papel que tuvo Catoira en la defensa de Galicia…',NULL,NULL,'https://es.wikipedia.org/wiki/Romería_vikinga_de_Catoira','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187494,'45079','Rondón (baile)','fiesta','fiestas_wiki','El rondón es un baile tradicional ejecutado en forma de rueda o círculo, típico de la Sierra de Gredos y del Valle del Alberche, en el sur de la provincia de Ávila, la Sierra de San Vicente y La Campana de Oropesa en el norte de Toledo y la Sierra Oeste de Madrid. Es típico de localidades como Candeleda, Sotillo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Rondón_(baile)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187495,'30030','Roque López','fiesta','fiestas_wiki','Roque López Duarte Máyquez (Era Alta, Murcia, 12 de agosto de 1747 – Murcia, Región de Murcia, 14 de octubre de 1811) fue un escultor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Roque_López','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187496,'38032','Rosario de cristal','fiesta','fiestas_wiki','El Rosario de Cristal es uno de los actos más relevantes de las fiestas del Pilar de Zaragoza, aunque poco conocidos fuera de Aragón, es la procesión que tiene lugar la tarde-noche del 13 de octubre.',NULL,NULL,'https://es.wikipedia.org/wiki/Rosario_de_cristal','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187497,'25061','Roscaderos (tauromaquia)','fiesta','fiestas_wiki','La suerte del roscadero es un tipo de tienta llevada a cabo por una cuadrilla que se defiende de las acometidas del toro o vaquilla con la única ayuda de un roscadero.​ La herramienta utilizada en esta suerte es un cesto de mimbre fabricado a mano por artesanos que cultivan su propia mimbre. El mimbre se puede…',NULL,NULL,'https://es.wikipedia.org/wiki/Roscaderos_(tauromaquia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187498,'44025','Ruta del tambor y el bombo','fiesta','fiestas_wiki','En las comarcas del Bajo Aragón, Andorra-Sierra de Arcos y Bajo Martín (todas dentro del Bajo Aragón Histórico), en España, existen nueve localidades pertenecientes a la provincia de Teruel, en las que se puede seguir en Semana Santa una ruta excepcional por el modo especial que tienen de celebrar esos días la…',NULL,NULL,'https://es.wikipedia.org/wiki/Ruta_del_tambor_y_el_bombo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187499,'30030','Saeta (música)','fiesta','fiestas_wiki','La saeta (del latín sagitta, «flecha») es un canto religioso tradicional interpretado fundamentalmente en las procesiones de Semana Santa en España, especialmente en Andalucía y algunas zonas de Extremadura y Murcia.​ En el siglo XIX, Antonio Machado Álvarez definía las saetas como "cancioncillas que tienen por…',NULL,NULL,'https://es.wikipedia.org/wiki/Saeta_(música)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187500,'26004','Salida del Santo','fiesta','fiestas_wiki','La Salida del Santo, abreviada y coloquialmente la Salida, es un acto de carácter religioso y popular que se celebra en la Villa de Bembibre, teniendo como foco y motivo fundamental el Santo Ecce-Homo, congregando esta celebración a todas las poblaciones de la comarca, del Arciprestazgo del Boeza, y limítrofes,…',NULL,NULL,'https://es.wikipedia.org/wiki/Salida_del_Santo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187501,'26010','Salvador Gutiérrez de León (escultor)','fiesta','fiestas_wiki','Salvador Gutiérrez de León y Aguirre "El Viejo" (Málaga, 1777 - Málaga, 1856) fue un escultor español, de los siglos XVIII y XIX, de la saga malagueña de escultores Gutiérrez de León, abuelo del conocido Antonio Gutiérrez de León.',NULL,NULL,'https://es.wikipedia.org/wiki/Salvador_Gutiérrez_de_León_(escultor)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187502,'38026','San Juan Evangelista (Parroquia de la Concepción de La Orotava)','fiesta','fiestas_wiki','San Juan Evangelista es una imagen de Juan el apóstol que se venera en la parroquia matriz de Nuestra Señora de la Concepción​ de la Villa de la Orotava, Tenerife, Canarias.',NULL,NULL,'https://es.wikipedia.org/wiki/San_Juan_Evangelista_(Parroquia_de_la_Concepción_de_La_Orotava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187503,'33014','Sanfermines','fiesta','fiestas_wiki','Las Fiestas de San Fermín, popularmente conocidas como Sanfermines,​ son una Fiesta de Interés Turístico Internacional en honor a San Fermín de Amiens que se celebra, anualmente, en la ciudad de Pamplona, capital de Navarra, de la que es copatrón. Los festejos comienzan con el lanzamiento del chupinazo desde el…',42.81666667,-1.65,'https://es.wikipedia.org/wiki/Sanfermines','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187504,'10067','Sanjuanes (Coria)','fiesta','fiestas_wiki','Los Sanjuanes es un festejo popular taurino que se celebra en la localidad de Coria (Provincia de Cáceres) del 23 al 28 de junio con motivo de la festividad local en honor de San Juan Bautista.',NULL,NULL,'https://es.wikipedia.org/wiki/Sanjuanes_(Coria)','Interés Turístico Regional');
