INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187506,'50020','Santa Águeda, el Carnaval de Kuartango','fiesta','fiestas_wiki','Santa Águeda, el Carnaval de Kuartango es una fiesta que se celebra todos los años desde 2004 el sábado próximo al 5 de febrero, festividad de Santa Águeda, en el Valle Kuartango, Álava (País Vasco).',NULL,NULL,'https://es.wikipedia.org/wiki/Santa_Águeda,_el_Carnaval_de_Kuartango');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187507,'44206','Santo Cristo de San Agustín (Granada)','fiesta','fiestas_wiki','El Cristo de San Agustín es una escultura de madera de carácter devocional, que se conserva en el Convento del Santo Ángel Custodio (Granada, España) y que está atribuida a Jacopo Florentino, quien pudo ejecutarla entre 1520 y 1525.​ Actualmente, la imagen está en usufructo de la Hermandad del Cristo de San Agustín…',NULL,NULL,'https://es.wikipedia.org/wiki/Santo_Cristo_de_San_Agustín_(Granada)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187508,'04063','Santo Encuentro','fiesta','fiestas_wiki','Santo Encuentro o procesión del Encuentro es la denominación de una de las celebraciones religiosas de Semana Santa en España. En ciudades como Se celebra al amanecer del Domingo de Pascua, saliendo por una calle los hombres con la imagen del Cristo resucitado, y por otra calle las mujeres con la imagen de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Santo_Encuentro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187509,'42152','Santo Entierro de Bercianos de Aliste','fiesta','fiestas_wiki','El Santo Entierro de Bercianos de Aliste es un tradicional acto de piedad católico, típico de la Semana Santa en el pueblo Bercianos de Aliste (provincia de Zamora).​ La Semana Santa en esta población tiene su instante álgido en el Viernes Santo, día en el que se recuerda y recrea la Muerte de Jesús de Nazaret…',NULL,NULL,'https://es.wikipedia.org/wiki/Santo_Entierro_de_Bercianos_de_Aliste','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187510,'46044','Santo Ángel Tutelar de la Villa de Ayora','fiesta','fiestas_wiki','La festividad del Santo Ángel de la Villa de Ayora está basada en un hecho milagroso que ocurrió en Ayora en el año (1392).',NULL,NULL,'https://es.wikipedia.org/wiki/Santo_Ángel_Tutelar_de_la_Villa_de_Ayora','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187511,'21021','Santos Varones (Cartaya)','fiesta','fiestas_wiki','El Auto del Descendimiento o de los Santos Varones es una representación dramática litúrgica que se celebra anualmente el Viernes Santo en la Parroquia de San Pedro de Cartaya. Aunque de origen desconocido, se estima que esta tradición supera los siete siglos.​ Actualmente es organizada por la Hermandad Sacramental…',NULL,NULL,'https://es.wikipedia.org/wiki/Santos_Varones_(Cartaya)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187512,'36052','Santuario de Nuestra Señora de Corpiño','fiesta','fiestas_wiki','El santuario de Nosa Señora, más conocido simplemente como O Corpiño, es un santuario situado en Corpiño, en la parroquia de Santa Baia de Losón perteneciente al municipio de Lalín, en una pequeña colina en lo alto del valle del río Deza, a medio camino de la carretera de Silleda a Vila de Cruces.​',42.74527778,-8.21527778,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Corpiño');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187513,'05006','Santuario de la Virgen del Acebo','fiesta','fiestas_wiki','El Santuario de la Virgen del Acebo, llamado también Santuario de Nuestra Señora del Acebo, está construido sobre la cumbre de un monte a una altitud de 1174 m s. n. m., que forma parte de la llamada sierra del Acebo.',43.158675,-6.49901389,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_del_Acebo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187514,'07050','Santísima Virgen de Gloria','fiesta','fiestas_wiki','La Santísima Virgen de Gloria es una imagen que representa a la Virgen María en su dolor. Se venera en el altar del Santísimo Cristo a la Columna, altar colateral de la nave del evangelio de la parroquia de san Juan Bautista de la Villa de la Orotava, Tenerife, Canarias.',NULL,NULL,'https://es.wikipedia.org/wiki/Santísima_Virgen_de_Gloria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187515,'25001','Santísimo Cristo de Ciudadela','fiesta','fiestas_wiki','El Santísimo Cristo de Ciudadela, también llamado Santísimo Cristo de los Paraires es una escultura de madera policromada que representa a Jesucristo de Nazaret crucificado y que se venera en la Iglesia del Santo Cristo de Ciudadela, situada en el casco antiguo de la ciudad de Ciudadela, la antigua capital de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_Ciudadela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187516,'38023','Santísimo Cristo de La Laguna','fiesta','fiestas_wiki','El Santísimo Cristo de La Laguna es una imagen católica de gran valor histórico, artístico, religioso y cultural que representa la imagen de Jesús de Nazaret crucificado. Está situada en San Cristóbal de La Laguna, municipio y ciudad de la isla de Tenerife (Canarias, España). Es una de las imágenes más veneradas de…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_La_Laguna');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187517,'45152','Santísimo Cristo de Valdelpozo','fiesta','fiestas_wiki','El Santísimo Cristo de Valdelpozo es una imagen católica que representa la imagen de Jesús de Nazaret crucificado. Su fiesta se celebra el 3 de mayo desde 1590. Está situado en el municipio de San Martín de Pusa (Toledo, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_Valdelpozo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187518,'18140','Santísimo Cristo de la Buena Muerte (Motril)','fiesta','fiestas_wiki','El Santísimo Cristo de la Buena Muerte de Motril es una obra confeccionada en 1954 por Domingo Sánchez Mesa en madera policromada con un tono marfil y semejante al Cristo de Mora. Al contemplar esta imagen se puede observar el realismo de las heridas y hematomas abiertos por la Crucifixión y el maltrato que sufrió…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_la_Buena_Muerte_(Motril)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187519,'06006','Santísimo Cristo de la Fe (Badajoz)','fiesta','fiestas_wiki','El Santísimo Cristo de la Fe es una imagen religiosa perteneciente a la Hermandad y Cofradía de penitencia de Nuestro Padre Jesús del Amparo, Dulce Nombre del Señor, Santísimo Cristo de la Fe y Nuestra Señora de la Piedad, María Santísima del Mayor Dolor (Hermandad de Santo Domingo (Badajoz)) en la ciudad de…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_la_Fe_(Badajoz)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187520,'47186','Santísimo Cristo de la Luz (Valladolid)','fiesta','fiestas_wiki','El Cristo de la Luz, una de las obras maestras del escultor Gregorio Fernández, fue tallado alrededor de 1630, en pleno apogeo del barroco castellano. Conocida como "La Perla" por su sobrecogedora expresividad, esta imagen es una de las más impactantes del artista. Actualmente, es propiedad del Museo Nacional de…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_la_Luz_(Valladolid)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187521,'07040','Santísimo Cristo de la Sangre (Palma de Mallorca)','fiesta','fiestas_wiki','El Santísimo Cristo de la Sangre o Sant Crist de la Sang es una talla que representa a Jesucristo de Nazaret crucificado que se venera en la Iglesia de la Anunciación de Nuestra Señora, más conocida como Iglesia de la Sangre (Iglesia del Hospital General de Palma de Mallorca)​ en la ciudad de Palma de Mallorca…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_de_la_Sangre_(Palma_de_Mallorca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187522,'38037','Santísimo Cristo del Perdón (Santa Cruz de La Palma)','fiesta','fiestas_wiki','El Santísimo Cristo del Perdón es una imagen de Jesucristo cautivo o maniatado, perteneciente al grupo escultórico de La Negación de San Pedro realizada en 1821 por el escultor Fernando Estévez de Salas para la Parroquia Matriz de El Salvador de Santa Cruz de La Palma.',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_del_Perdón_(Santa_Cruz_de_La_Palma)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187523,'02060','Santísimo Cristo del Sahúco','fiesta','fiestas_wiki','El Santísimo Cristo del Sahúco es una imagen religiosa de gran devoción en la provincia de Albacete, en la comunidad autónoma de Castilla-La Mancha, España. Se encuentra en el Santuario de el Sahúco, una pequeña aldea situada a unos 15 kilómetros de Peñas de San Pedro, y es el centro de una de las romerías más…',NULL,NULL,'https://es.wikipedia.org/wiki/Santísimo_Cristo_del_Sahúco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187524,'11031','Sara Baras','fiesta','fiestas_wiki','Sara Pereyra Baras (San Fernando, Cádiz, España, 25 de abril de 1971),​​ conocida como Sara Baras, es una bailaora, coreógrafa y directora de su compañía de baile española.​',NULL,NULL,'https://es.wikipedia.org/wiki/Sara_Baras','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187525,'35018','Sardiñada','fiesta','fiestas_wiki','La Sardiñada (denominada también como sardinada) es una costumbre culinaria de la cocina gallega (originaria en la provincia de Lugo) en el que se cocinan sardinas (Sardina pilchardus) asadas al aire libre. Se suelen preparar y servir en las romerías gallegas en homenaje a San Bartolomé (24 de agosto).​ Al igual…',NULL,NULL,'https://es.wikipedia.org/wiki/Sardiñada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187526,'09323','Sebastián Santos Rojas','fiesta','fiestas_wiki','Sebastián Santos Rojas (Higuera de la Sierra (Huelva), 2 de noviembre de 1895 - Sevilla, 16 de julio de 1977)​​ fue un imaginero y escultor español. Se especializó en imaginería religiosa.',NULL,NULL,'https://es.wikipedia.org/wiki/Sebastián_Santos_Rojas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187527,'47186','Sed Tengo (Gregorio Fernández)','fiesta','fiestas_wiki','Sed Tengo es una obra realizada por Gregorio Fernández y su taller entre 1612 y 1616. Procesionado el Viernes Santo por la Cofradía de las Siete Palabras, el grupo escultórico está ubicado en el Museo Nacional de Escultura, en Valladolid (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Sed_Tengo_(Gregorio_Fernández)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187528,'30011','Semana Blanca','fiesta','fiestas_wiki','La Semana Blanca es una semana no lectiva docente dentro del calendario escolar de enseñanzas no universitarias en España, para compensar el hecho de que los días festivos locales coinciden con los meses no lectivos del verano. Por ejemplo, en el caso de la ciudad de Málaga que celebra la Feria de Agosto. Esta…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Blanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187529,'04065','Semana Cervantina','fiesta','fiestas_wiki','La Semana Cervantina es una fiesta que se celebra en varias ciudades y municipios de España en honor a Miguel de Cervantes. En unos casos se celebra durante el mes de abril, coincidiendo con el aniversario del fallecimiento de Cervantes, el 22 de abril de 1616; mientras que en otros casos se celebra durante los…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Cervantina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187530,'29001','Semana Cervantina de Alcalá de Henares','fiesta','fiestas_wiki','La Semana Cervantina de Alcalá de Henares es una fiesta de interés turístico nacional que se celebra en la ciudad complutense en honor a Miguel de Cervantes. Tiene lugar durante el mes de octubre, coincidiendo con el aniversario de su bautismo, el 9 de octubre de 1547 en la antigua Iglesia de Santa María.',40.48212,-3.367013,'https://es.wikipedia.org/wiki/Semana_Cervantina_de_Alcalá_de_Henares','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187531,'48020','Semana Grande de Bilbao','fiesta','fiestas_wiki','La Semana Grande de Bilbao, también conocida por su nombre en euskera Aste Nagusia, es la principal fiesta de Bilbao, que se celebra anualmente durante nueve días a partir del sábado siguiente al 15 de agosto, festividad de la Asunción de Nuestra Señora. Su origen se remonta a finales del siglo XIX.​ Hasta la…',43.2622,-2.9533,'https://es.wikipedia.org/wiki/Semana_Grande_de_Bilbao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187532,'20069','Semana Grande de San Sebastián','fiesta','fiestas_wiki','La Semana Grande de San Sebastián (en euskara, Donostiako Aste Nagusia), es una de las principales fiestas del municipio español de San Sebastián, en Guipúzcoa. ​ La Semana Grande tiene lugar siempre la semana alrededor del Día de la Asunción de la Virgen del 15 de agosto,​de sábado a sábado, en la ciudad de San…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Grande_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187533,'16016','Semana Santa Marinera','fiesta','fiestas_wiki','La Semana Santa Marinera es el nombre que recibe la celebración de la Semana Santa en la ciudad de Valencia, capital de la Comunidad Valenciana (España), que tiene lugar en el distrito municipal número 11 llamado Poblats Marítims, que comprende los barrios del Grau, el Cabanyal, el Canyamelar y el CAP de França.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_Marinera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187534,'03038','Semana Santa de Torrevieja','fiesta','fiestas_wiki','La Semana Santa de Torrevieja es una tradición que se celebra en Torrevieja, España. La fecha de celebración siempre varía en función del calendario litúrgico, que marca el inicio y el fin de la cuaresma.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_de_Torrevieja');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187535,'17001','Semana Santa en Aguilar de la Frontera','fiesta','fiestas_wiki','Aguilar de la Frontera es un municipio español situado al suroeste de la provincia de Córdoba, en la comunidad autónoma de Andalucía. Esta población tiene una gran tradición cofrade, contando con un total de 18 hermandades de penitencia que sacan un total de 27 pasos que realizan estación de penitencia entre el…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Aguilar_de_la_Frontera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187536,'02001','Semana Santa en Albacete','fiesta','fiestas_wiki','La Semana Santa de Albacete es un gran evento de carácter religioso, social y cultural que se celebra cada año en la ciudad española de Albacete.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Albacete','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187537,'46013','Semana Santa en Alboraya','fiesta','fiestas_wiki','La Semana Santa de Alboraya se celebra en dicha población de la Huerta Norte (Valencia) y la organiza la Junta Local de Hermandades de Semana Santa. El calendario de celebración de la Semana Santa tiene lugar a principios de la primavera, aunque actos como el pregón se celebran unas semanas antes. Declarada Fiesta…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Alboraya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187538,'29001','Semana Santa en Alcalá de Henares','fiesta','fiestas_wiki','La Semana Santa de Alcalá de Henares conmemora anualmente la pasión, muerte y resurrección de Jesucristo, entre el Domingo de Ramos y el Domingo de Resurrección. Esta manifestación de religiosidad popular católica es llevada a cabo por hermandades y cofradías, algunas con varios siglos de historia.',40.480467,-3.36942,'https://es.wikipedia.org/wiki/Semana_Santa_en_Alcalá_de_Henares','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187539,'43002','Semana Santa en Alcañiz','fiesta','fiestas_wiki','La Semana Santa de Alcañiz es una fiesta de carácter cristiano que conmemora la pasión, muerte y resurrección de Jesucristo.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Alcañiz','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187540,'46017','Semana Santa en Alcira','fiesta','fiestas_wiki','La Semana Santa de Alzira, declarada de Interés Turístico Nacional, es una fiesta religiosa celebrada en la ciudad de Alcira, en la provincia de Valencia, que conmemora la pasión y muerte de Jesucristo. Sus inicios se remontan al siglo XVI. En la actualidad cuenta con dieciocho cofradías y hermandades y con…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Alcira','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187541,'16002','Semana Santa en Algeciras','fiesta','fiestas_wiki','La Semana Santa de Algeciras es la fiesta de conmemoración de la pasión, muerte y resurrección de Cristo para la comunidad católica de la ciudad de Algeciras. Sus actos principales son las procesiones realizadas entre el Domingo de Ramos y el Domingo de Resurrección. Estas procesiones son organizadas por sus…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Algeciras');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187542,'46079','Semana Santa en Alicante','fiesta','fiestas_wiki','La Semana Santa en Alicante es la celebración de la pasión, muerte y resurrección de Jesucristo a través de las procesiones que realizan las diferentes cofradías a la concatedral de San Nicolás de Bari de la ciudad de Alicante durante el periodo comprendido entre el Domingo de Ramos y el Domingo de Resurrección. A…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Alicante','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187543,'04004','Semana Santa en Almería','fiesta','fiestas_wiki','La Semana Santa de Almería representa la Pasión, muerte y resurrección de Jesucristo con las procesiones que recorren las calles de la ciudad, acompañadas por penitentes y devotos. La salida procesional de una hermandad durante esta semana recibe el nombre de estación de penitencia. Existen procesiones similares en…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Almería','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187544,'44025','Semana Santa en Andorra (Teruel)','fiesta','fiestas_wiki','La Semana Santa de Andorra es una celebración religiosa y de folclore declarada de Interés Turístico Internacional, formando parte de la denominada Ruta del tambor y el bombo del Bajo Aragón turolense junto a las localidades de Albalate del Arzobispo, Alcañiz, Alcorisa, Calanda, Híjar, La Puebla de Híjar, Samper de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Andorra_(Teruel)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187545,'32002','Semana Santa en Antequera','fiesta','fiestas_wiki','La Semana Santa en Antequera es, desde el punto de vista litúrgico y cultural, uno de los acontecimientos más importantes que se produce cada año en la ciudad española de Antequera. La Semana Santa abarca desde el Domingo de Ramos hasta el siguiente domingo, el Domingo de Resurrección. Cada día se procesionan…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Antequera','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187546,'30009','Semana Santa en Archena','fiesta','fiestas_wiki','La Semana Santa de Archena es el conjunto de actos, festividades y encuentros realizados en la localidad con relación a la Semana Santa y la Cuaresma. Los actos conmemorativos de la Pasión de Cristo en Archena vienen teniendo lugar desde hace 500 años aproximadamente. Y siguen vigentes en nuestros días gracias a la…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Archena','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187547,'29094','Semana Santa en Arenas','fiesta','fiestas_wiki','La Semana Santa es una fiesta de gran arraigo de la localidad de Arenas, en la provincia de Málaga. Este municipio se encuentra en la comarca de la Axarquía, a 10 kilómetros de Vélez-Málaga y a 15 de Torre del Mar, en la Costa del Sol Oriental. Las celebraciones principales de la Semana Santa de Arenas comienzan…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Arenas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187548,'26002','Semana Santa en Astorga','fiesta','fiestas_wiki','La Semana Santa en Astorga es uno de los principales acontecimientos culturales, religiosos y turísticos de esta ciudad española. Entre el Viernes de Dolores y el Domingo de Resurrección procesionan ocho cofradías y hermandades, a las que se une la Junta Profomento de la Semana Santa, que desfilan un gran elenco de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Astorga','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187549,'90158','Semana Santa en Ateca','fiesta','fiestas_wiki','La Semana Santa en Ateca es una celebración de índole religioso cultural que se celebra con motivo de la Semana Santa en la villa zaragozana de Ateca. Está declarada de interés turístico Regional​ el 22-11-1996 publicado en BOA de 16-12-1996.​ El origen de esta celebración nos remonta al siglo XVI, pero es en 1660…',41.33083333,-1.79277778,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ateca','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187550,'05002','Semana Santa en Avilés','fiesta','fiestas_wiki','La Semana Santa de Avilés se celebra en la localidad asturiana de Avilés, y está considerada Fiesta de Interés Turístico Regional por el Principado de Asturias La fiesta comprende todos los actos relacionados con la Semana Santa, tanto de carácter religioso como lúdico.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Avilés','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187551,'46044','Semana Santa en Ayora','fiesta','fiestas_wiki','La Semana Santa de Ayora es una de las principales celebraciones que tienen lugar en el municipio de Ayora, ubicado en la Comunidad Valenciana, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ayora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187552,'06006','Semana Santa en Badajoz','fiesta','fiestas_wiki','La Semana Santa de Badajoz, declarada Fiesta de Interés Turístico Internacional,​ se celebra en la ciudad de Badajoz (España), y sus orígenes se remontan al siglo XVI.​ Declarada como Fiesta de Interés Turístico Internacional en enero de 2025, habiéndose iniciado los trámites para conseguir tal declaración en 2016,…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Badajoz','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187553,'24010','Semana Santa en Baeza','fiesta','fiestas_wiki','La Semana Santa en Baeza es la conmemoración anual de la Pasión, Muerte y Resurrección de Cristo llevada a cabo a través de los cultos externos de las corporaciones penitenciales —y tres gloriosas— de la ciudad con ocasión de la celebración litúrgica de la Pasión y la Pascua en el seno de la Iglesia católica. Entre…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Baeza','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187554,'24013','Semana Santa en Beas de Segura','fiesta','fiestas_wiki','La Semana Sant en Beas de Segura, de la provincia de Jaén, Andalucía, es uno de los acontecimientos religiosos y culturales más importantes y arraigados de este pueblo, donde se conmemora la Pasión, Muerte y Resurrección de Jesucristo con la celebración de diversos actos litúrgicos y estaciones penitenciales.…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Beas_de_Segura');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187555,'49021','Semana Santa en Benavente','fiesta','fiestas_wiki','La Semana Santa de Benavente, provincia de Zamora, España, es una manifestación de religiosidad popular católica que conmemora la Pasión, Muerte y Resurrección de Cristo en los días que anteceden a la Pascua. Como en muchos otros lugares de Castilla y León, la Semana Santa se caracteriza por la sobriedad. Su…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Benavente');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187556,'46054','Semana Santa en Benetúser','fiesta','fiestas_wiki','La Semana Santa de Benetúser es una de las Semanas Santas más importantes de la Provincia de Valencia (España), puesto que es una de las primeras en las que se decidió realizar una representación de las escenas sacras en los entornos del municipio, siendo el único municipio de España en el que se integran las…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Benetúser','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187557,'90805','Semana Santa en Beniaján','fiesta','fiestas_wiki','La Semana Santa de Beniaján es el conjunto de actos que se realizan en la localidad de Beniaján (Murcia) durante la Semana Santa. Se trata de unas celebraciones muy tradicionales cuya antigüedad se remonta a siglos pasados, constituyendo en la actualidad uno de los periodos festivos más representativos y arraigados…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Beniaján');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187558,'48020','Semana Santa en Bilbao','fiesta','fiestas_wiki','La Semana Santa en Bilbao (Vizcaya) España. Es un acontecimiento cultural, religioso y de atracción turística. Entre el Viernes de Dolores y el Domingo de Resurrección se celebran en Bilbao 14 procesiones en las que participan las 9 cofradías penitenciales de la villa, agrupadas en la Hermandad de Cofradías…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Bilbao');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187559,'13023','Semana Santa en Bolaños de Calatrava','fiesta','fiestas_wiki','La Semana Santa de Bolaños es uno de los acontecimientos religiosos más importantes que se produce cada año en la localidad, desde el punto de vista religioso y cultural, su celebración comparte características con la del resto de pueblos del Campo de Calatrava. Lo que le ha valido la declaración de fiesta de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Bolaños_de_Calatrava','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187560,'50297','Semana Santa en Borja (Zaragoza)','fiesta','fiestas_wiki','La Semana Santa en Borja es una de las celebraciones más arraigadas y populares de la ciudad de Borja, en la provincia de Zaragoza.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Borja_(Zaragoza)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187561,'09003','Semana Santa en Burgos','fiesta','fiestas_wiki','La Semana Santa en Burgos es una celebración religiosa declarada Fiesta de Interés Turístico Nacional (Fiestas de Interés Turístico Nacional).​ Comienza el Jueves de Pasión y termina el Domingo de Resurrección. Participan dieciséis Hermandades y Cofradías que componen la Junta de Semana Santa de Burgos, encargada…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Burgos','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187562,'17006','Semana Santa en Cabra','fiesta','fiestas_wiki','La Semana Santa de Cabra es uno de los más importantes acontecimientos que se desarrollan cada año en la ciudad, desde el punto de vista cultural, religioso, artístico y participativo. Esta fiesta, goza de una antiquísima tradición, muestra de la cual es la fecha de fundación de la Archicofradía de la Vera+Cruz,…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cabra','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187563,'44051','Semana Santa en Calanda (Teruel)','fiesta','fiestas_wiki','La Semana Santa de Calanda (Teruel) es una celebración religiosa y de folclore declarada de Interés Turístico Nacional e Internacional, formando parte de la denominada Ruta del Tambor y el Bombo del Bajo Aragón Turolense junto a las localidades de Albalate del Arzobispo, Alcañiz, Alcorisa, Andorra, Híjar, La Puebla…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Calanda_(Teruel)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187564,'50067','Semana Santa en Calatayud','fiesta','fiestas_wiki','La Semana Santa de Calatayud es una fiesta de interés turístico regional que se celebra de forma anual durante la Semana Santa en la localidad de Calatayud, Aragón (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Calatayud','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187565,'30016','Semana Santa en Cartagena','fiesta','fiestas_wiki','Como en la mayor parte de España, la celebración de la Semana Santa se hace presente cada año en Cartagena con la organización de procesiones. Estas se extienden, con la primera procesión de España, desde la Madrugada del Viernes de Dolores, festividad de la patrona de la ciudad (la Virgen de la Caridad), hasta el…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cartagena','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187566,'26010','Semana Santa en Castilla y León','fiesta','fiestas_wiki','La Semana Santa en Castilla y León es, como en muchas otras comunidades autónomas españolas, una importante manifestación cultural y popular que gira en torno a la celebración religiosa cristiana de la Semana Santa. De gran variedad en cada una de las provincias, algunas como la de Valladolid son destacadas por el…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Castilla_y_León');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187567,'16007','Semana Santa en Chiclana de la Frontera','fiesta','fiestas_wiki','La Semana Santa en Chiclana de la Frontera tiene lugar entre los meses de marzo y abril, coincidiendo con la primera luna llena de primavera. En ella se conmemora la Pasión, Muerte y Resurrección de Jesús, iniciándose el Domingo de Ramos y finalizando el Domingo de Resurrección. Por el centro de la ciudad, se…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Chiclana_de_la_Frontera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187568,'30019','Semana Santa en Cieza','fiesta','fiestas_wiki','La Semana Santa de Cieza es el conjunto de ritos católicos que se realizan en la localidad de Cieza, Murcia, durante la Semana Santa. La Semana Santa de Cieza cuenta con más de 600 años de antigüedad y es el acto más turístico de la localidad murciana. Fue declarada de Interés Turístico Regional en el año 1993 y…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cieza','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187569,'13004','Semana Santa en Ciudad Real','fiesta','fiestas_wiki','La Semana Santa de Ciudad Real es uno de los más importantes acontecimientos que se produce cada año en la ciudad, desde el punto de vista religioso y cultural, celebrándose en la semana del primer plenilunio de la primavera, que da muestras de su antiquísima tradición basada en celebraciones paganas anteriores al…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ciudad_Real','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187570,'31077','Semana Santa en Corella','fiesta','fiestas_wiki','La Semana Santa de Corella es una fiesta de interés turístico celebrada en la localidad navarra de Corella.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Corella','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187571,'40063','Semana Santa en Cuéllar','fiesta','fiestas_wiki','La Semana Santa en Cúellar es una fiesta cristiana que conmemora la Pasión, Muerte y Resurrección de Cristo. En ella participan 4 cofradías y unos 700 cofrades en diversos actos y procesiones por toda la Villa.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cuéllar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187572,'10037','Semana Santa en Cáceres','fiesta','fiestas_wiki','La Semana Santa en Cáceres, declarada de Interés Turístico Internacional en 2011,​ dura ocho días (desde el Domingo de Ramos hasta el Domingo de Resurrección), diez si se cuenta los traslados procesionales, el Viernes de Dolores y el Sábado de Pasión, de varias cofradías. Sus pasos son de tradición castellana, es…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cáceres','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187573,'16009','Semana Santa en Cádiz','fiesta','fiestas_wiki','La Semana Santa de Cádiz representa la pasión, muerte y resurrección de Jesucristo con conjuntos escultóricos que procesionan sobre pasos por las calles de la ciudad. Esto están acompañados por penitentes (conocidos como nazarenos en otras localidades) y devotos. La salida procesional de una hermandad durante esta…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Cádiz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187574,'14021','Semana Santa en Córdoba','fiesta','fiestas_wiki','La Semana Santa de Córdoba representa la Pasión, Muerte y Resurrección de Jesucristo con grupos escultóricos que procesionan (pasos) por las calles de la ciudad, acompañados por penitentes y devotos. Existen procesiones similares en otras ciudades de Andalucía, España. La salida procesional de la hermandad esta…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Córdoba','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187575,'41041','Semana Santa en Estepa','fiesta','fiestas_wiki','La Semana Santa en Estepa es uno de los más importantes acontecimientos que se produce cada año en la ciudad, desde el punto de vista religioso, celebrándose en la semana del primer plenilunio de la primavera. La Semana Santa de esta ciudad es una de las más importantes de toda la provincia de Sevilla. Está…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Estepa','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187576,'46131','Semana Santa en Gandía','fiesta','fiestas_wiki','La Semana Santa de Gandía es una fiesta religiosa que se celebra en Gandía sin interrupción desde el año 1951, cuando se retomó la fiesta de conmemoración de la pasión y muerte de Jesús tras la Guerra Civil Española. Fue declarada Fiesta de Interés Turístico en 1983.​ y Fiesta de Interés Turístico Nacional en…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Gandía','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187577,'18087','Semana Santa en Granada','fiesta','fiestas_wiki','La Semana Santa de Granada representa la Pasión de Jesucristo con las procesiones que salen sobre pasos por las calles de la ciudad, acompañadas por nazarenos, camareras, acólitos, penitentes y devotos. La salida procesional de una hermandad durante esta semana recibe el nombre de estación de penitencia. Fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Granada','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187578,'19130','Semana Santa en Guadalajara','fiesta','fiestas_wiki','La Semana Santa de Guadalajara (España) es una muestra de religiosidad popular y una manifestación de cultura tradicional de enorme arraigo entre todos los guadalajareños. Se desarrolla por el casco histórico de la ciudad y da comienzo con la lectura del pregón de Semana Santa en la Concatedral de Santa María el…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Guadalajara','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187579,'02014','Semana Santa en Hellín','fiesta','fiestas_wiki','La Semana Santa de Hellín es el conjunto de actos que se realizan en la ciudad de Hellín, Albacete (España) durante la Semana Santa. Está declarada Fiesta de Interés Turístico Internacional, también está declarada por la UNESCO patrimonio inmaterial de la humanidad en 2018. Las tamboradas y las procesiones en…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Hellín','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187580,'23044','Semana Santa en Huelma','fiesta','fiestas_wiki','La Semana Santa de Huelma es la conmemoración anual de la Pasión, Muerte y Resurrección de Cristo llevada a cabo a través de los cultos externos de las cofradías penitenciales desde el Domingo de Ramos al Domingo de Resurrección.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Huelma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187581,'21041','Semana Santa en Huelva','fiesta','fiestas_wiki','La Semana Santa de Huelva, fiesta de Interés Turístico Nacional desde el 2003, representa la pasión, muerte y resurrección de Jesucristo con grupos escultóricos que procesionan sobre altares efímeros (pasos) por las calles de la ciudad, acompañados por penitentes y devotos. La salida procesional de una hermandad…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Huelva','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187582,'23050','Semana Santa en Jaén','fiesta','fiestas_wiki','La Semana Santa de Jaén es la celebración de la pasión, muerte y resurrección de Cristo a través de las procesiones que realizan las cofradías en esos días por la capital del Santo Reino. Además del incuestionable aspecto religioso, que la convierte en el acontecimiento de esta índole más importante de la ciudad de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Jaén','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187583,'11020','Semana Santa en Jerez de la Frontera','fiesta','fiestas_wiki','Declarada de Interés Turístico Nacional​ el 25 de febrero de 1993, y a expensas de ser declarada de Interés Turístico Internacional,​ la Semana Santa de Jerez de la Frontera es un gran evento de carácter religioso, social y cultural que conmemora la Pasión, Muerte y Resurrección de Cristo. Se celebra anualmente en…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Jerez_de_la_Frontera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187584,'30022','Semana Santa en Jumilla','fiesta','fiestas_wiki','La Semana Santa de Jumilla cuenta con más de 600 años de historia, es una de las más antiguas de España y está declarada de Interés Turístico desde febrero de 1980, de Interés Turístico Nacional desde diciembre de 2003​ y de Interés Turístico Internacional desde mayo de 2019,​ siendo también reconocida con la…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Jumilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187585,'46250','Semana Santa en Játiva','fiesta','fiestas_wiki','La Semana Santa de Játiva (en valenciano, Setmana Santa de Xàtiva) es una fiesta religiosa y cultural celebrada en la ciudad de Játiva, en la provincia de Valencia, que conmemora la pasión y muerte de Jesucristo. Está formada por dieciséis cofradías y organizada por la Hermandad de Cofradías de Semana Santa.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Játiva','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187586,'38026','Semana Santa en La Orotava','fiesta','fiestas_wiki','La Semana Santa de la Villa de La Orotava es uno de los acontecimientos religiosos más importantes de la localidad. Una cadena de fervores y evocaciones que recogen de forma mística y ensimismada la celebración de la Muerte y Resurrección de Cristo, una tradición que forma parte de la religiosidad y cultura orotavense.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_La_Orotava');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187587,'38051','Semana Santa en La Victoria de Acentejo','fiesta','fiestas_wiki','Cada año, se celebran en La Victoria de Acentejo una de las fiestas más importantes del municipio: la Semana Santa. Desde el Viernes de Dolores hasta el Domingo de Resurrección se celebran actos que conmemoran la Pasión, muerte y resurrección de Jesucristo.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_La_Victoria_de_Acentejo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187588,'35016','Semana Santa en Las Palmas de Gran Canaria','fiesta','fiestas_wiki','La Semana Santa de Las Palmas de Gran Canaria es celebrada en la ciudad que lleva su nombre, en la isla de Gran Canaria. Abarca el período desde el Domingo de Ramos al Domingo de Resurrección.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Las_Palmas_de_Gran_Canaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187589,'21044','Semana Santa en Lepe','fiesta','fiestas_wiki','La Semana Santa en Lepe es una conmemoración católica y folclórica de carácter anual del municipio de Lepe, provincia de Huelva.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Lepe');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187590,'26010','Semana Santa en León','fiesta','fiestas_wiki','La Semana Santa en León es uno de los principales acontecimientos culturales, religiosos y turísticos de esta ciudad española. Entre el Viernes de Dolores y el Domingo de Resurrección procesionan dieciséis cofradías, algunas de las cuales se remontan a los siglos XVI y XVII, que desfilan grupos escultóricos…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_León','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187591,'23055','Semana Santa en Linares','fiesta','fiestas_wiki','La Semana Santa de Linares es uno de los principales acontecimientos culturales, religiosos y de atracción turística de Linares (Jaén). Está declarada Fiesta de Interés Turístico Nacional de Andalucía desde 1998,​y destaca por las Bandas de Cabecera de las cofradías y hermandades, los tercios de trompeteros, la…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Linares','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187592,'46147','Semana Santa en Liria','fiesta','fiestas_wiki','La Semana Santa de Liria, Comunidad Valenciana, España, es la conmemoración de la pasión y muerte de Cristo a través de las procesiones que realizan las cofradías, durante el periodo comprendido entre el Domingo de Ramos y el Domingo de Resurrección. A lo largo de esos días, tres cofradías realizan su recorrido por…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Liria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187593,'18122','Semana Santa en Loja','fiesta','fiestas_wiki','La Semana Santa de Loja es una celebración de la Semana Santa que se celebra en la ciudad española de Loja, provincia de Granada. Constituye la más importante manifestación de cultura popular de Loja a lo largo y ancho del año. La Semana Santa de Loja, hunde su fundamento en la tradición devota de una parte bien…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Loja','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187594,'30024','Semana Santa en Lorca','fiesta','fiestas_wiki','La Semana Santa de Lorca es una de las más destacadas manifestaciones populares de celebración de la Semana Santa en España, habiendo sido declarada como fiesta de Interés Turístico Internacional en 2007.​ Actualmente se trabaja intensamente en la candidatura a ser preseleccionada para la declaración como…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Lorca','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187595,'14038','Semana Santa en Lucena','fiesta','fiestas_wiki','La Semana Santa de Lucena en la Provincia de Córdoba es una de las festividades religiosas más importantes de la localidad. En ella se representa la Pasión, Muerte y Resurrección de Cristo con la procesión de 17 cofradías y una agrupación parroquial, iniciándose el Domingo de Ramos y culminando el Domingo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Lucena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187596,'28079','Semana Santa en Madrid','fiesta','fiestas_wiki','Semana Santa en Madrid es la celebración popular de la pasión, muerte y resurrección de Cristo en la capital de España. Esta manifestación de religiosidad popular católica es llevada a cabo por un grupo de hermandades, cofradías, congregaciones y esclavitudes, algunas con varios siglos de historia​ que realizan…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187597,'23060','Semana Santa en Martos','fiesta','fiestas_wiki','La Semana Santa de Martos es una de las manifestaciones religiosas, culturales y populares más bellas y reconocidas de la provincia de Jaén y de Andalucía. Declarada Fiesta de Interés Turístico Nacional de Andalucía mediante resolución de 18 de junio de 2002, debido a la antigüedad en su celebración, originalidad y…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Martos','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187598,'08121','Semana Santa en Mataró','fiesta','fiestas_wiki','La Semana Santa en Mataró representa la Pasión de Jesucristo con conjuntos escultóricos que procesionan (pasos) por las calles de la ciudad, acompañados por penitentes y devotos. En ella se muestran diversos tipos de pasos, desde los de estilo andaluz hasta los propios, catalanes. Todas las cofradías y hermandades…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Mataró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187599,'11023','Semana Santa en Medina Sidonia','fiesta','fiestas_wiki','La Semana Santa es una celebración muy arraigada a la cultura asidonense.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Medina_Sidonia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187600,'47086','Semana Santa en Medina de Rioseco','fiesta','fiestas_wiki','Semana Santa de Medina de Rioseco es un acontecimiento religioso, cultural y turístico de la ciudad del Medina de Rioseco, situada en la provincia de Valladolid (España). En 1985 fue declarada por la Secretaría General de Turismo, dependiente del Ministerio de Industria, Turismo y Comercio, como Fiesta de Interés…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Medina_de_Rioseco','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187601,'47085','Semana Santa en Medina del Campo','fiesta','fiestas_wiki','La celebración de la Semana Santa en Medina del Campo es una fiesta declarada de Interés Turístico Internacional. En la actualidad cuenta con nueve cofradías penitenciales y aproximadamente 2800 cofrades, que participan en diecisiete desfiles procesionales.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Medina_del_Campo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187602,'52001','Semana Santa en Melilla','fiesta','fiestas_wiki','La Semana Santa de Melilla es una celebración religiosa de tradición católica que tiene lugar cada año en la ciudad autónoma de Melilla (España), durante la última semana de Cuaresma, entre el Domingo de Ramos y el Domingo de Resurrección. Forma parte de las manifestaciones de religiosidad popular de la Iglesia…',35.29444444,-2.935,'https://es.wikipedia.org/wiki/Semana_Santa_en_Melilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187603,'46171','Semana Santa en Moncada','fiesta','fiestas_wiki','La Semana Santa de Moncada fue declarada en su día fiesta de interés nacional. Las representaciones del Misterio de la Pasión en Moncada, se iniciaron el Jueves Santo del año 1959. Los primeros años, se montaron los escenarios en distintos emplazamientos del municipio, la Plaza de los Mártires, Plaza de San Jaime,…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Moncada','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187604,'30029','Semana Santa en Mula','fiesta','fiestas_wiki','La Semana Santa en Mula es el conjunto de ritos católicos que se realizan en la ciudad de Mula, durante la Semana Santa.​ Durante ella se celebra la tamborada característica con sus orígenes a mediados del siglo XIX, que representa una forma de crítica al poder establecido.',38.04194444,-1.49055556,'https://es.wikipedia.org/wiki/Semana_Santa_en_Mula','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187605,'30030','Semana Santa en Murcia','fiesta','fiestas_wiki','La Semana Santa de Murcia es una fiesta religiosa declarada de Interés Turístico Internacional que se desarrolla cada año entre el Viernes de Dolores y el Domingo de Resurrección en la ciudad de Murcia (España). Se trata de una de las Semanas Santas españolas de mayor importancia tanto por su excelente patrimonio…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Murcia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187606,'29067','Semana Santa en Málaga','fiesta','fiestas_wiki','La Semana Santa de Málaga es un gran evento de carácter religioso, social y cultural que se celebra cada año en la ciudad de Málaga. Tienen lugar desfiles procesionales desde el Domingo de Ramos hasta el Viernes Santo, quedando el Sábado Santo como lapso hasta el Domingo de Resurrección. Durante la Cuaresma y hasta…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Málaga','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187607,'06018','Semana Santa en Mérida','fiesta','fiestas_wiki','La Semana Santa de Mérida (España), declarada fiesta de Interés Turístico Internacional,​ es uno de los más importantes acontecimientos religiosos y culturales de la ciudad, atrayendo cada año a miles de visitantes a la capital de Extremadura, para contemplar el paso de las distintas hermandades y cofradías por las…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Mérida','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187608,'45121','Semana Santa en Ocaña','fiesta','fiestas_wiki','La Semana Santa de Ocaña, Toledo (declarada de Interés Turístico Nacional) se resume en siglos de Fe, de tradición viva, de sobria espiritualidad y penitencia. Generación tras generación se han mantenido casi intactas las mismas tradiciones y se ha transmitido de padres a hijos la devoción y sus formas de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ocaña','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187609,'11024','Semana Santa en Olvera','fiesta','fiestas_wiki','La Semana Santa en Olvera es uno de los más importantes acontecimientos que se produce cada año en la ciudad, desde el punto de vista religioso, celebrándose en la semana del primer plenilunio de la primavera, donde se conmemora la Pasión, Muerte y Resurrección de Jesucristo con la celebración de diversos actos…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Olvera','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187610,'03027','Semana Santa en Orihuela','fiesta','fiestas_wiki','La Semana Santa de Orihuela, es una fiesta religiosa, declarada de interés turístico internacional, en el año 2010,​​ representa otro atractivo cultural de la ciudad junto a su casco histórico que goza del reconocimiento como Conjunto Histórico-artístico y Monumental desde 1969.​​ Hay procesiones el Viernes de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Orihuela','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187611,'34120','Semana Santa en Palencia','fiesta','fiestas_wiki','La Semana Santa de Palencia destaca por su sobriedad, silencio, sencillez y solemnidad. Es una Fiesta declarada de Interés Turístico Internacional,​ título que comparte con ciudades vecinas como Valladolid, León o Zamora.​ Asimismo, es una de las celebraciones de este tipo más antiguas de España, ya que los…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Palencia','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187612,'07040','Semana Santa en Palma de Mallorca','fiesta','fiestas_wiki','La Semana Santa de Palma de Mallorca es una celebración cristiana que conmemora la pasión, muerte y resurrección de Cristo. Del Domingo de Ramos al Domingo de Pascua, excluyendo el Sábado Santo y añadiendo el Viernes de los Dolores, 33 cofradías participan en los actos procesionales de la ciudad. Durante este…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Palma_de_Mallorca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187613,'36011','Semana Santa en Pontevedra','fiesta','fiestas_wiki','La Semana Santa en Pontevedra es un ciclo de actos conmemorativos de la Pasión de Cristo llevados a cabo en la ciudad española de Pontevedra desde el Domingo de Ramos hasta el Domingo de Resurrección. La Semana Santa de Pontevedra es una tradición religiosa y cultural profundamente arraigada en la ciudad, que…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187614,'33051','Semana Santa en Pravia','fiesta','fiestas_wiki','La Semana Santa en Pravia es la celebración cristiana que conmemora la pasión, muerte y resurrección de Cristo en la localidad asturiana de Pravia.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Pravia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187615,'14056','Semana Santa en Puente Genil','fiesta','fiestas_wiki','La Semana Santa de Puente Genil, más conocida como la "Mananta", conmemora la pasión, muerte y resurrección de Cristo. Desde el Viernes de Dolores hasta el Domingo de Resurrección, un total de 23 hermandades recorren las calles haciendo estación de penitencia. Ostenta desde 1980 el título de Interés Turístico por…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Puente_Genil');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187616,'28125','Semana Santa en Robledo de Chavela','fiesta','fiestas_wiki','En la Semana Santa de Robledo de Chavela (Madrid) sobresalen dos manifestaciones populares especialmente interesantes: la Procesión de la Virgen de los Dolores y el Día del Judas.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Robledo_de_Chavela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187617,'29084','Semana Santa en Ronda','fiesta','fiestas_wiki','La Semana Santa en Ronda, declarada de Interés Turístico Andaluz, es, desde el punto de vista religioso, uno de los más importantes acontecimientos que se produce cada año en la ciudad, celebrándose en la semana del primer plenilunio de la primavera. La semana abarca desde el Domingo de Ramos hasta el siguiente…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ronda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187618,'24139','Semana Santa en Sahagún','fiesta','fiestas_wiki','La Semana Santa en Sahagún es una fiesta declarada de Interés Turístico Regional y Nacional.​​ A lo largo de la misma, la Cofrafía de Jesús Nazareno y Patrocinio de San José y la Hermandad penitencial de la Santa Vera Cruz recorren las calles de la villa del Domingo de Ramos al Domingo de Resurrección. Cumple con…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Sahagún','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187619,'37011','Semana Santa en Salamanca','fiesta','fiestas_wiki','La Semana Santa en Salamanca es una de las celebraciones más arraigadas de la ciudad y constituye el principal acontecimiento religioso de la capital charra, con sus consecuentes connotaciones culturales y turísticas. Con alrededor de diez mil cofrades, la ciudad fue pionera en la inclusión de la mujer en las…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Salamanca','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187620,'38023','Semana Santa en San Cristóbal de La Laguna','fiesta','fiestas_wiki','La Semana Santa en la ciudad de San Cristóbal de La Laguna (en la isla de Tenerife, Canarias, España) es considerada «un auténtico museo al aire libre»​ que recorre las calles laguneras con pasos de gran valor histórico y artístico, con piezas de imaginería y verdaderas obras de orfebrería isleña con más de cinco…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_San_Cristóbal_de_La_Laguna');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187621,'11032','Semana Santa en Sanlúcar de Barrameda','fiesta','fiestas_wiki','La Semana Santa en Sanlúcar de Barrameda es desde el punto de vista religioso y cultural, uno de los principales acontecimientos que tiene lugar en esta ciudad andaluza, y es, junto a la Feria de la Manzanilla, una de sus principales fiestas. Se celebra en la semana del primer plenilunio de la primavera, pudiendo…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Sanlúcar_de_Barrameda','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187622,'08245','Semana Santa en Santa Coloma de Gramanet','fiesta','fiestas_wiki','La Semana Santa de Santa Coloma de Gramanet conmemora la Vida, Pasión y Resurrección de Nuestro Santísimo Padre Jesús, a través de Procesiones. Antiguamente las Procesiones de Santa Coloma de Gramanet eran muy conocidas en toda la provincia de Barcelona, acudían miles de fieles a ver las procesiones, pero en 1958…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Santa_Coloma_de_Gramanet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187623,'38037','Semana Santa en Santa Cruz de La Palma','fiesta','fiestas_wiki','La Semana Santa de Santa Cruz de La Palma constituye la conmemoración anual de la Pasión, Muerte y Resurrección de Jesucristo. Se celebra en fecha variable durante los meses de marzo o abril y se trata, con excepción de las Fiestas Lustrales de la Bajada de la Virgen, del evento público de carácter religioso más…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Santa_Cruz_de_La_Palma','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187624,'38012','Semana Santa en Santa Cruz de Tenerife','fiesta','fiestas_wiki','La Semana Santa de Santa Cruz de Tenerife es la celebración de la pasión y muerte de Cristo a través de las procesiones y demás actos que se realizan en la ciudad y el municipio de Santa Cruz de Tenerife en la isla de Tenerife (Islas Canarias, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Santa_Cruz_de_Tenerife');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187625,'04063','Semana Santa en Santa María de Guía','fiesta','fiestas_wiki','La Semana Santa de Santa María de Guía es conocida en su presentación como Semana Santa en la Ciudad de Luján. Ya que es la localidad del insigne imaginero canario José Luján Pérez, la Semana Santa de la localidad norteña grancanaria abarca diferentes actos. Aunque en el municipio faltan algunas escenas referentes…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Santa_María_de_Guía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187626,'30901','Semana Santa en Santomera','fiesta','fiestas_wiki','La Semana Santa de Santomera es la celebración anual de la pasión, muerte y resurrección de Jesucristo que se realiza anualmente en la localidad murciana de Santomera. Gran unión de tradición, cultura y fe.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Santomera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187627,'20070','Semana Santa en Segura (Guipúzcoa)','fiesta','fiestas_wiki','La procesión de Semana Santa en Segura es una de las tradiciones religiosas más destacadas de Guipúzcoa, que se celebra cada año durante el Jueves y Viernes Santo. Con una historia que se remonta al menos a 1727, aunque se cree que podría ser anterior, esta procesión recorre las calles del municipio como parte de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Segura_(Guipúzcoa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187628,'42171','Semana Santa en Serón de Nágima','fiesta','fiestas_wiki','La Semana Santa de Serón de Nágima, es una de las manifestaciones religiosas más importantes que tienen lugar en esta villa situada en la provincia de Soria. En estas fechas acuden muchas de las gentes que un día dejaron el pueblo para participar y apoyar con su trabajo y con su presencia este acontecimiento. Junto…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Serón_de_Nágima');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187629,'41091','Semana Santa en Sevilla','fiesta','fiestas_wiki','La Semana Santa de Sevilla es una fiesta de carácter cristiano que conmemora la pasión, muerte y resurrección de Cristo. Entre el Domingo de Ramos y el Domingo de Resurrección, 60 hermandades desfilan hacia la catedral de la ciudad.​​ En los días previos, el Viernes de Dolores y el Sábado de Pasión, 16 hermandades…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Sevilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187630,'04026','Semana Santa en Sorbas','fiesta','fiestas_wiki','La Semana Santa en Sorbas (Almería) es una de las celebraciones culturales más importantes de la localidad. Un total de cinco cofradías y once imágenes procesionan desde el Viernes de Dolores hasta el Domingo de Resurrección en diez desfiles procesionales. El pueblo entero se vuelca con su Semana Santa, sus…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Sorbas','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187631,'42173','Semana Santa en Soria','fiesta','fiestas_wiki','La Semana Santa de Soria, declarada Fiesta de Interés turístico de Castilla y León, es uno de los múltiples atractivos que posee esta Muy Noble, Muy Leal y Antiquísima Ciudad. Semana Santa silenciosa y austera, devocional; fiel reflejo de la sociedad soriana que la sustenta. Destaca por su intenso sentimiento…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Soria','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187632,'02025','Semana Santa en Tobarra','fiesta','fiestas_wiki','La Semana Santa de Tobarra es uno de los acontecimientos más importantes de la provincia de Albacete, (España) y una de las Semanas Santas más destacadas a nivel nacional. Está declarada como Fiesta de Interés Turístico (BOE 10-XI-1983), Fiesta de Interés Turístico Regional (BOCM 19-VI-1984) y Fiesta de Interés…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Tobarra','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187633,'45168','Semana Santa en Toledo','fiesta','fiestas_wiki','La Semana Santa de Toledo es una celebración religiosa que conmemora la Pasión, Muerte y Resurrección de Jesucristo. Reconocida como Fiesta de Interés Turístico Internacional​,​ esta festividad constituye también uno de los principales atractivos turísticos de la ciudad. Se desarrolla a lo largo de nueve días,…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Toledo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187634,'23087','Semana Santa en Torredonjimeno','fiesta','fiestas_wiki','La ‘Semana Santa’ de Torredonjimeno es un período de ocho días que comienza con el Domingo de Ramos y culmina con el Domingo de Resurrección, siendo la última semana de la Cuaresma, en esta ciudad jienense al igual que en el resto de lugares en los que se celebra la semana de pasión.​ Entonces, se trata de una…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Torredonjimeno','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187635,'14065','Semana Santa en Torrente','fiesta','fiestas_wiki','La Semana Santa​ de Torrente​ se lleva celebrando desde el siglo XVII y destaca principalmente por elementos como la Reina del Encuentro y Ángel de la Resurrección,​ una figura única en España. En ella, se rememora la pasión, la victoria sobre la muerte de Jesucristo y su resurrección. Además, congrega año tras…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Torrente','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187636,'10195','Semana Santa en Trujillo','fiesta','fiestas_wiki','La Semana Santa Trujillana se celebra en la localidad de Trujillo, provincia de Cáceres, España. Es una Fiesta de Interés Turístico de Extremadura, declarada así en 2012.​ Se celebra en primavera, comienza con la lectura del Pregón de Semana Santa y culmina con la celebración del Chíviri.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Trujillo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187637,'47186','Semana Santa en Valladolid','fiesta','fiestas_wiki','La Semana Santa de Valladolid es el principal acontecimiento cultural, religioso y de atracción turística de la ciudad. Sus tallas se encuentran entre las de mayor valor artístico del mundo en escultura policromada, gracias sobre todo a imagineros como Juan de Juni y Gregorio Fernández, activos en el periodo en que…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Valladolid','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187638,'02027','Semana Santa en Villarrobledo','fiesta','fiestas_wiki','La Semana Santa de Villarrobledo (Albacete) vive actualmente una época de gran esplendor, habiendo sido declarada de "Interés turístico Regional" en octubre de 2008. Muchas son las novedades introducidas en los últimos años, con restauración generalizada de pasos e imágenes, y con la incorporación de otras nuevas.…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Villarrobledo','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187639,'27066','Semana Santa en Vivero','fiesta','fiestas_wiki','La Semana Santa en Vivero (en gallego y oficialmente: Semana Santa de Viveiro)​ es una celebración católica que tiene lugar en la ciudad española de Vivero (provincia de Lugo). Es una de las celebraciones religiosas más antiguas de Galicia, que se realiza anualmente y de modo ininterrumpido desde el siglo XIII.​​…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Vivero','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187640,'29094','Semana Santa en Vélez-Málaga','fiesta','fiestas_wiki','La Semana Santa de Vélez-Málaga está declarada Fiesta de Interés Turístico Nacional de Andalucía desde el año 2001, nombramiento a nivel autonómico que realiza la Junta de Andalucía. En sus desfiles procesionales participan un total de 19 cofradías, la última de ellas reconocida como tal en el año 2011 (Cofradía de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Vélez-Málaga','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187641,'49275','Semana Santa en Zamora','fiesta','fiestas_wiki','La Semana Santa de Zamora es una manifestación de religiosidad popular católica que celebra anualmente la pasión, muerte y resurrección de Cristo. Es el más relevante acontecimiento religioso, cultural y social de la ciudad de Zamora, siendo su desarrollo reflejo de su propia historia y evolución. Con un origen que…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Zamora','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187642,'50297','Semana Santa en Zaragoza','fiesta','fiestas_wiki','La Semana Santa en Zaragoza es una fiesta religiosa y cultural de interés turístico internacional, siendo su mayor atractivo el tambor, timbal y el bombo.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Zaragoza','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187643,'30030','Semana Santa en la Región de Murcia','fiesta','fiestas_wiki','La celebración de la Semana Santa congrega algunas de las principales manifestaciones culturales, artísticas y religiosas de la Región de Murcia. Además hay procesiones destacadas en casi todos los municipios de la Región.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_la_Región_de_Murcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187644,'41011','Semana Santa en Ágreda','fiesta','fiestas_wiki','La Semana Santa de Ágreda es la celebración de la Semana Santa que se celebra en la localidad soriana de Ágreda (Castilla y León, España). El Viernes Santo en particular está declarado como Fiesta de Interés Turístico Regional.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ágreda','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187645,'51025','Semana Santa en Ávila','fiesta','fiestas_wiki','La Semana Santa de Ávila, declarada de Interés Turístico Internacional desde 2014, constituye una gran expresión de arte y riqueza representada por los numerosos pasos que recorren la ciudad amurallada. Con sus 15 procesiones y 14 hermandades, es una de las más bellas de Castilla y León. El programa empieza el…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Ávila','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187646,'41039','Semana Santa en Écija','fiesta','fiestas_wiki','La Semana Santa de Écija en la provincia de Sevilla, España, es una de las festividades locales más importantes de la ciudad, dedicada a conmemorar la pasión, muerte y resurrección de Cristo. En 1998 fue declarada de Interés Turístico Nacional, destacándose como una de las principales celebraciones de primavera en…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Écija','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187647,'23092','Semana Santa en Úbeda','fiesta','fiestas_wiki','La Semana Santa de Úbeda es una de las más populares de Andalucía. Está declarada Fiesta de Interés Turístico desde 1980​ por el Ministerio de Comercio y Turismo del Gobierno de España y de Interés Turístico Nacional de Andalucía desde 1998​​ por la orden del 20 de mayo de 1997 de la Consejería de Turismo y Deporte…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Santa_en_Úbeda','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187648,'46029','Semana Taurina de Algemesí','fiesta','fiestas_wiki','La Semana de Toros (antiguamente ligada a las fiestas de la Virgen de la Salud) son las fiestas que por su duración y participación de gente, más involucra al pueblo.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Taurina_de_Algemesí');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187649,'47186','Sermón de las Siete Palabras','fiesta','fiestas_wiki','El Sermón de las Siete Palabras es uno de los actos más singulares y destacados de la Semana Santa de Valladolid, organizado por la Cofradía de las Siete Palabras. Cada Viernes Santo a mediodía, la Plaza Mayor, engalanada con telones negros, se transforma en un escenario del siglo XVI en el que un religioso, desde…',NULL,NULL,'https://es.wikipedia.org/wiki/Sermón_de_las_Siete_Palabras','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187650,'12080','Sexenio de Morella','fiesta','fiestas_wiki','El Sexenio (en valenciano, Sexenni) es una fiesta que se celebra en la localidad de Morella (Castellón, España) en honor de la Virgen de Vallivana. La fiesta tiene lugar una vez cada seis años y se celebra el tercer domingo de agosto desde 1678.',NULL,NULL,'https://es.wikipedia.org/wiki/Sexenio_de_Morella','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187651,'38037','Señor de la Piedra Fría (Santa Cruz de La Palma)','fiesta','fiestas_wiki','La imagen del Señor de la Piedra Fría, es una talla que representa a Jesucristo de Nazaret en su representación de la "Humildad y Paciencia", que se venera en la Iglesia de San Francisco de Asís en la ciudad de Santa Cruz de La Palma (Islas Canarias, España). Su hermandad es la Cofradía del Señor de la Piedra Fría…',NULL,NULL,'https://es.wikipedia.org/wiki/Señor_de_la_Piedra_Fría_(Santa_Cruz_de_La_Palma)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187652,'38012','Señor de las Tribulaciones (Santa Cruz de Tenerife)','fiesta','fiestas_wiki','La imagen del Señor de las Tribulaciones, también llamado Señor de Santa Cruz,​ es una talla de busto que representa a Jesucristo de Nazaret en su representación del "Ecce Homo", que se venera en la Iglesia de San Francisco de Asís en la ciudad de Santa Cruz de Tenerife (Islas Canarias, España). El Señor de las…',28.46794722,-16.24946667,'https://es.wikipedia.org/wiki/Señor_de_las_Tribulaciones_(Santa_Cruz_de_Tenerife)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187653,'90917','She (anuncio)','fiesta','fiestas_wiki','She, también llamado She, un cuento de J&B, es el título de un anuncio publicitario audiovisual navideño realizado por la agencia de publicidad El Ruso de Rocky para la marca de whisky escocés J&B en 2022.',NULL,NULL,'https://es.wikipedia.org/wiki/She_(anuncio)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187654,'04063','Simpecado','fiesta','fiestas_wiki','El Simpecado es un tipo de estandarte, bandera o insignia de significado religioso que ostenta en su centro una imagen de la Santísima Virgen María representada en alguno de sus misterios o advocaciones, que se saca procesionalmente en los Rosarios públicos o en otras procesiones de hermandades y cofradías de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Simpecado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187655,'20069','Sokamuturra','fiesta','fiestas_wiki','Sokamuturra es una expresión en euskera que designa a un espectáculo popular taurino, equivalente del toro enmaromado o toro ensogado, que se celebraba en diversas localidades del País Vasco, España. Diferentes crónicas atestiguan su celebración, normalmente unido a alguna festividad local, desde antiguo. En el…',NULL,NULL,'https://es.wikipedia.org/wiki/Sokamuturra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187656,'90472','Sopa de antruejo','fiesta','fiestas_wiki','La sopa de antruejo (denominada también sopa de carnaval) es una sopa elaborada regularmente con diversas partes de chacinería. Se trata de una sopa muy popular en Aceuchal (provincia de Badajoz).​ La denominación antruejo (se dice de cualquier día de gran comida) viene a indicar lo variado y rico de contenidos…',NULL,NULL,'https://es.wikipedia.org/wiki/Sopa_de_antruejo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187657,'10203','Soraya Arnelas','fiesta','fiestas_wiki','Soraya Arnelas Rubiales (Valencia de Alcántara, Cáceres, 13 de septiembre de 1982), conocida simplemente como Soraya Arnelas o Soraya, es una cantante, compositora, actriz y modelo española. Tras darse a conocer en 2005 en el programa Operación Triunfo, debutó discográficamente ese mismo año con Corazón de fuego,…',NULL,NULL,'https://es.wikipedia.org/wiki/Soraya_Arnelas','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187658,'28079','Sorteo Extraordinario de Navidad','fiesta','fiestas_wiki','El Sorteo Extraordinario de Navidad, conocido como Lotería de Navidad, es uno de los sorteos de lotería más importantes y populares que se celebra en España cada 22 de diciembre,​ y que tenía lugar tradicionalmente en el salón de sorteos de Loterías y Apuestas del Estado, en Madrid. Desde 2010, debido al numeroso…',NULL,NULL,'https://es.wikipedia.org/wiki/Sorteo_Extraordinario_de_Navidad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187659,'25061','Sorteo Extraordinario del Niño','fiesta','fiestas_wiki','El Sorteo Extraordinario de "El Niño", también conocido como Sorteo de "El Niño" o Lotería de "El Niño" o Lotería del Niño", es el segundo de los sorteos de lotería más populares que se celebran en España después del Sorteo de Navidad. Se lleva a cabo cada 6 de enero, coincidiendo con la festividad de los Reyes…',NULL,NULL,'https://es.wikipedia.org/wiki/Sorteo_Extraordinario_del_Niño');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187660,'14074','Suelta de Vaquillas de El Viso','fiesta','fiestas_wiki','La Suelta de Vaquillas de El Viso (Córdoba) es un festejo popular taurino que se celebra en el marco de las fiestas patronales del municipio en honor a Santa Ana, durante la segunda quincena de julio.',NULL,NULL,'https://es.wikipedia.org/wiki/Suelta_de_Vaquillas_de_El_Viso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187661,'10084','Suelta de la Gata Negra','fiesta','fiestas_wiki','La suelta de la Gata Negra es una fiesta que se celebra en Carasa, en el municipio de Voto (Cantabria), y está declarada de interés turístico regional. Se celebra cada 16 de agosto. Según documentos históricos oficiales, esta historia se remonta a 1477, año en el que se originó la celebración.',NULL,NULL,'https://es.wikipedia.org/wiki/Suelta_de_la_Gata_Negra','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187662,'38012','Super Chicha','fiesta','fiestas_wiki','Super Chicha es un personaje ficticio creado para el Carnaval de Santa Cruz de Tenerife del año 1999 y que se convirtió en uno de los personajes carnavaleros más entrañables y queridos.',NULL,NULL,'https://es.wikipedia.org/wiki/Super_Chicha','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187663,'90188','Suso de Marcos','fiesta','fiestas_wiki','Jesús López García, más conocido como Suso de Marcos (n. 17 de octubre de 1950, Boimorto, La Coruña), es un artista escultor español.',NULL,NULL,'https://es.wikipedia.org/wiki/Suso_de_Marcos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187664,'38006','Tablas de San Andrés','fiesta','fiestas_wiki','Las Tablas de San Andrés es una tradición característica del municipio de Icod de los Vinos y La Guancha en la isla de Tenerife, Canarias, que se celebra los dos últimos días de noviembre, coincidiendo con el día de San Andrés. En la víspera del día de San Andrés los lugareños se deslizan por algunas de las calles…',NULL,NULL,'https://es.wikipedia.org/wiki/Tablas_de_San_Andrés');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187665,'49164','Tafarrón','fiesta','fiestas_wiki','La fiesta del Tafarrón es una mascarada de invierno o antruejo​ (término más utilizado en Galicia) que se celebra en la localidad zamorana de Pozuelo de Tábara principalmente los días 25,26 y 27 de diciembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Tafarrón','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187666,'06006','Tam Tam Go!','fiesta','fiestas_wiki','Tam Tam Go! es un grupo de música español originario de Badajoz (Extremadura), que nació en el año 1987 como consecuencia de la disolución del grupo Daké (Reinerio Hevia, Nacho Lles, Javier Ortiz, Javier Campillo y Rafa Callejo). Tam Tam Go!',NULL,NULL,'https://es.wikipedia.org/wiki/Tam_Tam_Go!','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187667,'20069','Tamborrada de San Sebastián','fiesta','fiestas_wiki','La tamborrada de San Sebastián es la fiesta con la que cada 20 de enero la ciudad de San Sebastián, capital de la provincia de Guipúzcoa aparte de en la capital se celebra en otra ciudad Guipuzcoana Azpeitia en el País Vasco, celebra el día de San Sebastián, su santo patrón. La fiesta de la tamborrada consiste en…',NULL,NULL,'https://es.wikipedia.org/wiki/Tamborrada_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187668,'34120','Tararú','fiesta','fiestas_wiki','El tararú es una de las tradiciones más arraigadas de la Semana Santa en Palencia. El concepto hace referencia a los cofrades y nazarenos que desfilan en las procesiones de Semana Santa. Son las cofradías más numerosas de Palencia (Santo Sepulcro, Vera-Cruz y Nazarenos) las que han conservado durante mucho tiempo…',NULL,NULL,'https://es.wikipedia.org/wiki/Tararú','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187669,'43148','Tarraco Viva','fiesta','fiestas_wiki','Festival anual sobre el mundo romano celebrado en el mes de mayo en la ciudad de Tarragona, de la que coge su antiguo nombre romano, Tarraco. El festival tiene como objetivo principal la divulgación del conocimiento de la Edad Antigua en época romana. En el festival, participan numerosos grupos de reconstrucción…',NULL,NULL,'https://es.wikipedia.org/wiki/Tarraco_Viva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187670,'02001','Templete de la Feria','fiesta','fiestas_wiki','El templete de la Feria es un histórico templete modernista de la ciudad española de Albacete. Está ubicado en el centro del círculo central del Recinto Ferial de Albacete.',38.997199,-1.870439,'https://es.wikipedia.org/wiki/Templete_de_la_Feria','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187671,'19130','Tenorio Mendocino','fiesta','fiestas_wiki','El Tenorio Mendocino es una representación de la obra Don Juan Tenorio de José Zorrilla que se celebra anualmente el fin de semana más próximo al 31 de octubre en las calles y en los principales monumentos de la ciudad de Guadalajara (España).​​ Está declarada como Fiesta de Interés Turístico Regional por la Junta…',NULL,NULL,'https://es.wikipedia.org/wiki/Tenorio_Mendocino','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187672,'08302','Tercerol','fiesta','fiestas_wiki','El tercerol es una prenda que se usa para cubrir la cabeza​ en la Semana Santa aragonesa.​ El origen del nombre hace referencia a la orden tercera de San Francisco de Asís, que usaban una capucha que les daba un aspecto similar. La Hermandad de la Sangre de Cristo de Zaragoza retomó esta prenda para los portadores…',NULL,NULL,'https://es.wikipedia.org/wiki/Tercerol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187673,'12110','Teresa del Castillo','fiesta','fiestas_wiki','Teresa del Castillo fue una bordadora española del siglo XIX que desarrolló una importante labor artística empleando la técnica del bordado, muchas de sus obras estuvieron destinadas a hermandades de penitencia de la Semana Santa de Sevilla.​',NULL,NULL,'https://es.wikipedia.org/wiki/Teresa_del_Castillo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187674,'46077','Tomatina','fiesta','fiestas_wiki','La Tomatina es una fiesta que se celebra en el municipio valenciano de Buñol (España). Se celebra siempre el último miércoles del mes de agosto, dentro de la semana de fiestas de Buñol y consiste en que los participantes se arrojan tomates los unos a los otros.',39.4204194,-0.7899682,'https://es.wikipedia.org/wiki/Tomatina','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187675,'46111','Torico de la Cuerda de Chiva','fiesta','fiestas_wiki','El Torico de la Cuerda de Chiva (Valencia) es un festejo popular taurino que se celebra en el marco de unas fiestas organizadas por la Peña Taurina de Chiva junto con el Ayuntamiento de la localidad.​ Fue declarado Fiesta de Interés Turístico de la Comunidad Valenciana en 2019.​',NULL,NULL,'https://es.wikipedia.org/wiki/Torico_de_la_Cuerda_de_Chiva','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187676,'32083','Torneo del Toro de la Vega','fiesta','fiestas_wiki','El Torneo del Toro de la Vega era un evento taurino de origen medieval, celebrado en la localidad española de Tordesillas (Valladolid). Fue declarado fiesta de interés turístico en 1980​ y espectáculo taurino tradicional en 1999.​ Se celebra el martes de la segunda o tercera semana de septiembre como parte de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Torneo_del_Toro_de_la_Vega','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187677,'42113','Toro Jubilo de Medinaceli','fiesta','fiestas_wiki','El Toro Jubilo de Medinaceli (Soria) es un festejo popular taurino consistente en la celebración de un toro de fuego.',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_Jubilo_de_Medinaceli','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187678,'31157','Toro con Soga de Lodosa','fiesta','fiestas_wiki','El Toro con Soga de Lodosa (Navarra) es un festejo popular taurino que se celebra con motivo de las fiestas en honor de la Virgen de las Angustias, que tienen lugar el tercer fin de semana de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_con_Soga_de_Lodosa','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187679,'50073','Toro de Ronda de Cariñena','fiesta','fiestas_wiki','El Toro de Ronda es la denominación con la que se conoce popularmente en Aragón al toro engamellado que se celebra en el marco de las fiestas patronales. En Cariñena (Zaragoza) este festejo tiene lugar del 13 al 18 de septiembre, durante las fiestas patronales en honor al Santo Cristo de Santiago.',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_Ronda_de_Cariñena','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187680,'44201','Toro de Soga de Rubielos de Mora','fiesta','fiestas_wiki','El Toro de Soga es un festejo popular taurino que se celebra en Rubielos de Mora (Teruel) durante las fiestas patronales de la Santa Cruz, el 14 de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_Soga_de_Rubielos_de_Mora','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187681,'50208','Toro de Sogas de Pina de Ebro','fiesta','fiestas_wiki','El Toro de Sogas es un festejo popular taurino que se celebra en Pina de Ebro (Zaragoza) con motivo de la festividad de San Juan, el 24 de junio y fue declarado Fiesta de Interés Turístico de Aragón en 2008.',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_Sogas_de_Pina_de_Ebro','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187682,'49219','Toro de cuerda','fiesta','fiestas_wiki','El toro de cuerda es un ritual taurino y un tipo de encierro a través del cual se expresa la ancestral costumbre que el hombre tiene de jugar con el toro, desafiando la fuerza de éste y asumiendo un riesgo a cuerpo limpio. Constituye un evento eminentemente popular, que nada tiene que ver en su origen con las…',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_cuerda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187683,'49219','Toro de fuego','fiesta','fiestas_wiki','El toro de fuego es una fiesta española que consiste en correr un carretón o estructura realizado con un armazón o bastidor metálico, que imita la forma de un toro, sobre cuya superficie se colocan elementos pirotécnicos. Es muy utilizado en fiestas patronales o locales de numerosas localidades de España. Algunas…',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_fuego');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187684,'22039','Toro de fuego (Ayerbe)','fiesta','fiestas_wiki','El toro de fuego es un espectáculo que tiene lugar en la localidad oscense de Ayerbe durante las fiestas de Santa Leticia, patrona del municipio.​',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_de_fuego_(Ayerbe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187685,'49219','Toro embolado','fiesta','fiestas_wiki','El toro embolado o toro de fuego es un festejo tradicional que se celebra en España y que se encuentra relacionado con la tauromaquia. En esta celebración, un toro de lidia corre por la trama urbana de una determinada localidad portando sobre sus astas o cuernos un herraje, sobre los cuales se colocan estopas…',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_embolado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187686,'16016','Toro embolado (Los Barrios)','fiesta','fiestas_wiki','La fiesta del ''Toro embolao'', una de las más afamadas del municipio en las últimas décadas, consiste en correr un toro embolado por las calles del municipio hasta llegar a la plaza de toros.​',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_embolado_(Los_Barrios)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187687,'49219','Toro enmaromado','fiesta','fiestas_wiki','El Toro Enmaromado es un festejo popular con reses de lidia que tiene lugar en la ciudad de Benavente (Zamora, España).​ El "día grande" se celebra el miércoles anterior a la festividad de Corpus Christi, cuando se suelta un toro por las calles de la ciudad, atado por las astas con una maroma de normalmente 100…',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_enmaromado','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187688,'24013','Toro ensogado de Beas de Segura','fiesta','fiestas_wiki','El toro ensogado de Beas de Segura o fiestas de San Marcos es una de las tradiciones popular mas taurinas españolas y más arraigadas que se celebran en el municipio de Beas de Segura, (Jaén), en la comunidad autónoma de Andalucía, entre los días 22 al 25 de abril, en honor a San Marcos, corriendo toros y vacas…',NULL,NULL,'https://es.wikipedia.org/wiki/Toro_ensogado_de_Beas_de_Segura','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187689,'90011','Toros en el Mar','fiesta','fiestas_wiki','La fiesta de los Toros en el Mar se celebraban en la localidad asturiana de Candás, capital del concejo de Carreño. Se celebraban, intermitentemente, en el mes de septiembre durante las festividades del Cristo de Candás.',NULL,NULL,'https://es.wikipedia.org/wiki/Toros_en_el_Mar','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187690,'90158','Torre humana de Ateca','fiesta','fiestas_wiki','La torre humana de Ateca, conocida también como castillo andante de Ateca, es una tradición de este municipio de la provincia de Zaragoza, España. Esta pirámide humana se levanta dos veces al año: el día de la Ascensión y el de San Lorenzo (10 de agosto), patrón del barrio de San Martín de Ateca. Hasta los años…',NULL,NULL,'https://es.wikipedia.org/wiki/Torre_humana_de_Ateca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187691,'46257','Transbetxí','fiesta','fiestas_wiki','El Rally Transbetxí es un rally de motocultores que se organiza cada año el segundo fin de semana de Pascua en Betxí, provincia de Castellón (España). El tramo cronometrado prólogo se resliza el viernes a partir de las 23:30h en un circuito cerrado. Las restantes etapas se realizan el sábado por los términos…',NULL,NULL,'https://es.wikipedia.org/wiki/Transbetxí','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187692,'08102','Tres Vueltas de Igualada','fiesta','fiestas_wiki','Las Tres Vueltas de Igualada (en catalán: Tres Tombs d''Igualada) es una fiesta tradicional del municipio de Igualada, Barcelona, relacionada con las celebraciones del día de San Antonio Abad.​ Se trata de la fiesta de las Tres Vueltas más antigua de Cataluña, declarada Fiesta de Interés Turístico Nacional por el…',NULL,NULL,'https://es.wikipedia.org/wiki/Tres_Vueltas_de_Igualada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187693,'43161','Tres Vueltas de Valls','fiesta','fiestas_wiki','Las Tres Vueltas de San Antonio Abad de Valls es el nombre que recibe la celebración con la que comienza el calendario festivo anual de la localidad de Valls, capital de la comarca del Alto Campo, en Cataluña, España.​​ Festividad dedicada a San Antonio Abad y celebrada el 17 de enero, es la primera del calendario…',41.28428611,1.248,'https://es.wikipedia.org/wiki/Tres_Vueltas_de_Valls','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187694,'37344','Tributo de las Tres Vacas','fiesta','fiestas_wiki','El Tributo de las Tres Vacas es una ceremonia que reúne a los vecinos de los valles de Baretous (Bearne, Francia) y de Roncal (Navarra, España) en el punto llamado Piedra de San Martín situado en el collado de Ernaz el día 13 de julio de cada año, durante la cual los primeros entregan tres vacas a los segundos.…',NULL,NULL,'https://es.wikipedia.org/wiki/Tributo_de_las_Tres_Vacas','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187695,'30016','Trovalia','fiesta','fiestas_wiki','Trovalia es un festival internacional de poesía improvisada y cantada que se celebra en el municipio español de Cartagena durante los primeros días de agosto. Está organizado por la asociación de troveros del Campo de Cartagena "José María Marín" y cuenta con el patrocinio del Ayuntamiento de Cartagena.',NULL,NULL,'https://es.wikipedia.org/wiki/Trovalia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187696,'03904','Tía Javiera','fiesta','fiestas_wiki','La Tía Javiera es un personaje del imaginario madrileño, inspirado en una pastelera del siglo XIX que se hizo famosa vendiendo rosquillas en las fiestas de san Isidro Labrador.',NULL,NULL,'https://es.wikipedia.org/wiki/Tía_Javiera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187697,'36007','Una Navidad con Samantha Hudson','fiesta','fiestas_wiki','Una Navidad con Samantha Hudson es una película musical y cómica española de 2021, dirigida por Alejandro Marín.​',NULL,NULL,'https://es.wikipedia.org/wiki/Una_Navidad_con_Samantha_Hudson');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187698,'47109','Vaca enmaromada de Palazuelo de Vedija','fiesta','fiestas_wiki','La Vaca enmaromada de Palazuelo de Vedija es un festejo popular que se celebra en la localidad de Palazuelo de Vediija (Valladolid) alrededor del 22 de septiembre en honor a la San Mauricio.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Vaca_enmaromada_de_Palazuelo_de_Vedija');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187699,'34008','Vellarróns','fiesta','fiestas_wiki','Vellarróns son un disfraz y máscara de carnaval típica del pueblo de Castrelo de Cima en el municipio de Riós (Orense). Según cuenta Xosé R. Cruz, investigado de tradiciones y costumbres del Sureste orensano, en su trabajo "Trazos sobre a vestimenta tradicional no surleste ourensán" (Ed. Deputación de Ourense,…',NULL,NULL,'https://es.wikipedia.org/wiki/Vellarróns');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187700,'47186','Venerable Cofradía de la Preciosísima Sangre de Nuestro Señor Jesucristo','fiesta','fiestas_wiki','La Real y Venerable Cofradía de la Preciosísima Sangre de Nuestro Señor Jesucristo es una de las 20 cofradías que existen, en la actualidad, en la Semana Santa de Valladolid.',NULL,NULL,'https://es.wikipedia.org/wiki/Venerable_Cofradía_de_la_Preciosísima_Sangre_de_Nuestro_Señor_Jesucristo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187701,'27066','Venerable Orden Tercera Franciscana (Vivero)','fiesta','fiestas_wiki','La Venerable Orden Tercera Franciscana es una de las ocho cofradías que existen, en la Semana Santa de Vivero.',NULL,NULL,'https://es.wikipedia.org/wiki/Venerable_Orden_Tercera_Franciscana_(Vivero)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187702,'02001','Venerable, Antigua y Penitencial Cofradía del Santísimo Cristo de la Sangre (Albacete)','fiesta','fiestas_wiki','La Venerable, Antigua y Penitencial Cofradía del Santísimo Cristo de la Sangre es una cofradía de la Semana Santa de Albacete (España).​​ Tiene su sede canónica en la Iglesia de El Buen Pastor. Fue fundada en 2013. Procesiona en Viernes de Dolores y Sábado Santo.',NULL,NULL,'https://es.wikipedia.org/wiki/Venerable,_Antigua_y_Penitencial_Cofradía_del_Santísimo_Cristo_de_la_Sangre_(Albacete)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187703,'28079','Verbena de San Antonio de la Florida','fiesta','fiestas_wiki','La fiesta de San Antonio de la Florida (denominada popularmente también como verbena de San Antonio de la Florida) es una festividad popular celebrada anualmente cada 13 de junio en honor a San Antonio​ en la ciudad de Madrid. El lugar de congregación de la romería por el paseo de la Florida hacia la ermita de San…',NULL,NULL,'https://es.wikipedia.org/wiki/Verbena_de_San_Antonio_de_la_Florida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187704,'11031','Verbena de San Fernando','fiesta','fiestas_wiki','La verbena de San Fernando (denominada popularmente también como verbena de la Princesa) fue una festividad popular celebrada anualmente cada 30 de mayo en Madrid.​',NULL,NULL,'https://es.wikipedia.org/wiki/Verbena_de_San_Fernando');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187705,'07050','Verbena de San Juan Bautista','fiesta','fiestas_wiki','La Verbena de San Juan Bautista es una festividad popular celebrada anualmente cada 24 de junio en el Prado en honor de San Juan Bautista.​ Es una forma de celebrar la noche de San Juan que se celebra en muchas zonas de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Verbena_de_San_Juan_Bautista');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187706,'90090','Verdeo de la aceituna','fiesta','fiestas_wiki','El verdeo de la aceituna es el proceso de recolección temprana de las olivas, generalmente antes de que el fruto madure por completo y se produzca el envero, esto es, su cambio de coloración.​​Su nombre lo recibe por tratarse de la recolección de la aceituna verde.​',NULL,NULL,'https://es.wikipedia.org/wiki/Verdeo_de_la_aceituna');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187707,'16280','Vicente Gómez Zarzuela','fiesta','fiestas_wiki','Vicente Gómez-Zarzuela y Pérez (Sevilla, 27 de octubre de 1870-Arcos de la Frontera, provincia de Cádiz, 14 de diciembre de 1956) fue un músico y compositor español. Es recordado sobre todo por ser el autor de algunas marchas procesionales que se interpretan habitualmente acompañando a las procesiones de Semana…',NULL,NULL,'https://es.wikipedia.org/wiki/Vicente_Gómez_Zarzuela','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187708,'47086','Virgen Dolorosa (Medina de Rioseco)','fiesta','fiestas_wiki','La Virgen Dolorosa es una obra realizada hacia 1720 y atribuida a Tomás de Sierra. Procesionada el Jueves Santo, la imagen está ubicada en el Museo de Semana Santa de Medina de Rioseco, en Valladolid (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_Dolorosa_(Medina_de_Rioseco)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187709,'07049','Virgen de Lágrimas y Favores','fiesta','fiestas_wiki','María Santísima de Lágrimas y Favores es una variante de la advocación mariana de Nuestra Señora de los Dolores venerada en la ciudad española de Málaga, en la comunidad autónoma de Andalucía. Es una de las imágenes titulares de la Reales Cofradías Fusionadas, con sede canónica en la iglesia de San Juan. La imagen…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_Lágrimas_y_Favores','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187710,'16122','Virgen de la Almudena','fiesta','fiestas_wiki','Santa María de la Almudena o Nuestra Señora de la Almudena es una advocación mariana de la Virgen María. Es la patrona de la archidiócesis de Madrid, siendo venerada en la Catedral de Santa María de la Almudena. Su festividad se celebra el 9 de noviembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Almudena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187711,'41091','Virgen de la Amargura (Sevilla)','fiesta','fiestas_wiki','Virgen de la Amargura es una imagen de la Virgen María que se venera en el altar mayor de la iglesia de San Juan de la Palma de Sevilla, Andalucía, España. El 21 de noviembre de 1954 fue coronada canónicamente en la catedral de Sevilla siendo la primera Dolorosa en recibir esta distinción en la archidócesis.​…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Amargura_(Sevilla)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187712,'39029','Virgen de la Cama de Escalante','fiesta','fiestas_wiki','La Virgen de la Cama de Escalante es la patrona de Escalante (Cantabria), cuya imagen se ve acogida desde el año 1638 en el monasterio de San Juan de Monte Calvario,​ regentado por las monjas clarisas de Escalante. También es conocida como Virgen del Tránsito debido a la representación del momento en el Virgen…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Cama_de_Escalante');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187713,'18087','Virgen de la Consolación (Granada)','fiesta','fiestas_wiki','Nuestra Madre y Señora de la Consolación, también conocida como Virgen de la Consolación, es una imagen devocional de Granada (España), que forma parte de la Hermandad del Cristo de San Agustín y que procesiona anualmente durante la Semana Santa de Granada. Razones teológicas e históricas justifican dicha…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Consolación_(Granada)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187714,'29084','Virgen de la Paz Coronada (Ronda)','fiesta','fiestas_wiki','La Virgen de la Paz es una advocación mariana que se venera en la Iglesia de Nuestra Señora de la Paz de Ronda, provincia de Málaga (Andalucía, España). Es una devoción muy arraigada entre las familias rondeñas, siendo una tradición que se hereda de padres a hijos.​ La imagen de la Virgen de la Paz es una obra de…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Paz_Coronada_(Ronda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187715,'06006','Virgen de la Soledad (Patrona de Badajoz)','fiesta','fiestas_wiki','La Virgen de la Soledad de Badajoz, Ntra. Sra. de la Soledad Coronada, es una imagen de la advocación mariana de Nuestra Señora de la Soledad que se venera en la Ermita de la Soledad de la ciudad de Badajoz (España), siendo la patrona de dicha ciudad.',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_la_Soledad_(Patrona_de_Badajoz)','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187716,'41091','Virgen de las Angustias (Montes de Oca)','fiesta','fiestas_wiki','La Virgen de las Angustias fue una obra atribuida a José Montes de Oca y realizada posiblemente en 1738. Destruida en 1936, estaba ubicada en la Iglesia de San Román de Sevilla (Andalucía, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_las_Angustias_(Montes_de_Oca)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187717,'25001','Virgen de las Huertas','fiesta','fiestas_wiki','La Virgen de las Huertas o Santa María la Real de las Huertas es una advocación Mariana, Patrona de la ciudad de Lorca (Murcia). Es la advocación mariana más antigua de la ciudad de Lorca. Situada en la pedanía lorquina de Tiata, en el convento y santuario franciscano de La Virgen de las Huertas, conocido como el…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_las_Huertas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187718,'39017','Virgen de las Nieves (Campoo de Yuso)','fiesta','fiestas_wiki','La Virgen de las Nieves de Campoo de Yuso es una advocación mariana que se encuentra en dicho municipio de Cantabria (España), considerándose la patrona del municipio. La ermita que alberga a la virgen se encuentra cerca de la localidad de Monegro, desde la que se accede por una pequeña pista a un camino marcado…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_las_Nieves_(Campoo_de_Yuso)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187719,'03040','Virgen de las Virtudes (Villena)','fiesta','fiestas_wiki','Nuestra Señora de las Virtudes, también conocida como Virgen de las Virtudes y popularmente como «La Morenica», es una advocación de la Virgen María venerada en Villena (Alicante, España). En su honor se celebran las fiestas de Moros y Cristianos de Villena de 4 al 9 de septiembre. Su imagen se conserva en el…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_las_Virtudes_(Villena)','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187720,'40063','Virgen de los Cuchillos (Cuéllar)','fiesta','fiestas_wiki','La Virgen de los Cuchillos es una obra anónima de los siglos xvi, xvii o xviii. Portada el Viernes Santo por la Cofradía de la Dolorosa Virgen de los Cuchillos, la imagen está ubicada en la Iglesia de San Miguel de Cuéllar, en Segovia (Castilla y León, España).',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_los_Cuchillos_(Cuéllar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187721,'37300','Virgen de los Dolores y los Santos Pasos','fiesta','fiestas_wiki','En Murcia, en la Iglesia Parroquial de san Miguel Arcángel, a la derecha del altar, descansa una Virgen obra de Francisco Salzillo; Nuestra Señora Virgen de los Dolores y los Santos Pasos. Según la tradición, la larga devoción en la Diócesis de Cartagena a los Dolores de Nuestra Señora nace a finales del siglo XVII…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_los_Dolores_y_los_Santos_Pasos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187722,'02001','Virgen de los Llanos','fiesta','fiestas_wiki','La Virgen de los Llanos es una advocación mariana de la Virgen María. Es la patrona de la ciudad española de Albacete, y de la diócesis de Albacete, siendo venerada en la Catedral de San Juan de Albacete. Su festividad se celebra el 8 de septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_de_los_Llanos','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187723,'16122','Virgen del Azahar','fiesta','fiestas_wiki','Nuestra Señora del Azahar es una advocación mariana que se venera en Beniaján (Murcia, España). La talla recibe culto en una pequeña ermita erigida a las afueras de la población, en el paraje denominado Rincón de Villanueva, lugar jalonado por las fecundas huertas que caracterizan esta productiva comarca. La…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_del_Azahar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187724,'30043','Virgen del Castillo (Yecla)','fiesta','fiestas_wiki','La Virgen del Castillo es una advocación mariana que se venera como patrona de Cabezabellosa (Cáceres) y de Yecla (Murcia, España). Su santuario constituye un centro de peregrinación no sólo para los bellosos/as y yeclanos, sino también para los habitantes de toda su comarca e incluso del resto de la región y…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_del_Castillo_(Yecla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187725,'43904','Virgen del Rocío','fiesta','fiestas_wiki','La Virgen del Rocío, también conocida como la Blanca Paloma o la Reina de las Marismas, es una advocación mariana que se venera en el santuario de la aldea de El Rocío (Almonte, Huelva), además de ser patrona de dicho municipio. Fue coronada canónicamente en 1919, con bula de Benedicto XV.​ La Romería del Rocío…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_del_Rocío','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187726,'40063','Virgen del Rosario (Cuéllar)','fiesta','fiestas_wiki','La Virgen del Rosario es una escultura gótica que representa a María, madre de Jesús en su advocación de la Virgen del Rosario, que se venera en la capilla del Rosario, anexa a la iglesia de Santo Tomé de la villa de Cuéllar, en la provincia de Segovia, de la que es patrona, en cuyo honor se celebran los Encierros…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_del_Rosario_(Cuéllar)','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187727,'06006','Virgen y Romería de Bótoa','fiesta','fiestas_wiki','La Virgen de Bótoa es una advocación mariana cuyos orígenes se remontan al siglo XIV, en el paraje denominado desde antiguo por Budua o Botoba, actual Bótoa (de ahí su popular nombre), dentro del término municipal de Badajoz, y a pocos kilómetros de la casco urbano de la ciudad, de la que es considerada copatrona,…',NULL,NULL,'https://es.wikipedia.org/wiki/Virgen_y_Romería_de_Bótoa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187728,'09180','Visita a las siete iglesias','fiesta','fiestas_wiki','La visita a las siete iglesias es una tradición de Cuaresma originaria de la Iglesia católica que consiste en visitar siete iglesias la tarde del Jueves Santo. Tras la Misa de la Cena del Señor, el Santo Sacramento se coloca en el Monumento de la iglesia para su adoración. Durante la «Visita a las siete iglesias»,…',NULL,NULL,'https://es.wikipedia.org/wiki/Visita_a_las_siete_iglesias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187729,'32054','Voda da Pita','fiesta','fiestas_wiki','La Voda da Pita (boda de la Pita, en gallego) es una representación teatral popular que tiene lugar cada Martes de Carnaval en la plaza de As Eiroás (Orense). Es el acto central de la Fiesta de la Pita, que es el nombre con el que se denomina al carnaval de As Eiroás que, a su vez, se llama así en memoria del…',NULL,NULL,'https://es.wikipedia.org/wiki/Voda_da_Pita');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187730,'31232','Volatín de Tudela','fiesta','fiestas_wiki','El Volatín de Tudela es una fiesta declarada Fiesta de Interés Turístico de Navarra y Fiesta de Interés Turístico de Nacional celebrada en la localidad navarra de Tudela.',NULL,NULL,'https://es.wikipedia.org/wiki/Volatín_de_Tudela','IT Nacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187731,'46092','Volteo humano de campanas (Castielfabib)','fiesta','fiestas_wiki','El volteo o bandeo humano de campanas es una tradición festivo-religiosa que tiene lugar en el Campanario de la iglesia de Nuestra Señora de los Ángeles de Castielfabib, Valencia (Comunidad Valenciana, España). . . . Se realiza varias veces al año, siendo las principales, en la onomástica de San Guillermo, patrón…',NULL,NULL,'https://es.wikipedia.org/wiki/Volteo_humano_de_campanas_(Castielfabib)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187732,'07046','Vueltas de San Antón','fiesta','fiestas_wiki','Las Vueltas de San Antón es una festividad popular en Madrid, celebrada el día 17 de enero en honor a San Antonio Abad. El espacio de la celebración se centra en los alrededores de la parroquia de San Antón en las madrileñas calles de Hortaleza y Fuencarral.​​ Es considerada la primera de las fiestas populares del…',NULL,NULL,'https://es.wikipedia.org/wiki/Vueltas_de_San_Antón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187733,'90716','Vía Crucis Viviente de Andosilla','fiesta','fiestas_wiki','El vía crucis viviente de Andosilla (Navarra)​ es una representación de las últimas horas de Jesús de Nazaret, desde el juicio de Poncio Pilatos y su condena a muerte hasta su crucifixión, descendimiento y sepultura.​ La función, que tiene lugar cada Viernes Santo, se desarrolla por las calles del casco antiguo y…',42.37694444,-1.94194444,'https://es.wikipedia.org/wiki/Vía_Crucis_Viviente_de_Andosilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187734,'04063','Vía Crucis de la Cruz de los Jóvenes','fiesta','fiestas_wiki','El Vía Crucis de la Cruz de los Jóvenes fue un Vía Crucis extraordinario​ celebrado el 3 de junio de 2011 en la ciudad de Jaén con motivo de la llegada a la misma de la Cruz de los Jóvenes, el Icono de María​ y el Icono del Santo Rostro, durante su recorrido para la Jornada Mundial de la Juventud 2011.​ Fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Vía_Crucis_de_la_Cruz_de_los_Jóvenes','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187735,'41091','Vía Crucis de la Fe de Sevilla','fiesta','fiestas_wiki','El Vía Crucis de la Fe de Sevilla fue un viacrucis organizado en la ciudad andaluza de Sevilla el 17 de febrero de 2013 a imagen y semejanza del Vía Crucis de la JMJ de Madrid. Fue convocado por la archidiócesis de Sevilla con motivo del Año de la Fe, proclamado por el papa Benedicto XVI. El Consejo de Cofradías se…',NULL,NULL,'https://es.wikipedia.org/wiki/Vía_Crucis_de_la_Fe_de_Sevilla','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187736,'22074','Vía crucis a la Cruz del Campo','fiesta','fiestas_wiki','El vía crucis a la Cruz del Campo va desde el centro al noreste de Sevilla. Comienza en la casa palacio llamada Casa de Pilatos y termina en un templete conocido como la Cruz del Campo. La tradición comenzó con Fadrique Enríquez de Ribera, propietario del inmueble, aunque hoy la casa es propiedad de los duques de…',NULL,NULL,'https://es.wikipedia.org/wiki/Vía_crucis_a_la_Cruz_del_Campo','IT Internacional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187737,'13004','Vísperas de Ciudad Real','fiesta','fiestas_wiki','Las procesiones de Vísperas son aquellas realizadas en el período de Cuaresma antes de la Semana Santa o Semana de Pasión. Tienen su origen en los viacrucis parroquiales que se organizaban en distintas ciudades para meditar los venideros días de la Pasión de Jesucristo, fundamento de la fe cristiana. En Ciudad…',NULL,NULL,'https://es.wikipedia.org/wiki/Vísperas_de_Ciudad_Real','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187738,'28079','WorldPride Madrid 2017','fiesta','fiestas_wiki','El WorldPride Madrid 2017 fue la quinta edición del WorldPride celebrada con motivo del Día Internacional del Orgullo LGBT. Se celebró en la ciudad española de Madrid del 23 de junio al 2 de julio de 2017.',NULL,NULL,'https://es.wikipedia.org/wiki/WorldPride_Madrid_2017');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187739,'49017','Xiringüelu','fiesta','fiestas_wiki','El Xiringüelu es un baile popular de Asturias (España), caracterizado por sus pasos movidos, de donde le viene el nombre, pues xiringar en asturiano significa moverse, agitarse. Este baile se origina en el siglo XVII,​ y es propio de las romerías con gaita y tambor. Es habitual en todo el Principado, así como en…',NULL,NULL,'https://es.wikipedia.org/wiki/Xiringüelu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187740,'26010','Zafarronada','fiesta','fiestas_wiki','La zafarronada o antruejo de Omaña,​ es una tradición popular de origen pagano asociada a la celebración del Carnaval, propia de la comarca de Omaña en la provincia de León, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Zafarronada','Interés Turístico Regional');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187741,'31263','Zanpantzar','fiesta','fiestas_wiki','Joaldun es un personaje tradicional de la cultura navarra originario de los pueblos navarros de Ituren y Zubieta que anuncia la llegada del carnaval agitando sus cencerros (joareak o joaleak) en la última semana de enero. Se desconoce el origen de esta tradición rural, aunque puede constatarse gran similitud, tanto…',NULL,NULL,'https://es.wikipedia.org/wiki/Zanpantzar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(187742,'90271','Zapato de Oro (tauromaquia)','fiesta','fiestas_wiki','El Zapato de Oro es un galardón que se otorga desde 1972 a la faena artística de la Feria de Novilleros de Arnedo,​ en La Rioja (España), que se celebra anualmente en la plaza de toros de la localidad en el mes de septiembre, en las fiestas patronales de San Cosme y San Damián. La feria está considerada como una de…',NULL,NULL,'https://es.wikipedia.org/wiki/Zapato_de_Oro_(tauromaquia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url,nivel_sello) VALUES(187743,'43065','Álex García Fernández','fiesta','fiestas_wiki','Alejandro Juan García Fernández (San Cristóbal de La Laguna, Santa Cruz de Tenerife, 14 de noviembre de 1981), conocido como Álex García, es un actor español conocido por sus papeles en series de televisión como Sin tetas no hay paraíso o Tierra de lobos y en películas como Seis puntos sobre Emma, Kamikaze o Si yo…',NULL,NULL,'https://es.wikipedia.org/wiki/Álex_García_Fernández','IT Internacional');

